INSERT INTO auth.users ("id", "email", "encrypted_password", "raw_user_meta_data", "created_at", "updated_at") VALUES ('9246d47e-27b2-4617-bf9f-0f240855bb19', 'samnguyen4992@gmail.com', '$2a$10$ym7dVK8gXQPjMquFcW81w.1iQ7/lDY5KtGYnuIZcgxjdAKtPWgl5G', '{"sub": "9246d47e-27b2-4617-bf9f-0f240855bb19", "name": "1234", "role": "provider", "email": "samnguyen4992@gmail.com", "email_verified": true, "phone_verified": false}'::jsonb, '2026-05-12T11:03:04.679078+00:00', '2026-11-12T10:52:33.420472+00:00') ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('ca399a22-fce9-47c2-83b9-87c2271e39d0', NULL, 'Emory Johns Creek Hospital', 'Emory Johns Creek Hospital is part of Emory Healthcare, the most comprehensive academic health system in Georgia. It specializes in providing advanced therapies and personalized care across various medical specialties, including brain health, cancer care, and heart & vascular care.', '6325 Hospital Parkway', 'Johns Creek', 'GA', '30097', '678-474-7000', ARRAY['English']::text[], 'Hospital', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/emory-johns-creek-hospital-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/emory-johns-creek-hospital-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/emory-johns-creek-hospital-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/emory-johns-creek-hospital-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/emory-johns-creek-hospital-google-5.webp"], "rating": 3.1, "reviews": [{"date": "2026-05-14T14:39:45.956961468Z", "text": "Our hospital stay was nice overall with exceptional attention from the doctors as to not just band aid the obvious but  to really rule out other possible complications. Before being admitted, my mom had to stay overnight in the ER observation wing. Not many patients there but not much attention overnight from the nurses either, due to their sleeping?!?!? I was awake all night walking around and monitoring my mom’s blood pressure and helping her to the toilet since no one else was!!", "author": "Lauren Salter", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/114661068289813448058/reviews"}, {"date": "2026-05-29T16:58:36.196681719Z", "text": "I had surgery here and was very pleased with the staff and the team that performed my surgery! Dr. Cha performed the surgery, so I want to especially highlight her professionalism! Everything was done at the highest level, carefully and professionally. And the entire team that surrounded me before, during, and after the surgery was also a pleasant surprise. Everyone was incredibly sensitive, attentive, and kind, and most importantly, they knew their business! I definitely recommend them!", "author": "Julia Filippova", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103680655326548843931/reviews"}, {"date": "2026-06-04T20:44:48.497274184Z", "text": "My mother had a heart attack on June 1 and due to the urgency was Emory John''s Creek. Now let me preface with saying my dad had a heart attack a few years ago and was St. Joseph and then Northside. I had a triple bypass at Advent Hospital in Rome, Ga so we''ve experienced a several hospitals.  Emory John''s Creek is BY FAR the WORST experience any of us have had. The ICU nurses were AWFUL. Besides being non-attentive and RUDE they were not gentle, caring nor compassionate with my mom. She was then sent to the 6th floor which was better but not by much. The patient food and cafeteria was HORRIBLE like REALLY REALLY BAD. The nursing staff in general was not even close to the level of any of the other hospitals.  The Chaplin was awesome,  kind, compassionate and friendly.  The lad lady too was very friendly, kind and great at her job (Maggie) and Jennifer on the 6th floor was awesome. That was the only positive experience in a four day stay but seriously,  the ICU was just awful!!!!!!!", "author": "Shannon Robinson", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/109171884810004692942/reviews"}, {"date": "2026-02-24T20:03:43.524505513Z", "text": "Cath Lab & surgical suites - Dr Gregory Robertson Chief/Head & entire team.\n\nAAA+++ Operation. Professionalism personified. Dignified. Empathetic. Attentive. Knowledge, Skill and Competence levels unmatched.\n\nMy opinion - #1 Cardiovascular Interventional team nationwide. There may be others of this standard but none better.", "author": "Mike Macias", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101456567342014462062/reviews"}, {"date": "2026-04-29T13:31:34.034402673Z", "text": "The nurses were able to detect babies heartbeat, dropping every time my wife had contractions. The nurse scheduled on Shift detected that immediately and called in the doctors for an emergency C-section. I am so thankful that everything went great. The baby is healthy. Wife is good and I am very pleased with my experience at Emory John’s Creek Hospital.", "author": "Haydan Gomez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100838505952161267548/reviews"}], "location": {"latitude": 34.066700499999996, "longitude": -84.1764319}, "services": ["Brain Care", "Cancer Care", "Heart & Vascular Care", "Neonatal Intensive Care", "Mother/Baby Unit"], "price_tier": "$$", "open_sunday": true, "search_text": "hospital | english | brain care | cancer care | heart & vascular care | neonatal intensive care | mother/baby unit", "google_types": ["hospital", "point_of_interest", "health", "service", "establishment"], "open_weekend": true, "rating_count": 725, "open_saturday": true, "quality_score": 80, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "review_profile": {"rating": 3.1, "so