INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('5c09f9e9-6535-4194-9c17-f7987b8ad77f', NULL, 'Mercy Hospital Oklahoma City', 'Mercy Hospital Oklahoma City is a full-service hospital located in northwest Oklahoma City just off the Kilpatrick Turnpike. Committed to bringing a full array of medical services to the community, the hospital has earned multiple recognitions including being named a 2021 100 Top Hospital by Fortune/IBM Watson Health, 2021 Best Maternity Hospital by Newsweek and The Leapfrog Group, and receiving the 2021 Patient Safety Excellence Award by Healthgrades. The hospital is also a Comprehensive Stroke Center Certified by The Joint Commission and earned the 2020 Top 100 Consumer Loyalty by NRC Health.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('09eaa982-babc-4890-b48b-bbecae233d83', NULL, 'Nuga Skin Clinic', 'Nuga Skin Clinic is a premium skincare clinic in Duluth, GA, offering professional skin and body care treatments. They provide personalized skincare treatments, including facials, body care, and hair laser removal, with a focus on affordability and quality. The clinic is known for its skilled estheticians and comprehensive menu of services.', '3775 Venture dr. Building N', 'Duluth', 'GA', '30096', '(770) 687-2545', ARRAY['English']::text[], 'Dermatology', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nuga-skin-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nuga-skin-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nuga-skin-clinic-google-3.webp", "https://nugaskinclinic.com/wp-content/uploads/2022/04/main_welcome.png", "https://nugaskinclinic.com/wp-content/uploads/2022/04/NugaLogo2.png", "http://nugaskinclinic.com/wp-content/uploads/2022/04/Nuga_Logo_01.png", "https://nugaskinclinic.com/wp-content/uploads/2022/04/Nuga_Logo_02.png", "https://nugaskinclinic.com/wp-content/plugins/revslider/public/assets/assets/dummy.png"], "rating": 4.9, "reviews": [{"date": "2025-12-09T18:35:13.852326132Z", "text": "I always choose Nuga Beauty for my skin care.  All staffs are very professional,  and I feel welcome whenever I visit the clinic.\nClinic is very clean, they have so many different lasers that would help my skin glow.", "author": "hanna kim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114132333449183115231/reviews"}, {"date": "2026-01-20T03:55:53.709069789Z", "text": "I can’t recommend this skin clinic enough! I’ve been to many places that claim to be “Korean clinics,” but this is the real deal. From the moment you walk in, you can tell they are professionals with the latest machines, lasers, and treatments. They offer an incredible variety—everything from acne packages (which I’m currently doing and wow, my scarred skin has completely transformed!) to hair removal, slimming/weight loss treatments, and Botox.\nThe staff are knowledgeable and genuinely care about results. I’ve discovered reliable products here that actually work, and the packages and deals they offer make it even better. I’ve been coming consistently every 4 weeks and my skin has never looked better—I’m literally glowing!\nIf you want real results and top-notch care, this clinic is hands down the best. Truly a hidden gem!", "author": "Daniela Amaya", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111676563477140179153/reviews"}, {"date": "2025-12-14T00:10:24.919932508Z", "text": "I’ve been going there for more than 10 years. Seon Hee was so knowledgeable, explaining every step of the laser treatment, and recommending best treatment.\nMy skin is glowing despite being getting older, and I have less irritation than ever before.\nThe atmosphere was so relaxing, and the staff made me feel completely at ease.\nI highly recommend Nuga Skin Clinic, they truly care about results and client comfort.\nThank you for your hard work! 👍", "author": "Carol Kyungeui Sung", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100395110425813890328/reviews"}, {"date": "2026-01-12T02:10:20.868842560Z", "text": "I couldn’t be happier with my experience at Nuga! The staff is incredibly professional and knowledgeable; they truly understood my skin concerns from the start. After their anti aging laser treatment, my skin feels amazing and I’ve noticed my pores are visibly smaller. I trust them for my skin treatment.", "author": "Julie", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112904957955022731638/reviews"}, {"date": "2025-11-22T14:57:24.070215657Z", "text": "I had a wonderful experience at this skincare clinic. Even after just one session, I noticed immediate results, and my skin looked visibly brighter, clear,  and more hydrated. The esthetician was very knowledgeable and took great care in addressing my skin concerns. I truly appreciate the quality of service and will definitely be returning.", "author": "Sungmin Hong", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/118145603607777799353/reviews"}, {"date": "2025-12-09T18:35:13.852326132Z", "text": "I always choose Nuga Beauty for my skin care.  All staffs are very professional,  and I feel welcome whenever I visit the clinic.\nClinic is very clean, they have so many different lasers that would help my skin glow.", "author": "hanna kim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114132333449183115231/reviews"}, {"date": "2026-01-20T03:55:53.709069789Z", "text": "I can’t recommend this skin clinic enough! I’ve been to many places that claim to be “Korean clinics,” but this is the real deal. From the moment you walk in, you can tell they are professionals with the latest machines, lasers, and treatments. They offer an incredible variety—everything from acne packages (which I’m currently doing and wow, my scarred skin has completely transformed!) to hair removal, slimming/weight loss treatments, and Botox.\nThe staff are knowledgeable and genuinely care about results. I’ve discovered reliable products here that actually work, and the packages and deals they offer make it even better. I’ve been coming consistently every 4 weeks and my skin has never looked better—I’m literally glowing!\nIf you want real results and top-notch care, this clinic is hands down the best. Truly a hidden gem!", "author": "Daniela Amaya", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111676563477140179153/reviews"}, {"date": "2025-12-14T00:10:24.919932508Z", "text": "I’ve been going there for more than 10 years. Seon Hee was so knowledgeable, explaining every step of the laser treatment, and recommending best treatment.\nMy skin is glowing despite being getting older, and I have less irritation than ever before.\nThe atmosphere was so relaxing, and the staff made me feel completely at ease.\nI highly recommend Nuga Skin Clinic, they truly care about results and client comfort.\nThank you for your hard work! 👍", "author": "Carol Kyungeui Sung", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100395110425813890328/reviews"}, {"date": "2026-01-12T02:10:20.868842560Z", "text": "I couldn’t be happier with my experience at Nuga! The staff is incredibly professional and knowledgeable; they truly understood my skin concerns from the start. After their anti aging laser treatment, my skin feels amazing and I’ve noticed my pores are visibly smaller. I trust them for my skin treatment.", "author": "Julie", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112904957955022731638/reviews"}, {"date": "2025-11-22T14:57:24.070215657Z", "text": "I had a wonderful experience at this skincare clinic. Even after just one session, I noticed immediate results, and my skin looked visibly brighter, clear,  and more hydrated. The esthetician was very knowledgeable and took great care in addressing my skin concerns. I truly appreciate the quality of service and will definitely be returning.", "author": "Sungmin Hong", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/118145603607777799353/reviews"}], "website": "https://nugaskinclinic.com/", "location": {"latitude": 33.969720699999