INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('7b405412-8713-4338-a5af-4a3b44e3a01b', NULL, 'Northside Hospital Gwinnett', 'Northside Hospital Gwinnett is a leading healthcare provider in Georgia, offering comprehensive medical services including trauma care, cancer treatment, cardiovascular care, orthopedics, surgery, and maternity services. It is known for its advanced treatment options and compassionate care.', '1000 Medical Center Boulevard', 'Lawrenceville', 'GA', '30046', '404-531-4444', ARRAY['English']::text[], 'Hospital', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-gwinnett-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-gwinnett-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-gwinnett-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-gwinnett-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-gwinnett-google-5.webp", "https://northside.com/src/assets/img/NH_Logo_Navy_2021.svg", "https://northside.com/src/assets/img/mobile-search-trigger.svg", "https://northside.com/images/default-source/icons/find_primary_care.svg", "https://northside.com/images/default-source/icons/find_a_specialist.svg", "https://northside.com/images/default-source/icons/find_immediate_care.svg"], "rating": 2.3, "reviews": [{"date": "2026-05-18T02:49:50.639625729Z", "text": "The cardiothoracic surgery team and ICU nurses at Northside Hospital Gwinnett gave my mother (Azam Shakeri) a second chance at life, and there are truly no words powerful enough to express my gratitude. From the moment we arrived, every member of the team demonstrated exceptional professionalism, compassion, and expertise.\nThe surgical team :  Dr. Alan Winston Dr. David Zapata , performed a highly complex open heart procedure with remarkable precision and confidence. They took the time to explain every step, every risk, and every option with clarity and patience, helping us feel supported during one of the most difficult moments of our lives. Their skill, calm presence, and dedication were nothing short of extraordinary.\nThe ICU nursing staff:\nRN Ms.Soonam Kim , RN Ms. Rosalinda Camonayan , Ms. Josephine ,Ms. Iman , Mr. Anthony Mercurio and Mr. Goran Uzunov , Ms. Venessa , were equally exceptional. They cared for my mother with a level of attention, kindness, and expertise that went far beyond expectations. They monitored every detail, anticipated every need, and treated her with the same tenderness and respect they would give their own family. Their communication, professionalism, and genuine compassion made an overwhelming situation feel manageable.\nThanks to this incredible team, my mother is recovering, healing, and moving toward a new chapter of life. I will forever be grateful for their commitment, their humanity, and their life، saving work. Northside Hospital Gwinnett is truly blessed to have such outstanding professionals.\nI wholeheartedly recommend this hospital and its cardiac care team to anyone facing a heart-related emergency or surgery. They are, without question, among the very best.❤️❤️❤️🙏🙏🙏", "author": "Nina Zareh", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104521350602254403543/reviews"}, {"date": "2026-06-15T21:30:29.184815544Z", "text": "I was admitted in the hospital on June 12th 2026 for a left lower lobe pneumonia, and swelling of the esophagus. I was assigned to room S801, and the staff on that floor was amazing! They attended to my needs, very quickly. Nurse Mathew, and nurse Hanjun Lee did a great job attending to my medical needs, and were very knowledgeable of my condition, and explained in detail how my medication works. They all are true people persons, who know how to hold a conversation with a patient without getting overwhelmed. I love this staff on the 8th floor so please keep them together. Nurse Mathew, Nurse Hanjuh Lee, Nurse Leader Ebony & Mindy, Nurse Maria#1 and Patient Tech Angela. The EVS Staff was also great and very professional, Mary Salroron, Ida Lina and EVS Tech Paul. Also, not to forget the best secretary on the 8th floor, Naheed! The nursing assistance on the floor was very knowledgeable, kind and helpful. If I left any names out, this is for you also. Thank you staff!! -Garry C, room S-801.", "author": "G Ray", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103534442307233234019/reviews"}, {"date": "2026-06-04T13:45:39.609430769Z", "text": "Toke my baby to this hospital and it was by far the best experience ever! 🩵💙🩵 As soon as we checked in they had a room waiting for us, within 10 min the doctor came right in and examined my son and let me know what was going on. Within 45 min. We was discharged. Northside hospital 🏥 changed the game and I love it.", "author": "Kay Kaohu", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117966937447304137153/reviews"}, {"date": "2026-07-02T14:43:26.031986930Z", "text": "Unprofessional & incompetent. I waited three months to have surgery. I fasted 12 hours, no food, very little water. I wasn''t allowed to take any medication’s for my chronic migraines, vertigo, arthritis or fibromyalgia flareups. I was told that those medication’s could cause my blood to thin before surgery so they told me to stop taking them which I did for a full week. Needless to say that I suffered for that week in constant pain.\n\nThe day of my surgery I’m halfway to the hospital, being transported by the Veteran Affairs. I get a call from Northside Hospital Gwinnett asking me, do I have someone to stay with me overnight. I told the representative that I was not told that I would be staying overnight. She responded that I would not be staying overnight, but that I needed someone to stay with me at my home. When I told her that I do not, she then told me that she was not going to allow the surgery and that she was going to cancel it. I was highly upset and told her that she was being very unprofessional and that this is something that they could’ve told me during my 30 minute appointment via phone just yesterday. Not to mention that I had a pre-surgery appointment that I attended just last week and no one said anything about me having to have someone stay with me overnight. I’m a 55-year-old 100% disabled veteran who live alone & have been doing just fine for years.\n\nI had a post surgery appointment last week and none of this was mentioned. I had a triage nurse appointment via phone just yesterday for at least 30 minutes and none of this was ever mentioned. Now I’m halfway there being transported by the VA and Northside Hospital called me to tell me that they are going to cancel my appointment because I don’t have anyone to stay with me. Highly unprofessional , incompetent and appalling. No empathy for the predicament that they put me in. The representative simply did not care.\n\nI am going to communicate with the Veteran Affairs, who were paying for the surgery and ask them if there is another facility that they can schedule me to have the surgery. After this nightmare, I want nothing to do with Northside Hospital Gwinnett ever again.", "author": "Sir Knight", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/100693335818122735923/reviews"}, {"date": "2026-02-17T21:31:29.108371598Z", "text": "I recently visited Northside Hospital to take care of some business, and I had an absolutely amazing experience. From the moment I walked in, the staff was incredibly kind and helpful. Ms. Angela guided me right to where I needed to go, and then Ms. Nila was so patient and supportive as she helped me with all the paperwork. This is truly one of the best hospitals everyone should come here!", "author": "Cynthia Rwabuhinga", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105596261065061104770/reviews"}], "location": {"latitude": 33.9633367, "longitude": -84.0175173}, "services": ["Trauma Services", "Cancer Treatment", "Cardiovascular Care", "Orthopedics", "Maternity Services"], "price_tier": "$$", "open_sunday": true, "search_text": "hospital | english | trauma services | cancer treatment | cardiovascular care | orthopedics | maternity services", "google_types": ["medical_center", "hospital", "point_of_interest", "health", "service", "establishment"], "open_weekend": true, "rating_count": 1715, "open_saturday": true, "quality_score": 80, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "review_profile": {"rating": 2.3, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Clear explanations", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight clear explanations in their feedback."}, {"theme": "Strong results", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight strong results in their feedback."}], "summary": "Northside Hospital Gwinnett has a 2.3 star Google rating from 1715 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, strong results.", "review_count": 1715, "featured_reviews": [{"date": "2026-05-18T02:49:50.639625729Z", "text": "The cardiothoracic surgery team and ICU nurses at Northside Hospital Gwinnett gave my mother (Azam Shakeri) a second chance at life, and there are truly no words powerful enough to express my gratitude. From the moment we arrived, every member of the team demonstrated exceptional professionalism, compassion, and expertise.\nThe surgical team :  Dr. Alan Winston Dr. David Zapata , performed a highly complex open heart procedure with remarkable precision and confidence. They took the time to explain every step, every risk, and every option with clarity and patience, helping us feel supported during one of the most difficult moments of our lives. Their skill, calm presence, and dedication were nothing short of extraordinary.\nThe ICU nursing staff:\nRN Ms.Soonam Kim , RN Ms. Rosalinda Camonayan , Ms. Josephine ,Ms. Iman , Mr. Anthony Mercurio and Mr. Goran Uzunov , Ms. Venessa , were equally exceptional. They cared for my mother with a level of attention, kindness, and expertise that went far beyond expectations. They monitored every detail, anticipated every need, and treated her with the same tenderness and respect they would give their own family. Their communication, professionalism, and genuine compassion made an overwhelming situation feel manageable.\nThanks to this incredible team, my mother is recovering, healing, and moving toward a new chapter of life. I will forever be grateful for their commitment, their humanity, and their life، saving work. Northside Hospital Gwinnett is truly blessed to have such outstanding professionals.\nI wholeheartedly recommend this hospital and its cardiac care team to anyone facing a heart-related emergency or surgery. They are, without question, among the very best.❤️❤️❤️🙏🙏🙏", "author": "Nina Zareh", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104521350602254403543/reviews"}, {"date": "2026-06-15T21:30:29.184815544Z", "text": "I was admitted in the hospital on June 12th 2026 for a left lower lobe pneumonia, and swelling of the esophagus. I was assigned to room S801, and the staff on that floor was amazing! They attended to my needs, very quickly. Nurse Mathew, and nurse Hanjun Lee did a great job attending to my medical needs, and were very knowledgeable of my condition, and explained in detail how my medication works. They all are true people persons, who know how to hold a conversation with a patient without getting overwhelmed. I love this staff on the 8th floor so please keep them together. Nurse Mathew, Nurse Hanjuh Lee, Nurse Leader Ebony & Mindy, Nurse Maria#1 and Patient Tech Angela. The EVS Staff was also great and very professional, Mary Salroron, Ida Lina and EVS Tech Paul. Also, not to forget the best secretary on the 8th floor, Naheed! The nursing assistance on the floor was very knowledgeable, kind and helpful. If I left any names out, this is for you also. Thank you staff!! -Garry C, room S-801.", "author": "G Ray", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103534442307233234019/reviews"}, {"date": "2026-06-04T13:45:39.609430769Z", "text": "Toke my baby to this hospital and it was by far the best experience ever! 🩵💙🩵 As soon as we checked in they had a room waiting for us, within 10 min the doctor came right in and examined my son and let me know what was going on. Within 45 min. We was discharged. Northside hospital 🏥 changed the game and I love it.", "author": "Kay Kaohu", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117966937447304137153/reviews"}, {"date": "2026-07-02T14:43:26.031986930Z", "text": "Unprofessional & incompetent. I waited three months to have surgery. I fasted 12 hours, no food, very little water. I wasn''t allowed to take any medication’s for my chronic migraines, vertigo, arthritis or fibromyalgia flareups. I was told that those medication’s could cause my blood to thin before surgery so they told me to stop taking them which I did for a full week. Needless to say that I suffered for that week in constant pain.\n\nThe day of my surgery I’m halfway to the hospital, being transported by the Veteran Affairs. I get a call from Northside Hospital Gwinnett asking me, do I have someone to stay with me overnight. I told the representative that I was not told that I would be staying overnight. She responded that I would not be staying overnight, but that I needed someone to stay with me at my home. When I told her that I do not, she then told me that she was not going to allow the surgery and that she was going to cancel it. I was highly upset and told her that she was being very unprofessional and that this is something that they could’ve told me during my 30 minute appointment via phone just yesterday. Not to mention that I had a pre-surgery appointment that I attended just last week and no one said anything about me having to have someone stay with me overnight. I’m a 55-year-old 100% disabled veteran who live alone & have been doing just fine for years.\n\nI had a post surgery appointment last week and none of this was mentioned. I had a triage nurse appointment via phone just yesterday for at least 30 minutes and none of this was ever mentioned. Now I’m halfway there being transported by the VA and Northside Hospital called me to tell me that they are going to cancel my appointment because I don’t have anyone to stay with me. Highly unprofessional , incompetent and appalling. No empathy for the predicament that they put me in. The representative simply did not care.\n\nI am going to communicate with the Veteran Affairs, who were paying for the surgery and ask them if there is another facility that they can schedule me to have the surgery. After this nightmare, I want nothing to do with Northside Hospital Gwinnett ever again.", "author": "Sir Knight", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/100693335818122735923/reviews"}, {"date": "2026-02-17T21:31:29.108371598Z", "text": "I recently visited Northside Hospital to take care of some business, and I had an absolutely amazing experience. From the moment I walked in, the staff was incredibly kind and helpful. Ms. Angela guided me right to where I needed to go, and then Ms. Nila was so patient and supportive as she helped me with all the paperwork. This is truly one of the best hospitals everyone should come here!", "author": "Cynthia Rwabuhinga", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105596261065061104770/reviews"}]}, "review_summary": "Northside Hospital Gwinnett has a 2.3 star Google rating from 1715 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, strong results.", "google_maps_url": "https://maps.google.com/?cid=4764224694970824387&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJCQA6O4C-9YgRwzbhPR7tHUI", "quality_missing": ["website", "languages (non-default)", "insurance", "team_members", "appointment_url"], "search_keywords": ["hospital", "english", "trauma services", "cancer treatment", "cardiovascular care", "orthopedics", "maternity services"], "google_website_url": "https://www.northside.com/locations/northside-hospital-gwinnett", "google_primary_type": "Medical Center", "google_business_status": "OPERATIONAL", "google_formatted_address": "1000 Medical Center Blvd, Lawrenceville, GA 30046, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/113346064956450806491", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWUgDmduENwYT9vdCAbVeYDNTd3Bd8DUMxtk0FuEvRIq2H4xbQI=s100-p-k-no-mo", "displayName": "Northside Hospital Gwinnett"}], [{"uri": "https://maps.google.com/maps/contrib/102457738199706477494", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXGQrAxWeNswcauA4u4vUev8KcpIAHUtAJ7ZCJXqukLDDt0tt87=s100-p-k-no-mo", "displayName": "Bruce Johnson"}], [{"uri": "https://maps.google.com/maps/contrib/113346064956450806491", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWUgDmduENwYT9vdCAbVeYDNTd3Bd8DUMxtk0FuEvRIq2H4xbQI=s100-p-k-no-mo", "displayName": "Northside Hospital Gwinnett"}], [{"uri": "https://maps.google.com/maps/contrib/107803304015576911612", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjV7DL8Q-v5mcDce9NZxteMV1kGpY-9toDNpp3Jc_90pfuS838M=s100-p-k-no-mo", "displayName": "KS MS"}], [{"uri": "https://maps.google.com/maps/contrib/108701340777329801169", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocKseV0E9ZAjCejc9xNx-ZEbN70imYgTpuhf642utA5QJhQb1U8O=s100-p-k-no-mo", "displayName": "James Wiseman"}]]}'::jsonb, '2026-05-10T09:18:09.513159+00:00', 'northside-hospital-gwinnett', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('0d516fcd-5e0c-4080-ae5d-b2c6608eaf85', NULL, 'Insight Hospital & Medical Center Chicago', 'Insight Chicago is a nonprofit organization committed to the health and well being of the Bronzeville community in Chicago. As a Safety Net Hospital, Insight Chicago provides healthcare to all people, regardless of their ability to pay. The hospital is dedicated to delivering compassionate, loving, expert, and impactful care, with a focus on community betterment and holistic health. Patients can expect top-ranked patient safety, quality care, and a welcoming environment that treats every individual with dignity and respect.', '2525 s Michigan Ave., Chicago IL 60616', 'Chicago', 'IL', '60616', '(312) 567-2000', ARRAY['English', 'Vietnamese']::text[], 'Hospital', FALSE, '{"fax": "(312) 638-8320", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/insight-hospital-medical-center-chicago-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/insight-hospital-medical-center-chicago-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/insight-hospital-medical-center-chicago-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/insight-hospital-medical-center-chicago-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/insight-hospital-medical-center-chicago-google-5.webp"], "rating": 3.3, "reviews": [{"date": "2026-05-20T22:19:32.637311265Z", "text": "I would like to acknowledge and appreciate the assistance I received regarding the processing and retrieval of my medical imaging records and paperwork.\n\nThroughout the process, communication remained open and professional, especially during the delays related to the imaging equipment. Ciara was responsive, courteous, and diligent in providing updates and guidance, which helped make an otherwise stressful situation much smoother.\n\nHer professionalism, patience, and willingness to assist are greatly appreciated. Thank you for the excellent customer service and continued communication.\n\nRespectfully,\nCarline Brown", "author": "Ms. Carline Brown", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110456791242142296122/reviews"}, {"date": "2026-02-03T12:45:01.021557158Z", "text": "Can''t speak for other services but the inpatient psychiatric ward is the best I''ve been to and other patients have said the same. The clinicians and staff are almost all friendly and genuinely seem to care. They don''t treat you like an inmate and I can say my mental health was better for it. I had good experiences during follow-up appointments as well and got to talk to a few other clinicians, who were also caring and not dismissive. If I had to go inpatient again, I''d no doubt choose to come here.", "author": "Osmosis Jones", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/104602672184188210681/reviews"}, {"date": "2026-03-18T00:32:27.132686011Z", "text": "Pls Note: I wrote a previous review but it was either deleted or removed. This happened on Febuary 13, 2026.\n\nMy experience with Dr. Marco Rodriguez was shocking and deeply upsetting. During my father’s hospitalization, I attended a meeting to discuss his care and discharge. Instead of a professional and collaborative conversation, I was met with what I perceived as a dismissive and hostile demeanor. I was repeatedly talked over, not allowed to fully express my concerns, and felt that my input as a family advocate carried no weight.\n\nThe bedside manner was abrupt and unprofessional. I have never experienced a physician speak to me in that way. As he exited my father’s room, he told me in-front of the nurse and charge nurse who also seemed shocked  but put there heads down to “go ahead and go to the news” and “go ahead and sue him,” adding, “that’s just the way it is.” I was stunned that such a statement would be made during a serious discussion about my father’s health and discharge.\n\nFamilies deserve to feel heard, respected, and included in important medical conversations. Unfortunately, that was not my experience.", "author": "Jazziecat", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/109953928815959429266/reviews"}, {"date": "2025-09-13T07:08:23.212874489Z", "text": "Spent 3 1/2 hours in the outpatient room waiting to see the doctor (still waiting). Took X-rays without divulging critical diagnosis that was imperative to the procedure. “Please knock if you need assistance” (written on the door) is a scam, save your energy for walking out of this hospital. We can hear you in your chair on the other side of the door. The men’s room door would not lock and the stall had no knob to latch the door. Nothing like the fear of getting caught with your pants down.  Make sure you wash your hands, the amount of dust and dirt in the room might make me visit another hospital before I even get to leave this one. I’m all for a teaching hospital but let’s teach good practices, not this Insight Hospital.", "author": "Joe Benoit", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/108113486670255279182/reviews"}, {"date": "2026-05-03T16:43:53.672938225Z", "text": "The nurses and doctors treated my friend the other night and me with the upmost disrespect I’ve ever received from a hospital. After not checking up on us for an hour my friend asked me to ask them when he could leave. Said I was playing doctor when MY FRIEND ASKED ME TO ASK ONE QUESTION. The doctor said he couldn’t leave because of hit “heart rate” but then discharged us 10min later. ITS A SHAME THESE PEOPLE ARE IN THE FIELD OF TAKING CARE OF OTHERS. I would drive the distance to any other hospital than to deal with these kind of nurses and doctors. PLEASE DO NOT TAKE YOUR LOVED ONES HERE. I wish I could leave 0 stars )):", "author": "TickleMeElmo", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/108054241403086312452/reviews"}], "website": "https://insightchicago.com/", "location": {"latitude": 41.8468709, "longitude": -87.620599}, "services": ["Primary Care", "Specialist Care", "Outpatient Services", "Emergency Room", "Physical Therapy", "Orthopedic Surgery"], "insurance": {"notes": "Financial assistance available. See ''Insurance Plans Accepted'' and ''Financial Assistance'' pages for details.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Top Ranked For Patient Safety", "detail": "Your safety and health are our greatest priority.", "category": "care"}, {"title": "Quality Care For Quality Health", "detail": "We make quality healthcare accessible to all and provide a multitude of services for all of your needs.", "category": "care"}, {"title": "More Than Just a Hospital", "detail": "Insight Chicago provides more than just healthcare - we''re about community. We aim to educate and empower our community members to lead healthier, happier lives.", "category": "culture"}, {"title": "Patient Care Second To None", "detail": "We’re here to provide the best patient care and experience, regardless of your ability to pay.", "category": "care"}], "price_tier": "$$", "source_url": "https://insightchicago.com/?utm_campaign=gmb", "appointment": {"booking_note": "Schedule your appointment now.", "appointment_url": "https://insightchicago.com/appointment//", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking hospital in Chicago, IL", "search_text": "hospital | english | vietnamese | tiếng việt | người việt | bác sĩ việt | primary care | specialist care | outpatient services | emergency room | physical therapy | orthopedic surgery | specialty | outpatient | emergency | rehabilitation | surgery | ms pearl | front desk | denise martinez | central registration | chandra gibson | ricky | nurse | dr. ahmad elakil | physician | lori | checkout staff | mary | physical therapist | nurse taylor | abdullah | staff member", "google_types": ["hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 835, "team_members": [{"name": "Ms Pearl", "role": "Front Desk", "bio_snippet": "Greeted a patient with warmth reminiscent of a grandmother.", "languages_spoken": []}, {"name": "Denise Martinez", "role": "Central Registration", "bio_snippet": "Pleasant and kind, helped a patient discover secondary insurance.", "languages_spoken": []}, {"name": "Chandra Gibson", "role": "Central Registration", "bio_snippet": "Helped a patient with insurance information.", "languages_spoken": []}, {"name": "Ricky", "role": "Nurse", "bio_snippet": "Kind, warm, and patient.", "languages_spoken": []}, {"name": "Dr. Ahmad Elakil", "role": "Physician", "bio_snippet": "Excellent bedside manner, attentive and detailed about next steps.", "languages_spoken": []}, {"name": "Lori", "role": "Checkout Staff", "bio_snippet": "Warm and kind, scheduled follow-up visits.", "languages_spoken": []}, {"name": "Mary", "role": "Physical Therapist", "bio_snippet": "Instrumental in recovery, patient advocate, designed personalized plan.", "languages_spoken": []}, {"name": "Nurse Taylor", "role": "Nurse", "bio_snippet": "Wonderful, knowledgeable, and empathetic.", "languages_spoken": []}, {"name": "Abdullah", "role": "Staff Member", "bio_snippet": "Exceptional, answered all questions thoroughly, put smiles on faces.", "languages_spoken": []}], "open_saturday": true, "quality_score": 95, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "review_profile": {"rating": 3.3, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Strong results", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight strong results in their feedback."}], "summary": "Insight Hospital & Medical Center Chicago has a 3.3 star Google rating from 835 Google reviews. Patients commonly mention compassionate care, friendly staff, strong results.", "review_count": 835, "concern_themes": ["Long wait times in the emergency room (up to 8 hours)"], "positive_themes": ["Compassionate and warm staff", "Excellent bedside manner", "Clean and organized facilities", "Patient-centered care", "Helpful registration and front desk"], "featured_reviews": [{"date": "2026-05-20T22:19:32.637311265Z", "text": "I would like to acknowledge and appreciate the assistance I received regarding the processing and retrieval of my medical imaging records and paperwork.\n\nThroughout the process, communication remained open and professional, especially during the delays related to the imaging equipment. Ciara was responsive, courteous, and diligent in providing updates and guidance, which helped make an otherwise stressful situation much smoother.\n\nHer professionalism, patience, and willingness to assist are greatly appreciated. Thank you for the excellent customer service and continued communication.\n\nRespectfully,\nCarline Brown", "author": "Ms. Carline Brown", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110456791242142296122/reviews"}, {"date": "2026-02-03T12:45:01.021557158Z", "text": "Can''t speak for other services but the inpatient psychiatric ward is the best I''ve been to and other patients have said the same. The clinicians and staff are almost all friendly and genuinely seem to care. They don''t treat you like an inmate and I can say my mental health was better for it. I had good experiences during follow-up appointments as well and got to talk to a few other clinicians, who were also caring and not dismissive. If I had to go inpatient again, I''d no doubt choose to come here.", "author": "Osmosis Jones", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/104602672184188210681/reviews"}, {"date": "2026-03-18T00:32:27.132686011Z", "text": "Pls Note: I wrote a previous review but it was either deleted or removed. This happened on Febuary 13, 2026.\n\nMy experience with Dr. Marco Rodriguez was shocking and deeply upsetting. During my father’s hospitalization, I attended a meeting to discuss his care and discharge. Instead of a professional and collaborative conversation, I was met with what I perceived as a dismissive and hostile demeanor. I was repeatedly talked over, not allowed to fully express my concerns, and felt that my input as a family advocate carried no weight.\n\nThe bedside manner was abrupt and unprofessional. I have never experienced a physician speak to me in that way. As he exited my father’s room, he told me in-front of the nurse and charge nurse who also seemed shocked  but put there heads down to “go ahead and go to the news” and “go ahead and sue him,” adding, “that’s just the way it is.” I was stunned that such a statement would be made during a serious discussion about my father’s health and discharge.\n\nFamilies deserve to feel heard, respected, and included in important medical conversations. Unfortunately, that was not my experience.", "author": "Jazziecat", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/109953928815959429266/reviews"}, {"date": "2025-09-13T07:08:23.212874489Z", "text": "Spent 3 1/2 hours in the outpatient room waiting to see the doctor (still waiting). Took X-rays without divulging critical diagnosis that was imperative to the procedure. “Please knock if you need assistance” (written on the door) is a scam, save your energy for walking out of this hospital. We can hear you in your chair on the other side of the door. The men’s room door would not lock and the stall had no knob to latch the door. Nothing like the fear of getting caught with your pants down.  Make sure you wash your hands, the amount of dust and dirt in the room might make me visit another hospital before I even get to leave this one. I’m all for a teaching hospital but let’s teach good practices, not this Insight Hospital.", "author": "Joe Benoit", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/108113486670255279182/reviews"}, {"date": "2026-05-03T16:43:53.672938225Z", "text": "The nurses and doctors treated my friend the other night and me with the upmost disrespect I’ve ever received from a hospital. After not checking up on us for an hour my friend asked me to ask them when he could leave. Said I was playing doctor when MY FRIEND ASKED ME TO ASK ONE QUESTION. The doctor said he couldn’t leave because of hit “heart rate” but then discharged us 10min later. ITS A SHAME THESE PEOPLE ARE IN THE FIELD OF TAKING CARE OF OTHERS. I would drive the distance to any other hospital than to deal with these kind of nurses and doctors. PLEASE DO NOT TAKE YOUR LOVED ONES HERE. I wish I could leave 0 stars )):", "author": "TickleMeElmo", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/108054241403086312452/reviews"}]}, "review_summary": "Insight Hospital & Medical Center Chicago has a 3.3 star Google rating from 835 Google reviews. Patients commonly mention compassionate care, friendly staff, strong results.", "about_highlight": "Insight Chicago is a nonprofit organization committed to the health and well being of the Bronzeville community in Chicago. As a Safety Net Hospital, Insight Chicago provides healthcare to all people, regardless of their ability to pay. The hospital is dedicated to delivering compassionate, loving, expert, and impactful care, with a focus on community betterment and holistic health. Patients can expect top-ranked patient safety, quality care, and a welcoming environment that treats every individual with dignity and respect.", "appointment_url": "https://insightchicago.com/appointment//", "google_maps_url": "https://maps.google.com/?cid=4325210748989816616&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJGXT_XKQtDogRKD89oEI8Bjw", "quality_missing": ["insurance"], "search_keywords": ["hospital", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "primary care", "specialist care", "outpatient services", "emergency room", "physical therapy", "orthopedic surgery", "specialty", "outpatient", "emergency", "rehabilitation", "surgery", "ms pearl", "front desk", "denise martinez", "central registration", "chandra gibson", "ricky", "nurse", "dr. ahmad elakil", "physician", "lori", "checkout staff", "mary", "physical therapist", "nurse taylor", "abdullah", "staff member"], "services_offered": [{"name": "Primary Care", "category": "Primary Care", "description": "We have doctors in every field to help serve you, including primary care.", "is_featured": false, "patient_fit": null}, {"name": "Specialist Care", "category": "Specialty", "description": "Whether you''re looking for a specialist, we''ve got you covered.", "is_featured": false, "patient_fit": null}, {"name": "Outpatient Services", "category": "Outpatient", "description": "Insight Chicago offers outpatient services to ensure that our patients receive the care they need at any step of their health journey.", "is_featured": false, "patient_fit": null}, {"name": "Emergency Room", "category": "Emergency", "description": "Emergency care available.", "is_featured": false, "patient_fit": null}, {"name": "Physical Therapy", "category": "Rehabilitation", "description": "Physical therapy services for recovery and rehabilitation.", "is_featured": false, "patient_fit": null}, {"name": "Orthopedic Surgery", "category": "Surgery", "description": "Orthopedic surgical services.", "is_featured": false, "patient_fit": null}], "short_description": "Insight Hospital & Medical Center Chicago is a nonprofit safety net hospital committed to providing compassionate, expert care to all, regardless of ability to pay.", "google_website_url": "https://insightchicago.com/?utm_campaign=gmb", "google_primary_type": "Hospital", "provider_credentials": {"education": [], "providers": ["Ms Pearl", "Denise Martinez", "Chandra Gibson", "Ricky", "Dr. Ahmad Elakil", "Lori", "Mary", "Nurse Taylor", "Abdullah"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "2525 S Michigan Ave, Chicago, IL 60616, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/104291870633238827465", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWz5QnrN247hrRp0iFC0T600Gf3WsjhppYgM-7ivaFfFOBqsPA=s100-p-k-no-mo", "displayName": "Insight Hospital & Medical Center Chicago"}], [{"uri": "https://maps.google.com/maps/contrib/102750445771523678878", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUPI0iDF9sbwIgTb2rmrIfvVzeud9rRHffZXDy8lEQDxxQBHE9rng=s100-p-k-no-mo", "displayName": "Vince Au"}], [{"uri": "https://maps.google.com/maps/contrib/111844619849135006656", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocJ1xAvQqgOqwmLK9f6Xr4N6ILiVg0RJqE12vPITkdn5hpC9BQ=s100-p-k-no-mo", "displayName": "Keith Washington"}], [{"uri": "https://maps.google.com/maps/contrib/104291870633238827465", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWz5QnrN247hrRp0iFC0T600Gf3WsjhppYgM-7ivaFfFOBqsPA=s100-p-k-no-mo", "displayName": "Insight Hospital & Medical Center Chicago"}], [{"uri": "https://maps.google.com/maps/contrib/104291870633238827465", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWz5QnrN247hrRp0iFC0T600Gf3WsjhppYgM-7ivaFfFOBqsPA=s100-p-k-no-mo", "displayName": "Insight Hospital & Medical Center Chicago"}]]}'::jsonb, '2026-06-25T21:17:38.175777+00:00', 'insight-hospital-medical-center-chicago', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('e6f11841-bcf3-4aaf-8146-f8094a298838', NULL, 'NYC Health + Hospitals/Harlem', 'NYC Health + Hospitals/Harlem is the largest hospital in Central Harlem and the only Safety Net Hospital in Northern Manhattan. With 556 beds in operation, the facility handles over 287,000 clinic visits, nearly 94,000 ER visits, and more than 600 births annually. The hospital provides outstanding care to all New Yorkers, building on a historic legacy that includes saving the life of Rev. Dr. Martin Luther King, Jr. in 1958. Recognized as a U.S. News & World Report 2024-2025 Best Hospital, a Leader in LGBTQ Healthcare Equality, and an American Heart Association Get With The Guidelines award recipient, Harlem Hospital offers a comprehensive range of services from bariatric and orthopaedic surgery to family planning, HIV care, mental health, and women''s health. Patients benefit from adult and pediatric primary care, a Baby-Friendly Hospital, the Medina Clinic, and a dedicated WIC program. The hospital is committed to accessible care with language services, financial assistance, online appointment booking, virtual care, and a MyChart patient portal.', '506 Lenox Avenue, New York, NY 10037', 'New York', 'NY', '10037', '1-212-939-1000', ARRAY['English']::text[], 'Hospital', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsharlem-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsharlem-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsharlem-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsharlem-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsharlem-google-5.webp", "https://captcha.perfdrive.com/captcha-public/images/ss_captcha.png"], "rating": 3.9, "reviews": [{"date": "2026-06-09T18:46:28.860392586Z", "text": "I would like to recognize Jonathan Ortiz from Patient Finance at Harlem Hospital for providing exceptional customer service and assistance with my health insurance application. From the very beginning, Jonathan demonstrated professionalism, patience, and a genuine commitment to helping me navigate a process that can often be confusing and stressful.\n\nWhat truly sets Jonathan apart is his dedication to going above and beyond for patients. He took the time to explain every step, answered all of my questions thoroughly, and ensured that I understood my options. His responsiveness, attention to detail, and willingness to advocate on my behalf made a tremendous difference in my experience.\n\nIn an environment where quality customer service can sometimes be difficult to find, Jonathan consistently delivers a level of care, compassion, and professionalism that reflects the very best of Harlem Hospital. He treats every patient with dignity and respect and demonstrates the kind of commitment that organizations strive for but rarely find.\n\nHarlem Hospital is fortunate to have an employee like Jonathan Ortiz representing its mission and values. His dedication to helping patients access healthcare coverage is truly commendable, and I am grateful for all of his assistance.", "author": "Maryann Marino", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101181187104179665601/reviews"}, {"date": "2026-06-02T18:17:00.769514903Z", "text": "Sinnamon flowers was a great  employee she was so kind with great hospitality took my sons vitals and brought us to X-rays I really enjoyed visiting although I hate hospitals this was actually my first great experience at a hospital and I definitely think it was due to ms flowers expertise and hospitality thanks so much me and my son loves you for being so kind", "author": "Ashley Parker", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109843096244766398100/reviews"}, {"date": "2026-05-04T23:09:29.721382754Z", "text": "Over the years, my family and I have witnessed meaningful growth and positive change at Harlem Hospital. I truly appreciate the culture of compassion, dedication, and support demonstrated by the doctors—like Dr. Weir, dentists such as Dr. Camper, and orthopedic specialists like Dr. Dayna Phillips as well as the entire staff. Their willingness to take the time to truly listen to their patients reflects a deep commitment to quality care and makes a lasting difference in the lives of those they serve. Their commitment not only impacts the quality of care but also inspires confidence and trust in the community. I’m especially encouraged by the example this hospital sets for young aspiring Black children, like my daughters , who aspire to work in healthcare. It’s powerful for them to see what’s possible, and I look forward to the continued impact this institution will have on future generations in medicine.", "author": "Ayanna Suggs", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110175521198753083058/reviews"}, {"date": "2026-05-15T03:50:46.945641156Z", "text": "Dr. Ameer in the out patient adult behavioral health clinic is the best! She''s so easy to talk to! I have severe anxiety but she is very calming and I''m able to discuss how I''m really feeling with her. And the front desk staff is great too, especially Ms. King. It''s a very pleasant experience going there for my monthly visits.", "author": "Tricia Giustra-Jackson", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108836475844580581649/reviews"}, {"date": "2026-05-26T01:38:04.661189398Z", "text": "Referred to HHC/Harlem Dental at 15 w 136th Street, Extremely professional service by The DDS Dr.Rafid Inam and his Dental Assistant, They were extremely professional and very helpful and made my visit very smooth and tooth extraction were done very professionally without any discomfort. Walk in service is excellent, Building is cleaned and well maintained.\nHHC is always thriving and making it very easy for Patients and Employees to receive great medical services !", "author": "Shakera Choudhury", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100588659068839270408/reviews"}], "website": "http://www.nychealthandhospitals.org/Harlem", "location": {"latitude": 40.8143104, "longitude": -73.93950869999999}, "services": ["Adult Primary Care", "Pediatric Center", "Bariatric Surgery and Metabolic Services", "Baby-Friendly Hospital", "The Medina Clinic", "Breast Health Services", "LGBTQ+ Services", "Orthopaedic Surgery", "Family Planning", "HIV Services", "Mental Health Services", "Women''s Health", "WIC Program"], "insurance": {"notes": "The website offers financial assistance, health insurance search, and price transparency information, but does not list specific accepted insurance plans.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Largest hospital in Central Harlem", "detail": "Only Safety Net Hospital in Northern Manhattan.", "category": "access"}, {"title": "U.S. News & World Report Best Hospital", "detail": "Recognized as a 2024-2025 Best Hospital and for Heart Failure.", "category": "reviews"}, {"title": "LGBTQ+ Healthcare Equality Leader", "detail": "Leader in LGBTQ Healthcare Equality and gender-affirming care.", "category": "care"}, {"title": "American Heart Association Awards", "detail": "Get With The Guidelines – Heart Failure Gold Plus and Stroke Gold Plus with Target: Diabetes Honor Roll.", "category": "care"}, {"title": "Breast Imaging Center of Excellence", "detail": "Designated as a Breast Imaging Center of Excellence.", "category": "care"}, {"title": "Online Scheduling Available", "detail": "Make an appointment online or by phone at 1-844-NYC-4NYC.", "category": "convenience"}], "price_tier": "$$", "source_url": "http://www.nychealthandhospitals.org/Harlem", "appointment": {"booking_note": null, "appointment_url": "http://www.nychealthandhospitals.org/make-an-appointment/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "hospitals in new york that speak asian languages", "search_text": "hospital | english | adult primary care | pediatric center | bariatric surgery and metabolic services | baby-friendly hospital | the medina clinic | breast health services | lgbtq+ services | orthopaedic surgery | family planning | hiv services | mental health services | women''s health | wic program | primary care | pediatrics | surgery | maternity | specialty | preventive | reproductive | infectious disease | mental health | nutrition", "google_types": ["hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 1509, "open_saturday": true, "quality_score": 87, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "iframe_sources": ["https://newassets.hcaptcha.com/captcha/v1/caa502ef4d2063b68a3b48defc6ff368e0012d5d/static/hcaptcha.html#frame=checkbox&id=0yjebfpu426a&host=validate.perfdrive.com&sentry=true&reportapi=https%3A%2F%2Faccounts.hcaptcha.com&recaptchacompat=off&c