INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('8e4ddf8b-21ee-4695-b961-7fdbf64bcc68', NULL, 'TCM Healing Center', 'With almost 30 years of clinical experience, Dr. Biao Lu, Dr. Shiao-Ting Jing, and Dr. Miao Miao dedicate themselves to the highest standards of Traditional Chinese Medicine, acupuncture, herbology, nutritional counseling, and Qi Gong practice. Our doctors are graduates of prestigious universities like Beijing University of TCM and Yosan University, combining extensive training in both Western and Eastern medicine. Treatments are explained clearly and healing programs are designed to complement Western diagnoses, with profound herbal knowledge preventing any negative interactions with prescription drugs.', '12304 Santa Monica Blvd. Suite 120, Los Angeles, CA 90025', 'Los Angeles', 'CA', '90025', '310-826-5288', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"fax": "310-826-7178", "email": "contact@tcmhealingcenter.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tcm-healing-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tcm-healing-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tcm-healing-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tcm-healing-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tcm-healing-center-google-5.webp"], "rating": 5, "reviews": [{"date": "2026-01-13T23:44:14.578917379Z", "text": "Outstanding care and expertise.\nDr. Lu is an exceptional acupuncturist and has helped me tremendously through multiple complex issues. He supported my recovery from a torn labrum in my left hip, and I’m now seeing him for carpal tunnel, cubital tunnel, and complex regional pain syndrome.\n\nWhat truly sets this office apart is how responsive and compassionate they are. If I have an emergency flare-up, they always make time to see me without hesitation. Dr. Lu is incredibly knowledgeable, attentive, and truly invested in his patients’ healing.\n\nThe only time my pain is at a zero is after my treatment with Dr. Lu.", "author": "Katherine Meidanis", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102209822159089670747/reviews"}, {"date": "2026-02-09T22:27:37.415597156Z", "text": "Dr. Miao is exceptional. She is caring and professional. She explained things clearly and gave me advice to improve my health. The herbal tea she prescribed also helped me relieve my problem.", "author": "Manyi Yim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100147183962639647032/reviews"}, {"date": "2023-08-29T18:54:32.442661Z", "text": "Had a major skin flare up on my face which started as psoriasis, then got infected and I was so inflamed that I was unrecognizable. Went to highly recommended Beverly Hills Dermatologists and doctors and no one could tell me WHY this happened. They could only just prescribe meds - Antibiotics which I needed to battle the infection with but then steroids. Steroids are helpful, yes, but I didn’t want to continuously use them. If you’re like me and would like to know “why” you’re sick and what the triggers may be, then go see Dr. Lu. I walked into his office, he asked me what the issue was, I showed him and I believe that he held both of my wrists to feel the pulse and then he said “you’re allergic to mushrooms and spicy foods”. He told me to stop eating any foods with them and I would clear up my face in 6 weeks. He was right!!! I ate these all of my life but as you age and your body changes, all of a sudden, I couldn’t eat them anymore. After the consultation, he did acupuncture on me & prescribed some Chinese herbal tea concoctions which they prepare and have waiting for you at checkout.\nThis is a professional office. I can’t believe how much money and running around I had to do to find western doctors that couldn’t give me answers…then in 2 min, this guy simply tells me it’s mushrooms and spicy peppers. Dr. Lu is worth every dime.\n\nThe other doctor in the office is really great as well. My other friends go to her and highly recommend.", "author": "Food is Life", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100150438141042305613/reviews"}, {"date": "2024-07-22T02:42:33.975688Z", "text": "I have been going to them every time I’m in town and always get tremendous benefit. This is the best acupuncture provider I’ve ever been to and the wellness consultations are insightful and helpful. Love the supplements and teas they provide too. Top recommendation from me.", "author": "Andy Friedman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104732697566951634183/reviews"}, {"date": "2015-12-14T18:59:23.173Z", "text": "I am very grateful to Dr. Jing.  After two back surgeries, and a long, complicated illness, I could barely move or talk, because of almost non existent energy..\nDr. Jing is a miracle....I felt a difference after the very first treatment!  I''ve continued to feel better and better.\n\nShe is knowledgeable and kind, and the acupuncture doesn''t hurt.   I''ve had treatments at other places and wanted to scream and run out, but not here.\nI''ve taken members of my family, and they have had the same results.\nI''ve gone for allergies and sinuses and back problems and shoulder arthritis.   I will keep going there forever!", "author": "Elaine Franklin", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114149474976289981907/reviews"}], "website": "https://www.tcmhealingcenter.com/", "location": {"latitude": 34.039132699999996, "longitude": -118.4654055}, "services": ["Acupuncture", "Herbal Medicine", "Nutritional Counseling", "Infertility Treatment", "Women''s Health", "Pain Management", "Facial Acupuncture", "Qi Gong Practice"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Nearly 30 Years of Experience", "detail": "Our doctors have almost 30 years of clinical experience in Traditional Chinese Medicine.", "category": "care"}, {"title": "Graduates of Prestigious TCM Universities", "detail": "Doctors are graduates of Beijing University of TCM and Yosan University, offering the finest training in Asian medicine.", "category": "care"}, {"title": "Custom Herbal Formulas", "detail": "We customize herbal formulas using GMP-certified, high-quality herbs with no preservatives or heavy metals.", "category": "care"}, {"title": "Complementary to Western Medicine", "detail": "Healing programs are designed to complement Western diagnoses and medical care, with safe herbal knowledge.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.tcmhealingcenter.com/", "appointment": {"booking_note": null, "appointment_url": "https://www.tcmhealingcenter.com/new-patients", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Los Angeles, CA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | nutritional counseling | infertility treatment | women''s health | pain management | facial acupuncture | qi gong practice | infertility | cosmetic acupuncture | wellness | dr. biao lu | doctor of traditional chinese medicine | dr. shiao-ting jing | dr. miao miao", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 38, "team_members": [{"name": "Dr. Biao Lu", "role": "Doctor of Traditional Chinese Medicine", "bio_snippet": "Graduate of Beijing University of TCM and Yosan University, with nearly 30 years of clinical experience in TCM, acupuncture, herbology, nutritional counseling, and Qi Gong.", "languages_spoken": []}, {"name": "Dr. Shiao-Ting Jing", "role": "Doctor of Traditional Chinese Medicine", "bio_snippet": "Graduate of Beijing University of TCM and Yosan University, with nearly 30 years of clinical experience in TCM, acupuncture, herbology, nutritional counseling, and Qi Gong.", "languages_spoken": []}, {"name": "Dr. Miao Miao", "role": "Doctor of Traditional Chinese Medicine", "bio_snippet": "Graduate of Beijing University of TCM and Yosan University, with nearly 30 years of clinical experience in TCM, acupuncture, herbology, nutritional counseling, and Qi Gong.", "languages_spoken": []}], "language_note": "The clinic specializes in Traditional Chinese Medicine, with doctors trained at top Asian medicine universities (Beijing University of TCM and Yosan University), integrating Eastern and Western approaches for a culturally responsive healing practice.", "open_saturday": true, "quality_score": 95, "working_hours": {"friday": "7:00 AM – 5:30 PM", "monday": "7:30 AM – 5:00 PM", "sunday": "Closed", "tuesday": "7:30 AM – 6:00 PM", "saturday": "7:00 AM – 4:00 PM", "thursday": "7:30 AM – 5:00 PM", "wednesday": "7:00 AM – 5:30 PM"}, "gallery_images": ["https://static.wixstatic.com/media/03f5b2_52ded112ca0343cda702527168233d6b~mv2_d_2999_1459_s_2.jpg/v1/fill/w_1280,h_424,al_c,q_85,usm_0.66_1.00_0.01,enc_avif,quality_auto/03f5b2_52ded112ca0343cda702527168233d6b~mv2_d_2999_1459_s_2.jpg", "https://static.wixstatic.com/media/344d6868b318463fa4ada4204f8f5148.jpg/v1/fill/w_409,h_558,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/344d6868b318463fa4ada4204f8f5148.jpg"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 5, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight the practitioners'' deep knowledge and ability to diagnose and treat complex conditions effectively."}, {"theme": "Treatment Outcomes", "mentions": 5, "sentiment": "Positive", "summary_quote": "Patients report significant improvements in their conditions, with some describing the treatments as life-changing."}, {"theme": "Compassionate Care", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers frequently mention the practitioners'' kindness, attentiveness, and willingness to accommodate emergency needs."}, {"theme": "Communication", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients appreciate clear explanations of their conditions and personalized advice for improving their health."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "The treatments are described as pain-free and comfortable, contrasting with less pleasant experiences elsewhere."}], "summary": "Patients consistently praise TCM Healing Center for its exceptional care, knowledgeable practitioners, and effective treatments that address complex health issues with compassion and expertise.", "review_count": 38, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-01-13T23:44:14.578917379Z", "text": "Outstanding care and expertise.\nDr. Lu is an exceptional acupuncturist and has helped me tremendously through multiple complex issues. He supported my recovery from a torn labrum in my left hip, and I’m now seeing him for carpal tunnel, cubital tunnel, and complex regional pain syndrome.\n\nWhat truly sets this office apart is how responsive and compassionate they are. If I have an emergency flare-up, they always make time to see me without hesitation. Dr. Lu is incredibly knowledgeable, attentive, and truly invested in his patients’ healing.\n\nThe only time my pain is at a zero is after my treatment with Dr. Lu.", "author": "Katherine Meidanis", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102209822159089670747/reviews"}, {"date": "2026-02-09T22:27:37.415597156Z", "text": "Dr. Miao is exceptional. She is caring and professional. She explained things clearly and gave me advice to improve my health. The herbal tea she prescribed also helped me relieve my problem.", "author": "Manyi Yim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100147183962639647032/reviews"}, {"date": "2023-08-29T18:54:32.442661Z", "text": "Had a major skin flare up on my face which started as psoriasis, then got infected and I was so inflamed that I was unrecognizable. Went to highly recommended Beverly Hills Dermatologists and doctors and no one could tell me WHY this happened. They could only just prescribe meds - Antibiotics which I needed to battle the infection with but then steroids. Steroids are helpful, yes, but I didn’t want to continuously use them. If you’re like me and would like to know “why” you’re sick and what the triggers may be, then go see Dr. Lu. I walked into his office, he asked me what the issue was, I showed him and I believe that he held both of my wrists to feel the pulse and then he said “you’re allergic to mushrooms and spicy foods”. He told me to stop eating any foods with them and I would clear up my face in 6 weeks. He was right!!! I ate these all of my life but as you age and your body changes, all of a sudden, I couldn’t eat them anymore. After the consultation, he did acupuncture on me & prescribed some Chinese herbal tea concoctions which they prepare and have waiting for you at checkout.\nThis is a professional office. I can’t believe how much money and running around I had to do to find western doctors that couldn’t give me answers…then in 2 min, this guy simply tells me it’s mushrooms and spicy peppers. Dr. Lu is worth every dime.\n\nThe other doctor in the office is really great as well. My other friends go to her and highly recommend.", "author": "Food is Life", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100150438141042305613/reviews"}, {"date": "2024-07-22T02:42:33.975688Z", "text": "I have been going to them every time I’m in town and always get tremendous benefit. This is the best acupuncture provider I’ve ever been to and the wellness consultations are insightful and helpful. Love the supplements and teas they provide too. Top recommendation from me.", "author": "Andy Friedman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104732697566951634183/reviews"}, {"date": "2015-12-14T18:59:23.173Z", "text": "I am very grateful to Dr. Jing.  After two back surgeries, and a long, complicated illness, I could barely move or talk, because of almost non existent energy..\nDr. Jing is a miracle....I felt a difference after the very first treatment!  I''ve continued to feel better and better.\n\nShe is knowledgeable and kind, and the acupuncture doesn''t hurt.   I''ve had treatments at other places and wanted to scream and run out, but not here.\nI''ve taken members of my family, and they have had the same results.\nI''ve gone for allergies and sinuses and back problems and shoulder arthritis.   I will keep going there forever!", "author": "Elaine Franklin", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114149474976289981907/reviews"}]}, "review_summary": "Patients consistently praise TCM Healing Center for its exceptional care, knowledgeable practitioners, and effective treatments that address complex health issues with compassion and expertise.", "about_highlight": "With almost 30 years of clinical experience, Dr. Biao Lu, Dr. Shiao-Ting Jing, and Dr. Miao Miao dedicate themselves to the highest standards of Traditional Chinese Medicine, acupuncture, herbology, nutritional counseling, and Qi Gong practice. Our doctors are graduates of prestigious universities like Beijing University of TCM and Yosan University, combining extensive training in both Western and Eastern medicine. Treatments are explained clearly and healing programs are designed to complement Western diagnoses, with profound herbal knowledge preventing any negative interactions with prescription drugs.", "appointment_url": "https://www.tcmhealingcenter.com/new-patients", "google_maps_url": "https://maps.google.com/?cid=13211066749446894549&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJm7EIOkK7woAR1bPBoDYjV7c", "quality_missing": ["insurance"], "search_keywords": ["acupuncture & tcm", "acupuncture", "chinese medicine", "tcm", "herbal medicine", "cupping", "pain relief", "châm cứu", "đông y", "y học cổ truyền", "한의원", "침술", "한약", "中医", "针灸", "中药", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "nutritional counseling", "infertility treatment", "women''s health", "pain management", "facial acupuncture", "qi gong practice", "infertility", "cosmetic acupuncture", "wellness", "dr. biao lu", "doctor of traditional chinese medicine", "dr. shiao-ting jing", "dr. miao miao"], "cultural_context": "The clinic specializes in Traditional Chinese Medicine, with doctors trained at top Asian medicine universities (Beijing University of TCM and Yosan University), integrating Eastern and Western approaches for a culturally responsive healing practice.", "services_offered": [{"name": "Acupuncture", "category": "Acupuncture", "description": "The ancient art of acupuncture has been used in Asia for centuries to treat many conditions and relieve pain, from low back pain to headaches.", "is_featured": true, "patient_fit": "Patients seeking pain relief or holistic treatment."}, {"name": "Herbal Medicine", "category": "Herbal Medicine", "description": "We customize formulas using GMP-certified herbs to nourish and strengthen the body''s defenses while supporting acupuncture treatments.", "is_featured": true, "patient_fit": "Individuals needing personalized herbal support."}, {"name": "Nutritional Counseling", "category": "Nutritional Counseling", "description": "Integrates ancient wisdom of TCM with labs and functional medicine tests to address current health concerns.", "is_featured": true, "patient_fit": "Those seeking dietary and lifestyle balance."}, {"name": "Infertility Treatment", "category": "Infertility", "description": "Acupuncture and Chinese herbal medicine improve conception probability by enhancing hormonal functioning and overall vitality, supporting both natural and assisted methods like IVF.", "is_featured": true, "patient_fit": "Couples trying to conceive, including those using IVF or IUI."}, {"name": "Women''s Health", "category": "Women''s Health", "description": "TCM used to treat hormonal imbalance symptoms such as PMS, menopause, infertility, acne, and hormonal migraines, considering diet, lifestyle, and emotional well-being.", "is_featured": true, "patient_fit": "Women experiencing hormonal or reproductive health issues."}, {"name": "Pain Management", "category": "Pain Management", "description": "Acupuncture eases everything from low back pain, nerve pain, headaches, fibromyalgia, and menstrual cramps.", "is_featured": true, "patient_fit": "Patients with acute or chronic pain conditions."}, {"name": "Facial Acupuncture", "category": "Cosmetic Acupuncture", "description": "A cosmetic extension of traditional acupuncture that naturally helps make skin look younger, smoother, and healthier, addressing signs of aging and overall skin health.", "is_featured": false, "patient_fit": "Individuals seeking non-invasive cosmetic rejuvenation."}, {"name": "Qi Gong Practice", "category": "Wellness", "description": "Qi Gong practice is incorporated as part of the holistic healing approach.", "is_featured": false, "patient_fit": "Patients interested in mind-body practices."}], "short_description": "Traditional Chinese Medicine Healing Center offers expert acupuncture, herbal medicine, and holistic wellness in Los Angeles, CA.", "google_website_url": "https://www.tcmhealingcenter.com/", "google_primary_type": "Health", "provider_credentials": {"education": [], "providers": ["Dr. Biao Lu", "Dr. Shiao-Ting Jing", "Dr. Miao Miao"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "12304 Santa Monica Blvd #120, Los Angeles, CA 90025, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/111484133305330750557", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVqwyUxIDDr9HTVeribtkGdx1c7TTSCUKqu-4iX2LVAjin52SLs=s100-p-k-no-mo", "displayName": "TCM Healing Center"}], [{"uri": "https://maps.google.com/maps/contrib/111484133305330750557", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVqwyUxIDDr9HTVeribtkGdx1c7TTSCUKqu-4iX2LVAjin52SLs=s100-p-k-no-mo", "displayName": "TCM Healing Center"}], [{"uri": "https://maps.google.com/maps/contrib/111484133305330750557", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVqwyUxIDDr9HTVeribtkGdx1c7TTSCUKqu-4iX2LVAjin52SLs=s100-p-k-no-mo", "displayName": "TCM Healing Center"}], [{"uri": "https://maps.google.com/maps/contrib/102501483048195691302", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUwvfGoCHw7z_YxnEA2SEjqwMlVzOJlQBLK9STtKJ9cyQwHMe2s=s100-p-k-no-mo", "displayName": "TCM Healing Center"}], [{"uri": "https://maps.google.com/maps/contrib/102501483048195691302", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUwvfGoCHw7z_YxnEA2SEjqwMlVzOJlQBLK9STtKJ9cyQwHMe2s=s100-p-k-no-mo", "displayName": "TCM Healing Center"}]]}'::jsonb, '2026-06-26T10:27:14.687818+00:00', 'tcm-healing-center', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6b194ee1-a91c-4f81-8483-51a2088dff0e', NULL, 'Oriental Healing Center', 'Oriental Healing Center is a traditional Chinese medicine clinic located in San Jose, California. The center offers a variety of body treatments including acupuncture, massage, and cupping therapy to help patients feel relieved and pampered. With extended hours from 9:00 am to 9:30 pm daily (Sunday until 8:30 pm), the clinic provides convenient appointment-based care. The clinic is situated at 900 S. Winchester Blvd. #3 and can be reached at 408-868-2866. Services are by appointment only, ensuring personalized attention for each patient.', '900 S. Winchester Blvd. #3', 'San Jose', 'CA', '95128', '408-868-2866', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/oriental-healing-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/oriental-healing-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/oriental-healing-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/oriental-healing-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/oriental-healing-center-google-5.webp"], "rating": 4.3, "reviews": [{"date": "2025-09-13T14:14:33.699538661Z", "text": "I had a torn hip labrum 2 years ago and I was at a breaking point of taking meds every 4 hrs and PT feeling like it was not progressing where surgery was going to be an inevitable need. Tingling nerve pain,numbness down my left leg to toes. Finally started using acupuncture on top of PT to recover. It definitely alleviated the pain and improved mobility & the quality of my step within 2 months so I wasn''t limping and creating other issues. The acupuncture alleviated the pain and opened the channels in my body to recover. I minimized taking pain meds to nothing after 4 months while doing the acupuncture 1-3 a week depending on how active I was coaching. I''ve had 2 C-sections with a lot of scar tissue they have worked on for me as well. For the last 3 years I have been going for stress and tension which has kept me sane. It is on the higher end of cost but you can buy a package to make it less expensive. They take some insurance, but your policy has to include acupuncture which many do not because it is often not recognized as a medical practice by western standards! Acupuncture is well worth it for the stress relief (for me); I have used it since my teenage years now into my 40s for back, knee pain, stress fractures rather than always medicating. It has value for me.", "author": "Lifon Huynh", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/108797250435424753310/reviews"}, {"date": "2023-06-11T23:02:41.281613Z", "text": "I have been doing chiropractics and massage here for more than 1 year constantly. The owner has very professional chiropractic skills and is extremely friendly to customers. My neck pain reduced a lot after first 2 months and maintained a healthy and sustainable status for my daily work. Massage is 1 hour per time. The technicians are trained with medical knowledge. The cost can be covered a lot by insurance. I highly recommend to friends.", "author": "Ruiqi Hu", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114114903042332367614/reviews"}, {"date": "2017-06-04T03:20:36.580Z", "text": "This place is amazing! Dr. Liu and Dr. Sun are both welcoming and professional. I have been having neck and back pain for almost five years, and I have visited many many places for treatment and massage. This is the best one! They first worked on my muscle to get me relaxed, then they corrected my scoliosis. I feel so much better when I got out. Definitely recommend it!", "author": "Chang Yang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108927086357149690358/reviews"}, {"date": "2018-02-12T21:51:40.626Z", "text": "My wife and I went from one clinic to another in the bay area before we finally came to Oriental Healing 3 years ago. At Oriental, I have received very good treatment from Johnny, Sunny and Dr. Sun for my neck and mid back problems I had for a long time. Oriental also offers some things I never had in other clinics, such as heartfelt greetings, clean and welcome facility, husband-wife suite, in depth doctor diagnosis, welcome gift pak (cookie, soy milk, snack, etc), professional therapists, wellness teaching''s, and much more. And, we just keep coming back because we know they care for our well-being.", "author": "Stephen Kuo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112259765649456576206/reviews"}, {"date": "2017-06-04T03:34:08.753Z", "text": "Oriental Healing is great！ i have been going to this place at least one year now. i have consistent neck and back issue over four years. They really listen to what you want and provide a deep and relaxed massage. i highly recommend this place！", "author": "Ting Feng", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117500815246859990261/reviews"}], "website": "http://orientalhealingcenterusa.com/", "location": {"latitude": 37.310855, "longitude": -121.9496019}, "services": ["Acupuncture", "Massage", "Cupping Therapy"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Traditional Chinese Medicine", "detail": "Offers acupuncture, massage, cupping, and other TCM treatments.", "category": "care"}, {"title": "Extended Hours", "detail": "Open daily from 9:00 am to 9:30 pm (Sunday until 8:30 pm).", "category": "convenience"}, {"title": "By Appointment Only", "detail": "All services are by appointment only.", "category": "access"}, {"title": "Convenient Location", "detail": "Located at 900 S. Winchester Blvd. #3 in San Jose.", "category": "convenience"}], "price_tier": "$$", "source_url": "http://orientalhealingcenterusa.com/", "appointment": {"booking_note": "By appointment only. Call 408-868-2866 to schedule.", "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Chinese speaking medical clinic in San Jose, CA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | massage | cupping therapy | traditional chinese medicine", "google_types": ["wellness_center", "medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 19, "language_note": "The clinic specializes in traditional Chinese medicine (TCM) modalities such as acupuncture, tuina massage, cupping, and scraping. The Chinese name ''甲骨中医'' and the use of Chinese characters indicate a focus on serving the Asian community, particularly Chinese-speaking patients.", "open_saturday": true, "quality_score": 90, "working_hours": {"friday": "10:00 AM – 7:00 PM", "monday": "10:00 AM – 7:00 PM", "sunday": "10:00 AM – 7:00 PM", "tuesday": "10:00 AM – 7:00 PM", "saturday": "10:00 AM – 7:00 PM", "thursday": "10:00 AM – 7:00 PM", "wednesday": "10:00 AM – 7:00 PM"}, "gallery_images": ["http://orientalhealingcenterusa.com/wp-content/uploads/2025/08/cropped-cropped-header-3.jpg", "http://orientalhealingcenterusa.com/wp-content/uploads/2018/12/11-380x254.jpg", "http://orientalhealingcenterusa.com/wp-content/uploads/2018/12/1233-380x254.jpg", "http://orientalhealingcenterusa.com/wp-content/uploads/2018/12/private_var_mobile_Containers_Data_Application_A9DF1198-E8BE-435C-891E-0A1F8FBCDA26_tmp_mail_wxid_pp8mnziuiy9u11_15_thumb-380x254.jpg", "http://orientalhealingcenterusa.com/wp-content/uploads/2018/12/private_var_mobile_Containers_Data_Application_A9DF1198-E8BE-435C-891E-0A1F8FBCDA26_tmp_mail_wxid_pp8mnziuiy9u11_21_thumb-380x254.jpg", "http://orientalhealingcenterusa.com/wp-content/uploads/2018/12/OrientalHealingCenter-1207-2018-1-300x175.jpg"], "review_profile": {"rating": 4.3, "source": "google", "themes": [{"theme": "Treatment Outcomes", "mentions": 5, "sentiment": "Positive", "summary_quote": "Patients highlight significant pain relief and improved mobility, with many noting long-term benefits from acupuncture, chiropractic care, and massage."}, {"theme": "Staff Professionalism", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers consistently describe the staff as highly skilled, friendly, and attentive to patient needs."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "The clinic is praised for its clean, welcoming atmosphere and thoughtful amenities like husband-wife suites and welcome gifts."}, {"theme": "Communication", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients appreciate how the staff listens to their concerns and tailors treatments to their specific needs."}, {"theme": "Cost and Value", "mentions": 1, "sentiment": "Neutral", "summary_quote": "While some note the treatments are on the higher end of cost, many find value in packages and insurance coverage."}], "summary": "Patients at Oriental Healing Center consistently praise the clinic for its effective treatments, professional staff, and welcoming environment. Many report significant improvements in chronic pain and overall well-being, making it a highly recommended destination for holistic care.", "review_count": 19, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2025-09-13T14:14:33.699538661Z", "text": "I had a torn hip labrum 2 years ago and I was at a breaking point of taking meds every 4 hrs and PT feeling like it was not progressing where surgery was going to be an inevitable need. Tingling nerve pain,numbness down my left leg to toes. Finally started using acupuncture on top of PT to recover. It definitely alleviated the pain and improved mobility & the quality of my step within 2 months so I wasn''t limping and creating other issues. The acupuncture alleviated the pain and opened the channels in my body to recover. I minimized taking pain meds to nothing after 4 months while doing the acupuncture 1-3 a week depending on how active I was coaching. I''ve had 2 C-sections with a lot of scar tissue they have worked on for me as well. For the last 3 years I have been going for stress and tension which has kept me sane. It is on the higher end of cost but you can buy a package to make it less expensive. They take some insurance, but your policy has to include acupuncture which many do not because it is often not recognized as a medical practice by western standards! Acupuncture is well worth it for the stress relief (for me); I have used it since my teenage years now into my 40s for back, knee pain, stress fractures rather than always medicating. It has value for me.", "author": "Lifon Huynh", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/108797250435424753310/reviews"}, {"date": "2023-06-11T23:02:41.281613Z", "text": "I have been doing chiropractics and massage here for more than 1 year constantly. The owner has very professional chiropractic skills and is extremely friendly to customers. My neck pain reduced a lot after first 2 months and maintained a healthy and sustainable status for my daily work. Massage is 1 hour per time. The technicians are trained with medical knowledge. The cost can be covered a lot by insurance. I highly recommend to friends.", "author": "Ruiqi Hu", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114114903042332367614/reviews"}, {"date": "2017-06-04T03:20:36.580Z", "text": "This place is amazing! Dr. Liu and Dr. Sun are both welcoming and professional. I have been having neck and back pain for almost five years, and I have visited many many places for treatment and massage. This is the best one! They first worked on my muscle to get me relaxed, then they corrected my scoliosis. I feel so much better when I got out. Definitely recommend it!", "author": "Chang Yang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108927086357149690358/reviews"}, {"date": "2018-02-12T21:51:40.626Z", "text": "My wife and I went from one clinic to another in the bay area before we finally came to Oriental Healing 3 years ago. At Oriental, I have received very good treatment from Johnny, Sunny and Dr. Sun for my neck and mid back problems I had for a long time. Oriental also offers some things I never had in other clinics, such as heartfelt greetings, clean and welcome facility, husband-wife suite, in depth doctor diagnosis, welcome gift pak (cookie, soy milk, snack, etc), professional therapists, wellness teaching''s, and much more. And, we just keep coming back because we know they care for our well-being.", "author": "Stephen Kuo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112259765649456576206/reviews"}, {"date": "2017-06-04T03:34:08.753Z", "text": "Oriental Healing is great！ i have been going to this place at least one year now. i have consistent neck and back issue over four years. They really listen to what you want and provide a deep and relaxed massage. i highly recommend this place！", "author": "Ting Feng", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117500815246859990261/reviews"}]}, "review_summary": "Patients at Oriental Healing Center consistently praise the clinic for its effective treatments, professional staff, and welcoming environment. Many report significant improvements in chronic pain and overall well-being, making it a highly recommended destination for holistic care.", "about_highlight": "Oriental Healing Center is a traditional Chinese medicine clinic located in San Jose, California. The center offers a variety of body treatments including acupuncture, massage, and cupping therapy to help patients feel relieved and pampered. With extended hours from 9:00 am to 9:30 pm daily (Sunday until 8:30 pm), the clinic provides convenient appointment-based care. The clinic is situated at 900 S. Winchester Blvd. #3 and can be reached at 408-868-2866. Services are by appointment only, ensuring personalized attention for each patient.", "google_maps_url": "https://maps.google.com/?cid=15286413550479209682&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJ_1hY9z7Lj4AR0vQHHiJAJNQ", "quality_missing": ["insurance", "team_members", "appointment_url"], "search_keywords": ["acupuncture & tcm", "acupuncture", "chinese medicine", "tcm", "herbal medicine", "cupping", "pain relief", "châm cứu", "đông y", "y học cổ truyền", "한의원", "침술", "한약", "中医", "针灸", "中药", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "massage", "cupping therapy", "traditional chinese medicine"], "cultural_context": "The clinic specializes in traditional Chinese medicine (TCM) modalities such as acupuncture, tuina massage, cupping, and scraping. The Chinese name ''甲骨中医'' and the use of Chinese characters indicate a focus on serving the Asian community, particularly Chinese-speaking patients.", "services_offered": [{"name": "Acupuncture", "category": "Traditional Chinese Medicine", "description": "Acupuncture is generally safe when done by an appropriately trained practitioner using clean needle technique and single-use needles.", "is_featured": false, "patient_fit": null}, {"name": "Massage", "category": "Traditional Chinese Medicine", "description": "Massage is to work and act on the body with pressure. Massage techniques are commonly applied with hands, fingers, elbows, knees, forearms, feet...", "is_featured": false, "patient_fit": null}, {"name": "Cupping Therapy", "category": "Traditional Chinese Medicine", "description": "Cupping is generally safe when applied by trained professionals on people who are otherwise healthy.", "is_featured": false, "patient_fit": null}], "short_description": "Oriental Healing Center is a wellness center in San Jose, CA, offering traditional Chinese medicine treatments including acupuncture, massage, and cupping therapy.", "google_website_url": "http://orientalhealingcenterusa.com/", "google_primary_type": "Health", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "900 S Winchester Blvd #3, San Jose, CA 95128, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/103977147031130909684", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVs6-WnndFIZ0sut7nuYsSJCmgssHy3xtXzN0vp0G93QHYcAuo=s100-p-k-no-mo", "displayName": "Oriental Healing Center - Jia Gu Zhong Yi"}], [{"uri": "https://maps.google.com/maps/contrib/109849026903893201606", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWMXAEEHiLM7pFphnnOtEUX1J9deWiTz_JLLqYPEnCRzXkpwb5ghA=s100-p-k-no-mo", "displayName": "Jayasimha Nuggehalli"}], [{"uri": "https://maps.google.com/maps/contrib/106332771240827170434", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocKpZT0CUImsttetuUDc4yeoVN14yRJ6Nv_IJwcnhIdZAHqNfg=s100-p-k-no-mo", "displayName": "Johnny Liu"}], [{"uri": "https://maps.google.com/maps/contrib/106332771240827170434", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocKpZT0CUImsttetuUDc4yeoVN14yRJ6Nv_IJwcnhIdZAHqNfg=s100-p-k-no-mo", "displayName": "Johnny Liu"}], [{"uri": "https://maps.google.com/maps/contrib/106332771240827170434", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocKpZT0CUImsttetuUDc4yeoVN14yRJ6Nv_IJwcnhIdZAHqNfg=s100-p-k-no-mo", "displayName": "Johnny Liu"}]]}'::jsonb, '2026-06-26T11:01:01.410734+00:00', 'oriental-healing-center', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('dfc12e46-f2c8-4fd1-8217-eb8621b6c776', NULL, 'Northside Hospital Duluth', 'Northside Hospital is an extensive network of state-of-the-art facilities staffed with skilled, caring professionals dedicated to the health and wellness of the communities they serve. Clinical excellence and compassionate, patient-centered care go hand-in-hand, with a focus on advancing health through consistent quality standards and leading-edge therapies. The hospital has earned advanced certification in heart failure, national recognition for bone and marrow transplants, statewide patient safety awards, and a national ''high performing'' designation for multiple clinical conditions.', '3620 Howell Ferry Rd NW, Duluth, GA 30096, USA', 'Duluth', 'GA', '30096', '(678) 312-6800', ARRAY['English']::text[], 'Hospital', FALSE, '{"images": ["https://northside.com/src/assets/img/NH_Logo_Navy_2021.svg", "https://northside.com/src/assets/img/mobile-search-trigger.svg", "https://northside.com/images/default-source/icons/find_primary_care.svg", "https://northside.com/images/default-source/icons/find_a_specialist.svg", "https://northside.com/images/default-source/icons/find_immediate_care.svg", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-duluth-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-duluth-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-duluth-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-duluth-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/northside-hospital-duluth-google-5.webp", "https://www.northside.com/src/assets/img/NH_Logo_Navy_2021.svg", "https://www.northside.com/src/assets/img/mobile-search-trigger.svg", "https://www.northside.com/src/assets/img/404-shutterstock_1313513048.jpg", "https://www.northside.com/src/assets/img/NH_Logo_White_2021.svg", "https://www.northside.com/src/assets/img/Icons/X-icon-white-2024.svg", "https://www.northside.com/src/assets/img/Icons/X-icon-MD-white-2024.svg", "https://www.northside.com/src/assets/img/Icons/Glassdoor-icon-white-2024.svg", "https://www.northside.com/src/assets/img/Icons/Threads-icon-white-2024.svg", "https://www.northside.com/src/assets/img/Icons/Threads-MD-icon-white-2024.svg"], "rating": 2.4, "reviews": [{"date": "2026-03-07T04:23:17.310972148Z", "text": "The treatment was wonderful, I was seen quickly. I felt like my provider actually cared a lot about me.\nMy biggest complaint was the financial services woman who came to my room. She was so rude to me after a head injury. I hadn’t even been discharged yet, and she was asking me about payment plans. I told her just to bill me, but she demanded that I pay right then and there.\nSorry, I forgot to bring my wallet with me to the ER.\nAll this made me want to do is never come back when I need help.\nI have insurance, just because I can’t pay my co-pay today., Doesn’t mean you aren’t getting paid.\nI have never been so harassed in a hospital ever in my entire life. I have never been so harassed by financial service services in this hospital until today.", "author": "Christina Brucker", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/105638366547795803759/reviews"}, {"date": "2026-06-04T14:46:16.969248417Z", "text": "Patti in the radiology imaging dept is really sweet and pleasant . She has great bedside manners and made our family feel comfortable. You can tell she enjoys what she does & I recommend other nurses take notes. It’s important to be mindful of how a patient may feel in times like this so thank you Patti!", "author": "China Smith", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111624805507535232760/reviews"}, {"date": "2026-02-11T05:04:16.186338962Z", "text": "i never really leave reviews but after MULTIPLE negative experiences i will not be back. i have had lupus SLE for 5 years. i recently experienced a crippling flare up and came to this location. i was told everything was fine as was sent home after a light dose of pain medication. mind you, i am on a specific pain management regime that is almost never followed at this hospital. i proceeded to go home and had to return the following day due the flare up worsening and pain radiating to 3/4 ligaments. i was left in a room for an hour screaming in pain while i consistently heard staff laughing, eating, and talking about everything else\nbesides their duties. i understand nursing is a hard profession and they are not properly compensated for their role. but the sheer disconnect and laziness caused my fiancee to grab me and take\nme to emory to receive proper care. we will never be returning here i would avoid if you have any chronic illness you will be treated poorly", "author": "Farrah Collins", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/117552106350414309096/reviews"}, {"date": "2026-06-05T08:07:37.412124580Z", "text": "Don''t even try to go to this hospital I beg, I''ve been here numerous times for different reasons and each time I am welcomed with rude, lazy, impatient nurses that could care less about losing a job. I came in here recently for pains in my lower abdomen turns out I had.an ovarian cyst bursting and I was in critical pain but nonetheless the nurse/ doctor who was speaking to me about my symptoms INSISTED I was pregnant mind you I am a teenager and although it''s not uncommon she kept repeating herself after I kept saying I''m not active in anyway and had an attitude and started yelling at me she was completely unprofessional and I left without knowing what was wrong till later that night when I had to come back as the cyst was rupturing.", "author": "Lola", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/107686868540720072204/reviews"}, {"date": "2026-04-10T22:03:50.722615776Z", "text": "I had a very frustrating and disappointing experience with NS Hospital. My son was taken to the ER for what turned out to be a simple ear infection. There were no tests, no scans, and nothing that would indicate a high level of complexity in care.\n\nBased on the visit, I strongly believe this should have been billed as a Level 2 visit. Instead, we received a bill for $2,454 with Level 3 charges, along with a long list of additional fees that made no sense for such a straightforward case. To make matters worse, the provider sent a separate bill for the same visit, this time charging it as a Level 4 visit. It’s honestly shocking that they can’t even be consistent about how they classify the same visit.\n\nThis feels less like healthcare and more like a money-focused business trying to squeeze every possible dollar out of patients. There was no indication that patient care was the priority here—just billing at the highest possible levels.\n\nOverall, this experience felt like a scam. I would not recommend this hospital to anyone.", "author": "sandesh shinde", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/104299004539145749744/reviews"}], "website": "https://www.northside.com/locations/duluth", "location": {"latitude": 33.999107099999996, "longitude": -84.1630921}, "services": ["Cancer Care", "Cardiovascular Services", "Orthopedics", "Maternity Services", "Trauma Services"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Advanced certification in heart failure", "detail": "Northside Hospital has earned advanced certification in heart failure.", "category": "care"}, {"title": "National recognition for bone and marrow transplants", "detail": "Northside Hospital has received national recognition for bone and marrow transplants.", "category": "care"}, {"title": "Statewide patient safety awards", "detail": "Northside Hospital has won statewide patient safety awards.", "category": "care"}, {"title": "High performing designation", "detail": "Northside Hospital has been designated as ''high performing'' for multiple clinical conditions.", "category": "care"}, {"title": "Best Company Outlook list", "detail": "Northside Hospital is the only Georgia hospital on the recent Best Company Outlook list.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.northside.com/locations/duluth", "appointment": {"booking_note": null, "appointment_url": "https://providers.northside.com/search?search_alerts=false&provider_fields=-clinical_keywords&sort=relevance%2Cnetworks%2Cavailability_density_best", "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": true, "search_text": "hospital | english | cancer care | cardiovascular services | orthopedics | maternity services | trauma services", "google_types": ["general_hospital", "hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 337, "open_saturday": true, "quality_score": 87, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "review_profile": {"rating": 2.4, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Negative", "summary_quote": "Multiple reviewers describe encounters with rude, impatient, and unprofessional staff, particularly in emergency situations."}, {"theme": "Billing Practices", "mentions": 2, "sentiment": "Negative", "summary_quote": "Patients express frustration with inconsistent and excessive billing, with one reviewer describing it as ''less like healthcare and more like a money-focused business.''"}, {"theme": "Treatment Outcomes", "mentions": 2, "sentiment": "Negative", "summary_quote": "Several reviewers report inadequate care during critical moments, leading to worsened conditions and the need for treatment elsewhere."}, {"theme": "Communication", "mentions": 2, "sentiment": "Negative", "summary_quote": "Patients highlight dismissive and unhelpful communication from staff, particularly when discussing symptoms or billing concerns."}, {"theme": "Compassionate Care", "mentions": 1, "sentiment": "Positive", "summary_quote": "One reviewer praises a radiology staff member for their kindness and bedside manner, noting how it made their family feel comfortable."}], "summary": "Patients report mixed experiences at Northside Hospital Duluth, with some praising compassionate care from specific staff members, while others express frustration with unprofessional behavior, billing practices, and inadequate treatment during critical moments.", "review_count": 337, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-03-07T04:23:17.310972148Z", "text": "The treatment was wonderful, I was seen quickly. I felt like my provider actually cared a lot about me.\nMy biggest complaint was the financial services woman who came to my room. She was so rude to me after a head injury. I hadn’t even been discharged yet, and she was asking me about payment plans. I told her just to bill me, but she demanded that I pay right then and there.\nSorry, I forgot to bring my wallet with me to the ER.\nAll this made me want to do is never come back when I need help.\nI have insurance, just because I can’t pay my co-pay today., Doesn’t mean you aren’t getting paid.\nI have never been so harassed in a hospital ever in my entire life. I have never been so harassed by financial service services in this hospital until today.", "author": "Christina Brucker", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/105638366547795803759/reviews"}, {"date": "2026-06-04T14:46:16.969248417Z", "text": "Patti in the radiology imaging dept is really sweet and pleasant . She has great bedside manners and made our family feel comfortable. You can tell she enjoys what she does & I recommend other nurses take notes. It’s important to be mindful of how a patient may feel in times like this so thank you Patti!", "author": "China Smith", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111624805507535232760/reviews"}, {"date": "2026-02-11T05:04:16.186338962Z", "text": "i never really leave reviews but after MULTIPLE negative experiences i will not be back. i have had lupus SLE for 5 years. i recently experienced a crippling flare up and came to this location. i was told everything was fine as was sent home after a light dose of pain medication. mind you, i am on a specific pain management regime that is almost never followed at this hospital. i proceeded to go home and had to return the following day due the flare up worsening and pain radiating to 3/4 ligaments. i was left in a room for an hour screaming in pain while i consistently heard staff laughing, eating, and talking about everything else\nbesides their duties. i understand nursing is a hard profession and they are not properly compensated for their role. but the sheer disconnect and laziness caused my fiancee to grab me and take\nme to emory to receive proper care. we will never be returning here i would avoid if you have any chronic illness you will be treated poorly", "author": "Farrah Collins", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/117552106350414309096/reviews"}, {"date": "2026-06-05T08:07:37.412124580Z", "text": "Don''t even try to go to this hospital I beg, I''ve been here numerous times for different reasons and each time I am welcomed with rude, lazy, impatient nurses that could care less about losing a job. I came in here recently for pains in my lower abdomen turns out I had.an ovarian cyst bursting and I was in critical pain but nonetheless the nurse/ doctor who was speaking to me about my symptoms INSISTED I was pregnant mind you I am a teenager and although it''s not uncommon she kept repeating herself after I kept saying I''m not active in anyway and had an attitude and started yelling at me she was completely unprofessional and I left without knowing what was wrong till later that night when I had to come back as the cyst was rupturing.", "author": "Lola", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/107686868540720072204/reviews"}, {"date": "2026-04-10T22:03:50.722615776Z", "text": "I had a very frustrating and disappointing experience with NS Hospital. My son was taken to the ER for what turned out to be a simple ear infection. There were no tests, no scans, and nothing that would indicate a high level of complexity in care.\n\nBased on the visit, I strongly believe this should have been billed as a Level 2 visit. Instead, we received a bill for $2,454 with Level 3 charges, along with a long list of additional fees that made no sense for such a straightforward case. To make matters worse, the provider sent a separate bill for the same visit, this time charging it as a Level 4 visit. It’s honestly shocking that they can’t even be consistent about how they classify the same visit.\n\nThis feels less like healthcare and more like a money-focused business trying to squeeze every possible dollar out of patients. There was no indication that patient care was the priority here—just billing at the highest possible levels.\n\nOverall, this experience felt like a scam. I would not recommend this hospital to anyone.", "author": "sandesh shinde", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/104299004539145749744/reviews"}]}, "review_summary": "Patients report mixed experiences at Northside Hospital Duluth, with some praising compassionate care from specific staff members, while others express frustration with unprofessional behavior, billing practices, and inadequate treatment during critical moments.", "about_highlight": "Northside Hospital is an extensive network of state-of-the-art facilities staffed with skilled, caring professionals dedicated to the health and wellness of the communities they serve. Clinical excellence and compassionate, patient-centered care go hand-in-hand, with a focus on advancing health through consistent quality standards and leading-edge therapies. The hospital has earned advanced certification in heart failure, national recognition for bone and marrow transplants, statewide patient safety awards, and a national ''high performing'' designation for multiple clinical conditions.", "appointment_url": "https://providers.northside.com/search?search_alerts=false&provider_fields=-clinical_keywords&sort=relevance%2Cnetworks%2Cavailability_density_best", "google_maps_url": "https://maps.google.com/?cid=12519573937524282368&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJFcRpt2yi9YgRAJRfJSp2vq0", "important_links": [{"url": "https://www.northside.com/contact-us", "text": "Contact"}, {"url": "https://www.northside.com/about/quality-safety-and-service-outcomes", "text": "Quality, Safety and Service Outcomes"}, {"url": "https://www.northside.com/medical-professionals/for-physicians-providers/physician-opportunities", "text": "Physician Opportunities"}, {"url": "https://www.northside.com/medical-professionals/for-physicians-providers/medical-staff-services", "text": "Medical Staff Services"}, {"url": "https://www.northside.com/patients-visitors/billing-and-insurance/pay-bill", "text": "Pay My Bill"}, {"url": "https://www.northside.com/patient-portal", "text": "Patient Portal"}, {"url": "https://www.northside.com/locations", "text": "Find a Location"}, {"url": "https://www.northside.com/providers/search", "text": "Find a Provider"}, {"url": "https://www.northside.com/services/medical-services", "text": "Find a Condition or Treatment"}, {"url": "https://www.northside.com/find-a-doctor", "text": "Find a Doctor"}, {"url": "https://www.northside.com/services/medical-services", "text": "Find a Service"}, {"url": "https://www.northside.com/patients-visitors/patient-registration-and-forms", "text": "Patient Registration and Forms"}, {"url": "https://www.northside.com/patients-visitors/spiritual-services", "text": "Spiritual Services"}, {"url": "https://www.northside.com/patients-visitors/billing-and-insurance", "text": "Billing and Insurance"}, {"url": "https://providers.northside.com/search?search_alerts=false&provider_fields=-clinical_keywords&sort=relevance%2Cnetworks%2Cavailability_density_best", "text": "Book Appointment"}, {"url": "https://providers.northside.com/search?search_alerts=false&provider_fields=-clinical_keywords&sort=relevance%2Cnetworks%2Cavailability_density_best ", "text": "Book Appointment"}, {"url": "https://www.northside.com/providers", "text": "Providers"}, {"url": "https://www.northside.com/services", "text": "Services"}, {"url": "https://www.northside.com/locations", "text": "Locations"}, {"url": "https://www.northside.com/medical-professionals", "text": "For Providers"}, {"url": "https://www.northside.com/services/cancer-institute/cancer-treatment-options/research-and-clinical-trials", "text": "For Researchers"}, {"url": "https://www.northside.com/patients-visitors/billing-and-insurance/pricing-transparency-information", "text": "Price Transparency"}, {"url": "http://www.facebook.com/pages/Northside-Hospital-Atlanta/113473218686584", "text": ""}, {"url": "https://www.glassdoor.com/Reviews/Northside-Hospital-Reviews-E20642.htm", "text": ""}], "quality_missing": ["languages (non-default)", "insurance", "team_members"], "search_keywords": ["hospital", "english", "cancer care", "cardiovascular services", "orthopedics", "maternity services", "trauma services"], "short_description": "Northside Hospital Duluth is part of a broad network of best-in-class facilities providing a lifetime of care with clinical excellence and compassionate, patient-centered service.", "google_website_url": "https://www.northside.com/locations/northside-hospital-duluth", "google_primary_type": "General Hospital", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "3620 Howell Ferry Rd NW, Duluth, GA 30096, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/113296602551920179293", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocLPqTZupPU4s1IOoLDXAJAcjwGipg6F3GM-rbLQGnDregPO4A=s100-p-k-no-mo", "displayName": "Northside Hospital Duluth"}], [{"uri": "https://maps.google.com/maps/contrib/100436087115146034576", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVA8aPCWSdaS3DcTitejII4f2nUEyO6K6NpU5giNQTGcKw2sk5wmQ=s100-p-k-no-mo", "displayName": "Tikara Abramson"}], [{"uri": "https://maps.google.com/maps/contrib/110869265837859891327", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX2ttqWEU-6ulmucCsZ1EhUjEJImG6TetWu6PLFfr5YuU2sXDAz=s100-p-k-no-mo", "displayName": "Jackson Golden"}], [{"uri": "https://maps.google.com/maps/contrib/110869265837859891327", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX2ttqWEU-6ulmucCsZ1EhUjEJImG6TetWu6PLFfr5YuU2sXDAz=s100-p-k-no-mo", "displayName": "Jackson Golden"}], [{"uri": "https://maps.google.com/maps/contrib/110869265837859891327", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX2ttqWEU-6ulmucCsZ1EhUjEJImG6TetWu6PLFfr5YuU2sXDAz=s100-p-k-no-mo", "displayName": "Jackson Golden"}]]}'::jsonb, '2026-05-10T09:18:21.230406+00:00', 'northside-hospital-duluth', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('bee6d78e-55a4-4bf6-93f4-df33c3ea3378', NULL, 'Anchor Dental', 'Anchor Dental is a family dental practice in Dacula, GA, serving Dacula, Buford, Braselton, Hamilton Mill, and Suwanee. Led by Dr. Tom Tang, a Vietnamese immigrant and former U.S. Navy dental officer, the practice offers comprehensive dental care including preventive, pediatric, cosmetic, and emergency services. With a focus on compassionate, patient-centered care, Anchor Dental provides a welcoming environment for patients of all ages. The team is known for their professionalism, affordability, and use of advanced technology, earning a 5.0 rating from over 160 Google reviews.', '2103 Cain Circle Suite 190a, Dacula, GA 30019', 'Dacula', 'GA', '30019', '+1-770-988-4588', ARRAY['English']::text[], 'Dental', FALSE, '{"fax": "+1-770-988-4881", "email": "info@anchordentalga.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/anchor-dental-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/anchor-dental-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/anchor-dental-google-3.webp", "https://anchordentalga.com/images/Anchor Dental-SF.png", "https://anchordentalga.com/_astro/Anchor%20Dental-SF.BduycrUO_Z16NDBM.webp", "https://anchordentalga.com/_astro/tomtang.DMbI9O5S_Z1DyFhj.webp", "https://anchordentalga.com/_astro/office.CL5bMAFn_Z4s6Mh.webp", "https://anchordentalga.com/_astro/dental-exam.DWl-EBEs_Z1ENaxb.webp", "https://anchordentalga.com/_astro/Reception.BLNjyZp5_Z2twLeA.webp", "https://anchordentalga.com/_astro/family.Bugsa20E_3vGQQ.webp", "https://anchordentalga.com/_astro/DSC_1171.BEULvuMK_ZdjVA5.webp", "https://anchordentalga.com/_astro/emergency.CBCIdq7m_1A3E3W.webp", "https://anchordentalga.com/_astro/callus.BDjOYgjX_q8WGQ.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/anchor-dental-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/anchor-dental-google-5.webp", "https://www.anchordentalga.com/_astro/Anchor%20Dental-SF.BduycrUO_Z16NDBM.webp", "https://www.anchordentalga.com/_astro/tomtang.DMbI9O5S_Z1DyFhj.webp", "https://www.anchordentalga.com/_astro/office.CL5bMAFn_Z4s6Mh.webp", "https://www.anchordentalga.com/_astro/dental-exam.DWl-EBEs_Z1ENaxb.webp", "https://www.anchordentalga.com/_astro/Reception.BLNjyZp5_Z2twLeA.webp", "https://www.anchordentalga.com/_astro/family.Bugsa20E_3vGQQ.webp", "https://www.anchordentalga.com/_astro/DSC_1171.BEULvuMK_ZdjVA5.webp", "https://www.anchordentalga.com/_astro/emergency.CBCIdq7m_1A3E3W.webp", "https://www.anchordentalga.com/_astro/callus.BDjOYgjX_q8WGQ.webp"], "rating": 5, "pricing": [{"name": "General treatment cost transparency", "notes": "Patients report the office is upfront about costs of treatments.", "price": null, "category": "Exam", "price_range": null}], "reviews": [{"date": "2026-01-30T15:50:53.061712385Z", "text": "I’ve been getting my dental work done here for the past few months. I’ve had cleanings, fillings, and extractions. The staff is wonderful to work with. The office is upfront about the cost of the treatments. I’m very happy with the care I’m receiving and would highly recommend them.", "author": "Dana C", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106005468489884417529/reviews"}, {"date": "2026-02-02T23:36:47.087251449Z", "text": "This is the best experience I have had at a dental office thus far. They are patient, organized, and can fit you in and still take the time to care for what’s important to you. Dr. Tom Tan, the Dentist, really took the time to hear all of my concerns and offer recommendations. I’m bringing my children next. I have been to this office over 5 times and they are consistent in every visit. Great care is standard!", "author": "lavanna G", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105328714971882250167/reviews"}, {"date": "2026-01-30T19:25:36.912112073Z", "text": "The entire team was friendly and professional. The hygienist was gentle and thorough, offering helpful advice. The dentist took the time to explain everything clearly, including the treatment plan. Highly recommend!", "author": "Dionne Lynch", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112031990615311932670/reviews"}, {"date": "2025-11-15T02:52:00.777324868Z", "text": "The entire staff at Anchor Dental was extremely kind, polite, and helpful! I came in with a chipped front tooth and needed both a filling and a cleaning. Dr. Tang did an excellent job with the filling - it was quick, painless, and my tooth feels completely natural, as if the chip never happened. The cleaning was also thorough, efficient, and comfortable.\n\nThank you so much Anchor Dental staff!!", "author": "Matt Ha", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105333429617078691159/reviews"}, {"date": "2026-02-18T23:12:38.067941407Z", "text": "First visit here and I’m so happy I found this place!!\nThe front desk staff was very friendly. I hate going to the dentist with a passion after a bad experience in the past. So it has been a while for me since I have step foot in any dental office. Dr Tom immediately put me at ease and took his time, was very patient explaining everything to me. He made sure I was very comfortable and not in any pain, so grateful for finding Anchor Dental. Thank you to Dr Tang and his staff!", "author": "Clare Szeto", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112518031966354690197/reviews"}, {"date": "2 days ago", "text": "I recently had a wonderful first visit to Anchor Dental, where I was warmly greeted and quickly made comfortable. ... I was impressed by the office''s cleanliness, the friendliness of the staff, and their efficient teamwork, which made the entire experience smooth. Plus, they offer Saturday appointments, making it even more convenient. I''ve found my new family dentist close to home!", "author": "Brian Bergman", "rating": null, "source": "Google"}, {"date": "9 days ago", "text": "The entire staff was nothing but truly incredible! Toothaches are the absolute worst! I called them ... I was there an hour later from the call! ... Truly a friendly place with much care for your experience and concerns. This dentist office is also very affordable even with insurance.", "author": "Brooklyn Grove", "rating": null, "source": "Google"}, {"date": "26 days ago", "text": "Anchor Dental - Dr Tang and the entire staff - are knowledgeable, professional, kind and totally patient focused. Combine this with being ''in network'' for AARP Delta Dental and having the latest high tech imaging on site, makes Anchor Dental a 5 Star recommendation.", "author": "Lynn Agnes", "rating": null, "source": "Google"}, {"date": "3 months ago", "text": "This is the best experience I have had at a dental office thus far. They are patient, organized, and can fit you in and still take the time to care for what''s important to you. Dr. Tom Tang ... really took the time to hear all of my concerns and offer recommendations. I''m bringing my children next. ... Great care is standard!", "author": "Lavanna G.", "rating": null, "source": "Google"}, {"date": "1 month ago", "text": "Wow! I cannot say enough about the outstanding service provided at Anchor Dental for an emergency situation! From the initial phone call and follow up provided by Jessica at the front desk, she was compassionate and knowledgeable ... Kelly (hygienist) was professional and efficient, and Dr. Tang was so kind, professional, and was able to relieve my pain and help me with my options. You can clearly see their priorities are providing quality patient care!", "author": "Anna Lawrence", "rating": null, "source": "Google"}, {"date": "4 months ago", "text": "I''ve been getting my dental work done here for the past few months. I''ve had cleanings, fillings, and extractions. The staff is wonderful to work with. The office is upfront about the cost of the treatments. I''m very happy with the care I''m receiving and would highly recommend them.", "author": "Dana C.", "rating": null, "source": "Google"}, {"date": "2026-04-01T19:36:11.713086720Z", "text": "BEST DENTIST EVER! After my last dentist retired, this office opened right in front of my parent’s neighborhood and it’s AMAZING. Dr. Tang does a great job with cleaning’s and all the staff is so nice (front desk is da bomb dot com)! I got a filling here without any numbing (my choice, he did offer!) and still didn’t feel a thing! My new favorite dentist, everyone should go here ❤️", "author": "Jess Dasher", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100213220483871099221/reviews"}, {"date": "2026-05-23T14:50:22.025290849Z", "text": "The entire staff was nothing but truly incredible! Toothaches are the absolute worst! I called them to see how they may be able to help and when they could get me in. I was there an hour later from the call! They were so helpful from the front desk lady all the way to the surgical doctor. Truly a friendly place with much care for your experience and concerns. This dentist office is also very affordable even with insurance. Thank you Anchor Dentist Team! 🙂", "author": "Brooklyn Grove", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111591766704664645461/reviews"}, {"date": "2026-05-30T14:19:32.856299293Z", "text": "I recently had a wonderful first visit to Anchor Dental, where I was warmly greeted and quickly made comfortable.\n\nJasmine escorted me to the exam room, reviewed my appointment details, took my vitals, and assisted Dr. Tang throughout the procedure, even applying the finishing touches afterward. Dr. Tang thoroughly explained the procedure and answered all my questions.  I felt relaxed and confident in their care.\n\nI was impressed by the office’s cleanliness, the friendliness of the staff, and their efficient teamwork, which made the entire experience smooth. Plus, they offer Saturday appointments, making it even more convenient. I’ve found my new family dentist close to home!", "author": "Brian Bergman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113253389329941525855/reviews"}, {"date": "2026-01-30T15:50:53.061712385Z", "text": "I’ve been getting my dental work done here for the past few months. I’ve had cleanings, fillings, and extractions. The staff is wonderful to work with. The office is upfront about the cost of the treatments. I’m very happy with the care I’m receiving and would highly recommend them.", "author": "Dana C", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106005468489884417529/reviews"}, {"date": "2026-02-02T23:36:47.087251449Z", "text": "This is the best experience I have had at a dental office thus far. They are patient, organized, and can fit you in and still take the time to care for what’s important to you. Dr. Tom Tan, the Dentist, really took the time to hear all of my concerns and offer recommendations. I’m bringing my children next. I have been to this office over 5 times and they are consistent in every visit. Great care is standard!", "author": "lavanna G", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105328714971882250167/reviews"}, {"date": "2026-05-30T14:19:32.856299293Z", "text": "I recently had a wonderful first visit to Anchor Dental, where I was warmly greeted and quickly made comfortable.\n\nJasmine escorted me to the exam room, reviewed my appointment details, took my vitals, and assisted Dr. Tang throughout the procedure, even applying the finishing touches afterward. Dr. Tang thoroughly explained the procedure and answered all my questions.  I felt relaxed and confident in their care.\n\nI was impressed by the office’s cleanliness, the friendliness of the staff, and their efficient teamwork, which made the entire experience smooth. Plus, they offer Saturday appointments, making it even more convenient. I’ve found my new family dentist close to home!", "author": "Brian Bergman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113253389329941525855/reviews"}, {"date": "2026-04-01T19:36:11.713086720Z", "text": "BEST DENTIST EVER! After my last dentist retired, this office opened right in front of my parent’s neighborhood and it’s AMAZING. Dr. Tang does a great job with cleaning’s and all the staff is so nice (front desk is da bomb dot com)! I got a filling here without any numbing (my choice, he did offer!) and still didn’t feel a thing! My new favorite dentist, everyone should go here ❤️", "author": "Jess Dasher", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100213220483871099221/reviews"}, {"date": "2026-05-23T14:50:22.025290849Z", "text": "The entire staff was nothing but truly incredible! Toothaches are the absolute worst! I called them to see how they may be able to help and when they could get me in. I was there an hour later from the call! They were so helpful from the front desk lady all the way to the surgical doctor. Truly a friendly place with much care for your experience and concerns. This dentist office is also very affordable even with insurance. Thank you Anchor Dentist Team! 🙂", "author": "Brooklyn Grove", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111591766704664645461/reviews"}], "website": "https://anchordentalga.com", "location": {"latitude": 34.0582601, "longitude": -83.9269448}, "services": ["Dental Exam", "Cleaning", "Pediatric", "Crowns/Veneers", "Tooth Replacements", "Root Canal Therapy", "Emergency Services", "Tooth Bond/Filling", "Bleachings", "Denture and Partials", "Tooth Extractions", "Pediatric Dentistry", "Tooth Replacements (Implants and Bridges)", "Tooth Bonding/Fillings", "Teeth Whitening (Bleaching)", "Dentures and Partials", "Crowns and Veneers", "Dental Implants and Bridges", "Tooth Bonding and Fillings", "Crowns & Veneers", "Tooth Replacements (Implants & Bridges)", "Tooth Bonding / Fillings", "Dentures & Partials", "Teeth Cleaning", "Emergency Dental Services", "Tooth Bonding & Fillings", "Emergency Dental Care", "Teeth Whitening", "Bleachings (Teeth Whitening)"], "insurance": {"notes": "Patients mention the practice is affordable even with insurance and upfront about costs. In-network with AARP Delta Dental.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": ["Delta Dental"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "5.0 Rating", "detail": "Over 160+ Google reviews with a perfect 5.0 rating.", "category": "reviews"}, {"title": "Family & Pediatric Dentistry", "detail": "Serving patients of all ages, with pediatric services available from age one.", "category": "care"}, {"title": "Saturday Appointments", "detail": "Convenient Saturday hours available for busy schedules.", "category": "convenience"}, {"title": "Emergency Dental Care", "detail": "Prompt, compassionate urgent care for toothaches, chipped teeth, and other emergencies.", "category": "care"}, {"title": "In-Network Insurance", "detail": "In-network with AARP Delta Dental and accepts other major dental plans.", "category": "insurance"}, {"title": "Immigrant-Led Practice", "detail": "Founded by Dr. Tom Tang, who immigrated from Vietnam and brings a deep understanding of diverse patient needs.", "category": "culture"}, {"title": "In-Network with Delta Dental", "detail": "Explicitly noted as in-network for AARP Delta Dental.", "category": "insurance"}, {"title": "Emergency Services", "detail": "Prompt, compassionate emergency dental care when you need it most.", "category": "care"}, {"title": "Pediatric Dentistry", "detail": "First visit recommended by age 1; gentle, child-friendly approach.", "category": "care"}, {"title": "5.0 Google Rating", "detail": "Over 160 five-star reviews on Google.", "category": "reviews"}, {"title": "In-network with AARP Delta Dental", "detail": "Accepts AARP Delta Dental insurance as in-network.", "category": "insurance"}, {"title": "High-Tech Imaging", "detail": "Latest digital X-ray and imaging technology on site.", "category": "technology"}, {"title": "Affordable Care", "detail": "Patients describe the practice as affordable and upfront about costs.", "category": "pricing"}], "price_tier": "$$", "source_url": "https://www.anchordentalga.com", "appointment": {"booking_note": null, "appointment_url": "https://anchordental.as.me/schedule.php", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | dental exam | cleaning | pediatric | crowns/veneers | tooth replacements | root canal therapy | emergency services | tooth bond/filling | bleachings | denture and partials | tooth extractions | pediatric dentistry | tooth replacements (implants and bridges) | tooth bonding/fillings | teeth whitening (bleaching) | dentures and partials | crowns and veneers | dental implants and bridges | tooth bonding and fillings | crowns & veneers | tooth replacements (implants & bridges) | tooth bonding / fillings | dentures & partials | teeth cleaning | emergency dental services | tooth bonding & fillings | emergency dental care | teeth whitening | bleachings (teeth whitening) | preventive | restorative | emergency | cosmetic | surgical | delta dental | dr. tom tang | dentist, dmd | jasmine | dental assistant | jessica | front desk | kelly | hygienist", "google_types": ["dentist", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 167, "team_members": [{"name": "Dr. Tom Tang", "role": "Dentist, DMD", "bio_snippet": "Dr. Tom Tang grew up in southern Vietnam and immigrated to the U.S. in the early 1990s. He earned his BBA from Georgia State University and his dental degree from the University of Kentucky School of Dental Medicine. He served as a dental officer in the U.S. Navy at Naval Station Norfolk and Camp Lejeune and has experience in both general and pediatric dentistry. He currently volunteers on the board of Truth Community Clinic providing free care to underserved families.", "languages_spoken": []}, {"name": "Jasmine", "role": "Dental Assistant", "bio_snippet": "Escorted a patient to the exam room, assisted Dr. Tang during procedure, and applied finishing touches.", "languages_spoken": []}, {"name": "Jessica", "role": "Front Desk", "bio_snippet": "Compassionate and knowledgeable front desk staff, handled emergency calls and follow-up.", "languages_spoken": []}, {"name": "Kelly", "role": "Hygienist", "bio_snippet": "Professional and efficient hygienist mentioned in patient reviews.", "languages_spoken": []}], "language_note": "Dr. Tom Tang immigrated from southern Vietnam in the early 1990s. His family''s struggles with access to dental care inspired him to pursue dentistry. He earned his dental degree from the University of Kentucky School of Dental Medicine through a U.S. Navy scholarship and later served as a dental officer. He also volunteers at the Truth Community Clinic in Lawrenceville, providing free care to underserved families. His personal story and commitment to service reflect a deep understanding of immigrant and underserved communities.", "open_saturday": true, "quality_score": 95, "working_hours": {"friday": "8:00 AM – 4:00 PM", "monday": "8:00 AM – 4:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 4:00 PM", "saturday": "7:00 AM – 1:00 PM", "thursday": "Closed", "wednesday": "8:00 AM – 4:00 PM"}, "gallery_images": ["https://www.anchordentalga.com/_astro/office.CL5bMAFn_Z4s6Mh.webp", "https://www.anchordentalga.com/_astro/dental-exam.DWl-EBEs_Z1ENaxb.webp", "https://www.anchordentalga.com/_astro/Reception.BLNjyZp5_Z2twLeA.webp", "https://www.anchordentalga.com/_astro/family.Bugsa20E_3vGQQ.webp", "https://www.anchordentalga.com/_astro/DSC_1171.BEULvuMK_ZdjVA5.webp", "https://www.anchordentalga.com/_astro/emergency.CBCIdq7m_1A3E3W.webp", "https://www.anchordentalga.com/_astro/callus.BDjOYgjX_q8WGQ.webp", "https://www.anchordentalga.com/_astro/tomtang.DMbI9O5S_Z1DyFhj.webp"], "iframe_sources": ["https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d491.3557000671377!2d-83.92673172656833!3d34.05838786987723!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x88f5eb004374d897%3A0x36c824f99b10a2cd!2sAnchor%20Dental!5e0!3m2!1sen!2sus!4v1740940278400!5m2!1sen!2sus"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 5, "sentiment": "Positive", "summary_quote": "Every reviewer highlights friendly, knowledgeable staff who make patients feel comfortable and well-cared for."}, {"theme": "Clinical Expertise", "mentions": 4, "sentiment": "Positive", "summary_quote": "Dr. Tang and the team are praised for their thoroughness, patience, and ability to address patient concerns effectively."}, {"theme": "Facility Environment", "mentions": 3, "sentiment": "Positive", "summary_quote": "The office is described as clean, organized, and welcoming, contributing to a positive patient experience."}, {"theme": "Communication", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients appreciate the clear explanations of procedures and upfront cost transparency."}, {"theme": "Convenience", "mentions": 2, "sentiment": "Positive", "summary_quote": "Reviewers value the flexible scheduling, including Saturday appointments and quick availability for urgent needs."}], "summary": "Patients consistently praise Anchor Dental for its friendly, professional staff, thorough care, and convenient scheduling. Many reviewers highlight the exceptional patient experience and affordability, making it a top choice for dental care.", "review_count": 167, "concern_themes": [], "positive_themes": ["Friendly staff", "Professional", "Affordable", "Gentle care", "Saturday appointments", "Efficient", "Emergency care"], "featured_reviews": [{"date": "2026-01-30T15:50:53.061712385Z", "text": "I’ve been getting my dental work done here for the past few months. I’ve had cleanings, fillings, and extractions. The staff is wonderful to work with. The office is upfront about the cost of the treatments. I’m very happy with the care I’m receiving and would highly recommend them.", "author": "Dana C", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106005468489884417529/reviews"}, {"date": "2026-02-02T23:36:47.087251449Z", "text": "This is the best experience I have had at a dental office thus far. They are patient, organized, and can fit you in and still take the time to care for what’s important to you. Dr. Tom Tan, the Dentist, really took the time to hear all of my concerns and offer recommendations. I’m bringing my children next. I have been to this office over 5 times and they are consistent in every visit. Great care is standard!", "author": "lavanna G", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105328714971882250167/reviews"}, {"date": "2026-05-30T14:19:32.856299293Z", "text": "I recently had a wonderful first visit to Anchor Dental, where I was warmly greeted and quickly made comfortable.\n\nJasmine escorted me to the exam room, reviewed my appointment details, took my vitals, and assisted Dr. Tang throughout the procedure, even applying the finishing touches afterward. Dr. Tang thoroughly explained the procedure and answered all my questions.  I felt relaxed and confident in their care.\n\nI was impressed by the office’s cleanliness, the friendliness of the staff, and their efficient teamwork, which made the entire experience smooth. Plus, they offer Saturday appointments, making it even more convenient. I’ve found my new family dentist close to home!", "author": "Brian Bergman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113253389329941525855/reviews"}, {"date": "2026-04-01T19:36:11.713086720Z", "text": "BEST DENTIST EVER! After my last dentist retired, this office opened right in front of my parent’s neighborhood and it’s AMAZING. Dr. Tang does a great job with cleaning’s and all the staff is so nice (front desk is da bomb dot com)! I got a filling here without any numbing (my choice, he did offer!) and still didn’t feel a thing! My new favorite dentist, everyone should go here ❤️", "author": "Jess Dasher", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100213220483871099221/reviews"}, {"date": "2026-05-23T14:50:22.025290849Z", "text": "The entire staff was nothing but truly incredible! Toothaches are the absolute worst! I called them to see how they may be able to help and when they could get me in. I was there an hour later from the call! They were so helpful from the front desk lady all the way to the surgical doctor. Truly a friendly place with much care for your experience and concerns. This dentist office is also very affordable even with insurance. Thank you Anchor Dentist Team! 🙂", "author": "Brooklyn Grove", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111591766704664645461/reviews"}]}, "review_summary": "Patients consistently praise Anchor Dental for its friendly, professional staff, thorough care, and convenient scheduling. Many reviewers highlight the exceptional patient experience and affordability, making it a top choice for dental care.", "about_highlight": "Anchor Dental is a family dental practice in Dacula, GA, serving Dacula, Buford, Braselton, Hamilton Mill, and Suwanee. Led by Dr. Tom Tang, a Vietnamese immigrant and former U.S. Navy dental officer, the practice offers comprehensive dental care including preventive, pediatric, cosmetic, and emergency services. With a focus on compassionate, patient-centered care, Anchor Dental provides a welcoming environment for patients of all ages. The team is known for their professionalism, affordability, and use of advanced technology, earning a 5.0 rating from over 160 Google reviews.", "appointment_url": "https://anchordental.as.me/schedule.php", "google_maps_url": "https://maps.google.com/?cid=3947445727857255117&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJl9h0QwDr9YgRzaIQm_kkyDY", "important_links": [{"url": "https://www.anchordentalga.com/#about", "text": "Meet the Doctor"}, {"url": "https://www.anchordentalga.com/services", "text": "Services"}, {"url": "https://www.anchordentalga.com/contact", "text": "Contact"}, {"url": "https://www.anchordentalga.com/emergency-dentist", "text": "Emergency"}, {"url": "https://anchordental.as.me/schedule.php", "text": "Request Appointments"}, {"url": "https://www.anchordentalga.com/meet-the-doctor", "text": "Learn More"}, {"url": "https://www.google.com/search?sca_esv=f76dbb9d142d848d&cs=0&si=AL3DRZEsmMGCryMMFSHJ3StBhOdZ2-6yYkXd_doETEE1OR-qOS-SfrtZi9nEaORHBKw14UWmbchS5VMmQg__NnnYc6ZxXUu_p5q5tiREngwwttah-Ltzs-ZY63o48xgpIegLcuCsj6bz&q=Anchor+Dental+Reviews&sa=X&ved=2ahUKEwiYjo3l5PeUAxWl6ckDHUePOfwQ0bkNegQILBAI&biw=955&bih=1015&dpr=0.9", "text": "View all reviews on Google"}, {"url": "https://www.anchordentalga.com/services/dental-exam", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/teeth-cleaning", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/pediatric-dentistry", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/dental-crowns-veneers", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/dental-implants", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/root-canal-therapy", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/emergency-dental-care", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/tooth-bonding-fillings", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/teeth-whitening", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/dentures-partials", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services/tooth-extractions", "text": "Learn more →"}, {"url": "https://www.anchordentalga.com/services", "text": "Learn More"}, {"url": "https://www.facebook.com/profile.php?id=61570103782056", "text": "Facebook"}], "json_ld_schemas": [{"geo": {"@type": "GeoCoordinates", "latitude": 34.058388, "longitude": -83.926732}, "url": "https://anchordentalga.com", "logo": "https://anchordentalga.com/images/Anchor Dental-SF.png", "name": "Anchor Dental", "@type": "Dentist", "email": "info@anchordentalga.com", "image": "https://anchordentalga.com/images/Anchor Dental-SF.png", "hasMap": "https://maps.app.goo.gl/wprXPqsJjZgbjp3y8", "sameAs": ["https://www.facebook.com/profile.php?id=61570103782056", "https://www.instagram.com/anchordentalga/"], "address": {"@type": "PostalAddress", "postalCode": "30019", "addressRegion": "GA", "streetAddress": "2103 Cain Circle Suite 190a", "addressCountry": "US", "addressLocality": "Dacula"}, "founder": {"name": "Dr. Tom Tang", "@type": "Person", "jobTitle": "Dentist, DMD"}, "@context": "https://schema.org", "employee": {"name": "Dr. Tom Tang", "@type": "Person", "jobTitle": "Dentist, DMD"}, "telephone": "+1-770-988-4588", "areaServed": [{"name": "Dacula", "@type": "City", "sameAs": "https://en.wikipedia.org/wiki/Dacula,_Georgia"}, {"name": "Buford", "@type": "City", "sameAs": "https://en.wikipedia.org/wiki/Buford,_Georgia"}, {"name": "Braselton", "@type": "City", "sameAs": "https://en.wikipedia.org/wiki/Braselton,_Georgia"}, {"name": "Hamilton Mill", "@type": "City"}, {"name": "Suwanee", "@type": "City", "sameAs": "https://en.wikipedia.org/wiki/Suwanee,_Georgia"}, {"name": "Lawrenceville", "@type": "City"}], "priceRange": "$$", "description": "Anchor Dental is a family dental practice in Dacula, GA serving Dacula, Buford, Braselton, Hamilton Mill, and Suwanee. We offer family, pediatric, cosmetic, emergency dental care, crowns, veneers, implants, root canals, and more.", "hasOfferCatalog": {"name": "Dental Services", "@type": "OfferCatalog", "itemListElement": [{"@type": "Offer", "itemOffered": {"name": "Dental Exam", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Dental Cleaning", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Pediatric Dentistry", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Crowns and Veneers", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Dental Implants", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Root Canal Therapy", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Emergency Dental Care", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Teeth Whitening", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Tooth Extractions", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Dentures and Partials", "@type": "Service"}}, {"@type": "Offer", "itemOffered": {"name": "Tooth Bonding and Fillings", "@type": "Service"}}]}, "paymentAccepted": "Cash, Check, Credit Card, Dental Insurance", "medicalSpecialty": "Dentistry", "currenciesAccepted": "USD"}, {"url": "https://anchordentalga.com", "name": "Anchor Dental", "@type": "WebSite", "@context": "https://schema.org", "publisher": {"url": "https://anchordentalga.com", "name": "Anchor Dental", "@type": "Dentist"}, "description": "Family dental practice in Dacula, GA serving Dacula, Buford, Braselton, Hamilton Mill, and Suwanee. Led by Dr. Tom Tang, DMD.", "potentialAction": {"@type": "SearchAction", "target": {"@type": "EntryPoint", "urlTemplate": "https://anchordentalga.com/?s={search_term_string}"}, "query-input": "required name=search_term_string"}}, {"url": "https://anchordentalga.com", "name": "Anchor Dental", "@type": "Dentist", "review": [{"@type": "Review", "author": {"name": "Brian Bergman", "@type": "Person"}, "reviewBody": "I recently had a wonderful first visit to Anchor Dental, where I was warmly greeted and quickly made comfortable. Jasmine escorted me to the exam room, reviewed my appointment details, took my vitals, and assisted Dr. Tang throughout the procedure, even applying the finishing touches afterward. Dr. Tang thoroughly explained the procedure and answered all my questions. I felt relaxed and confident in their care. I was impressed by the office''s cleanliness, the friendliness of the staff, and their efficient teamwork, which made the entire experience smooth. Plus, they offer Saturday appointments, making it even more convenient. I''ve found my new family dentist close to home!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "Brooklyn Grove", "@type": "Person"}, "reviewBody": "The entire staff was nothing but truly incredible! Toothaches are the absolute worst! I called them to see how they may be able to help and when they could get me in. I was there an hour later from the call! They were so helpful from the front desk lady all the way to the surgical doctor. Truly a friendly place with much care for your experience and concerns. This dentist office is also very affordable even with insurance. Thank you Anchor Dentist Team! 🙂", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "Lynn Agnes", "@type": "Person"}, "reviewBody": "Anchor Dental - Dr Tang and the entire staff - are knowledgeable, professional, kind and totally patient focused. Combine this with being \"in network\" for AARP Delta Dental and having the latest high tech imaging on site, makes Anchor Dental a 5 Star recommendation.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "Lavanna G.", "@type": "Person"}, "reviewBody": "This is the best experience I have had at a dental office thus far. They are patient, organized, and can fit you in and still take the time to care for what''s important to you. Dr. Tom Tang, the Dentist, really took the time to hear all of my concerns and offer recommendations. I''m bringing my children next. I have been to this office over 5 times and they are consistent in every visit. Great care is standard!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "Anna Lawrence", "@type": "Person"}, "reviewBody": "Wow! I cannot say enough about the outstanding service provided at Anchor Dental for an emergency situation! From the initial phone call and follow up provided by Jessica at the front desk, she was compassionate and knowledgeable, and helpful with answers to all my questions. Kelly (hygienist) was professional and efficient, and Dr. Tang was so kind, professional, and was able to relieve my pain and help me with my options. You can clearly see their priorities are providing quality patient care!", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": "5"}}, {"@type": "Review", "author": {"name": "Dana C.", "@type": "Person"}, "reviewBody": "I''ve been getting my dental work done here for the past few months. I''ve had cleanings, fillings, and extractions. The staff is wonderful to work with. The office is upfront about the cost of the treatments. I''m very happy with the care I''m receiving and would highly recommend them.", "reviewRating": {"@type": "Rating", "bestRating": "5", "ratingValue": "5"}}], "@context": "https://schema.org", "aggregateRating": {"@type": "AggregateRating", "bestRating": "5", "ratingValue": "5.0", "reviewCount": "160+", "worstRating": "1"}}, {"@type": "FAQPage", "@context": "https://schema.org", "mainEntity": [{"name": "Can I get a cavity even if I don''t feel any pain?", "@type": "Question", "acceptedAnswer": {"text": "Yes, cavities can develop without pain. That''s why regular dental checkups are important—your dentist can detect early cavities before they become painful.", "@type": "Answer"}}, {"name": "What causes sensitive teeth and how can I treat it?", "@type": "Question", "acceptedAnswer": {"text": "Tooth sensitivity can be caused by worn enamel, gum recession, or cavities. Using desensitizing toothpaste, avoiding overly hot or cold foods, and talking to your dentist about possible treatments can help alleviate sensitivity.", "@type": "Answer"}}, {"name": "What are dental implants and are they safe?", "@type": "Question", "acceptedAnswer": {"text": "Dental implants are artificial tooth roots placed in the jawbone to support crowns or bridges. They are generally safe and a long-term solution for missing teeth, but the procedure may not be suitable for everyone.", "@type": "Answer"}}, {"name": "How can I keep my teeth healthy during pregnancy?", "@type": "Question", "acceptedAnswer": {"text": "Hormonal changes during pregnancy can increase the risk of gum disease. Brush and floss regularly, and visit your dentist for checkups. Let your dentist know if you are pregnant, as certain dental treatments might need to be postponed.", "@type": "Answer"}}, {"name": "Are dental X-rays safe?", "@type": "Question", "acceptedAnswer": {"text": "Dental X-rays are considered safe and use very low levels of radiation. Dentists take precautions, such as using lead aprons, to minimize exposure.", "@type": "Answer"}}, {"name": "What can I do to avoid teeth grinding (bruxism)?", "@type": "Question", "acceptedAnswer": {"text": "If you grind your teeth, your dentist may recommend a mouthguard to protect your teeth. Stress management techniques, avoiding caffeine, and addressing sleep issues can also help reduce grinding.", "@type": "Answer"}}, {"name": "Are root canals painful?", "@type": "Question", "acceptedAnswer": {"text": "With advances in dentistry, root canal treatments today are much more comfortable and are done with local anesthesia to prevent pain. Historically they had a bad reputation due to outdated techniques, but modern procedures are far more comfortable.", "@type": "Answer"}}]}], "quality_missing": ["languages (non-default)"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "dental exam", "cleaning", "pediatric", "crowns/veneers", "tooth replacements", "root canal therapy", "emergency services", "tooth bond/filling", "bleachings", "denture and partials", "tooth extractions", "pediatric dentistry", "tooth replacements (implants and bridges)", "tooth bonding/fillings", "teeth whitening (bleaching)", "dentures and partials", "crowns and veneers", "dental implants and bridges", "tooth bonding and fillings", "crowns & veneers", "tooth replacements (implants & bridges)", "tooth bonding / fillings", "dentures & partials", "teeth cleaning", "emergency dental services", "tooth bonding & fillings", "emergency dental care", "teeth whitening", "bleachings (teeth whitening)", "preventive", "restorative", "emergency", "cosmetic", "surgical", "delta dental", "dr. tom tang", "dentist, dmd", "jasmine", "dental assistant", "jessica", "front desk", "kelly", "hygienist"], "cultural_context": "Dr. Tom Tang immigrated from southern Vietnam in the early 1990s. His family''s struggles with access to dental care inspired him to pursue dentistry. He earned his dental degree from the University of Kentucky School of Dental Medicine through a U.S. Navy scholarship and later served as a dental officer. He also volunteers at the Truth Community Clinic in Lawrenceville, providing free care to underserved families. His personal story and commitment to service reflect a deep understanding of immigrant and underserved communities.", "services_offered": [{"name": "Dental Exam", "category": "Preventive", "description": "Comprehensive exams assessing teeth, gums, and jaw using X-rays to identify hidden issues.", "is_featured": false, "patient_fit": "All ages"}, {"name": "Cleaning", "category": "Preventive", "description": "Professional cleaning to remove plaque, tartar, and stains, including polishing, flossing, and fluoride treatment.", "is_featured": false, "patient_fit": "All ages"}, {"name": "Pediatric Dentistry", "category": "Pediatric", "description": "Gentle dental care for children, with first visit recommended by age 1. Services include exams, cleanings, fluoride, sealants, fillings, crowns, and space maintainers.", "is_featured": false, "patient_fit": "Children"}, {"name": "Crowns/Veneers", "category": "Restorative", "description": "Custom crowns for damaged teeth and veneers for cosmetic enhancement.", "is_featured": false, "patient_fit": "Adults"}, {"name": "Tooth Replacements", "category": "Restorative", "description": "Dental implants and bridges for permanent, natural-looking tooth replacement.", "is_featured": false, "patient_fit": "Adults"}, {"name": "Root Canal Therapy", "category": "Restorative", "description": "Treatment to remove infected pulp, clean and disinfect root canals, and fill them to save the tooth.", "is_featured": false, "patient_fit": "Adults"}, {"name": "Emergency Services", "category": "Emergency", "description": "Urgent care for toothaches, chipped teeth, and other dental emergencies.", "is_featured": false, "patient_fit": "All ages"}, {"name": "Tooth Bonding/Fillings", "category": "Restorative", "description": "Quick, cost-effective cosmetic repair for decay, chips, cracks, gaps, and discoloration.", "is_featured": false, "patient_fit": "All ages"}, {"name": "Bleachings (Teeth Whitening)", "category": "Cosmetic", "description": "In-office teeth whitening treatment, often completed in about an hour, with optional light or laser enhancement.", "is_featured": false, "patient_fit": "Adults"}, {"name": "Dentures and Partials", "category": "Restorative", "description": "Removable full or partial dentures crafted from flexible resin or metal to restore function and aesthetics.", "is_featured": false, "patient_fit": "Adults"}, {"name": "Tooth Extractions", "category": "Surgical", "description": "Safe removal of teeth due to decay, infection, overcrowding, or impaction, with aftercare guidance.", "is_featured": false, "patient_fit": "All ages"}], "google_website_url": "http://www.anchordentalga.com/", "insurance_accepted": ["Delta Dental"], "google_primary_type": "Dentist", "provider_credentials": {"education": [], "providers": ["Dr. Tom Tang", "Jasmine", "Jessica", "Kelly"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "accepting_new_patients": true, "google_business_status": "OPERATIONAL", "google_formatted_address": "2103 Cain Cir #190a, Dacula, GA 30019, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/100217729094725522053", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWspjMAwZunoz_3_Fcw8ko4iVsbOKAp4xmPkpQPnNvlq1vhcDc=s100-p-k-no-mo", "displayName": "Anchor Dental"}], [{"uri": "https://maps.google.com/maps/contrib/102581909298578736177", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocJ3jsqGo0zrMZ_E2kanNIjgGvaxsb8TTr9h06LrkGhvYr6fusI=s100-p-k-no-mo", "displayName": "Thinh Truong"}], [{"uri": "https://maps.google.com/maps/contrib/100217729094725522053", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWspjMAwZunoz_3_Fcw8ko4iVsbOKAp4xmPkpQPnNvlq1vhcDc=s100-p-k-no-mo", "displayName": "Anchor Dental"}], [{"uri": "https://maps.google.com/maps/contrib/106005468489884417529", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocID1dNb35gp0CRWbCD9pzzJYZGCfKwGVutVCwfhyPaNLrjWow=s100-p-k-no-mo", "displayName": "Dana C"}], [{"uri": "https://maps.google.com/maps/contrib/100217729094725522053", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWspjMAwZunoz_3_Fcw8ko4iVsbOKAp4xmPkpQPnNvlq1vhcDc=s100-p-k-no-mo", "displayName": "Anchor Dental"}]]}'::jsonb, '2026-06-16T10:51:36.53695+00:00', 'anchor-dental', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('0c7ccb98-6ed1-4317-aece-05627cb33b96', NULL, 'Houston Methodist Hospital', 'Houston Methodist Hospital, located in the Texas Medical Center, is the flagship hospital of Houston Methodist. With over 900 beds, 8,400 employees, and six Centers of Excellence, we offer a full spectrum of care including specialty physician offices, imaging and labs, and teams of experts using the newest technologies. For 100 years, Houston Methodist has provided the best clinical care, advanced technology and patient experience — that is our promise of leading medicine. Houston Methodist Hospital is ranked among the country''s top hospitals in 10 specialties in U.S. News & World Report''s 2025-2026 America''s "Best Hospitals" issue and again named the No. 1 hospital in Texas.', '6565 Fannin St., Houston, TX 77030', 'Houston', 'TX', '77030', '713.790.3311', ARRAY['English']::text[], 'Hospital', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/houston-methodist-hospital-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/houston-methodist-hospital-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/houston-methodist-hospital-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/houston-methodist-hospital-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/houston-methodist-hospital-google-5.webp", "https://www.houstonmethodist.org/-/media/images/locations/open-graph/alllocations_opengraph_1200x630.jpg?mw=1382&hash=32FFC72FD024F6F59037D07D5A3B7BBD", "https://www.houstonmethodist.org/-/media/images/locations/open-graph/alllocations_opengraph_1200x630.jpg?mw=1382&hash=32FFC72FD024F6F59037D07D5A3B7BBD", "https://www.houstonmethodist.org/-/media/images/header-images/logo_blue.ashx?mw=1382&hash=8A91EB4C01E3251453B1E00688D5C2F0", "https://www.houstonmethodist.org/-/media/icons/navigation/nav_icon_white_fad.ashx?mw=1382&hash=FC61E96285672B57431E56AA2FE2ADE7", "https://www.houstonmethodist.org/-/media/icons/navigation/nav_icon_white_getcarenow.ashx?mw=1382&hash=9B075B845C60C8AFB524F53978A5168B", "https://www.houstonmethodist.org/-/media/icons/navigation/nav_icon_white_mychart.ashx?mw=1382&hash=1D89D32EC17C28DE105B6F74997436E3", "https://www.houstonmethodist.org/-/media/icons/navigation/nav_icon_white_onhealthblog.ashx?mw=1382&hash=B6E2CEAD71B23FBC09A5540AB52F0F46", "https://www.houstonmethodist.org/-/media/icons/navigation/nav_icon_white_injuryclinic.ashx?mw=1382&hash=2C2B37E09F2D9882E44AF58DE509AAF5", "https://www.houstonmethodist.org/-/media/images/navigation-images/hm_megamenu_dropdown_physicianinaction_250x250.ashx?mw=1382&hash=80DAEEEB98AF56DE3EB389FC1B4CD263", "https://www.houstonmethodist.org/-/media/images/navigation-images/locations-500x500.ashx?mw=1382&hash=A925C50283CBB4167CCB363422C25A6C", "https://www.houstonmethodist.org/-/media/icons/blood-drop-heart-donation-37x39.ashx?h=39&iar=0&mw=1382&w=37&hash=86305F0067C9C469ED45719AA415143A", "https://www.houstonmethodist.org/-/media/images/locations/hospitals/hmh/hmh_waltertower_1140x560.ashx?h=560&iar=0&mw=1382&w=1140&hash=C644DDD474072F52C1EBAD1B6E0EA7DE"], "rating": 3.6, "reviews": [{"date": "2025-08-24T14:39:11.211368819Z", "text": "I believe this is one of the best hospitals in the region. From my experience everyone including the reception staff, nurses, doctors and even the public security officers were extremely helpful and caring.\n\nOne of my colleagues had an emergency situation and the response was outstanding. The ambulance service arrived very quickly and by the time we reached the hospital everything was already arranged. The medical team immediately took the necessary actions without any delay.\n\nThe professionalism, efficiency and kindness shown by the entire staff truly stood out. I highly recommend their services.", "author": "Dilan Keshawa", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101028193555852982410/reviews"}, {"date": "2026-05-10T17:43:22.861707430Z", "text": "We traveled from Florida for my daughter’s surgery (2nd one in 2 years) and can’t say enough about this hospital. From pre-op, post op and the team on her floor the level of care and sincere interest in her health was evident. The facility is beautiful with everything the family also needs while the patient is in the hospital. I stayed in the room with my daughter and they were kind to me as well. Even the food staff team were extra kind. I will never forgot the afternoon tea cart that came by with beverages and baked goods or fruit for the afternoon pick me up. The chaplain visited us and spent some uplifting time and also offered music, art or pet therapy if needed. I can’t even imagine how wonderful those options might be for a discouraged patient. This is a 5 star hospital and certainly worth traveling out of state!", "author": "Kelley Sims", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105636682166056146739/reviews"}, {"date": "2026-06-06T00:55:55.740440393Z", "text": "My husband had a Bilateral lung transplant and he has had some good nurses. I want to give a special thanks to Lamar Castleberry he’s a fine example on how a nurse should care for a patient. I just love his ethics and how he carry himself on the job. I pray, God continue to let his light shine on this young man. I also want to thank Nadine on the night shift for being a great nurse. She also enjoys her job and does it well. Over all Houston Methodist Transplant team are the BEST!", "author": "Captain Diversity", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102960259109674884267/reviews"}, {"date": "2026-02-02T02:15:36.148994060Z", "text": "The pictures attached are how I found my husband''s room today.    I also want to bring your attention to several issues we have ran into with the staff.  While in ICU nurse Jada refused to clean him when he soiled himself, nurse Yina had no patience for him and nurse Carmela was rude and basically ignored him.   Nurse Brenda  and Nog in the Alkek wing are a joke and really should choose a different profession. That being said said I want to let you know that nurses Stephanie G., Cristian, Ken,Kylie, Catherine, Eric, Kayla,and nurse aid Fabian all deserve not only a daisy nomination but also a huge thank you!  Had it not been for his team of doctors and  those eight wonderful people he would have died.\nBack to the room conditions, it is unacceptable for a hospital room to be that filthy, especially when the patient had been fighting a massive infection for almost 50 days.", "author": "Kim Olivares", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/116946828608284927046/reviews"}, {"date": "2026-02-28T06:03:16.259365308Z", "text": "If a family member dies in this hospital, make sure you are able to leave the hospital. You are not allowed to sit in this area after 10pm. No signs stating this information. I have been staying in the room with my sister and she passed. My family is hours away and I have to wait for them to arrive. This hospital  does not care about the comfort of family members in this situation.\nDo not close your eyes either out of emotional exhaustion as it is a no sleeping zone apparently.", "author": "Glenna Turney", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/101556114543245549195/reviews"}], "website": "https://www.houstonmethodist.org/locations/texas-medical-center/", "location": {"latitude": 29.7103654, "longitude": -95.3990881}, "services": ["Cancer Center", "DeBakey Heart & Vascular Center", "J.C. Walter Jr. Transplant Center", "Lynda K. and David M. Underwood Center for Digestive Health", "Neurological Institute", "Orthopedics & Sports Medicine", "Primary Care Group", "Imaging and Screenings", "Emergency Care", "Virtual Urgent Care"], "insurance": {"notes": "Insurance information is available at houstonmethodist.org/for-patients/patient-resources/insurance/ and for this location at /locations/texas-medical-center/for-patients/insurances-accepted/. No specific plans listed on this page.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "#1 Hospital in Texas for Patient Care & Quality", "detail": "Ranked No. 1 hospital in Texas by U.S. News & World Report 2025-2026.", "category": "care"}, {"title": "Top 10 Specialties Honor Roll", "detail": "Ranked among the country''s top hospitals in 10 specialties in U.S. News & World Report''s 2025-2026 America''s Best Hospitals issue.", "category": "care"}, {"title": "6 Centers of Excellence", "detail": "Specialized centers including Cancer, Heart & Vascular, Transplant, Digestive Health, Neurological Institute, and Orthopedics & Sports Medicine.", "category": "care"}, {"title": "Full Spectrum of Care", "detail": "Specialty physician offices, imaging and labs, and personalized care tailored to unique needs.", "category": "care"}, {"title": "Over 900 Beds & 8,400 Employees", "detail": "Flagship hospital in the Texas Medical Center with extensive capacity and staff.", "category": "care"}, {"title": "100 Years of Leading Medicine", "detail": "Houston Methodist has provided the best clinical care, advanced technology and patient experience for a century.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.houstonmethodist.org/locations/texas-medical-center/?utm_source=gmb&utm_medium=organic&utm_campaign=all_location_gmb&utm_content=website-click", "appointment": {"booking_note": null, "appointment_url": "https://www.houstonmethodist.org/get-care-now/", "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": true, "scout_query": "hospitals that speak Vietnamese in Houston, Texas", "search_text": "hospital | english | cancer center | debakey heart & vascular center | j.c. walter jr. transplant center | lynda k. and david m. underwood center for digestive health | neurological institute | orthopedics & sports medicine | primary care group | imaging and screenings | emergency care | virtual urgent care | cancer | heart & vascular | transplant | gastroenterology & gi surgery | neurology & neurosurgery | orthopedics | primary care | imaging | emergency | urgent care", "google_types": ["general_hospital", "hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 1149, "open_saturday": true, "quality_score": 87, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://www.houstonmethodist.org/-/media/images/locations/hospitals/hmh/hmh_waltertower_1140x560.ashx", "https://www.houstonmethodist.org/-/media/images/locations/hospitals/location-database/hospital-hmh-6565-fannin-480x274.ashx"], "review_profile": {"rating": 3.6, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Strong results", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight strong results in their feedback."}], "summary": "Houston Methodist Hospital has a 3.6 star Google rating from 1149 Google reviews. Patients commonly mention compassionate care, friendly staff, strong results.", "review_count": 1149, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2025-08-24T14:39:11.211368819Z", "text": "I believe this is one of the best hospitals in the region. From my experience everyone including the reception staff, nurses, doctors and even the public security officers were extremely helpful and caring.\n\nOne of my colleagues had an emergency situation and the response was outstanding. The ambulance service arrived very quickly and by the time we reached the hospital everything was already arranged. The medical team immediately took the necessary actions without any delay.\n\nThe professionalism, efficiency and kindness shown by the entire staff truly stood out. I highly recommend their services.", "author": "Dilan Keshawa", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101028193555852982410/reviews"}, {"date": "2026-05-10T17:43:22.861707430Z", "text": "We traveled from Florida for my daughter’s surgery (2nd one in 2 years) and can’t say enough about this hospital. From pre-op, post op and the team on her floor the level of care and sincere interest in her health was evident. The facility is beautiful with everything the family also needs while the patient is in the hospital. I stayed in the room with my daughter and they were kind to me as well. Even the food staff team were extra kind. I will never forgot the afternoon tea cart that came by with beverages and baked goods or fruit for the afternoon pick me up. The chaplain visited us and spent some uplifting time and also offered music, art or pet therapy if needed. I can’t even imagine how wonderful those options might be for a discouraged patient. This is a 5 star hospital and certainly worth traveling out of state!", "author": "Kelley Sims", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105636682166056146739/reviews"}, {"date": "2026-06-06T00:55:55.740440393Z", "text": "My husband had a Bilateral lung transplant and he has had some good nurses. I want to give a special thanks to Lamar Castleberry he’s a fine example on how a nurse should care for a patient. I just love his ethics and how he carry himself on the job. I pray, God continue to let his light shine on this young man. I also want to thank Nadine on the night shift for being a great nurse. She also enjoys her job and does it well. Over all Houston Methodist Transplant team are the BEST!", "author": "Captain Diversity", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102960259109674884267/reviews"}, {"date": "2026-02-02T02:15:36.148994060Z", "text": "The pictures attached are how I found my husband''s room today.    I also want to bring your attention to several issues we have ran into with the staff.  While in ICU nurse Jada refused to clean him when he soiled himself, nurse Yina had no patience for him and nurse Carmela was rude and basically ignored him.   Nurse Brenda  and Nog in the Alkek wing are a joke and really should choose a different profession. That being said said I want to let you know that nurses Stephanie G., Cristian, Ken,Kylie, Catherine, Eric, Kayla,and nurse aid Fabian all deserve not only a daisy nomination but also a huge thank you!  Had it not been for his team of doctors and  those eight wonderful people he would have died.\nBack to the room conditions, it is unacceptable for a hospital room to be that filthy, especially when the patient had been fighting a massive infection for almost 50 days.", "author": "Kim Olivares", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/116946828608284927046/reviews"}, {"date": "2026-02-28T06:03:16.259365308Z", "text": "If a family member dies in this hospital, make sure you are able to leave the hospital. You are not allowed to sit in this area after 10pm. No signs stating this information. I have been staying in the room with my sister and she passed. My family is hours away and I have to wait for them to arrive. This hospital  does not care about the comfort of family members in this situation.\nDo not close your eyes either out of emotional exhaustion as it is a no sleeping zone apparently.", "author": "Glenna Turney", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/101556114543245549195/reviews"}]}, "review_summary": "Houston Methodist Hospital has a 3.6 star Google rating from 1149 Google reviews. Patients commonly mention compassionate care, friendly staff, strong results.", "about_highlight": "Houston Methodist Hospital, located in the Texas Medical Center, is the flagship hospital of Houston Methodist. With over 900 beds, 8,400 employees, and six Centers of Excellence, we offer a full spectrum of care including specialty physician offices, imaging and labs, and teams of experts using the newest technologies. For 100 years, Houston Methodist has provided the best clinical care, advanced technology and patient experience — that is our promise of leading medicine. Houston Methodist Hospital is ranked among the country''s top hospitals in 10 specialties in U.S. News & World Report''s 2025-2026 America''s \"Best Hospitals\" issue and again named the No. 1 hospital in Texas.", "appointment_url": "https://www.houstonmethodist.org/get-care-now/", "google_maps_url": "https://maps.google.com/?cid=14993415476628073483&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJVVXFMHHAQIYRC6xC_u9PE9A", "important_links": [{"url": "https://www.houstonmethodist.org/find-a-doctor/", "text": "Find a Doctor"}, {"url": "https://www.houstonmethodist.org/contact-us/", "text": "Contact Us"}, {"url": "https://www.houstonmethodist.org/cms-hpt.txt", "text": "Pricing Transparency"}, {"url": "https://www.houstonmethodist.org/find-a-doctor/", "text": "Schedule a Doctor''s Appointment"}, {"url": "https://www.houstonmethodist.org/mammogram/screening/scheduling/", "text": "Schedule a Mammogram"}, {"url": "https://www.houstonmethodist.org/imaging-orders/", "text": "Schedule an Imaging Appointment"}, {"url": "https://www.houstonmethodist.org/orthopedics/locations/orthopedic-injury-clinics/", "text": "Visit a Same Day Orthopedic Clinic"}, {"url": "https://www.houstonmethodist.org/find-a-doctor/", "text": "Provider Directory"}, {"url": "https://www.houstonmethodist.org/for-patients/patient-resources/insurance/", "text": "Insurance"}, {"url": "https://www.houstonmethodist.org/for-patients/guest-services/egreeting-cards/", "text": "eGreeting Cards"}, {"url": "https://www.houstonmethodist.org/orthopedics/locations/orthopedic-injury-clinics/", "text": "Same Day Orthopedic Clinics"}, {"url": "https://www.houstonmethodist.org/spg/", "text": "Specialty Physician Group"}, {"url": "https://www.houstonmethodist.org/medical-services/", "text": "All Services & Specialties"}, {"url": "https://www.houstonmethodist.org/heart-vascular/prevention/heart-scan-packages/", "text": "Heart Scan Services"}, {"url": "https://www.houstonmethodist.org/spine/schedule/", "text": "Same Day Spine Care"}, {"url": "https://www.houstonmethodist.org/locations/emergency-care-centers/", "text": "Emergency Care"}, {"url": "https://www.houstonmethodist.org/for-health-professionals/global-health-care-services/", "text": "Global Health Care Services"}, {"url": "https://www.houstonmethodist.org/locations/hospitals/", "text": "Hospitals"}, {"url": "https://www.houstonmethodist.org/locations/breast-care-center/", "text": "Breast Care Centers"}, {"url": "https://www.houstonmethodist.org/international-locations/", "text": "International Locations"}, {"url": "https://www.houstonmethodist.org/locations/", "text": "See All Locations"}, {"url": "https://www.houstonmethodist.org/locations/", "text": "Convenient Locations Across the Greater Houston Area Find a location for you and your family near work or home"}, {"url": "https://www.houstonmethodist.org/locations/", "text": "Locations"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/", "text": "Houston Methodist Hospital"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/services/", "text": "Services at Houston Methodist Hospital"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/for-patients/", "text": "Patient & Visitor Resources at Houston Methodist Hospital"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/about/", "text": "About Houston Methodist Hospital"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/for-patients/parking/", "text": "Parking"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/about/", "text": "Learn more about us"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/nursing-contributions/", "text": "Professional Contributions of Nursing at Houston Methodist Hospital >"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/for-patients/insurances-accepted/", "text": "Insurance"}, {"url": "https://www.houstonmethodist.org/locations/the-woodlands/patient-visitor-resources/insurance-information/", "text": ""}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/for-patients/insurance-information/billing/", "text": "Billing – other service providers"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/for-patients/", "text": "patient & visitor resources"}, {"url": "https://www.houstonmethodist.org/locations/texas-medical-center/patient-guide/", "text": "Patient Guide"}, {"url": "https://www.houstonmethodist.org/-/media/pdf/locatio