INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('9c28752f-7873-4cd4-8bce-88a1b7ef186e', NULL, 'First Hill Dental Center - Dr. Singh DMD', 'First Hill Dental Center is your neighborhood clinic in Seattle, providing exceptional oral health care in a stress-free environment. Led by Dr. Singh DMD, our team practices with compassion, trust, and clinical excellence.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('b8461fbb-5749-4db0-befc-936b12619494', NULL, 'K&T Dental', 'K&T Dental is a modern dental practice in San Jose, California, led by Dr. Thinh Tran, D.D.S., and supported by an experienced endodontist. The clinic provides comprehensive general and specialty dentistry in a new facility equipped with the latest technology. Their services include dental implants, crowns, root canals, clear braces, veneers, and preventative care, with a focus on personalized, minimally invasive treatment. The team is dedicated to offering quality care in a comfortable setting, placing and restoring dental implants in-house and providing root canal therapy by a specialist. They also offer a crown warranty and emphasize individualized dental plans.', '919 Story Rd #1128, San Jose, CA 95122', 'San Jose', 'CA', '95122', '(408)-816-7912', ARRAY['English', 'Vietnamese']::text[], 'Dental', FALSE, '{"email": "ktdentalsanjose@gmail.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kt-dental-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kt-dental-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kt-dental-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kt-dental-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kt-dental-google-5.webp"], "rating": 5, "reviews": [{"date": "2026-02-13T22:30:36.531048147Z", "text": "I have been a patient at K&T Dental, San Jose for three years. Although I live in Santa Cruz, I choose Dr. Thinh Tran DDS as my dentist because he provides excellent service and takes great care of my teeth. The customer service team is very friendly and helpful. They are proactive in contacting me to schedule appointments and follow up on my dental care.", "author": "Tran Thuan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109104299671800424737/reviews"}, {"date": "2025-09-12T19:12:44.437155796Z", "text": "Dr. Tran is an excellent dentist! He’s very thorough and takes the time to explain why treatment is needed. As a dental student, I really appreciated it because it was a learning opportunity for me too! Throughout the appointment, he constantly checked in to make sure I was comfortable and was gentle the entire time. He also worked efficiently & I was surprised by how quick the appointment was without feeling rushed.\n\nI can get nervous at the dentist, but I felt at ease with Dr. Tran. Having been to several dentists in the past, I can honestly say I trust him fully and 100% recommend him!", "author": "Jena Aivy Tran", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115597015208606067091/reviews"}, {"date": "2025-03-27T00:22:49.268422Z", "text": "My family switched to Dr. Thinh Tran about a year ago and the experience has been great. Dr. Tran is very gentle and does an excellent job on cleaning and explaining things to you. Staff is all very nice and Kim is also very good at explaining insurance and ways to save money. They also offer warranties for dental implants and crown. Highly recommend this office!", "author": "Janet V", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103050286407271747943/reviews"}, {"date": "2025-03-21T21:40:39.363316Z", "text": "All my dental work with Dr. Thinh has been great. He''s patient,  always takes the time to explain the process, and answers any question I had. Additionally, the office is nice and clean. The front desk, Miss Kim, is also kind and awesome. 100% would recommend :)", "author": "My-Ngoc Nguyen", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101054816592397281374/reviews"}, {"date": "2025-03-21T16:45:54.317826Z", "text": "Dr. Tran is an excellent dentist, and we highly recommend him! He gives thorough cleanings and examinations. We’ve been seeing him for over three years now, and the trust we''ve built has only grown stronger. Finding a trustworthy dentist wasn’t easy, but Dr. Tran delivers consistently.\n\nThe staff is also very nice, especially the receptionist at the front desk, who is always very welcoming and helpful!", "author": "Robin Cristobal", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104653390947012044581/reviews"}], "website": "https://ktdentalsanjose.com/", "location": {"latitude": 37.3312549, "longitude": -121.85836909999999}, "services": ["Dental Implants", "Crowns", "Root Canals", "Clear Braces", "Veneers", "Preventative", "Emergency Dental Care", "Cosmetic Dentistry"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "General Dentist and Endodontist", "detail": "The clinic has both a general dentist and a root canal specialist on staff, allowing for comprehensive care including root canal therapy and retreatment.", "category": "care"}, {"title": "Dental Implants In-House", "detail": "We place and restore dental implants completely in-house, offering a seamless solution for missing teeth.", "category": "care"}, {"title": "Crown Warranty", "detail": "We guarantee our crown restorations with a warranty, ensuring long-lasting, functional results.", "category": "care"}, {"title": "Latest Technology", "detail": "We use the latest dental technology and research to make your visits as comfortable and efficient as possible.", "category": "technology"}, {"title": "Individualized Care", "detail": "Our mission is to provide personalized dental care without a one-size-fits-all approach.", "category": "care"}], "price_tier": "$$", "source_url": "https://ktdentalsanjose.com/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese dentist in California", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | dental implants | root canals | clear braces | preventative | emergency dental care | cosmetic dentistry | restorative | endodontic | orthodontic | cosmetic | preventive | emergency | thinh tran | d.d.s. (doctor of dental surgery) | unnamed endodontist | endodontist", "google_types": ["dentist", "dental_clinic", "medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 109, "team_members": [{"name": "Thinh Tran", "role": "D.D.S. (Doctor of Dental Surgery)", "bio_snippet": "Lead dentist at K&T Dental.", "languages_spoken": []}, {"name": "Unnamed Endodontist", "role": "Endodontist", "bio_snippet": "Root canal specialist performing root canal therapy and retreatment.", "languages_spoken": []}], "open_saturday": true, "quality_score": 93, "working_hours": {"friday": "9:00 AM – 6:00 PM", "monday": "Closed", "sunday": "Closed", "tuesday": "9:00 AM – 6:00 PM", "saturday": "9:00 AM – 1:00 PM", "thursday": "9:00 AM – 6:00 PM", "wednesday": "9:00 AM – 6:00 PM"}, "gallery_images": ["https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/frontDesk-8L7A2441-good%20(1).jpeg/:/cr=t:0%25,l:0%25,w:100%25,h:100%25", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/waitArea-8L7A2432-good.jpg/:/rs=w:370,cg:true,m", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/hallwayWhole-8L7A2443-good.jpeg/:/cr=t:0%25,l:0%25,w:100%25,h:100%25/rs=w:370,cg:true", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/Thinh-Portrait-IMG_2178-BEST.jpg/:/rs=w:370,cg:true,m", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/hallwayWhole-IMG_2114-good.jpeg/:/rs=w:370,cg:true,m", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/KTPortrait-IMG_2148-good.jpeg/:/rs=w:370,cg:true,m", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/waitArea-IMG_2111-good-0001.jpg/:/rs=w:370,cg:true,m", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/ThinhWorking-IMG_2196-good-0001.jpeg/:/cr=t:0%25,l:0%25,w:100%25,h:100%25/rs=w:370,cg:true", "https://img1.wsimg.com/isteam/ip/fc98210c-696f-4dfe-a899-2a2a5e670e8a/equipment-8L7A2419-good.jpeg/:/cr=t:0%25,l:0%25,w:100%25,h:100%25/rs=w:370,cg:true"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Clear explanations", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight clear explanations in their feedback."}, {"theme": "Comfortable visits", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight comfortable visits in their feedback."}], "summary": "K&T Dental has a 5.0 star Google rating from 109 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "review_count": 109, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-02-13T22:30:36.531048147Z", "text": "I have been a patient at K&T Dental, San Jose for three years. Although I live in Santa Cruz, I choose Dr. Thinh Tran DDS as my dentist because he provides excellent service and takes great care of my teeth. The customer service team is very friendly and helpful. They are proactive in contacting me to schedule appointments and follow up on my dental care.", "author": "Tran Thuan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109104299671800424737/reviews"}, {"date": "2025-09-12T19:12:44.437155796Z", "text": "Dr. Tran is an excellent dentist! He’s very thorough and takes the time to explain why treatment is needed. As a dental student, I really appreciated it because it was a learning opportunity for me too! Throughout the appointment, he constantly checked in to make sure I was comfortable and was gentle the entire time. He also worked efficiently & I was surprised by how quick the appointment was without feeling rushed.\n\nI can get nervous at the dentist, but I felt at ease with Dr. Tran. Having been to several dentists in the past, I can honestly say I trust him fully and 100% recommend him!", "author": "Jena Aivy Tran", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115597015208606067091/reviews"}, {"date": "2025-03-27T00:22:49.268422Z", "text": "My family switched to Dr. Thinh Tran about a year ago and the experience has been great. Dr. Tran is very gentle and does an excellent job on cleaning and explaining things to you. Staff is all very nice and Kim is also very good at explaining insurance and ways to save money. They also offer warranties for dental implants and crown. Highly recommend this office!", "author": "Janet V", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103050286407271747943/reviews"}, {"date": "2025-03-21T21:40:39.363316Z", "text": "All my dental work with Dr. Thinh has been great. He''s patient,  always takes the time to explain the process, and answers any question I had. Additionally, the office is nice and clean. The front desk, Miss Kim, is also kind and awesome. 100% would recommend :)", "author": "My-Ngoc Nguyen", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101054816592397281374/reviews"}, {"date": "2025-03-21T16:45:54.317826Z", "text": "Dr. Tran is an excellent dentist, and we highly recommend him! He gives thorough cleanings and examinations. We’ve been seeing him for over three years now, and the trust we''ve built has only grown stronger. Finding a trustworthy dentist wasn’t easy, but Dr. Tran delivers consistently.\n\nThe staff is also very nice, especially the receptionist at the front desk, who is always very welcoming and helpful!", "author": "Robin Cristobal", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104653390947012044581/reviews"}]}, "review_summary": "K&T Dental has a 5.0 star Google rating from 109 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "about_highlight": "K&T Dental is a modern dental practice in San Jose, California, led by Dr. Thinh Tran, D.D.S., and supported by an experienced endodontist. The clinic provides comprehensive general and specialty dentistry in a new facility equipped with the latest technology. Their services include dental implants, crowns, root canals, clear braces, veneers, and preventative care, with a focus on personalized, minimally invasive treatment. The team is dedicated to offering quality care in a comfortable setting, placing and restoring dental implants in-house and providing root canal therapy by a specialist. They also offer a crown warranty and emphasize individualized dental plans.", "google_maps_url": "https://maps.google.com/?cid=18190349424390041173&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJo3193GHNj4ARVe7_xGwacfw", "quality_missing": ["insurance", "appointment_url"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "dental implants", "root canals", "clear braces", "preventative", "emergency dental care", "cosmetic dentistry", "restorative", "endodontic", "orthodontic", "cosmetic", "preventive", "emergency", "thinh tran", "d.d.s. (doctor of dental surgery)", "unnamed endodontist", "endodontist"], "services_offered": [{"name": "Dental Implants", "category": "Restorative", "description": "We place and restore dental implants completely in-house. Contact us to see if dental implants may be a good option for you.", "is_featured": true, "patient_fit": "Patients with missing teeth"}, {"name": "Crowns", "category": "Restorative", "description": "We are proud to deliver quality, long-lasting, and functional crown restorations. In fact, it''s guaranteed! Please ask about our crown warranty.", "is_featured": false, "patient_fit": null}, {"name": "Root Canals", "category": "Endodontic", "description": "We have root canal specialists. Our endodontist specializing in root canal therapy, Root Canal Treatment and Root Canal Retreatment. A majority of dental pain originate from an infected or a degenerated tooth. Root canal treatment removes the infection and prevents the tooth from being extracted.", "is_featured": false, "patient_fit": "Patients with infected or degenerated teeth causing dental pain"}, {"name": "Clear Braces", "category": "Orthodontic", "description": "A proper bite and straight teeth are a strong foundation for oral health and prevents wear of the teeth due to grinding. Clear braces offers a simple and flexible solution.", "is_featured": false, "patient_fit": "Patients seeking teeth straightening"}, {"name": "Veneers", "category": "Cosmetic", "description": "Considering that nice bright smile that would make you confident to smile? We can help you achieve your dream smile.", "is_featured": false, "patient_fit": "Patients desiring a brighter, more uniform smile"}, {"name": "Preventative", "category": "Preventive", "description": "As they say, prevention is better than treatment. We want to see our patients undergo as little treatment as possible with minimally invasive dentistry.", "is_featured": false, "patient_fit": "All patients"}, {"name": "Emergency Dental Care", "category": "Emergency", "description": "Emergency dental care available.", "is_featured": true, "patient_fit": "Patients with dental emergencies"}, {"name": "Cosmetic Dentistry", "category": "Cosmetic", "description": "Whether you need cosmetic dentistry, you will be in great hands.", "is_featured": false, "patient_fit": null}], "short_description": "K&T Dental is a modern dental practice in San Jose offering general dentistry, endodontic care, and cosmetic services with a focus on personalized, technology-driven treatment.", "google_website_url": "https://ktdentalsanjose.com/", "google_primary_type": "Dentist", "provider_credentials": {"education": [], "providers": ["Thinh Tran", "Unnamed Endodontist"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "919 Story Rd #1128, San Jose, CA 95122, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/111624469898933226157", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjW8JbkIkY6g2TKq5by79BzS0CIiz58rTuVY-XGc3tsKHSDUFpc=s100-p-k-no-mo", "displayName": "K&T Dental"}], [{"uri": "https://maps.google.com/maps/contrib/111624469898933226157", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjW8JbkIkY6g2TKq5by79BzS0CIiz58rTuVY-XGc3tsKHSDUFpc=s100-p-k-no-mo", "displayName": "K&T Dental"}], [{"uri": "https://maps.google.com/maps/contrib/106376655468137145820", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVie1DKre60tV1cDfs7n1JugQf0HqXGYVDLTQNOAY-WN9RHsjU6aA=s100-p-k-no-mo", "displayName": "Hải Cao Minh"}], [{"uri": "https://maps.google.com/maps/contrib/109104299671800424737", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXSxJlLByPDQw_PGnhyA-2r06QVBRSUssxCrpiyMq2Z_afsiSyc-g=s100-p-k-no-mo", "displayName": "Tran Thuan"}], [{"uri": "https://maps.google.com/maps/contrib/116768020794103700348", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocJRxS4zofTltGP0vFx7T2aKwPyTcfQ6Fm0R6IE9zufTB2wrWg=s100-p-k-no-mo", "displayName": "KT N"}]]}'::jsonb, '2026-06-25T19:15:22.812279+00:00', 'kt-dental', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('4b27c72c-94c7-4203-8470-f5c6013766a9', NULL, 'Floss & Gloss Dental', 'Floss & Gloss Dental, located in Garden Grove, CA, is led by Dr. Thuy Nguyen, who was born and raised in the community. The practice is dedicated to providing quality dental care with an emphasis on patient education and comfort. Services include comprehensive exams, oral hygiene maintenance, root canal therapy, veneers and bonding, crowns and bridges, and more. Patients describe the experience as pain-free and drama-free, helping them achieve an amazing smile.', '10542 McFadden Ave', 'Garden Grove', 'CA', '92843', '714-531-4531', ARRAY['English', 'Vietnamese']::text[], 'Dental', FALSE, '{"fax": "714-531-4533", "email": "contact@flossandgloss.net", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/floss-gloss-dental-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/floss-gloss-dental-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/floss-gloss-dental-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/floss-gloss-dental-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/floss-gloss-dental-google-5.webp"], "rating": 5, "reviews": [{"date": "2019-02-04T00:13:30.964435856Z", "text": "I was experiencing excruciating pain because I needed a root canal done since a year ago. I never got it done because it was $1000+ for one tooth. I was desperate and only had so much money to pay for it on a Sunday. I called this office and they made an appointment for me and made it affordable as well. I used to hate dentists because of how expensive and heartless they can be. I''ve struggled with my finances so it means a lot to have affordable treatment, especially when I was in so much pain. Not to mention the front desk, assistant and the dentist were very kind and accommodating. They made many efforts to make sure I was not in too much pain and that I was able to relax. They played a movie for me while it getting my root canal done.", "author": "Coral Braccini", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110853684128957658521/reviews"}, {"date": "2020-01-17T17:13:30.972665Z", "text": "It is always disconcerting to select a new dentist, but after persistent and drastic price increases for all services over the years, I got tired of having to pay for the overhead at my Newport Beach dental office.\nI selected Dr. Thuy Nguyen mainly on the basis of Yelp reviews, and because she has the same first name as one of my best friends: not very sophisticated, but: I got lucky!\nThe first impression: modern and clean office, professional and friendly reception, appointment on time.\nI needed a crown replaced, and in the process some decay was discovered underneath my old/damaged crown. Dr. Thuy remedied that problem, and my temp was perfect, as was my new crown two weeks later.\nI have nothing bad to say about my previous dentist, and I realize this is a very subjective feeling, but: I felt I was in better hands than before, and I will definitely stay with this office.", "author": "Andreas Raffel", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116910722157131458503/reviews"}, {"date": "2025-02-07T22:57:45.868837Z", "text": "I would never say that I enjoy going to the dentist.;-)  If you''re looking for one, I would recommend Floss & Gloss Dental for 100% . They make you feel comfortable, they are professional and they treat you like you''re their family :-) Thank you for everything ;-)", "author": "si wo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105242162534529514606/reviews"}, {"date": "2020-05-22T05:22:46.011434Z", "text": "I have had a problem with my teeth long time and i don''t trust any doctor, because they don''t care about ones feelings (pain problems) . I searched several places until came up with Floss & Gloss Dental, still afraid but needed to be done ,  my first impression was stunning when entering the place it was very clean , neat, and very warm hearted receptionist helpful on all your questions , the doctor is a professional person who knows what is she doing, and explains carefully each process that it takes . She won''t leave you alone she focus on one patient at a time professionalism it''s all about.  Friendly customer service and reliable. All i can say thank you doc. This is my first time here i''ll be back  for sure... strongly recomended..", "author": "garmatz mtz", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114230897576899978246/reviews"}, {"date": "2019-09-16T22:03:31.614807Z", "text": "I got referred to Dr. Thuy from my stepdad a few years back. Best experience with anything healthcare related. Very impeccably clean office.You always have her full attention, in part because she doesn’t run her office like an assembly line, so no extended waits. She works on one client at a time, so most likely, you will be the only patient there unless she is finishing up on a client before you.Both Dr. Thuy and Lee are very personable, and for me at least, make me feel like I am just catching up with good friends.\n\nUnlike many other dentists out there, I don’t feel like she just sees dollar signs when viewing me. She is very open about information and answering questions. You never feel rushed into making a decision. I always feel like we’re on the same team when we discuss my prognosis and the best options for both my health and pocketbook.  Very jovial atmosphere. I always feel relaxed there and when leaving. Thanks Dr.Thuy and Lee!!", "author": "Jeff", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101422803924375756769/reviews"}], "website": "http://www.flossandgloss.net/", "location": {"latitude": 33.7376288, "longitude": -117.9451824}, "services": ["Comprehensive Exam", "Oral Hygiene Maintenance", "Root Canal Therapy", "Veneers and Bonding", "Crowns and Bridges"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Comprehensive Dental Services", "detail": "Offers exams, cleanings, root canals, veneers, crowns, bridges, and more.", "category": "care"}, {"title": "Local Experienced Dentist", "detail": "Dr. Thuy Nguyen is born and raised in Garden Grove, serving her community.", "category": "care"}, {"title": "Pain-Free Care", "detail": "Patients describe the experience as pain-free and drama-free.", "category": "reviews"}], "price_tier": "$$", "source_url": "http://www.flossandgloss.net/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese dentist in California", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | comprehensive exam | oral hygiene maintenance | root canal therapy | veneers and bonding | crowns and bridges | dr. thuy nguyen", "google_types": ["dentist", "dental_clinic", "doctor", "medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 16, "team_members": [{"name": "Dr. Thuy Nguyen", "role": "Dentist", "bio_snippet": "Dr. Nguyen was born and raised in Garden Grove, CA and continues to serve her surrounding community to provide quality care, prides herself in educating patients on oral hygiene and making patients feel at ease at every visit.", "languages_spoken": []}], "open_saturday": false, "quality_score": 93, "working_hours": {"friday": "9:00 AM – 5:00 PM", "monday": "9:00 AM – 5:00 PM", "sunday": "9:00 AM – 3:00 PM", "tuesday": "9:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "9:00 AM – 5:00 PM", "wednesday": "Closed"}, "gallery_images": ["https://static.wixstatic.com/media/ba54e6ca7dda42486659cfb31ed219ee.jpg/v1/fill/w_141,h_141,al_c,q_80,blur_3,enc_avif,quality_auto/ba54e6ca7dda42486659cfb31ed219ee.jpg", "https://static.wixstatic.com/media/7e94950769fd4a8786ed7d29e7c3478b.jpg/v1/fill/w_147,h_147,al_c,q_80,usm_0.66_1.00_0.01,blur_2,enc_avif,quality_auto/7e94950769fd4a8786ed7d29e7c3478b.jpg", "https://static.wixstatic.com/media/a9e3b121fbae579029bad4619a3000df.jpg/v1/fill/w_136,h_144,al_c,q_80,usm_0.66_1.00_0.01,blur_2,enc_avif,quality_auto/a9e3b121fbae579029bad4619a3000df.jpg", "https://static.wixstatic.com/media/34d8a95205665efcd696d7328fcc8dd1.jpg/v1/fill/w_147,h_145,al_c,q_80,usm_0.66_1.00_0.01,blur_2,enc_avif,quality_auto/34d8a95205665efcd696d7328fcc8dd1.jpg", "https://static.wixstatic.com/media/53e96a4964c1fd93a87306e1e6da14b5.jpg/v1/fill/w_154,h_230,al_c,q_80,usm_0.66_1.00_0.01,blur_2,enc_avif,quality_auto/53e96a4964c1fd93a87306e1e6da14b5.jpg"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Clear explanations", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight clear explanations in their feedback."}, {"theme": "Comfortable visits", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight comfortable visits in their feedback."}], "summary": "Floss & Gloss Dental has a 5.0 star Google rating from 16 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "review_count": 16, "concern_themes": [], "positive_themes": ["pain-free", "amazing smile"], "featured_reviews": [{"date": "2019-02-04T00:13:30.964435856Z", "text": "I was experiencing excruciating pain because I needed a root canal done since a year ago. I never got it done because it was $1000+ for one tooth. I was desperate and only had so much money to pay for it on a Sunday. I called this office and they made an appointment for me and made it affordable as well. I used to hate dentists because of how expensive and heartless they can be. I''ve struggled with my finances so it means a lot to have affordable treatment, especially when I was in so much pain. Not to mention the front desk, assistant and the dentist were very kind and accommodating. They made many efforts to make sure I was not in too much pain and that I was able to relax. They played a movie for me while it getting my root canal done.", "author": "Coral Braccini", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110853684128957658521/reviews"}, {"date": "2020-01-17T17:13:30.972665Z", "text": "It is always disconcerting to select a new dentist, but after persistent and drastic price increases for all services over the years, I got tired of having to pay for the overhead at my Newport Beach dental office.\nI selected Dr. Thuy Nguyen mainly on the basis of Yelp reviews, and because she has the same first name as one of my best friends: not very sophisticated, but: I got lucky!\nThe first impression: modern and clean office, professional and friendly reception, appointment on time.\nI needed a crown replaced, and in the process some decay was discovered underneath my old/damaged crown. Dr. Thuy remedied that problem, and my temp was perfect, as was my new crown two weeks later.\nI have nothing bad to say about my previous dentist, and I realize this is a very subjective feeling, but: I felt I was in better hands than before, and I will definitely stay with this office.", "author": "Andreas Raffel", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116910722157131458503/reviews"}, {"date": "2025-02-07T22:57:45.868837Z", "text": "I would never say that I enjoy going to the dentist.;-)  If you''re looking for one, I would recommend Floss & Gloss Dental for 100% . They make you feel comfortable, they are professional and they treat you like you''re their family :-) Thank you for everything ;-)", "author": "si wo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105242162534529514606/reviews"}, {"date": "2020-05-22T05:22:46.011434Z", "text": "I have had a problem with my teeth long time and i don''t trust any doctor, because they don''t care about ones feelings (pain problems) . I searched several places until came up with Floss & Gloss Dental, still afraid but needed to be done ,  my first impression was stunning when entering the place it was very clean , neat, and very warm hearted receptionist helpful on all your questions , the doctor is a professional person who knows what is she doing, and explains carefully each process that it takes . She won''t leave you alone she focus on one patient at a time professionalism it''s all about.  Friendly customer service and reliable. All i can say thank you doc. This is my first time here i''ll be back  for sure... strongly recomended..", "author": "garmatz mtz", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114230897576899978246/reviews"}, {"date": "2019-09-16T22:03:31.614807Z", "text": "I got referred to Dr. Thuy from my stepdad a few years back. Best experience with anything healthcare related. Very impeccably clean office.You always have her full attention, in part because she doesn’t run her office like an assembly line, so no extended waits. She works on one client at a time, so most likely, you will be the only patient there unless she is finishing up on a client before you.Both Dr. Thuy and Lee are very personable, and for me at least, make me feel like I am just catching up with good friends.\n\nUnlike many other dentists out there, I don’t feel like she just sees dollar signs when viewing me. She is very open about information and answering questions. You never feel rushed into making a decision. I always feel like we’re on the same team when we discuss my prognosis and the best options for both my health and pocketbook.  Very jovial atmosphere. I always feel relaxed there and when leaving. Thanks Dr.Thuy and Lee!!", "author": "Jeff", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101422803924375756769/reviews"}]}, "review_summary": "Floss & Gloss Dental has a 5.0 star Google rating from 16 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "about_highlight": "Floss & Gloss Dental, located in Garden Grove, CA, is led by Dr. Thuy Nguyen, who was born and raised in the community. The practice is dedicated to providing quality dental care with an emphasis on patient education and comfort. Services include comprehensive exams, oral hygiene maintenance, root canal therapy, veneers and bonding, crowns and bridges, and more. Patients describe the experience as pain-free and drama-free, helping them achieve an amazing smile.", "google_maps_url": "https://maps.google.com/?cid=14585520555648215608&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJEePEApkn3YAROOqR_6otaso", "quality_missing": ["insurance", "appointment_url"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "comprehensive exam", "oral hygiene maintenance", "root canal therapy", "veneers and bonding", "crowns and bridges", "dr. thuy nguyen"], "services_offered": [{"name": "Comprehensive Exam", "category": "Dental", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Oral Hygiene Maintenance", "category": "Dental", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Root Canal Therapy", "category": "Dental", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Veneers and Bonding", "category": "Dental", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Crowns and Bridges", "category": "Dental", "description": null, "is_featured": false, "patient_fit": null}], "short_description": "Floss & Gloss Dental offers comprehensive dental care in Garden Grove, CA, led by Dr. Thuy Nguyen. We pride ourselves on providing pain-free, quality care to help you achieve your most amazing smile.", "google_website_url": "http://www.flossandgloss.net/", "google_primary_type": "Dentist", "provider_credentials": {"education": [], "providers": ["Dr. Thuy Nguyen"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "10542 W McFadden Ave, Garden Grove, CA 92843, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/116248765460330027257", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjV2fh3fbmXyrSYFWN8WmVPRHayOed4-2orZU3XY7K8YmUPklhs=s100-p-k-no-mo", "displayName": "Floss & Gloss Dental | Best Dentist in Garden Grove CA"}], [{"uri": "https://maps.google.com/maps/contrib/116248765460330027257", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjV2fh3fbmXyrSYFWN8WmVPRHayOed4-2orZU3XY7K8YmUPklhs=s100-p-k-no-mo", "displayName": "Floss & Gloss Dental | Best Dentist in Garden Grove CA"}], [{"uri": "https://maps.google.com/maps/contrib/116248765460330027257", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjV2fh3fbmXyrSYFWN8WmVPRHayOed4-2orZU3XY7K8YmUPklhs=s100-p-k-no-mo", "displayName": "Floss & Gloss Dental | Best Dentist in Garden Grove CA"}], [{"uri": "https://maps.google.com/maps/contrib/116248765460330027257", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjV2fh3fbmXyrSYFWN8WmVPRHayOed4-2orZU3XY7K8YmUPklhs=s100-p-k-no-mo", "displayName": "Floss & Gloss Dental | Best Dentist in Garden Grove CA"}], [{"uri": "https://maps.google.com/maps/contrib/116248765460330027257", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjV2fh3fbmXyrSYFWN8WmVPRHayOed4-2orZU3XY7K8YmUPklhs=s100-p-k-no-mo", "displayName": "Floss & Gloss Dental | Best Dentist in Garden Grove CA"}]]}'::jsonb, '2026-06-25T19:16:21.789883+00:00', 'floss-gloss-dental', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('19de1d00-eede-4335-8d80-391c5bceaaad', NULL, 'Smile Again Dental Center', 'Smile Again Dental Center in Westminster, CA is dedicated to exceeding expectations with compassionate, comprehensive dental care. We are the only dental office in the area with an on-site digital lab over 5,000 sq. ft., making your visit more convenient and time efficient. We believe in creating affordable, yet star-quality smiles using skilled cosmetic dentistry, master digital in-house lab, and advanced sedation and implant dentistry. Our team is committed to providing the highest standard of care, from preventive general dentistry to complex restorative procedures, all tailored to your individual needs.', '14501 Magnolia St #107, Westminster, CA 92683', 'Westminster', 'CA', '92683', '714-248-9883', ARRAY['English', 'Vietnamese']::text[], 'Dental', FALSE, '{"fax": "714-248-9774", "email": "smileagaindentalcenter.sa@gmail.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/smile-again-dental-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/smile-again-dental-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/smile-again-dental-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/smile-again-dental-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/smile-again-dental-center-google-5.webp"], "rating": 4.6, "reviews": [{"date": "2026-01-14T01:09:47.295611213Z", "text": "My first time here at Smile Again Dental.  The office is so modern, new and clean. The staff and dentist Tuyet Nguyen is so kind and explain the whole treatment. I got teeth cleaning and my lower anterior chip so Dr. Tuyet done composite filling the same day. Her work was done beautifully. I will recommend all of my family and friend to this dental office. Thank you Smile Again Dental.", "author": "James Tran", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109171983486068716539/reviews"}, {"date": "2025-04-26T18:21:55.333034Z", "text": "Finding Smile Again Dental Center has truly been a blessing for my entire family! From the moment you walk in, you can immediately tell how much pride they take in their practice. The office is spotless, beautifully designed, and feels welcoming and comfortable.\n\nThe customer service here is absolutely outstanding. Everyone, from the front desk staff to the dental assistants and doctors, is friendly, attentive, and genuinely cares about making sure you have a great experience. They pay incredible attention to detail, which is something you don’t always find at other places.\n\nWe originally came to Smile Again Dental Center because my mom had gotten a dental implant done at another office and was experiencing a lot of pain and discomfort when eating. It was heartbreaking seeing her struggle. Thankfully, the doctor at Smile Again Dental took the time to properly assess the situation, explained everything to us clearly, and fixed the problem with so much care and expertise. Now, she’s finally able to eat comfortably again without any pain, something we are beyond grateful for!\n\nAnother thing I love about this office is that they offer a full range of services, and everything is done in-house, which makes the whole process so much quicker and more convenient. No need to bounce around from office to office for different procedures, they handle it all right there.\n\nOn top of everything, the quality of care you get for the price is truly amazing. You can tell they don’t cut corners, but they also don’t overcharge like a lot of places do.\n\nI’m so thankful we found Smile Again Dental Center, it’s now our go-to dental office for the whole family! If you’re looking for a dental team that truly cares and delivers top-notch results, this is the place to go! :)", "author": "Annie Ta", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101018980263649197639/reviews"}, {"date": "2026-04-02T21:29:35.675125296Z", "text": "Amazing place & Staff!!! I have never seen such a prepositional and beautiful establishment. The best dental work I have ever experienced. Extremely grateful for this Absolute Gem!!! Quick appointments, fast, always early, a the best dental work possible. Extremely low rates!!! Would highly recommend any friends of family to this establishment at any time!!!!", "author": "Jack Lukk", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108308730892074975924/reviews"}, {"date": "2026-03-28T20:31:18.070368184Z", "text": "Excellent doctors here. Dr. John Ngo handled my extractions, and I was very impressed with his professionalism. He made the whole experience much easier for me, and thanks to him I am not afraid of the dentist anymore. He is my favorite doctor!!", "author": "Skyla Horn", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/118285449054478394345/reviews"}, {"date": "2025-08-23T19:31:42.836154733Z", "text": "I’m honestly blown away by how smooth my visit was. Checking in as a new patient took no time at all, and I loved that everything was electronic… no stacks of paper to fill out.\n\nThe cleaning was amazing too. At other places I’ve been, it always felt a little rough, but here it was gentle and I actually walked out happy. I didn’t have any cavities, but I did ask about bonding a small spot on one tooth for cosmetic reasons. They were super accommodating and it turned out amazing.\n\nFriendly staff, simple process, and a visit that left me smiling. I’m really glad I chose this place!", "author": "Daniel Ngo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104390873259237264606/reviews"}], "website": "http://smileagaindentalcenter.com/", "location": {"latitude": 33.751613299999995, "longitude": -117.97298509999999}, "services": ["General Dental Care", "Laser Dentistry", "Dental Implants", "Cosmetic Dentistry", "All-On-4 Implants", "Tooth Extractions and Root Canals", "Dentures and Partials"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "On-Site Digital Lab", "detail": "We are the only dental office with an on-site digital lab over 5,000 sq. ft., making your visit more convenient and time efficient.", "category": "technology"}, {"title": "Laser Dentistry", "detail": "Our laser technologies treat tooth decay, gum disease, and infections with reduced discomfort and smoother recovery.", "category": "technology"}, {"title": "Comprehensive Dental Care", "detail": "We offer general, cosmetic, implant, and sedation dentistry, with 3D CT scans for precise treatment planning.", "category": "care"}, {"title": "Affordable Star-Quality Smiles", "detail": "We believe in creating affordable yet high-quality smiles using skilled cosmetic dentistry and our in-house lab.", "category": "value"}], "price_tier": "$$", "source_url": "http://smileagaindentalcenter.com/", "appointment": {"booking_note": "Call us to schedule an appointment, or send us an email and we''ll get back to you as soon as possible.", "appointment_url": "https://patient.rocks/Dashboard/PatientDashboard/NmExMjRjN2QtMzY1ZC00NDgyLWE0ZjItODc3ZDIz", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese dentist in California", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | general dental care | laser dentistry | dental implants | cosmetic dentistry | all-on-4 implants | tooth extractions and root canals | dentures and partials | general dentistry", "google_types": ["dental_clinic", "dentist", "medical_clinic", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 130, "open_saturday": true, "quality_score": 92, "working_hours": {"friday": "9:00 AM – 6:00 PM", "monday": "9:00 AM – 6:00 PM", "sunday": "Closed", "tuesday": "9:00 AM – 6:00 PM", "saturday": "9:00 AM – 4:30 PM", "thursday": "9:00 AM – 6:00 PM", "wednesday": "9:00 AM – 6:00 PM"}, "gallery_images": ["https://static.wixstatic.com/media/6ff1cc_cb15b0905df94f87be2b5dca0b6cc95f~mv2.jpg", "https://static.wixstatic.com/media/6ff1cc_4f6c1b68b4c84bec9dc74690fceefe1d~mv2.jpg"], "review_profile": {"rating": 4.6, "source": "google", "themes": [{"theme": "Facility Environment", "mentions": 3, "sentiment": "Positive", "summary_quote": "Multiple reviewers describe the office as modern, clean, and beautifully designed, creating a welcoming atmosphere."}, {"theme": "Staff Professionalism", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers consistently mention the friendly, attentive, and professional staff who make the experience enjoyable."}, {"theme": "Clinical Expertise", "mentions": 4, "sentiment": "Positive", "summary_quote": "Patients commend the dentists for their skill, professionalism, and ability to handle treatments with care and precision."}, {"theme": "Communication", "mentions": 2, "sentiment": "Positive", "summary_quote": "Reviewers appreciate the clear explanations and attention to detail provided by the dental team."}, {"theme": "Treatment Outcomes", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients express satisfaction with the quality of dental work, noting excellent results and cosmetic improvements."}], "summary": "Patients consistently praise Smile Again Dental Center for its modern, clean facility, friendly and professional staff, and high-quality dental care. Many reviewers highlight the exceptional service and expertise of the dentists, making their visits comfortable and stress-free.", "review_count": 130, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-01-14T01:09:47.295611213Z", "text": "My first time here at Smile Again Dental.  The office is so modern, new and clean. The staff and dentist Tuyet Nguyen is so kind and explain the whole treatment. I got teeth cleaning and my lower anterior chip so Dr. Tuyet done composite filling the same day. Her work was done beautifully. I will recommend all of my family and friend to this dental office. Thank you Smile Again Dental.", "author": "James Tran", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109171983486068716539/reviews"}, {"date": "2025-04-26T18:21:55.333034Z", "text": "Finding Smile Again Dental Center has truly been a blessing for my entire family! From the moment you walk in, you can immediately tell how much pride they take in their practice. The office is spotless, beautifully designed, and feels welcoming and comfortable.\n\nThe customer service here is absolutely outstanding. Everyone, from the front desk staff to the dental assistants and doctors, is friendly, attentive, and genuinely cares about making sure you have a great experience. They pay incredible attention to detail, which is something you don’t always find at other places.\n\nWe originally came to Smile Again Dental Center because my mom had gotten a dental implant done at another office and was experiencing a lot of pain and discomfort when eating. It was heartbreaking seeing her struggle. Thankfully, the doctor at Smile Again Dental took the time to properly assess the situation, explained everything to us clearly, and fixed the problem with so much care and expertise. Now, she’s finally able to eat comfortably again without any pain, something we are beyond grateful for!\n\nAnother thing I love about this office is that they offer a full range of services, and everything is done in-house, which makes the whole process so much quicker and more convenient. No need to bounce around from office to office for different procedures, they handle it all right there.\n\nOn top of everything, the quality of care you get for the price is truly amazing. You can tell they don’t cut corners, but they also don’t overcharge like a lot of places do.\n\nI’m so thankful we found Smile Again Dental Center, it’s now our go-to dental office for the whole family! If you’re looking for a dental team that truly cares and delivers top-notch results, this is the place to go! :)", "author": "Annie Ta", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101018980263649197639/reviews"}, {"date": "2026-04-02T21:29:35.675125296Z", "text": "Amazing place & Staff!!! I have never seen such a prepositional and beautiful establishment. The best dental work I have ever experienced. Extremely grateful for this Absolute Gem!!! Quick appointments, fast, always early, a the best dental work possible. Extremely low rates!!! Would highly recommend any friends of family to this establishment at any time!!!!", "author": "Jack Lukk", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108308730892074975924/reviews"}, {"date": "2026-03-28T20:31:18.070368184Z", "text": "Excellent doctors here. Dr. John Ngo handled my extractions, and I was very impressed with his professionalism. He made the whole experience much easier for me, and thanks to him I am not afraid of the dentist anymore. He is my favorite doctor!!", "author": "Skyla Horn", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/118285449054478394345/reviews"}, {"date": "2025-08-23T19:31:42.836154733Z", "text": "I’m honestly blown away by how smooth my visit was. Checking in as a new patient took no time at all, and I loved that everything was electronic… no stacks of paper to fill out.\n\nThe cleaning was amazing too. At other places I’ve been, it always felt a little rough, but here it was gentle and I actually walked out happy. I didn’t have any cavities, but I did ask about bonding a small spot on one tooth for cosmetic reasons. They were super accommodating and it turned out amazing.\n\nFriendly staff, simple process, and a visit that left me smiling. I’m really glad I chose this place!", "author": "Daniel Ngo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104390873259237264606/reviews"}]}, "review_summary": "Patients consistently praise Smile Again Dental Center for its modern, clean facility, friendly and professional staff, and high-quality dental care. Many reviewers highlight the exceptional service and expertise of the dentists, making their visits comfortable and stress-free.", "about_highlight": "Smile Again Dental Center in Westminster, CA is dedicated to exceeding expectations with compassionate, comprehensive dental care. We are the only dental office in the area with an on-site digital lab over 5,000 sq. ft., making your visit more convenient and time efficient. We believe in creating affordable, yet star-quality smiles using skilled cosmetic dentistry, master digital in-house lab, and advanced sedation and implant dentistry. Our team is committed to providing the highest standard of care, from preventive general dentistry to complex restorative procedures, all tailored to your individual needs.", "appointment_url": "https://patient.rocks/Dashboard/PatientDashboard/NmExMjRjN2QtMzY1ZC00NDgyLWE0ZjItODc3ZDIz", "google_maps_url": "https://maps.google.com/?cid=5273484010228764688&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJFxpHGjMm3YAREFBjZsQtL0k", "quality_missing": ["insurance", "team_members"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "general dental care", "laser dentistry", "dental implants", "cosmetic dentistry", "all-on-4 implants", "tooth extractions and root canals", "dentures and partials", "general dentistry"], "services_offered": [{"name": "General Dental Care", "category": "General Dentistry", "description": "Full mouth examination, digital imaging, X-rays, 3D CT scan, dental scaling and polishing, preventive treatments.", "is_featured": true, "patient_fit": null}, {"name": "Laser Dentistry", "category": "Dental", "description": "Laser treatments for tooth decay, gum disease, and bacterial infection with minimal bleeding and faster healing.", "is_featured": true, "patient_fit": null}, {"name": "Dental Implants", "category": "Cosmetic Dentistry", "description": "Long-term tooth replacement with 3D CT scan guided placement, custom implant crowns from our in-house lab.", "is_featured": true, "patient_fit": null}, {"name": "Cosmetic Dentistry", "category": "Cosmetic Dentistry", "description": "Skilled cosmetic dentistry to enhance your smile, including veneers, crowns, and more.", "is_featured": false, "patient_fit": null}, {"name": "All-On-4 Implants", "category": "Cosmetic Dentistry", "description": "Full-arch implant solution using All-On-4 technique for stable, natural-looking dentures.", "is_featured": false, "patient_fit": null}, {"name": "Tooth Extractions and Root Canals", "category": "General Dentistry", "description": "Safe and comfortable tooth extractions and root canal treatments to preserve your oral health.", "is_featured": false, "patient_fit": null}, {"name": "Dentures and Partials", "category": "General Dentistry", "description": "Custom dentures and partials designed in our digital lab for a perfect fit and natural appearance.", "is_featured": false, "patient_fit": null}], "short_description": "Smile Again Dental Center in Westminster, CA offers comprehensive dental care with an on-site digital lab, laser dentistry, and dental implants.", "google_website_url": "http://smileagaindentalcenter.com/", "google_primary_type": "Health", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "14501 Magnolia St #101&107, Westminster, CA 92683, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/106178301804151701335", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWIjFPqQfpOYc56ePfZ_N_GpvFl9vQShbp12WCDt6AfJEMVeNiq=s100-p-k-no-mo", "displayName": "Smile Again Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/106178301804151701335", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWIjFPqQfpOYc56ePfZ_N_GpvFl9vQShbp12WCDt6AfJEMVeNiq=s100-p-k-no-mo", "displayName": "Smile Again Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/106178301804151701335", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWIjFPqQfpOYc56ePfZ_N_GpvFl9vQShbp12WCDt6AfJEMVeNiq=s100-p-k-no-mo", "displayName": "Smile Again Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/106178301804151701335", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWIjFPqQfpOYc56ePfZ_N_GpvFl9vQShbp12WCDt6AfJEMVeNiq=s100-p-k-no-mo", "displayName": "Smile Again Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/112206472928912534369", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocKpJ2oJOtxEom49iQMh5MrIDPGXdUjUAZSoj9eMg7M-ULyUgA=s100-p-k-no-mo", "displayName": "Chi Le"}]]}'::jsonb, '2026-06-25T19:17:56.690773+00:00', 'smile-again-dental-center', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6d7920da-2955-452f-97a7-a7f8f202ac97', NULL, 'North Valley Dental: H. Pham, DDS', 'North Valley Dental, led by Dr. H. Pham, DDS, is a family and cosmetic dentistry practice located in Milpitas, California. The practice emphasizes exceptional care with a gentle touch, serving patients in a modern facility. As a community-focused dental office, North Valley Dental aims to provide quality dental care for patients of all ages.', '991 Montague Expwy #201', 'Milpitas', 'CA', '95035', '(408) 945-9752', ARRAY['English', 'Vietnamese']::text[], 'Dental', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/north-valley-dental-h.-pham-dds-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/north-valley-dental-h.-pham-dds-google-2.webp"], "rating": 5, "reviews": [{"date": "2018-03-14T23:25:21.479Z", "text": "We love Dr. Pham and his staff! He is great with our kids (we''ve been bringing them to him since they were a little under 2 years old each) and I feel like we''re going to visit friends when we have an appointment. He takes the time to make our kids comfortable and slowly introduces them to new parts of the cleaning process without pressuring them. I think this is very important in helping kids get comfortable with the dentist instead of breeding a hatred for going to the dentist that some adults have!  Highly recommended!", "author": "Alison Garabedian", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115581526689164827429/reviews"}, {"date": "2018-05-17T00:09:04.597Z", "text": "Dr Pham is a good dentist not by the simple gauge of cleanings (someone who needs dental work should never ask a person with perfect teeth for recommendations!), but when you actually need help. And Dr Pham did just that. I had a bonded composite fall loose from a tooth, which left the tooth vulnerable, and they quickly responded to take care of it. It''s probably been 2-3 years since then, and despite having to have that tooth repaired twice before - that bond has been holding well since!\nMy work used to be nearby, but now I drive 30 minutes to see Dr Pham.", "author": "Grace Chen", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109973186441230695993/reviews"}, {"date": "2024-03-08T14:34:55.906087Z", "text": "I recently visited Dr.Pham  for a dental check-up, and I couldn''t be happier with the experience. The staff was friendly and welcoming, the office was clean .I left feeling confident in my dental health and grateful for such a positive experience. I highly recommend Dr. Pham  and their team to anyone in need of exceptional dental care.", "author": "R W", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112986801476458322256/reviews"}, {"date": "2016-06-16T15:40:17.845Z", "text": "I had been to numerous dentist previously and Dr. Pham is truly Bar None in the bay area. He clearly explains what procedure he will be preforming before starting. Dr. Pham also makes sure your time in his office is a comfortable as possible. I have recommended him to my family, friends and now to you Googlers. If you want a true professional in an extremely friendly and clean environment then North Valley Dental is the place for you.", "author": "R Ruano", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113717815423620313716/reviews"}], "website": "http://www.northvalleydental.com/", "location": {"latitude": 37.4133347, "longitude": -121.88526490000001}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "ac