INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('d4cf5c47-5341-42a2-bb7e-517bdf56aa89', NULL, 'V Family Dentistry', 'At V Family Dentistry in Houston, TX, we are committed to providing comprehensive dental care for patients of all ages in a warm and friendly environment. Our experienced team, led by Dr. Vi Hoang, utilizes the latest techniques and advanced technology to ensure your smile remains healthy and beautiful. Whether you need routine check-ups, cosmetic enhancements, or restorative treatments, we tailor our services to meet your unique needs.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('62642768-e2b0-426a-82bb-d67fe67cd9b4', NULL, 'HWY 6 FAMILY DENTISTRY', 'HWY6 Family Dentistry (also referred to as Hwy 6 Dentistry) is a family-oriented dental practice located in Houston, TX, dedicated to reimagining dentistry by blending compassion with clinical excellence. The practice emphasizes a patient-first philosophy, transparent treatment planning, and a warm, modern environment designed to put every visitor at ease. From general dentistry and orthodontics to dental implants and emergency care, the clinic offers a comprehensive one-stop shop approach, supported by advanced technology like CBCT Vatech scans, iTero 3D oral scanning, and digital X-rays. The team, led by Dr. Nathan Pham (DDS, FICOI) and Dr. Alex Thuy Nguyen (DDS), prioritizes comfort through gentle techniques, sedation options, and personalized care, striving to transform lives one smile at a time.', '9470 HWY6 S Houston, TX 77083', 'Houston', 'TX', '77083', '(281) 247-5938', ARRAY['English', 'Spanish', 'Vietnamese']::text[], 'Dental', FALSE, '{"email": "hwy6familydental@gmail.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hwy-6-family-dentistry-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hwy-6-family-dentistry-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hwy-6-family-dentistry-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hwy-6-family-dentistry-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hwy-6-family-dentistry-google-5.webp"], "rating": 4.9, "pricing": [{"name": "Emergency Exam", "notes": "Cash only", "price": "$66", "category": "Emergency", "price_range": null}, {"name": "Braces & Invisalign", "notes": "$1,000 OFF (special offer mentioned on the page)", "price": null, "category": "Orthodontics", "price_range": null}, {"name": "Single Tooth Implant", "notes": "15% OFF (special offer mentioned on the page)", "price": null, "category": "Implants", "price_range": null}, {"name": "Teeth Whitening", "notes": "15% OFF (special offer mentioned on the page)", "price": null, "category": "Cosmetic", "price_range": null}], "reviews": [{"date": "2026-05-16T14:22:07.177576166Z", "text": "I had a great experience at this office for my son''s braces treatment. From the very beginning, the entire team was super accommodating, welcoming, and kind. They took the time to explain the treatment process clearly and always made us feel comfortable during every visit. The staff is very professional, patient, and truly cares about their patients and families. We are very happy with the progress of his braces treatment and appreciate all the hard work and attention the office has given us. I would definitely recommend this office to anyone looking for quality orthodontic care and a friendly environment.", "author": "Thanh Hoang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110272846558311683146/reviews"}, {"date": "2026-05-16T19:22:29.163752958Z", "text": "I usually get anxious about dental visits, but this office made the experience surprisingly comfortable. Everyone was patient, kind, and reassuring. The dentist was gentle and explained each step before starting. Definitely the best dental experience I’ve had. It’s a clean office, friendly staff, great dentist, and excellent care. Highly recommend!", "author": "Melissa a", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112856442306456240085/reviews"}, {"date": "2026-03-19T22:21:16.942705645Z", "text": "Finding a dental practice that balances high-end clinical expertise with a classy and elegant atmosphere is rare. This office is a true gem—the decor is sophisticated, and the entire staff is incredibly warm, cultured, and genuinely kind.  The services is top notch in every category/task.\n\nWhat truly sets this office apart is their character. They value clients’ feelings and comfort levels more than money. My mom was very nervous about a major procedure, and they were so compassionate. They made it clear they only wanted her to move forward if she was 100% comfortable—they were perfectly fine with not \"making the sale\" because they cared more about her well-being than the bottom line.\n​\n​\nExpert Care & High-Tech Precision\n​Modern & Clean: Their equipment and tools are modern, high-tech, and spotlessly clean, which gives me total peace of mind. They even have nice TVs playing calming nature and scenic videos, which are so helpful for relaxing.\n​\nDr. Nathan Pam: He is the definition of an expert who clearly values his clients. Not only is his professional approach top-tier, but he is also incredibly kind and makes you feel truly heard.\n​\nKathryn, Megan, & Amy: These ladies are absolute pros. They cleaned my teeth thoroughly and properly while remaining incredibly gentle. They are so kind and answer every question I have; they treat you like a person instead of just a job, and they are amazing at helping you relax and feel positive.\n​Integrity Above All Else.  I have been a client for almost 3 years and recommend them to everyone.\n\nExceptional Front Office & Billing\n​Kathy, Naomi, & Quynh (Admin/Billing): They are remarkably professional and warm, especially if a client is feeling nervous. They truly go out of their way to find the best deals, terms, and advice for insurance billing to make things as easy as possible on your pocket. I ask a lot of questions, and they always respond with warmth and incredible patience.\n\n​Hospitality & Special Care\n​Special Compassion: They are very respectful in general but show extra compassion for the elderly, which means the world to our family.\n​Amenities: The hospitality is fantastic—they have a great coffee machine and are always quick to offer water or other drinks if you aren''t having coffee.\n\n​This is a practice that leads with its heart. If you want a team that is elegant, professional, and treats you with genuine care, I cannot recommend them enough.", "author": "Khurram", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103138811396839258952/reviews"}, {"date": "2026-01-28T22:11:47.452055007Z", "text": "The entire team is outstanding and professional. They remember and maintain so many details. I love them. My entire family of 4 goes here and they have the best prices and the most modern tech. They always make me feel comfortable from the second I walk in the door.  They have a comfortable waiting area with beverages and soft music. Very hospitable and knowledgeable.", "author": "Cal Lopez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106169270327418835282/reviews"}, {"date": "2026-01-30T15:47:15.231243903Z", "text": "I really love this dental office. Everyone here is so kind and caring. They always make me feel comfortable and welcome. The doctor and staff explain everything clearly and never rush me. I feel confident coming here for my dental care. Highly recommend!", "author": "Yuki N", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107586481417981114492/reviews"}], "website": "https://www.hwy6dentistry.com/", "location": {"latitude": 29.674837900000004, "longitude": -95.6441109}, "services": ["General Dentistry", "Orthodontics (Braces & Invisalign)", "Dental Implants", "Cosmetic Dentistry", "Emergency Dentistry", "Teeth Whitening", "Wisdom Teeth Extractions", "Root Canal & Crowns"], "insurance": {"notes": "Medicaid is accepted for children only. For other insurance plans, patients are encouraged to call the office to verify coverage. The practice also accepts most major dental insurance plans.", "accepts_medicaid": true, "accepts_medicare": null, "accepted_networks": ["MetLife", "Delta Dental", "Aetna", "Humana", "Blue Cross Blue Shield", "GEHA", "Cigna", "Guardian", "Sunlife", "Medicaid"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "24/7 Online Booking", "detail": "Patients can schedule appointments at their convenience, including evenings and weekends, through the online booking system.", "category": "convenience"}, {"title": "Sedation Available", "detail": "Laughing gas (nitrous) sedation is offered for patients of all ages to ensure stress-free visits.", "category": "care"}, {"title": "Invisalign Preferred Providers", "detail": "The doctors are Invisalign preferred providers, specializing in discreet, comfortable smile transformations.", "category": "technology"}, {"title": "Advanced Technology", "detail": "The clinic utilizes CBCT Vatech scans, iTero 3D oral scanning, and digital X-rays for precise diagnostics with minimal radiation.", "category": "technology"}, {"title": "Transparent Pricing", "detail": "Patient reviews highlight clear, detailed treatment plan explanations with no hidden fees.", "category": "convenience"}, {"title": "Children''s Medicaid Accepted", "detail": "Medicaid for children is accepted, making care accessible for families.", "category": "insurance"}, {"title": "Bilingual & Multicultural Staff", "detail": "The team is noted as friendly and attentive, with patient testimonials in Vietnamese and Spanish reflecting a culturally welcoming environment.", "category": "culture"}, {"title": "Same-Day Emergency Availability", "detail": "Emergency appointments are available with flexible scheduling, including Saturday hours and after-hours care when possible.", "category": "care"}], "price_tier": "$", "source_url": "https://www.hwy6dentistry.com/", "appointment": {"booking_note": "Book online or call (281) 247-5938. Same-day emergency availability and 24/7 online scheduling available.", "appointment_url": "https://www.hwy6dentistry.com/#", "new_patient_note": "New patient specials are available on the Special Offers page.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese dentist in Texas", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | spanish | vietnamese | tiếng việt | người việt | bác sĩ việt | general dentistry | orthodontics (braces & invisalign) | dental implants | cosmetic dentistry | emergency dentistry | teeth whitening | wisdom teeth extractions | root canal & crowns | preventive | cosmetic | restorative | emergency | oral surgery | metlife | delta dental | aetna | humana | blue cross blue shield | geha | cigna | guardian | sunlife | medicaid | nathan pham, dds, ficoi | dentist / implant specialist | alex thuy nguyen, dds | debra | dental assistant | katherine (katherin) | celene pham | staff (likely hygienist or assistant)", "google_types": ["dentist", "dental_clinic", "medical_clinic", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 315, "team_members": [{"name": "Nathan Pham, DDS, FICOI", "role": "Dentist / Implant Specialist", "bio_snippet": "Dr. Nathan Pham graduated from UT Health Science Center in Houston, holds a Fellowship in the International Congress of Oral Implantologists (FICOI), and specializes in implantology, sedation dentistry, and comprehensive family care. He is known for his compassionate approach and commitment to ongoing education.", "languages_spoken": ["Vietnamese", "English"]}, {"name": "Alex Thuy Nguyen, DDS", "role": "Dentist", "bio_snippet": "Dr. Alex Thuy Nguyen has three years of dedicated practice, specializing in general dentistry and orthodontic treatment. He focuses on patient comfort, using laughing gas to reduce anxiety, and provides a wide range of services from cleanings to braces and wisdom teeth extractions.", "languages_spoken": ["Vietnamese", "English"]}, {"name": "Debra", "role": "Dental Assistant", "bio_snippet": "Mentioned in patient testimonials as an incredibly knowledgeable and caring dental assistant.", "languages_spoken": ["English"]}, {"name": "Katherine (Katherin)", "role": "Dental Assistant", "bio_snippet": "Mentioned in patient testimonials as an incredibly knowledgeable and caring dental assistant.", "languages_spoken": ["English"]}, {"name": "Celene Pham", "role": "Staff (likely hygienist or assistant)", "bio_snippet": "Mentioned in a positive patient review for providing a great experience.", "languages_spoken": ["English"]}], "language_note": "The practice serves a diverse multicultural community in Houston, with many patient testimonials in Vietnamese and Spanish, and staff who are described as friendly and attentive across language backgrounds. The clinic provides bilingual accessibility, as evidenced by the Spanish-language page and Vietnamese patient quotes. Dr. Nathan Pham and Dr. Alex Thuy Nguyen are both of Vietnamese heritage, and the practice explicitly welcomes Vietnamese-speaking and Spanish-speaking patients.", "open_saturday": true, "quality_score": 100, "working_hours": {"friday": "8:30 AM – 5:00 PM", "monday": "8:30 AM – 5:00 PM", "sunday": "Closed", "tuesday": "8:30 AM – 5:00 PM", "saturday": "8:30 AM – 2:30 PM", "thursday": "8:30 AM – 5:00 PM", "wednesday": "8:30 AM – 5:00 PM"}, "gallery_images": ["https://cdn.prod.website-files.com/650c5d00bebdf74a3b9ddf92/650c8cc24e90145c3de87f60_logohy6.svg", "https://cdn.prod.website-files.com/650c5d00bebdf74a3b9ddf92/650c8cce280996c0fee2025a_logo-white-hwy6.svg", "https://cdn.prod.website-files.com/650c5d00bebdf74a3b9ddf92/6511fd16e617c09caafada00_Dr.%20Alex%20Thuy%20Nguyen.webp", "https://cdn.prod.website-files.com/650c5d00bebdf74a3b9ddf92/6511fd161123b9230cb35479_Dr.%20Nathan%20Pham.webp", "https://cdn.prod.website-files.com/650c5d00bebdf74a3b9ddf92/6511fd1321cf4381e740b035_Safety.webp", "https://cdn.prod.website-files.com/650c5d00bebdf74a3b9ddf92/6511fd13c111962be9c7c017_Connect%20with%20us.webp"], "review_profile": {"rating": 4.9, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 5, "sentiment": "Positive", "summary_quote": "Every reviewer highlights friendly, knowledgeable staff who prioritize patient comfort and care."}, {"theme": "Facility Environment", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients appreciate the clean, modern, and calming atmosphere of the office."}, {"theme": "Communication", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers commend the staff for explaining procedures clearly and ensuring patient understanding."}, {"theme": "Clinical Expertise", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients note the high-quality care and advanced technology used in treatments."}, {"theme": "Patient Comfort", "mentions": 4, "sentiment": "Positive", "summary_quote": "Many reviewers emphasize how the staff goes above and beyond to make patients feel at ease."}], "summary": "Patients consistently praise HWY 6 FAMILY DENTISTRY for its welcoming atmosphere, professional staff, and high-quality care. Many highlight the team''s kindness, clear communication, and modern facilities, making dental visits comfortable and stress-free.", "review_count": 315, "concern_themes": [], "positive_themes": ["Friendly and attentive staff", "Transparent pricing and clear treatment plans", "Gentle, pain-free procedures", "Modern, clean facility with advanced technology", "Comforting environment (Netflix, coffee bar, calming decor)", "Great with anxious patients", "Bilingual/multilingual care"], "featured_reviews": [{"date": "2026-05-16T14:22:07.177576166Z", "text": "I had a great experience at this office for my son''s braces treatment. From the very beginning, the entire team was super accommodating, welcoming, and kind. They took the time to explain the treatment process clearly and always made us feel comfortable during every visit. The staff is very professional, patient, and truly cares about their patients and families. We are very happy with the progress of his braces treatment and appreciate all the hard work and attention the office has given us. I would definitely recommend this office to anyone looking for quality orthodontic care and a friendly environment.", "author": "Thanh Hoang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110272846558311683146/reviews"}, {"date": "2026-05-16T19:22:29.163752958Z", "text": "I usually get anxious about dental visits, but this office made the experience surprisingly comfortable. Everyone was patient, kind, and reassuring. The dentist was gentle and explained each step before starting. Definitely the best dental experience I’ve had. It’s a clean office, friendly staff, great dentist, and excellent care. Highly recommend!", "author": "Melissa a", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112856442306456240085/reviews"}, {"date": "2026-03-19T22:21:16.942705645Z", "text": "Finding a dental practice that balances high-end clinical expertise with a classy and elegant atmosphere is rare. This office is a true gem—the decor is sophisticated, and the entire staff is incredibly warm, cultured, and genuinely kind.  The services is top notch in every category/task.\n\nWhat truly sets this office apart is their character. They value clients’ feelings and comfort levels more than money. My mom was very nervous about a major procedure, and they were so compassionate. They made it clear they only wanted her to move forward if she was 100% comfortable—they were perfectly fine with not \"making the sale\" because they cared more about her well-being than the bottom line.\n​\n​\nExpert Care & High-Tech Precision\n​Modern & Clean: Their equipment and tools are modern, high-tech, and spotlessly clean, which gives me total peace of mind. They even have nice TVs playing calming nature and scenic videos, which are so helpful for relaxing.\n​\nDr. Nathan Pam: He is the definition of an expert who clearly values his clients. Not only is his professional approach top-tier, but he is also incredibly kind and makes you feel truly heard.\n​\nKathryn, Megan, & Amy: These ladies are absolute pros. They cleaned my teeth thoroughly and properly while remaining incredibly gentle. They are so kind and answer every question I have; they treat you like a person instead of just a job, and they are amazing at helping you relax and feel positive.\n​Integrity Above All Else.  I have been a client for almost 3 years and recommend them to everyone.\n\nExceptional Front Office & Billing\n​Kathy, Naomi, & Quynh (Admin/Billing): They are remarkably professional and warm, especially if a client is feeling nervous. They truly go out of their way to find the best deals, terms, and advice for insurance billing to make things as easy as possible on your pocket. I ask a lot of questions, and they always respond with warmth and incredible patience.\n\n​Hospitality & Special Care\n​Special Compassion: They are very respectful in general but show extra compassion for the elderly, which means the world to our family.\n​Amenities: The hospitality is fantastic—they have a great coffee machine and are always quick to offer water or other drinks if you aren''t having coffee.\n\n​This is a practice that leads with its heart. If you want a team that is elegant, professional, and treats you with genuine care, I cannot recommend them enough.", "author": "Khurram", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103138811396839258952/reviews"}, {"date": "2026-01-28T22:11:47.452055007Z", "text": "The entire team is outstanding and professional. They remember and maintain so many details. I love them. My entire family of 4 goes here and they have the best prices and the most modern tech. They always make me feel comfortable from the second I walk in the door.  They have a comfortable waiting area with beverages and soft music. Very hospitable and knowledgeable.", "author": "Cal Lopez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106169270327418835282/reviews"}, {"date": "2026-01-30T15:47:15.231243903Z", "text": "I really love this dental office. Everyone here is so kind and caring. They always make me feel comfortable and welcome. The doctor and staff explain everything clearly and never rush me. I feel confident coming here for my dental care. Highly recommend!", "author": "Yuki N", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107586481417981114492/reviews"}]}, "review_summary": "Patients consistently praise HWY 6 FAMILY DENTISTRY for its welcoming atmosphere, professional staff, and high-quality care. Many highlight the team''s kindness, clear communication, and modern facilities, making dental visits comfortable and stress-free.", "about_highlight": "HWY6 Family Dentistry (also referred to as Hwy 6 Dentistry) is a family-oriented dental practice located in Houston, TX, dedicated to reimagining dentistry by blending compassion with clinical excellence. The practice emphasizes a patient-first philosophy, transparent treatment planning, and a warm, modern environment designed to put every visitor at ease. From general dentistry and orthodontics to dental implants and emergency care, the clinic offers a comprehensive one-stop shop approach, supported by advanced technology like CBCT Vatech scans, iTero 3D oral scanning, and digital X-rays. The team, led by Dr. Nathan Pham (DDS, FICOI) and Dr. Alex Thuy Nguyen (DDS), prioritizes comfort through gentle techniques, sedation options, and personalized care, striving to transform lives one smile at a time.", "appointment_url": "https://www.hwy6dentistry.com/#", "google_maps_url": "https://maps.google.com/?cid=8941534509529071883&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJj1EYyV_dQIYRC4FgG0O2Fnw", "quality_missing": [], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "spanish", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "general dentistry", "orthodontics (braces & invisalign)", "dental implants", "cosmetic dentistry", "emergency dentistry", "teeth whitening", "wisdom teeth extractions", "root canal & crowns", "preventive", "cosmetic", "restorative", "emergency", "oral surgery", "metlife", "delta dental", "aetna", "humana", "blue cross blue shield", "geha", "cigna", "guardian", "sunlife", "medicaid", "nathan pham, dds, ficoi", "dentist / implant specialist", "alex thuy nguyen, dds", "debra", "dental assistant", "katherine (katherin)", "celene pham", "staff (likely hygienist or assistant)"], "cultural_context": "The practice serves a diverse multicultural community in Houston, with many patient testimonials in Vietnamese and Spanish, and staff who are described as friendly and attentive across language backgrounds. The clinic provides bilingual accessibility, as evidenced by the Spanish-language page and Vietnamese patient quotes. Dr. Nathan Pham and Dr. Alex Thuy Nguyen are both of Vietnamese heritage, and the practice explicitly welcomes Vietnamese-speaking and Spanish-speaking patients.", "services_offered": [{"name": "General Dentistry", "category": "Preventive", "description": "Annual checkups, cleanings, fillings, and deep cleaning.", "is_featured": true, "patient_fit": "Patients seeking routine family dental care."}, {"name": "Orthodontics (Braces & Invisalign)", "category": "Cosmetic", "description": "Braces and clear aligner treatments for smile transformation.", "is_featured": true, "patient_fit": "Adults and teens looking for orthodontic correction."}, {"name": "Dental Implants", "category": "Restorative", "description": "Single tooth implants, implant-supported restorations with flexible financing.", "is_featured": true, "patient_fit": "Patients needing tooth replacement."}, {"name": "Cosmetic Dentistry", "category": "Cosmetic", "description": "Veneers, teeth whitening, and artistic smile enhancements.", "is_featured": true, "patient_fit": "Patients looking to improve the aesthetic appearance of their smile."}, {"name": "Emergency Dentistry", "category": "Emergency", "description": "Immediate care for dental emergencies, with $66 emergency exam (cash only).", "is_featured": true, "patient_fit": "Patients experiencing acute dental pain or urgent issues."}, {"name": "Teeth Whitening", "category": "Cosmetic", "description": "Professional teeth whitening services with special offers.", "is_featured": false, "patient_fit": "Patients wanting a brighter smile."}, {"name": "Wisdom Teeth Extractions", "category": "Oral Surgery", "description": "Extraction of wisdom teeth and impacted teeth.", "is_featured": false, "patient_fit": "Patients with problematic wisdom teeth."}, {"name": "Root Canal & Crowns", "category": "Restorative", "description": "Painless root canal treatments and custom crowns.", "is_featured": false, "patient_fit": "Patients with infected or damaged teeth requiring endodontic treatment."}], "short_description": "A family-focused dental practice in Houston offering general, cosmetic, orthodontic, and emergency dentistry with a warm, modern environment, transparent pricing, and a commitment to patient comfort.", "google_website_url": "https://www.hwy6dentistry.com/", "insur