INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6c10158b-2541-443b-be0c-9c82fe0a3819', NULL, 'Solid Primary Care', 'Solid Primary Care provides simply good primary care with a focus on helping you live your life to the fullest. Our goal is to remove physical barriers that prevent you from savoring life or hitting your goals. We uphold the time-honored, professional ethos of the physician while appropriately enhancing the patient experience with technology and innovation. Beyond anything else, we have set a system in place so that you always come first.
