INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('75cb987d-bcbd-48d1-96cf-e4c32e13c906', NULL, 'Washington Acupuncture & Traditional Chinese Herbal Medicine', 'Washington Acupuncture & Traditional Chinese Medicine (WATCM) opened in downtown Washington DC in May, 2001. We are a husband and wife team and are first and foremost a Traditional Acupuncture and Chinese Herbal Medicine clinic specializing in women’s and men’s reproductive health, pain management, stress induced disorders and nutrition. We also provide our patients a place to turn first for a broad range of health concerns, whether the common cold, headache, digestive complaints or back strain. Our experience and training has given us the unique ability to create treatment plans for both long term patient care for chronic conditions and desired relief of acute conditions. Our commitment to the highest standards of care has allowed us to develop a patient centered, clinically precise and thoughtful practice for which over 20 years has met the needs of our busy patients. We are proud to be Washington DC’s first board certified reproductive acupuncture practice (ABORM). In 2008 our office was named an off-site teaching facility for Georgetown University Medical School residency program.', '1900 L Street, NW Suite 740', 'Washington', 'DC', '20036', '202.783.9404', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"email": "contact@acupuncture-dc.net", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/washington-acupuncture-traditional-chinese-herbal-medicine-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/washington-acupuncture-traditional-chinese-herbal-medicine-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/washington-acupuncture-traditional-chinese-herbal-medicine-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/washington-acupuncture-traditional-chinese-herbal-medicine-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/washington-acupuncture-traditional-chinese-herbal-medicine-google-5.webp"], "rating": 5, "reviews": [{"date": "2026-03-01T09:07:25.697487411Z", "text": "Kate and Kelly are the best! They helped me during a very tough time with my fertility IVF journey. I truly believe in my heart they helped my transfer ‘stick’. Kate helped me during my last few weeks before birthing my beautiful baby boy! They are true experts and Kate helped me release so much fear and tension that she identified in me that can block you from overall health. I am forever grateful!", "author": "Zsu K", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105647549164620211282/reviews"}, {"date": "2020-11-12T22:34:09.612837Z", "text": "[Update 11/22/19]\nIt''s been 1 year and 10 months, and Kelly has helped me not only maintain health but also achieve athletic goals. He has treated countless sports-relared muscle injuries and joint pains that I''ve suffered by using different methods including Gua Sha, heat cupping, and electroacupuncture. He doesn''t need X-rays, MRI or other labs. He listens to his clients carefully and also can find the problems by touch/palpation.\n\nI have just completed my 2nd full marathon. I ran my first race last year after the miraculous recovery from the debilitating back issue which a chiropractor (MD) couldn''t fix after 33 sessions (3months) for $3000. Kelly diligently worked on the problem area, and I recovered from being unable to stand up straight/walk to running a full marathon. Kelly has continued to support me throughout my training and enabled me to earn another finisher medal (*See photo from this year''s race)\n\nThis man is literally my primary doctor now.\n____________\n[Update 1/30/19]\nI still see Kelly regularly, and we have worked on many body parts: neck, shoulders, upper & lower back, hips, thighs, legs, feet (I''m quite athletic). My hives are well under control, and I''ve been off the allergy medication that I was on for 2+ years every day before seeing him.\n\n_________________\n[Update 3/28/18]\nIt''s been 2 months since the first treatment, and I just had the 6th one. Mr. Kelly has been treating a variety of muscle problems mainly caused by atheletic activities I practice regularly. Temporary and minor issues such as muscle cramps, pains, tightness, are usually resolved in just one treatment. The chronic and more severe ones are under control. His needles work really well with my tough muscles that don''t respond to pain/anti-inflammatory meds and massage (including acupressure).    Today I had a treatment for my hives (hypersensitivity).  Mr. Kelly is certainly a very experienced, knowledgeable and skilled acupuncturist, and I am very happy to have found him.\n\n_________\n[1/2018]\nJust had Acupuncture & Guasha session #2.\nMy neck injury from a bike accident that I suffered over 2 week healed completely in just 1 session. Pain is 100% gone. My neck has regained a full range of motion which it didn''t achieve for a long time even before the accident.\n\nNow I have my old lower-back injury seen again. We then will move on to work on my thigh muscles & hip joint problems which my old acupuncturist could not do due to my move.\n\nMr. Kelly Welch is REALLY GOOD. His needles hit exactly where the problems are, unlocking stiffened muscle fibers, releasing the tension in the area, allowing the muscles to relax, and promoting the blood flow to achieve the normal circulation so that body can work on its own, adjust and heal.\n\nI am a big of acupuncture and have been to an exceptional practitioner, Mr. Wakisaka, for 1 year while in Japan. I can tell when the needle just hit the target and when it missed. I can tell when muscles respond. This is how you know the practitioner is good.\n\nAfter I left Japan I was looking for another good acupuncturist to continue the treatment.\nI did Google search for acupuncture practices nearby, and there were a few. I checked each one  of their websites carefully before I picked one.\nAfter 2 sessions, I am sold. I can trust Mr. Kelly and have him take over what is left by Mr. Wakisaka. I''m looking forward to more sessions by Mr. Kelly.\n---------------------------", "author": "Miyuki Horie", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111406335342753076075/reviews"}, {"date": "2024-02-01T11:38:39.431836Z", "text": "When I first started looking for an acupuncturist for fertility, I heard from multiple friends and my doctor that Kate Yonkers and Kelly Welch were the best in the area. I initially opted to go to another acupuncturist closer to me that I thought would take insurance. After three months of receiving the same exact treatment every week in a large group treatment room divided by curtains and not feeling like I was making any progress, I decided to switch to Kate and Kelly. The difference was night and day from the first appointment. Kate listened to my health history and goals, and each session was completely customized to where I was in my fertility journey. The price was actually less than the initial practice I visited, and the rooms are private, clean, and relaxing. Fertility issues can be so disheartening, and Kate made me feel more hopeful and like I was working toward a shared goal. Ultimately, I opted to do IUI and was successful. I feel certain my sessions with Kate helped get my body and mind on track. She was incredibly knowledgeable about the entire fertility process, the test results I was receiving from the doctors, and the medicines I was being prescribed. I am so grateful to have found this practice and continue to go regularly during my pregnancy. I cannot recommend them highly enough!", "author": "Sarah R", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103600107292640246252/reviews"}, {"date": "2024-02-12T14:14:54.745598Z", "text": "This entire practice is great!  I''ve seen Kelly for over 15 years for  acute pain/injury issues as well as longer term conditions (like general inflammation or rising blood pressure) and I don''t plan to ever stop!  His treatments have proven to be effective for pain relief and for my overall wellness.  Kelly always starts with a check-in to see what I want to work on at that time and he always knows just what to do for any issue I bring up.  He''s helped me in so many different ways...I''m grateful to have found Kelly and Kate so many years ago and have recommended them to many friends.  I''m happy to share that recommendation with everyone.", "author": "L.D. Hall", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114410957568969607673/reviews"}, {"date": "2024-01-12T03:23:12.650510Z", "text": "Kate and Kelly at Washington Acupuncture are phenomenal! After seeing Kate for a few months, I was able to heal an injury that doctors told me I could only do surgery for (and that had a less than 10% sticking rate). I''ve continued coming because I feel so much more balanced and healthy, and connected to my body, when doing acupuncture; it really helps me to take care of myself in this crazy and hectic world where I''m moving nonstop. Kate is also such a gentle and kind person and really connects with her clients on a human and emotional level. I highly recommend seeing Kate and Kelly for your acupuncture needs; coming here is a ritual now for me that I don''t think I could live without.", "author": "Alexandra Tureau", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113372222202898145019/reviews"}], "website": "http://acupuncture-dc.net/", "location": {"latitude": 38.9035043, "longitude": -77.0438841}, "services": ["General Acupuncture", "Fertility Acupuncture", "Menopause Support", "Orthopedics / Pain Management", "Traditional Chinese Herbal Medicine", "Nutritional Support"], "insurance": {"notes": "No insurance information available on the page.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Over 20 years serving Washington DC", "detail": "Opened in downtown Washington DC in May, 2001, providing over two decades of patient care.", "category": "care"}, {"title": "Husband and wife team", "detail": "The practice is run by a husband and wife team, offering a personal, patient-centered approach.", "category": "culture"}, {"title": "Board Certified Reproductive Acupuncture", "detail": "First board certified reproductive acupuncture practice (ABORM) in downtown Washington DC.", "category": "care"}, {"title": "Georgetown University Medical School Teaching Facility", "detail": "Named an off-site teaching facility for Georgetown University Medical School residency program in 2008.", "category": "care"}, {"title": "Convenient downtown location near Metro", "detail": "Centrally located at 19th and L streets, 2 blocks from Farragut North (Red Line) and Farragut West (Blue/Orange Lines).", "category": "convenience"}], "price_tier": "$$", "source_url": "http://acupuncture-dc.net/", "appointment": {"booking_note": "To schedule an appointment, please email contact@acupuncture-dc.net.", "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Washington, D.C.", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | general acupuncture | fertility acupuncture | menopause support | orthopedics / pain management | traditional chinese herbal medicine | nutritional support | nutrition | kelly welch, msaom, l.ac., dom, faborm | acupuncturist | kate yonkers, msa, l.ac., dipl.ac.", "google_types": ["medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 26, "team_members": [{"name": "Kelly Welch, MSAOM, L.Ac., DOM, FABORM", "role": "Acupuncturist", "bio_snippet": "Specialized in Traditional Chinese reproductive medicine for over a decade; became the first Board Certified Reproductive Acupuncturist in downtown Washington, D.C. in 2013.", "languages_spoken": []}, {"name": "Kate Yonkers, MSA, L.Ac., Dipl.Ac.", "role": "Acupuncturist", "bio_snippet": "Interests in gynecology, maternal health, fertility, and using nutrition as a vehicle to supplement treatment with acupuncture and Traditional Chinese Herbal Medicine.", "languages_spoken": []}], "open_saturday": false, "quality_score": 93, "working_hours": {"friday": "7:30 AM – 5:00 PM", "monday": "Closed", "sunday": "Closed", "tuesday": "7:30 AM – 5:00 PM", "saturday": "Closed", "thursday": "7:30 AM – 6:00 PM", "wednesday": "7:30 AM – 6:00 PM"}, "gallery_images": ["https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/c6c6cda5-fffb-4c20-969b-4455df388acf/IMG_8690-7.jpg", "https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/32f39d7b-784c-4d00-8da6-1f2c202e2fbe/IMG_8542-8_Headshot.jpg", "https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/bfa518ab-b215-4b41-aa21-de3088d7b643/IMG_8496.jpg", "https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/1655575039144-XERA1VSKTZQ3HEFSVM9B/IMG_8381-2.jpg", "https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/1655575136122-1MA0OF2ERSE9W48NCREN/IMG_8395.jpg", "https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/1696603496734-2A5RHJR1MNLMJDNO1V28/Menopause.png", "https://images.squarespace-cdn.com/content/v1/62a655a751d87f6961999ad4/1696603909792-ITK8W2UD0JKSWR91UVOV/Orthopedics3.png"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Treatment Outcomes", "mentions": 5, "sentiment": "Positive", "summary_quote": "Patients report remarkable recoveries from injuries, fertility success, and overall health improvements."}, {"theme": "Clinical Expertise", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers emphasize Kate and Kelly''s deep knowledge and ability to diagnose and treat complex conditions effectively."}, {"theme": "Personalized Care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients appreciate the customized treatments tailored to their specific needs and stages in their health journeys."}, {"theme": "Compassionate Approach", "mentions": 3, "sentiment": "Positive", "summary_quote": "Many mention the emotional support and kindness provided by Kate and Kelly, making them feel hopeful and cared for."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "The private, clean, and relaxing treatment rooms are frequently noted as enhancing the overall experience."}], "summary": "Patients consistently praise Kate and Kelly for their expertise, personalized care, and effective treatments, particularly in fertility support, pain relief, and overall wellness. Many highlight their compassionate approach and the significant improvements in their health.", "review_count": 26, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-03-01T09:07:25.697487411Z", "text": "Kate and Kelly are the best! They helped me during a very tough time with my fertility IVF journey. I truly believe in my heart they helped my transfer ‘stick’. Kate helped me during my last few weeks before birthing my beautiful baby boy! They are true experts and Kate helped me release so much fear and tension that she identified in me that can block you from overall health. I am forever grateful!", "author": "Zsu K", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105647549164620211282/reviews"}, {"date": "2020-11-12T22:34:09.612837Z", "text": "[Update 11/22/19]\nIt''s been 1 year and 10 months, and Kelly has helped me not only maintain health but also achieve athletic goals. He has treated countless sports-relared muscle injuries and joint pains that I''ve suffered by using different methods including Gua Sha, heat cupping, and electroacupuncture. He doesn''t need X-rays, MRI or other labs. He listens to his clients carefully and also can find the problems by touch/palpation.\n\nI have just completed my 2nd full marathon. I ran my first race last year after the miraculous recovery from the debilitating back issue which a chiropractor (MD) couldn''t fix after 33 sessions (3months) for $3000. Kelly diligently worked on the problem area, and I recovered from being unable to stand up straight/walk to running a full marathon. Kelly has continued to support me throughout my training and enabled me to earn another finisher medal (*See photo from this year''s race)\n\nThis man is literally my primary doctor now.\n____________\n[Update 1/30/19]\nI still see Kelly regularly, and we have worked on many body parts: neck, shoulders, upper & lower back, hips, thighs, legs, feet (I''m quite athletic). My hives are well under control, and I''ve been off the allergy medication that I was on for 2+ years every day before seeing him.\n\n_________________\n[Update 3/28/18]\nIt''s been 2 months since the first treatment, and I just had the 6th one. Mr. Kelly has been treating a variety of muscle problems mainly caused by atheletic activities I practice regularly. Temporary and minor issues such as muscle cramps, pains, tightness, are usually resolved in just one treatment. The chronic and more severe ones are under control. His needles work really well with my tough muscles that don''t respond to pain/anti-inflammatory meds and massage (including acupressure).    Today I had a treatment for my hives (hypersensitivity).  Mr. Kelly is certainly a very experienced, knowledgeable and skilled acupuncturist, and I am very happy to have found him.\n\n_________\n[1/2018]\nJust had Acupuncture & Guasha session #2.\nMy neck injury from a bike accident that I suffered over 2 week healed completely in just 1 session. Pain is 100% gone. My neck has regained a full range of motion which it didn''t achieve for a long time even before the accident.\n\nNow I have my old lower-back injury seen again. We then will move on to work on my thigh muscles & hip joint problems which my old acupuncturist could not do due to my move.\n\nMr. Kelly Welch is REALLY GOOD. His needles hit exactly where the problems are, unlocking stiffened muscle fibers, releasing the tension in the area, allowing the muscles to relax, and promoting the blood flow to achieve the normal circulation so that body can work on its own, adjust and heal.\n\nI am a big of acupuncture and have been to an exceptional practitioner, Mr. Wakisaka, for 1 year while in Japan. I can tell when the needle just hit the target and when it missed. I can tell when muscles respond. This is how you know the practitioner is good.\n\nAfter I left Japan I was looking for another good acupuncturist to continue the treatment.\nI did Google search for acupuncture practices nearby, and there were a few. I checked each one  of their websites carefully before I picked one.\nAfter 2 sessions, I am sold. I can trust Mr. Kelly and have him take over what is left by Mr. Wakisaka. I''m looking forward to more sessions by Mr. Kelly.\n---------------------------", "author": "Miyuki Horie", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111406335342753076075/reviews"}, {"date": "2024-02-01T11:38:39.431836Z", "text": "When I first started looking for an acupuncturist for fertility, I heard from multiple friends and my doctor that Kate Yonkers and Kelly Welch were the best in the area. I initially opted to go to another acupuncturist closer to me that I thought would take insurance. After three months of receiving the same exact treatment every week in a large group treatment room divided by curtains and not feeling like I was making any progress, I decided to switch to Kate and Kelly. The difference was night and day from the first appointment. Kate listened to my health history and goals, and each session was completely customized to where I was in my fertility journey. The price was actually less than the initial practice I visited, and the rooms are private, clean, and relaxing. Fertility issues can be so disheartening, and Kate made me feel more hopeful and like I was working toward a shared goal. Ultimately, I opted to do IUI and was successful. I feel certain my sessions with Kate helped get my body and mind on track. She was incredibly knowledgeable about the entire fertility process, the test results I was receiving from the doctors, and the medicines I was being prescribed. I am so grateful to have found this practice and continue to go regularly during my pregnancy. I cannot recommend them highly enough!", "author": "Sarah R", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103600107292640246252/reviews"}, {"date": "2024-02-12T14:14:54.745598Z", "text": "This entire practice is great!  I''ve seen Kelly for over 15 years for  acute pain/injury issues as well as longer term conditions (like general inflammation or rising blood pressure) and I don''t plan to ever stop!  His treatments have proven to be effective for pain relief and for my overall wellness.  Kelly always starts with a check-in to see what I want to work on at that time and he always knows just what to do for any issue I bring up.  He''s helped me in so many different ways...I''m grateful to have found Kelly and Kate so many years ago and have recommended them to many friends.  I''m happy to share that recommendation with everyone.", "author": "L.D. Hall", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114410957568969607673/reviews"}, {"date": "2024-01-12T03:23:12.650510Z", "text": "Kate and Kelly at Washington Acupuncture are phenomenal! After seeing Kate for a few months, I was able to heal an injury that doctors told me I could only do surgery for (and that had a less than 10% sticking rate). I''ve continued coming because I feel so much more balanced and healthy, and connected to my body, when doing acupuncture; it really helps me to take care of myself in this crazy and hectic world where I''m moving nonstop. Kate is also such a gentle and kind person and really connects with her clients on a human and emotional level. I highly recommend seeing Kate and Kelly for your acupuncture needs; coming here is a ritual now for me that I don''t think I could live without.", "author": "Alexandra Tureau", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113372222202898145019/reviews"}]}, "review_summary": "Patients consistently praise Kate and Kelly for their expertise, personalized care, and effective treatments, particularly in fertility support, pain relief, and overall wellness. Many highlight their compassionate approach and the significant improvements in their health.", "about_highlight": "Washington Acupuncture & Traditional Chinese Medicine (WATCM) opened in downtown Washington DC in May, 2001. We are a husband and wife team and are first and foremost a Traditional Acupuncture and Chinese Herbal Medicine clinic specializing in women’s and men’s reproductive health, pain management, stress induced disorders and nutrition. We also provide our patients a place to turn first for a broad range of health concerns, whether the common cold, headache, digestive complaints or back strain. Our experience and training has given us the unique ability to create treatment plans for both long term patient care for chronic conditions and desired relief of acute conditions. Our commitment to the highest standards of care has allowed us to develop a patient centered, clinically precise and thoughtful practice for which over 20 years has met the needs of our busy patients. We are proud to be Washington DC’s first board certified reproductive acupuncture practice (ABORM). In 2008 our office was named an off-site teaching facility for Georgetown University Medical School residency program.", "google_maps_url": "https://maps.google.com/?cid=9404824071460751582&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJecvc0ru3t4kR3gh2AqqlhII", "quality_missing": ["insurance", "appointment_url"], "search_keywords": ["acupuncture & tcm", "acupuncture", "chinese medicine", "tcm", "herbal medicine", "cupping", "pain relief", "châm cứu", "đông y", "y học cổ truyền", "한의원", "침술", "한약", "中医", "针灸", "中药", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "general acupuncture", "fertility acupuncture", "menopause support", "orthopedics / pain management", "traditional chinese herbal medicine", "nutritional support", "nutrition", "kelly welch, msaom, l.ac., dom, faborm", "acupuncturist", "kate yonkers, msa, l.ac., dipl.ac."], "services_offered": [{"name": "General Acupuncture", "category": "Acupuncture", "description": "For a broad range of health concerns including common cold, headache, digestive complaints, back strain, and more.", "is_featured": true, "patient_fit": "Patients seeking treatment for general health issues or acute conditions."}, {"name": "Fertility Acupuncture", "category": "Acupuncture", "description": "Specialty in women’s and men’s reproductive health; the practice is Washington DC’s first board certified reproductive acupuncture practice.", "is_featured": true, "patient_fit": "Individuals or couples seeking support for fertility and reproductive health."}, {"name": "Menopause Support", "category": "Acupuncture", "description": "Acupuncture and Traditional Chinese Herbal Medicine to support women through menopause.", "is_featured": false, "patient_fit": "Women experiencing menopause symptoms."}, {"name": "Orthopedics / Pain Management", "category": "Acupuncture", "description": "Treatment for pain management and orthopedic issues using acupuncture and herbal medicine.", "is_featured": false, "patient_fit": "Patients with acute or chronic pain conditions."}, {"name": "Traditional Chinese Herbal Medicine", "category": "Herbal Medicine", "description": "Chinese herbal formulas prescribed to supplement acupuncture treatments.", "is_featured": false, "patient_fit": "Patients who may benefit from herbal medicine in addition to acupuncture."}, {"name": "Nutritional Support", "category": "Nutrition", "description": "Using nutrition as a vehicle to supplement treatment with acupuncture and Traditional Chinese Herbal Medicine.", "is_featured": false, "patient_fit": "Patients interested in dietary guidance to support their health."}], "short_description": "A husband and wife team offering Traditional Acupuncture and Chinese Herbal Medicine in downtown Washington DC, specializing in reproductive health, pain management, and nutrition for over 20 years.", "google_website_url": "http://acupuncture-dc.net/", "google_primary_type": "Medical Clinic", "provider_credentials": {"education": [], "providers": ["Kelly Welch, MSAOM, L.Ac., DOM, FABORM", "Kate Yonkers, MSA, L.Ac., Dipl.Ac."], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "1900 L St NW Ste 740, Washington, DC 20036, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/101449889188719545987", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocI3Qa7-dc_sVMXbsLqidAzGoLbvKxwXSgWRmZuTC47jpy3Spg=s100-p-k-no-mo", "displayName": "Washington Acupuncture & Traditional Chinese Herbal Medicine"}], [{"uri": "https://maps.google.com/maps/contrib/117139478264736049365", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUNM8cxDxkfe369kcy5MP0UaRVpX2EDe2lQLsW9D1HXzo4UbJodlw=s100-p-k-no-mo", "displayName": "Ola Olad"}], [{"uri": "https://maps.google.com/maps/contrib/117139478264736049365", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUNM8cxDxkfe369kcy5MP0UaRVpX2EDe2lQLsW9D1HXzo4UbJodlw=s100-p-k-no-mo", "displayName": "Ola Olad"}], [{"uri": "https://maps.google.com/maps/contrib/111406335342753076075", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVIM6Ypqr8W9pJdWetp8iwQshkpX0y0FAbadq7JXvIMR5dXRoZzlg=s100-p-k-no-mo", "displayName": "Miyuki Horie"}], [{"uri": "https://maps.google.com/maps/contrib/111406335342753076075", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVIM6Ypqr8W9pJdWetp8iwQshkpX0y0FAbadq7JXvIMR5dXRoZzlg=s100-p-k-no-mo", "displayName": "Miyuki Horie"}]]}'::jsonb, '2026-06-26T11:49:37.582611+00:00', 'washington-acupuncture-traditional-chinese-herbal-medicine', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6b777af9-9628-4879-8203-34ee70885db9', NULL, 'Dr. Keith W. Chan', 'Dr. Keith Chan is a board-certified orthopaedic surgeon and San Francisco native who graduated from Stanford University for both undergraduate and medical school. He completed his orthopaedic surgery residency at NYU Hospital for Joint Diseases and a sports medicine fellowship at Southern California Orthopedic Institute. Dr. Chan specializes in the latest arthroscopic and minimally invasive surgical techniques for shoulder, hip, and knee conditions, including superior capsular reconstruction, hip arthroscopy for femoroacetabular impingement, and biologic interventions such as stem cell and PRP therapy. He is an Associate Instructor for the Arthroscopy Association of North America, teaching advanced techniques to surgeons worldwide. At California Pacific Orthopaedics, Dr. Chan is dedicated to helping patients return to their regular activities through cutting-edge, patient-centered care.', '3838 California Street, Suites 108, 516, 707 and 715, San Francisco, CA 94118', 'San Francisco', 'CA', '94118', '(415) 668-8010', ARRAY['English', 'Chinese']::text[], 'Orthopedics', FALSE, '{"fax": "(415) 752-2560", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-keith-w.-chan-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-keith-w.-chan-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-keith-w.-chan-google-3.webp"], "rating": 5, "reviews": [{"date": "2026-02-25T00:25:05.431679631Z", "text": "Dr. Chan has been an absolutely incredible surgeon. From the very beginning, I felt confident in his expertise and care. He is truly skilled at what he does — meticulous, thoughtful, and clearly exceptional at his craft. My healing process has gone so smoothly, and I genuinely credit that to his precision and guidance.\n\nBeyond his surgical skill, he made me feel supported and reassured during a time that could have felt overwhelming. That meant more than I can say.\n\nHis staff is also wonderful — kind, responsive, organized, and professional. The entire experience felt seamless because of the team around him.\n\nI’m so grateful to have been in Dr. Chan’s care. I would recommend him without hesitation.", "author": "Becca Obregon", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100478235120879941911/reviews"}, {"date": "2025-11-25T00:29:53.190360347Z", "text": "Dr. Chan was extraordinary. I had been having chronic knees pain for many months and Dr. Chan diagnosed my condition and instructed me to follow up with a rheumatologist. He also gave me long lasting steroids injections that alleviated my knees pain completely. For the past few days, I have been able to walk, run errands, work at my desk, shop, as I used to do. I haven’t felt this good without pain in so long. I highly recommend Dr. Chan.", "author": "Beatriz Monteiro", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107847912057962018835/reviews"}, {"date": "2026-02-02T21:39:00.790445768Z", "text": "Dr Chan is extremely knowledgeable and professional.  He is clear and concise.  Also the surgery results were clearly shared (I even got photos of the work).\n\nEveryone says the physical therapy is key and Dr Chan also emphasized that point and reminded me to complete my ankle pumps and quad work to ensure best possible results.\n\nNever easy to manage injured people, so I feel like I had the right doctor and appreciate his follow up after surgery as well\n\nAnd the result of the surgery has been absolutely top notc\n\nEdit: 3.5 months later and still doing great. Dr chan schedules regular checkins and as long as I put in the effort to show up; he makes sure to check my knee.  Good work and good outcome!", "author": "Adam Larner", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110437196903538190555/reviews"}, {"date": "2025-10-21T00:04:03.035720339Z", "text": "Dr. Chan is extremely direct and clear. I was a bit intimidated by my first ever surgery but I felt complete trust and confidence in Dr. Chan from his knowledge and care. His team is incredibly helpful and responsive leading up to and after surgery, too.", "author": "Nicholas Rodriguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106891462564926263609/reviews"}, {"date": "2026-01-08T05:45:02.646349754Z", "text": "Dr. Chan performed my knee surgery a few months ago and did a great job!  He was attentive, patient and informative, particularly when going over the surgery prior to the operation and when going through the images and videos taken during the surgery. He showed and explained what we were looking in the video and walked through what he did. My knee feels better and stronger, and with PT I was able to return to my martial arts training and other activities quickly.  Thank you Dr. Chan!", "author": "Ben Lam", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117915305833596167406/reviews"}], "website": "https://calpacortho.com/team/keith-chan/", "location": {"latitude": 37.786180699999996, "longitude": -122.4576078}, "services": ["Sports Medicine", "Shoulder & Elbow", "ACL and PCL Reconstruction", "Arthroscopic Rotator Cuff Repair", "Hip Arthroscopy", "Cartilage Restoration", "Non-Surgical and Biologic Interventions", "BEAR Implant Procedure"], "insurance": {"notes": "Insurance information not provided on this page. Please contact the office for details.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Board-Certified Orthopaedic Surgeon", "detail": "Dr. Chan is board-certified and fellowship-trained in sports medicine.", "category": "care"}, {"title": "Stanford Trained", "detail": "Graduated from Stanford University for both undergraduate and medical school.", "category": "care"}, {"title": "Minimally Invasive Expertise", "detail": "Specializes in arthroscopic and minimally invasive techniques for shoulder, hip, and knee.", "category": "technology"}, {"title": "Biologic Interventions", "detail": "Integrates stem cell and PRP technology into nonoperative and operative treatment plans.", "category": "technology"}, {"title": "Hip Preservation Focus", "detail": "Special focus on hip arthroscopy and preventing hip arthritis through preservation techniques.", "category": "care"}, {"title": "Nationally Recognized Educator", "detail": "Serves as an Associate Instructor for the Arthroscopy Association of North America (AANA).", "category": "care"}], "price_tier": "$$", "source_url": "https://calpacortho.com/team/keith-chan/?utm_source=GMBSocialClimb&utm_medium=Dr.KeithW.Chan", "appointment": {"booking_note": null, "appointment_url": "https://calpacortho.com/appointments/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese orthopedic clinic in San Francisco, CA", "search_text": "orthopedics | orthopedic | joint pain | sports medicine | spine | knee | cơ xương khớp | chấn thương chỉnh hình | 정형외과 | 骨科 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | shoulder & elbow | acl and pcl reconstruction | arthroscopic rotator cuff repair | hip arthroscopy | cartilage restoration | non-surgical and biologic interventions | bear implant procedure | orthopaedics | surgery | non-surgical | keith w. chan, m.d. | orthopaedic surgeon | corbin wirta, pa-c | physician assistant", "google_types": ["doctor", "medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 85, "team_members": [{"name": "Keith W. Chan, M.D.", "role": "Orthopaedic Surgeon", "bio_snippet": "Board-certified orthopaedic surgeon, Stanford-trained, fellowship in sports medicine. Expert in arthroscopic and minimally invasive surgery for shoulder, hip, and knee.", "languages_spoken": ["English"]}, {"name": "Corbin Wirta, PA-C", "role": "Physician Assistant", "bio_snippet": "Physician Assistant working with Dr. Chan.", "languages_spoken": ["English"]}], "open_saturday": false, "quality_score": 95, "working_hours": {"friday": "8:00 AM – 5:00 PM", "monday": "8:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "8:00 AM – 5:00 PM", "wednesday": "8:00 AM – 5:00 PM"}, "gallery_images": ["https://calpacortho.com/wp-content/uploads/2026/02/keith-chan-2026-02.webp"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 5, "sentiment": "Positive", "summary_quote": "Every reviewer highlights Dr. Chan''s exceptional surgical skills and meticulous approach."}, {"theme": "Communication", "mentions": 4, "sentiment": "Positive", "summary_quote": "Patients appreciate Dr. Chan''s clear, concise explanations and thorough follow-up."}, {"theme": "Treatment Outcomes", "mentions": 4, "sentiment": "Positive", "summary_quote": "Many report significant pain relief and successful recovery, crediting Dr. Chan''s precision."}, {"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "The team is described as kind, responsive, and organized, enhancing the overall experience."}, {"theme": "Patient Support", "mentions": 3, "sentiment": "Positive", "summary_quote": "Dr. Chan''s reassurance and attentiveness made patients feel confident and cared for."}], "summary": "Patients consistently praise Dr. Chan for his exceptional surgical skills, clear communication, and supportive care, with many highlighting successful treatment outcomes and a professional, responsive team.", "review_count": 85, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-02-25T00:25:05.431679631Z", "text": "Dr. Chan has been an absolutely incredible surgeon. From the very beginning, I felt confident in his expertise and care. He is truly skilled at what he does — meticulous, thoughtful, and clearly exceptional at his craft. My healing process has gone so smoothly, and I genuinely credit that to his precision and guidance.\n\nBeyond his surgical skill, he made me feel supported and reassured during a time that could have felt overwhelming. That meant more than I can say.\n\nHis staff is also wonderful — kind, responsive, organized, and professional. The entire experience felt seamless because of the team around him.\n\nI’m so grateful to have been in Dr. Chan’s care. I would recommend him without hesitation.", "author": "Becca Obregon", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100478235120879941911/reviews"}, {"date": "2025-11-25T00:29:53.190360347Z", "text": "Dr. Chan was extraordinary. I had been having chronic knees pain for many months and Dr. Chan diagnosed my condition and instructed me to follow up with a rheumatologist. He also gave me long lasting steroids injections that alleviated my knees pain completely. For the past few days, I have been able to walk, run errands, work at my desk, shop, as I used to do. I haven’t felt this good without pain in so long. I highly recommend Dr. Chan.", "author": "Beatriz Monteiro", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107847912057962018835/reviews"}, {"date": "2026-02-02T21:39:00.790445768Z", "text": "Dr Chan is extremely knowledgeable and professional.  He is clear and concise.  Also the surgery results were clearly shared (I even got photos of the work).\n\nEveryone says the physical therapy is key and Dr Chan also emphasized that point and reminded me to complete my ankle pumps and quad work to ensure best possible results.\n\nNever easy to manage injured people, so I feel like I had the right doctor and appreciate his follow up after surgery as well\n\nAnd the result of the surgery has been absolutely top notc\n\nEdit: 3.5 months later and still doing great. Dr chan schedules regular checkins and as long as I put in the effort to show up; he makes sure to check my knee.  Good work and good outcome!", "author": "Adam Larner", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110437196903538190555/reviews"}, {"date": "2025-10-21T00:04:03.035720339Z", "text": "Dr. Chan is extremely direct and clear. I was a bit intimidated by my first ever surgery but I felt complete trust and confidence in Dr. Chan from his knowledge and care. His team is incredibly helpful and responsive leading up to and after surgery, too.", "author": "Nicholas Rodriguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106891462564926263609/reviews"}, {"date": "2026-01-08T05:45:02.646349754Z", "text": "Dr. Chan performed my knee surgery a few months ago and did a great job!  He was attentive, patient and informative, particularly when going over the surgery prior to the operation and when going through the images and videos taken during the surgery. He showed and explained what we were looking in the video and walked through what he did. My knee feels better and stronger, and with PT I was able to return to my martial arts training and other activities quickly.  Thank you Dr. Chan!", "author": "Ben Lam", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117915305833596167406/reviews"}]}, "review_summary": "Patients consistently praise Dr. Chan for his exceptional surgical skills, clear communication, and supportive care, with many highlighting successful treatment outcomes and a professional, responsive team.", "about_highlight": "Dr. Keith Chan is a board-certified orthopaedic surgeon and San Francisco native who graduated from Stanford University for both undergraduate and medical school. He completed his orthopaedic surgery residency at NYU Hospital for Joint Diseases and a sports medicine fellowship at Southern California Orthopedic Institute. Dr. Chan specializes in the latest arthroscopic and minimally invasive surgical techniques for shoulder, hip, and knee conditions, including superior capsular reconstruction, hip arthroscopy for femoroacetabular impingement, and biologic interventions such as stem cell and PRP therapy. He is an Associate Instructor for the Arthroscopy Association of North America, teaching advanced techniques to surgeons worldwide. At California Pacific Orthopaedics, Dr. Chan is dedicated to helping patients return to their regular activities through cutting-edge, patient-centered care.", "appointment_url": "https://calpacortho.com/appointments/", "google_maps_url": "https://maps.google.com/?cid=4209975882757754477&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJ1Sw4uj2HhYARbc68jMLWbDo", "quality_missing": ["insurance"], "search_keywords": ["orthopedics", "orthopedic", "joint pain", "sports medicine", "spine", "knee", "cơ xương khớp", "chấn thương chỉnh hình", "정형외과", "骨科", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "shoulder & elbow", "acl and pcl reconstruction", "arthroscopic rotator cuff repair", "hip arthroscopy", "cartilage restoration", "non-surgical and biologic interventions", "bear implant procedure", "orthopaedics", "surgery", "non-surgical", "keith w. chan, m.d.", "orthopaedic surgeon", "corbin wirta, pa-c", "physician assistant"], "services_offered": [{"name": "Sports Medicine", "category": "Sports Medicine", "description": "Comprehensive care for sports injuries and athletic performance.", "is_featured": true, "patient_fit": "Athletes and active individuals"}, {"name": "Shoulder & Elbow", "category": "Orthopaedics", "description": "Surgical and non-surgical treatment of shoulder and elbow conditions.", "is_featured": true, "patient_fit": null}, {"name": "ACL and PCL Reconstruction", "category": "Surgery", "description": "Reconstruction of anterior and posterior cruciate ligaments.", "is_featured": false, "patient_fit": "Patients with knee ligament injuries"}, {"name": "Arthroscopic Rotator Cuff Repair", "category": "Surgery", "description": "Minimally invasive repair of rotator cuff tears.", "is_featured": false, "patient_fit": "Patients with shoulder rotator cuff tears"}, {"name": "Hip Arthroscopy", "category": "Surgery", "description": "Minimally invasive surgery for hip conditions including femoroacetabular impingement and labral tears.", "is_featured": false, "patient_fit": "Patients with hip impingement or labral pathology"}, {"name": "Cartilage Restoration", "category": "Surgery", "description": "Procedures to restore articular cartilage in joints.", "is_featured": false, "patient_fit": "Patients with cartilage defects"}, {"name": "Non-Surgical and Biologic Interventions", "category": "Non-Surgical", "description": "Stem cell and PRP therapy for nonoperative and operative patients.", "is_featured": false, "patient_fit": "Patients seeking biologic treatment options"}, {"name": "BEAR Implant Procedure", "category": "Surgery", "description": "Bridge-Enhanced ACL Repair using the BEAR implant.", "is_featured": false, "patient_fit": "Patients with ACL tears"}], "short_description": "Board-certified orthopaedic surgeon specializing in sports medicine and minimally invasive arthroscopic surgery at California Pacific Orthopaedics.", "google_website_url": "https://calpacortho.com/team/keith-chan/?utm_source=GMBSocialClimb&utm_medium=Dr.KeithW.Chan", "google_primary_type": "Doctor", "provider_credentials": {"education": [], "providers": ["Keith W. Chan, M.D.", "Corbin Wirta, PA-C"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "3838 California St #715, San Francisco, CA 94118, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/100883923913532217882", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU16CwFnpcbhPmzyd8job2OODeqb1BgtP3f17lyS0Zed3QLEzk=s100-p-k-no-mo", "displayName": "Dr. Keith W. Chan"}], [{"uri": "https://maps.google.com/maps/contrib/110609341072210610221", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocLUqDkSBGsNP-WfZGt2h-aaudikOVCp0GVlQQx7L8hNTAqJvw=s100-p-k-no-mo", "displayName": "Estela Garcia-Murillo"}], [{"uri": "https://maps.google.com/maps/contrib/100883923913532217882", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU16CwFnpcbhPmzyd8job2OODeqb1BgtP3f17lyS0Zed3QLEzk=s100-p-k-no-mo", "displayName": "Dr. Keith W. Chan"}]]}'::jsonb, '2026-06-26T14:09:43.321358+00:00', 'dr-keith-w-chan', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('b0d8cc96-5d03-43e1-8872-87bc3b316b6f', NULL, 'SUNG HYUN KIM, M.D. Internal Medicine', 'Sung Hyun Kim, M.D. Internal Medicine is a client-centered internal medicine practice serving the communities of Los Angeles and Orange County. Dr. Kim emphasizes building strong, long-lasting bonds with each patient through sound medical advice, responsible diagnoses, and procedures. The practice offers a holistic approach to medicine, viewing each patient as a whole rather than a single symptom to be treated.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('42754786-2362-4c04-abd8-02b3da1e1b39', NULL, 'Chicken Soup Chinese Medicine', 'Chicken Soup Chinese Medicine and its practitioners offer Integrated Chinese Medicine consultations and treatment plans. Integrated Chinese Medicine incorporates all the pillars of Traditional Chinese Medicine (TCM) – acupuncture therapy, Chinese herbal medicine, moxibustion, cupping, diet and nutrition, exercise, acupressure/massage – within a framework of integrative medicine and integrative health. All the practitioners at Chicken Soup Chinese Medicine provide services in a caring environment that puts the person – not their illness – at the center. Through consultations and ongoing case management, relationships are developed with clients and practitioners across the country as well as here in San Francisco.', '2300 Sutter Street, Suite 203, San Francisco, CA, 94115', 'San Francisco', 'CA', '94115', '415-861-1101', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', TRUE, '{"email": "something@something.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chicken-soup-chinese-medicine-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chicken-soup-chinese-medicine-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chicken-soup-chinese-medicine-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chicken-soup-chinese-medicine-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chicken-soup-chinese-medicine-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2019-07-02T08:03:42.569905Z", "text": "I have had 20 surgeries throughout my life. I had suffered with chronic pain for 35 years. Dr Misha Cohen has far exceeded my expectations! She and her staff helped me change my life. It was my first acupuncture experience and I feel so fortunate and blessed to have a wonderful person in my corner like Dr Misha. Chicken Soup Chinese Medicine is a value to our community on so many levels. I recommend a treatment plan by Dr Misha. Once I started following the treatment plan, my health improved amazingly! Make sure you follow the entire treatment plan including herbs, supplements, topicals, etc. I never knew I was so allergic to red sauce! When I stopped eating it my stomach stopped hurting and feeling bloated. It was the small simple things that Dr Misha recommended I change that made stellar differences in my overall health. I visited two times a week for 90 days and followed the treatment plan. Now I visit about once or twice a month or more depending on my body pain. I still maintain my healthy lifestyle. Chicken Soup Chinese Medicine changed my life!", "author": "BayAerialDrone 2017", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105106589058782918777/reviews"}, {"date": "2016-09-30T00:02:08.593Z", "text": "I have been coming here for three years. Misha has expertly helped me through athletic injuries to stress relief and sleep deprivation to fertility treatments (it worked). Her staff is wonderful, bedside manner super caring and they manage to work with my erratic professional schedule in getting me last minute appointments. I had never had acupuncture before coming to chicken soup and came on recommendation from several friends. It is now in my regular practice and I love it.", "author": "Lauren Weymouth", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100948830305017680150/reviews"}, {"date": "2018-07-13T20:30:28.547Z", "text": "I am a first timer to  Dr Misha''s Chinese Medicine and Acupuncture Clinic. All I can say is, \"Wow, where have you been all my life!?\" I have suffered from chronic pain for decades from a trauma accident over thirty years ago and also a recent accident two years ago. Dr Misha Cohen and her staff are simply the best!! I am feeling  better for the first time in years. I look forward to seeing my changes in the future! Thank you so much!", "author": "Bay Aerial Drone", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100932317228785438227/reviews"}, {"date": "2021-02-20T01:00:22.442204Z", "text": "I definitely don’t appreciate the fact that I called and left a voicemail 2hrs before my appointment to tell them I couldn’t make it. And the fact that I wanted to get my treatment today made me feel bad too. Because it works but there are definitely other places to go. I’m a disabled veteran with numerous issues and one being my stomach. Now they said they didn’t get the message or see my name but I called because I respected their time and the VA dime. Even mentioned coming back in March just to make all appointments from Louisiana. But I definitely just called my doctor to complain of being fussed at for not being able to make it. Then whomever called ask someone in the background should they cancel my Tuesday appointment. Yes indeed fussing at me.. please cancel.. definitely putting this in my VA record has one of my weekly stressors..", "author": "monica jones", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/114393398978889486262/reviews"}, {"date": "2017-02-22T14:32:25.881Z", "text": "Dr. Misha and team are the best; a resource to be cherished, preserved and respected. I am grateful to have stumbled across Chicken Soup Chinese Medicine in 2012,  and continue to consult with for better health.", "author": "Kirsten Fletcher", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117867818892321997976/reviews"}], "website": "http://www.chickensoupchinesemedicine.com/", "location": {"latitude": 37.7857066, "longitude": -122.4384066}, "services": ["Acupuncture Therapy", "Chinese Herbal Medicine", "Moxibustion", "Cupping", "Diet and Nutrition Counseling", "Exercise Therapy", "Acupressure/Massage", "Telehealth Sessions", "Case Management"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Integrated Chinese Medicine", "detail": "Combines all pillars of TCM with integrative medicine and integrative health.", "category": "care"}, {"title": "Telehealth Available", "detail": "Chinese Medicine Telehealth sessions and alternative treatment options are offered.", "category": "convenience"}, {"title": "Caring for Veterans", "detail": "Proudly caring for veterans, as indicated by a TriWest badge.", "category": "care"}, {"title": "Comprehensive Care", "detail": "Personalized treatment and lifestyle programs based on Integrated Chinese Medicine.", "category": "care"}], "price_tier": "$$", "source_url": "http://www.chickensoupchinesemedicine.com/", "appointment": {"booking_note": "Request an Appointment", "appointment_url": "http://www.chickensoupchinesemedicine.com/contact", "new_patient_note": null, "phone_booking_available": null, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking clinic in San Francisco", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | acupuncture therapy | chinese herbal medicine | moxibustion | diet 