INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('dcb37335-30f9-4090-9618-701d52239223', NULL, 'NYC Health + Hospitals/Gotham Health, Judson', 'NYC Health + Hospitals/Gotham Health, Judson is a community health center located at 34 Spring Street, New York, NY 10012, offering primary care services. It is part of the NYC Health + Hospitals system, the largest municipal health system in the US. For appointments, call 1-844-692-4692.', '34 Spring Street, New York, NY 10012', 'New York', 'NY', '10012', '1-844-692-4692', ARRAY['English', 'Chinese']::text[], 'Hospital', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsgotham-health-judson-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsgotham-health-judson-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsgotham-health-judson-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsgotham-health-judson-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nyc-health-hospitalsgotham-health-judson-google-5.webp"], "rating": 4.6, "reviews": [{"date": "2025-10-23T02:35:43.041939803Z", "text": "Judson is a decent place for care but I got to say I''m not a fan of some of the staff. I''m seen at both Gouverneur and Judson but, it feels like 2 totally different places and I don''t mean that in a nice way. The heavyset hispanic nurse, is taking my vitals and asking me questions like why you here, but has Airpods on and is in middle of conversation. I say this because she never picks up her phone but after doing my vitals and asking questions goes straight into convo. Like, why am I being asked about myself when you are on the phone. For all I know she talks about me after I leave. I''m sure she does. While we at it, why was she in street clothes? Nearly everyone else has only scrubs but she and another nurse had on jeans.\n\nI never have these problems at Gouverneur. I may wait longer but it''s clearly a more professional spot. Think ill be transferring my care there for now on.", "author": "UR1 TRUKING", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/116722724932474466068/reviews"}, {"date": "2025-07-30T20:24:40.935222186Z", "text": "*Not a review of the staff, who are all 5 star and I adore!*\n\nIt''s been at least six months that several smoke alarms have been chirping low battery very loudly throughout this large office. I feel so much for the staff, especially reception, who has to listen to this all day. Could management disrespect their staff more than to go so long failing to do such a simple repair that would have such a big impact?  (Also not fun being a migraine patient and having to listen to this).\n\nAnd this is besides the fact that the smoke alarms haven''t been in operation, surely a fire code violation (hint hint).", "author": "Sara Nahshon", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/115808689870107528997/reviews"}, {"date": "2022-07-22T17:30:43.885850Z", "text": "On the behalf of my son, our experience with the Judson Health Clinic was nothing less than excellence. From the time we walked in to leaving, we were treated with respect and kindness. All the staff was attentive to our needs and made sure everything was in place for our visit. Dr. M. Baehser is an excellent doctor. Very detailed, kind, and humorous which made my 20-year-old son with Autism comfortable enough to talk and have an important conversation with him. I would recommend this office to anyone. And it''s located in one of the best areas in NYC. After, you can definitely get a bite to eat at one of the fine restaurants located in the area.", "author": "Carlene Wright", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102416360827227451881/reviews"}, {"date": "2021-10-05T17:48:41.098297Z", "text": "I found this clinic after doing research online for a Dr. who specializes in adolescents for my teenage son.  I could not be any happier than I am now after finding Dr. Baehser. . He takes the time to really get to know his patients and goes above and beyond to make sure their needs are met. My son also likes him tremendously and is super comfortable with him. The clinic itself is always spotless and the entire staff is always helpful and friendly. I feel very lucky to have found The Judson Health Clinic.", "author": "Amy Gavilanes", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117232635948458410663/reviews"}, {"date": "2019-05-29T23:52:18.316301Z", "text": "First time visiting a healthcare center and doctor in 2 years. Was pleasantly surprised by the great service and excellent staff. Was greeted warmly by Felicia the receptionist on arrival and she was very helpful with the paperwork.\n\nI saw Dr Rachel Bring who made me feel comfortable and at ease. She was easy to communicate with, listened and answered all my questions. I genuinely felt the doctor cared and wanted to help. Definitely recommend this practice.", "author": "Hitz Mistry", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113461460206217500618/reviews"}], "website": "https://www.nychealthandhospitals.org/locations/judson/", "location": {"latitude": 40.7215504, "longitude": -73.9958868}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": nu