INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('d073e6ef-d180-471f-a775-7d4853696f81', NULL, 'UT Physicians Multispecialty – Greens', 'This outpatient clinic in Houston is fully equipped and staffed with experts experienced in different specialties to provide comprehensive care for each patient. Unique to this location, the Greens clinic offers medication management and care coordination as valued-added services supported by a dedicated team including physicians, advanced care providers, clinical case managers, social workers, pharmacists, nurses, and medical assistants. In 2021, the American Heart Association recognized this clinic for 70% or greater high cholesterol control among its adult patients. Parking is free and the clinic serves adult and pediatric patients across multiple specialties.', '550 Greens Pkwy, Ste 150, Houston, TX 77067-4532', 'Houston', 'TX', '77067', '(713) 486-5600', ARRAY['English', 'Vietnamese']::text[], 'OB/GYN', FALSE, '{"fax": "(713) 486-5562", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ut-physicians-multispecialty-greens-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ut-physicians-multispecialty-greens-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ut-physicians-multispecialty-greens-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ut-physicians-multispecialty-greens-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ut-physicians-multispecialty-greens-google-5.webp"], "rating": 4.3, "reviews": [{"date": "2026-02-25T17:32:30.090491497Z", "text": "Ashley Thurston Rn is the most unprofessional and inconsiderate individual I have been in contact with while going to this location. She is unconcerned and sarcastic towards the needs and requests of patients. But other than that Doctors are great there and most nurses and management are helpful as well. You may have wait time but will get the information needed.", "author": "Parys Burks", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/107350950580921244148/reviews"}, {"date": "2026-04-09T00:57:19.496245526Z", "text": "I have never been made to feel so small and stupid by a provider. I am literally doing what I was told to when I was first diagnosed with hypothyroidism in 2016. I am also following up on the adenoma as I was told it would still needed it to be monitored with the DHEA-S fluctuations.\n\nPrior to this in 2016 I was treated with levothyroxine at that time for thyroid levels much more stable than the latest bloodwork. I was advised back when I started treatment it would need to be continuously monitored and might be something I was on for the rest of my life.  In 2020 it was one of the many health issues that had fell off with the plague which indirectly lead me to having worse issues come 2023 when my gallbladder shut down and put me into pre diabetes and liver failure at the same time.\n\nDuring this meeting she addressed my levels as “sub clinical”, despite me telling her my weight is the highest it has ever been, my hair is coming out in clumps, I’m cold all the time and gain weight despite having no appetite. Couple that with an unrelenting fatigue that has just exacerbated my sleep need from Narcolepsy leaving me sleeping 12+ hours a day. I literally feel like I am wasting away and all she seemed to care to say it couldn’t possibly be a thyroid issue. That treating it wouldn’t help my weight and try to push GLP-1s.\n\nWhat surprised me was the disrespect I received from this provider. I’ve seen endocrinologist before I’ve been on medications for this and other conditions before for endocrinology issues but somehow I am in the wrong for scheduling to see her with the scheduling department.", "author": "Sakura Tsunami", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/101048765377690310796/reviews"}, {"date": "2025-11-25T14:35:06.590425825Z", "text": "My daughter and I went together to have our yearly. Dr Ha Nguyen and all the nurses and front desk was amazing. Dr Nguyen was very down to earth and very concerned about me and my daughter’s health. She took her time with us. We were in and out. We will be returning next year. Such an amazing clinic.", "author": "Kimberly Williams", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103945116033089384935/reviews"}, {"date": "2026-01-03T01:01:03.146322917Z", "text": "Dr. Nguyen is amazing but I''m having to give a 2 star review because of my experience with trying to receive post op care.\nI''m absolutely disappointed in support staff at this clinic. I had a c-section on Dec. 16th and was supposed to have a 2 week follow up with my OB. I called and called and called trying to get an appointment, which for some reason you can''t make a c-section follow up with the receptionist it has to be done through a nurse? Every time they sent me to the nurses line I got the answering machine and never received a call back. Had to speak with a receptionist about this issue and she said she would leave a note with the nursing manager.\nGot a call from her and she explained all of the OBs had the ENTIRE week of off for new years holiday. Which is kind of absurd in my opinion. Then went on to say that the next week all of the OBs were booked. (So this would be past the 2 week point of when I was told by the HOSPITAL to be seen, have my bandage removed and inspected. I''m also still having clots which I mentioned to her. ) She claimed she was going to work on trying to find me an appointment at a different location of theirs and she would call back. Surprise surprise, never got a call back. As much as I really liked having Dr. Nguyen as my OB I will never come back to this place. Their staff doesn''t care about your wellbeing. I spoke with the Hospital I gave birth at and the RN there recommended I go to urgent care because its important that I be seen.\nIf you want to feel cared about. This is not the location to go to.", "author": "Nicole W", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/115284125525954314402/reviews"}, {"date": "2026-04-07T01:02:13.782688630Z", "text": "The suite 150 is not accessible from the main entrance! You have to go out and around the building to find it. I wish I knew that ahead.. found out only thanks to this sign posted on one of the other suites.\n\nGreat, they also have online interpreters (including my niche Czech language) to translate for you, that was really helpful.", "author": "Michaela Honková", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105647279148251960378/reviews"}], "website": "https://www.utphysicians.com/clinic/ut-physicians-multispecialty-greens/", "location": {"latitude": 29.947061500000004, "longitude": -95.4227142}, "services": ["Primary Care", "Family Medicine", "Internal Medicine", "Obstetrics and Gynecology (OB/GYN)", "Pediatrics", "Endocrinology, Diabetes, and Metabolism", "Cardiovascular Disease", "Psychiatry - Child and Adolescent", "Counseling - Adult", "Counseling - Child and Adolescent", "Nutrition/Dietetics", "Medication Management", "Care Coordination"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Multispecialty Care", "detail": "Fully equipped clinic with experts in multiple specialties providing comprehensive care for adult and pediatric patients.", "category": "care"}, {"title": "Free Parking", "detail": "Parking is free at the UT Physicians Greens Clinic.", "category": "convenience"}, {"title": "Medication Management & Care Coordination", "detail": "Offers medication management and care coordination with a team including physicians, advanced care providers, case managers, social workers, pharmacists, and nurses.", "category": "care"}, {"title": "AHA High Cholesterol Control Recognition", "detail": "Recognized by the American Heart Association in 2021 for achieving 70% or greater high cholesterol control among adult patients.", "category": "care"}, {"title": "Evening and Saturday Hours", "detail": "Open Tuesday and Thursday until 7 p.m. and Saturday from 8 a.m. to 12 p.m.", "category": "convenience"}, {"title": "24-Hour Nurse Triage Line", "detail": "After-hours service available via a 24-hour nurse triage line at 713-486-UTRN (8876).", "category": "care"}], "price_tier": "$$", "source_url": "https://www.utphysicians.com/clinic/ut-physicians-multispecialty-greens/?utm_source=extnetwork&utm_medium=YextListings&utm_campaign=56738", "appointment": {"booking_note": null, "appointment_url": "https://www.utphysicians.com/request-an-appointment/?preferredclinic_name=UT+Physicians+Multispecialty+-+Greens", "new_patient_note": "New patients: please check the patient info tab for documentation to complete before arriving for your first appointment.", "phone_booking_available": null, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese OB/GYN clinic in Houston, TX", "search_text": "ob/gyn | obgyn | obstetrics | gynecology | women''s health | prenatal | pregnancy | sản phụ khoa | bác sĩ sản | khám thai | 산부인과 | 여성병원 | 妇产科 | 产科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | primary care | family medicine | internal medicin