, "category": "Primary Care", "description": "Empathetic, affirming care for the transgender community in a safe, judgment-free space.", "is_featured": true, "patient_fit": "Transgender and gender-diverse individuals seeking affirming healthcare."}, {"name": "Preventative Care", "category": "Primary Care", "description": "Preventive health services to maintain wellness and catch issues early.", "is_featured": false, "patient_fit": "Patients focused on staying healthy and preventing disease."}, {"name": "Mental Health", "category": "Primary Care", "description": "Mental health support integrated into primary care.", "is_featured": false, "patient_fit": "Patients needing mental health care in a primary care setting."}, {"name": "Addiction Treatment", "category": "Addiction", "description": "Comprehensive addiction treatment for substance abuse including alcohol, opioids, benzos, and more.", "is_featured": true, "patient_fit": "Individuals struggling with substance use disorders seeking recovery."}, {"name": "Medication Assisted Therapy", "category": "Addiction", "description": "Medication-assisted treatment using Suboxone, Methadone, Sublocade, Subutex, Vivitrol, and more.", "is_featured": false, "patient_fit": "Patients needing medication support for opioid or alcohol addiction."}, {"name": "Outpatient Treatment", "category": "Addiction", "description": "Outpatient addiction treatment programs.", "is_featured": false, "patient_fit": "Individuals who need structured treatment while living at home."}, {"name": "Alcohol Addiction Treatment", "category": "Addiction", "description": "Specialized treatment for alcohol addiction.", "is_featured": false, "patient_fit": "Individuals seeking help for alcohol use disorder."}, {"name": "Opioid Addiction Treatment", "category": "Addiction", "description": "Treatment for opioid addiction including heroin, morphine, oxycontin, and more.", "is_featured": false, "patient_fit": "Individuals struggling with opioid dependence."}, {"name": "Gender Affirming Care", "category": "Primary Care", "description": "Gender-affirming care services.", "is_featured": false, "patient_fit": "Transgender and gender-diverse individuals."}, {"name": "Pediatric, Adult & Geriatric Care", "category": "Primary Care", "description": "Care for patients of all ages, from children to seniors.", "is_featured": false, "patient_fit": "All age groups."}, {"name": "Care Coordination", "category": "Primary Care", "description": "Coordination of care across specialists and services.", "is_featured": false, "patient_fit": "Patients needing help navigating the healthcare system."}, {"name": "Rapid Tests", "category": "Primary Care", "description": "On-site rapid testing services.", "is_featured": false, "patient_fit": "Patients needing quick test results."}, {"name": "Heart Health", "category": "Primary Care", "description": "Cardiovascular health management.", "is_featured": false, "patient_fit": "Patients with heart health concerns."}, {"name": "Patient Advocacy", "category": "Primary Care", "description": "Advocacy support for patients navigating their healthcare journey.", "is_featured": false, "patient_fit": "Patients needing help understanding and accessing care."}], "short_description": "Sequoia MD provides direct, personalized primary care and addiction treatment in Sacramento, offering same-day appointments, telemedicine, and transparent membership pricing without insurance.", "google_website_url": "https://sequoiamd.com/", "google_primary_type": "Doctor", "provider_credentials": {"education": [], "providers": ["Dr. Justin Altschuler", "Kristin", "Ruby"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "accepting_new_patients": true, "google_business_status": "OPERATIONAL", "google_formatted_address": "5025 J St #206, Sacramento, CA 95819, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/107303454346215927801", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXNrv8_NWwtRMfDAnw91oFSS0jDEg5jlIYX-1bsnfjazvO_J4BC=s100-p-k-no-mo", "displayName": "Sequoia MD"}], [{"uri": "https://maps.google.com/maps/contrib/111744258308447841414", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocLCp_tDQrpmuwaaC7pdLclEKApAcgQqKXxOb4x9R-0XHvBWrg=s100-p-k-no-mo", "displayName": "Ruby Zepeda Flores"}], [{"uri": "https://maps.google.com/maps/contrib/111744258308447841414", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocLCp_tDQrpmuwaaC7pdLclEKApAcgQqKXxOb4x9R-0XHvBWrg=s100-p-k-no-mo", "displayName": "Ruby Zepeda Flores"}], [{"uri": "https://maps.google.com/maps/contrib/107303454346215927801", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXNrv8_NWwtRMfDAnw91oFSS0jDEg5jlIYX-1bsnfjazvO_J4BC=s100-p-k-no-mo", "displayName": "Sequoia MD"}], [{"uri": "https://maps.google.com/maps/contrib/107303454346215927801", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXNrv8_NWwtRMfDAnw91oFSS0jDEg5jlIYX-1bsnfjazvO_J4BC=s100-p-k-no-mo", "displayName": "Sequoia MD"}]]}'::jsonb, '2026-06-26T12:30:21.470151+00:00', 'sequoia-md', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('06d12c88-3978-4cea-a6d7-1e1144ee7002', NULL, 'Piedmont Eastside Medical Center', 'Piedmont Eastside Medical Center is a 305-bed, multi-campus system serving Gwinnett and surrounding counties for over 40 years. With two campuses in Snellville, the hospital offers comprehensive medical, surgical, and diagnostic services, including 24/7 emergency care, bariatric surgery, behavioral health, cancer care, heart care, maternity with neonatal intensive care, neurosciences, orthopedics, rehabilitation, robotic surgery, and urgent care.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('1617c8dc-2a8b-48f4-880a-d678c17cb51e', NULL, 'San Jose Behavioral Health', 'San Jose Behavioral Health is a supportive and nurturing environment providing clinically superior services to adults and adolescents struggling with mental health or behavioral health issues in the Silicon Valley area and surrounding communities. Our 133-bed inpatient facility combines the clinical sophistication of a large program with the personalized attention of a small facility. Patients work closely with board-certified psychiatrists, internal medicine physicians, mental health therapists, registered nurses, activity therapists, and mental health technicians in a dynamic healing community. Upon completion, each patient leaves with a comprehensive aftercare plan to maintain progress.', '455 Silicon Valley Boulevard, San Jose, CA 95138', 'San Jose', 'CA', '95138', '(833) 231-6800', ARRAY['English', 'Vietnamese']::text[], 'Mental Health', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-jose-behavioral-health-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-jose-behavioral-health-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-jose-behavioral-health-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-jose-behavioral-health-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-jose-behavioral-health-google-5.webp"], "rating": 2.3, "reviews": [{"date": "2026-06-10T08:59:43.626647922Z", "text": "Consistent with other reviews, it was nearly impossible to get in contact with anyone at this facility. It felt like a miracle on the rare occasion someone would answer the phone. The receptionists that worked during the visiting hours were great. The lack of communication from the facility should be unacceptable.\n\nEdit: responding to your comment - if it’s crucial for you to understand more, then please call me. Multiple contacts at this facility have my contact information.", "author": "Shannon Owings", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/110473012452507325044/reviews"}, {"date": "2025-11-13T19:25:41.397777225Z", "text": "I was sad seeing all the negative reviews. My son was sent to SJBH ( minor department) Pacifica to be exact and we had a great experience. Taylor the social worker was so kind, helpful, and responsive. She truly was God sent she did everything to help my son during this difficult time for him and my family. Taylor and the team continued to keep me informed on my son''s behavior, medication, and overall needs. Doctor GG and nurse Angela, Ryan, and Walter were also great people who helped my son. My son still says Ryan deserves a raise. Hopefully he gets one. Everyone was compassionate, nurturing, and supportive. I personally can say nothing but good things even for the receptionist and other staff that helped my son and my family. My son stayed here for 2 weeks. I hope whoever reads this review understands it takes a lot of trust for a parent to give to other adults to look after your child. And I honestly felt my son was safe in their care. I thank everyone for the help and support you gave my son. I truly pray that he continues to get better as he moves on from Sunol Hills to a PHP program closer to our home. Thank you SJBH and staff thank you Taylor for caring and showing my son compassion. I am forever grateful for you all.", "author": "Larissa Hernandez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108555114118259120018/reviews"}, {"date": "2026-05-25T02:13:57.612238362Z", "text": "I would give it a lower review if I could. Roaches in cafeteria, horrible food, horrible snacks, uncomfy rooms, cold rooms, bad markers, hygiene, calls not returned, bad patient care, neglect, ankle monitors that makes it feel like a prison, full strip down at entry no matter age, invasion of all privacy and dignity. staff only checks on you to add it on their little ipad. My friend hurt herself in there and staff didnt notice the obvious. one of my friends was getting abused at home and they sent him back anyways. Horrible place, shitty therapist and social workers. BHAs are the only good ones but they cant do much. units should be separated by age not how dangerous. 13 year olds shouldnt be with  16-17 yr olds. But also the super dangerous or like at risk should be watched accordingly.", "author": "Felix Gillespie", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/111760339110068258328/reviews"}, {"date": "2026-03-21T22:10:22.760704756Z", "text": "My son is in this horrible place , you can not get through to talk to doctors are get any answers .\nCalling 10 times a day for 5 days , no return calls ,no one answers !\nSo frustrating when your trying to get some answers or to relay health care like medications and what’s been going on with him .\nI have reached out also multiple times a day trying to get through to his social worker to set up alternate visitation hours . I get up at 2 am , there visiting hours during the week are from 8:15 to 9:15 pm .\nHow crazy are these hours .\nThis place is not there to help your family members they are there to over medicate and keep your family members coming back so they have jobs period !!!!!\nThey are not trying g to help anyone but themselves …\nIf you can get your family member out of this HORRIBLE place do it and do it fast !\nThey should be shut down and I will be filing a formal complaint with the city state , Federal , agencies that should be overseeing these places !!!!\nThe receptionist in the front is the best part about this place. She was very friendly and could find a way better place to work than this place .", "author": "gaston daugherty", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/104876445761370419626/reviews"}, {"date": "2026-05-05T12:55:03.849814288Z", "text": "Terrible experience. Its a cold prison. From my experience a lot of people who end up there didn''t even expect to end up there and didn''t even know what they were signing and end up getting 5150''d. And there''s weekly evaluation to see if you qualify to leave but you have to give specific answers and they don''t tell you what those answers are. And turns out THEY DONT even have a reason to KEEP you there. Me and a stranger compared our evaluation forms that was given to us and it said the EXACT same thing. The \"reason\" for being admitted: \"Potential psychosis\". And the mental health \"reason\" to stay confined without return home \"N/A\".\n\nAnd it was the exact same and we had completely different stories of how we ending up in there. Its like the person who makes these \"evaluation \" forms just copy & pastes a template with no concern of the patient.", "author": "iStanKnowledge&Reason", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/111108182913106986076/reviews"}], "website": "https://www.sanjosebh.com/", "location": {"latitude": 37.2489656, "longitude": -121.77442429999999}, "services": ["Adolescent Inpatient", "Adult Inpatient", "Adult Outpatient (IOP/PHP)", "Adolescent IOP", "Connections – Santa Cruz", "Continuing Care", "Recreation Therapy", "Telehealth", "Veterans Affairs"], "insurance": {"notes": "Call for free insurance verification. Most insurance accepted.", "accepts_medicaid": null, "accepts_medicare": true, "accepted_networks": ["Blue Cross Blue Shield", "Cigna", "Kaiser Permanente", "Magellan Health", "Medicare", "Optum"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Open 24/7", "detail": "Walk-ins are welcome 24 hours a day, 7 days a week for immediate care.", "category": "access"}, {"title": "Most Insurance Accepted", "detail": "Accepts a wide range of insurance plans including Medicare, Blue Shield, Cigna, Kaiser Permanente, and more.", "category": "insurance"}, {"title": "Free Insurance Verification", "detail": "Call to verify your insurance coverage at no cost.", "category": "insurance"}, {"title": "Joint Commission Accredited", "detail": "Holds the Gold Seal of Approval from The Joint Commission for quality care.", "category": "quality"}, {"title": "133-Bed Facility", "detail": "A comprehensive inpatient mental health hospital with serene views and a healing environment.", "category": "care"}, {"title": "Board-Certified Staff", "detail": "Care provided by board-certified psychiatrists, physicians, therapists, and nurses.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.sanjosebh.com/?utm_source=Google&utm_medium=organic&utm_campaign=listing&utm_term=brand", "appointment": {"booking_note": "Walk-ins welcome 24/7. Call (833) 231-6800 for free insurance verification.", "appointment_url": "https://www.sanjosebh.com/admissions/pre-admission/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking hospital in San Jose, CA", "search_text": "mental health | psychiatry | psychiatrist | psychology | therapist | counseling | depression | anxiety | tâm lý | tâm thần | trầm cảm | 정신과 | 심리상담 | 心理医生 | 精神科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | adolescent inpatient | adult inpatient | adult outpatient (iop/php) | adolescent i