INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('a5ae20f4-d9f3-4f8d-a370-2ff100bc53bc', NULL, 'Clínica Médica Mundo Latino', 'Clinica Mundo Latino is dedicated to providing compassionate and accessible primary care services for individuals and families. Their bilingual team focuses on preventive care, chronic disease management, wellness exams, and urgent visits, ensuring personalized attention in a culturally respectful environment. They proudly serve the Latino community with quality healthcare that prioritizes health, trust, and convenience, offering over 200 services and medical procedures including an onsite lab and minor surgeries.', '5945 Bellaire Blvd, Ste F Houston, Texas 77081', 'Houston', 'TX', '77081', '(832)251-8309', ARRAY['English', 'Spanish', 'Korean']::text[], 'Primary Care', FALSE, '{"email": "info@clinicamundolatino.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-medica-mundo-latino-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-medica-mundo-latino-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-medica-mundo-latino-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-medica-mundo-latino-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-medica-mundo-latino-google-5.webp"], "rating": 5, "reviews": [{"date": "2025-06-14T00:29:39.322939Z", "text": "Nice caring ladies! They gave me a prescription discount and service discount and second final visit Sunday no extra charge! They really care about your needs and financial situation. Come get serviced here! I recommend", "author": "Zamira Vanegas", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106231890374046199758/reviews"}, {"date": "2025-05-14T14:30:26.242712Z", "text": "Great clean place,\nStaff was kind the entire time!", "author": "Marlene Ramirez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100715126725956346453/reviews"}, {"date": "2026-06-23T11:42:54.974917747Z", "text": "Great local clinic with a welcoming and professional environment. The place looks clean, organized, and focused on serving the community with care and respect. It’s great to see a medical clinic that supports the Latino community and makes people feel comfortable. Highly recommended.", "author": "Harold Rubi", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109828987861695497926/reviews"}, {"date": "2026-06-23T03:04:00.986768111Z", "text": "“Excellent clinic with a caring and professional staff. The healthcare providers were knowledgeable, attentive, and made me feel comfortable throughout my visit. Clean facility and efficient service. Highly recommended!”", "author": "Kevin Castellanos Dominguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107205417389207795436/reviews"}, {"date": "2026-06-23T01:29:04.957318676Z", "text": "FORMIDABLE 💪", "author": "KAMANKOLA OFICIAL", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109525548961179783270/reviews"}], "website": "http://clinicamundolatino.com", "location": {"latitude": 29.704766399999997, "longitude": -95.48643419999999}, "services": ["Primary Family Doctor", "Follow-up Care", "Minor Surgeries", "Preventive Exams", "Laboratory Tests & Diagnosis", "Weight Loss & Vitamin Shots", "DOT/CDL Exams"], "insurance": {"notes": "W