INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('ca2f0f8b-7d2b-47af-a4b1-78cbe6c0e2aa', NULL, 'HOPE Clinic', 'HOPE Clinic is a full-service Federally Qualified Health Center (FQHC) offering evidence-based and data-driven healthcare to the Greater Houston community. The clinic believes healthcare should be accessible and affordable, accepting multiple payment options and working with those who are underinsured or uninsured. Recognized as a Patient-Centered Medical Home (PCMH), it provides comprehensive, coordinated care designed around the patient. With a focus on cultural competency and language access, the clinic serves patients from over 90 countries and provides services in over 30 languages, ensuring quality healthcare is delivered in a culturally and linguistically appropriate manner.', 'HOPE Beltway', 'Houston', 'TX', '77036', '(713) 773-0803', ARRAY['Vietnamese', 'Spanish', 'Burmese', 'English', 'Chinese', 'Arabic']::text[], 'Community Health Center', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hope-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hope-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hope-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hope-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hope-clinic-google-5.webp"], "rating": 3.6, "reviews": [{"date": "2026-03-31T21:00:44.063660590Z", "text": "Dr. H. Nguyen is an exceptional pediatrician. She is very caring and listens to our concerns and is always helpful. She looks at all the information and continually tries until things get better. We feel incredibly fortunate to have found this pediatrician. She takes the time to listen, explain things thoroughly, and never make us feel rushed or dismissed. What stands out most is her ability to connect with our two kids. She balances professionalism with kindness in a way that builds real trust. Thank you Dr. Nguyen for being such a wonderful doctor and human being and always go over and beyond for our family.", "author": "Tatiana McBride", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100310059357449079081/reviews"}, {"date": "2026-04-01T02:24:50.259365671Z", "text": "Dr. Nguyen has been our pediatrician for years. As a mom, I worry about everything, and having her as our pediatrician has given me so much peace of mind. She’s incredibly kind, patient, and just easy to talk to. I never feel silly asking questions, and she always takes the time to really listen. Visits are calm and positive instead of stressful. I can tell she truly cares about her patients and their families. We’re so grateful we found her. It is very hard to build real connection with doctors these days and with Dr. Nguyen, I know my whole family is in good hands. Thank you, Dr. Nguyen!", "author": "Michelle SG", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114939113055177635841/reviews"}, {"date": "2026-05-21T19:42:50.006940037Z", "text": "Dr. [Name] was very professional, caring, and took the time to listen to all of my concerns. The staff was friendly, and the office was clean and organized. I didn’t feel rushed during my appointment, and everything was explained clearly. I highly recommend this doctor to anyone looking for quality care.”", "author": "Omar Alnaseri", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102923431161801715865/reviews"}, {"date": "2026-05-11T14:50:47.404337220Z", "text": "Gloria, not sure who she is since I only saw her name badge, was extremely rude and unprofessional. She was loudly arguing and practically yelling at the front desk staff right in front of patients, which made the entire environment uncomfortable and chaotic. It’s shocking to see someone act that way in a professional setting, especially around patients. The front desk staff, however, were very kind and handled the situation much more professionally than she did.", "author": "Oscar Sanchez", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/101893484853373881529/reviews"}, {"date": "2026-01-24T19:43:35.312113639Z", "text": "I am writing this review with a lot of gratitude and well being\nThe clinical staff is well trained and knowledgeable\nI received the most amazing and accurate medical treatment.\nI want to congratulate  the entire front desk staff specially Mr Habit.   He is very helpful considerate and most importantly CORDIAL\nconsider your future medical care and well being at HOPE CLINIC ON CORPORATE\nHOUSTON\nGracias a todo el personal medico de la clinica\nEl servicio SIEMPRE es SUPER AMABLE  y conocedor\nGracias NUEVAMENTE y FELICIDADES\nPor proveer  un excellente servicio medico", "author": "Rocio Klock", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101913891814834494979/reviews"}], "website": "http://www.hopechc.org/", "location": {"latitude": 29.703575599999997, "longitude": -95.5511289}, "services": ["Adult Medicine", "Pediatric Care", "Women''s Health (OB/GYN)", "Behavioral Health", "Dental Care", "Vision Care", "Laboratory Services", "Pharmacy"], "insurance": {"notes": "Accepts multiple payment options and works with those who are underinsured or uninsured.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Federally Qualified Health Center (FQHC)", "detail": "HOPE Clinic is a full-service FQHC offering affordable, evidence-based care to the Greater Houston community.", "category": "care"}, {"title": "Over 30 Languages Served", "detail": "Healthcare is provided in a culturally and linguistically appropriate manner in over 30 languages, with interpretation services available.", "category": "culture"}, {"title": "Patient-Centered Medical Home (PCMH)", "detail": "Recognized by NCQA as a PCMH, providing coordinated, accessible, and comprehensive patient-centered care.", "category": "care"}, {"title": "Accepts Multiple Payment Options", "detail": "Accepts multiple payment options and works with underinsured and uninsured patients to ensure affordable care.", "category": "insurance"}, {"title": "Comprehensive Services", "detail": "Offers adult medicine, pediatrics, women''s health, behavioral health, dental, vision, laboratory, and pharmacy services.", "category": "care"}], "price_tier": "$", "source_url": "http://www.hopechc.org/", "appointment": {"booking_note": "Book an appointment online or call (713) 773-0803.", "appointment_url": "https://www.hopechc.org/book-appointment", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese speaking hospital in Houston, TX", "search_text": "community health center | community health | fqhc | sliding scale | medicaid | medicare | low cost | trung tâm y tế cộng đồng | 커뮤니티 헬스 | 社区医疗中心 | vietnamese | tiếng việt | người việt | bác sĩ việt | spanish | burmese | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | arabic | adult medicine | pediatric care | women''s health (ob/gyn) | behavioral health | dental care | vision care | laboratory services | pharmacy | primary care | women''s health | dental | vision | diagnostic | dr. huda tsihira-sengal | physician | dr. khoa pham | dr. krenek | stephanie gonzalez | front desk", "google_types": ["medical_clinic", "medical_center", "hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 510, "team_members": [{"name": "Dr. Huda Tsihira-Sengal", "role": "Physician", "bio_snippet": "Praised by patients for clear explanations and thorough care during baby''s first health exam.", "languages_spoken": []}, {"name": "Dr. Khoa Pham", "role": "Physician", "bio_snippet": "Praised for treating patients with great respect and patience, especially children with special needs.", "languages_spoken": []}, {"name": "Dr. Krenek", "role": "Physician", "bio_snippet": "Praised for taking time to see children and answer all questions.", "languages_spoken": []}, {"name": "Stephanie Gonzalez", "role": "Front Desk", "bio_snippet": "Praised for being amazing and ensuring patients take the best care for themselves and their children.", "languages_spoken": []}], "language_note": "HOPE Clinic serves patients from over 90 countries and provides services in over 30 languages, with a focus on cultural competency and language access. The clinic''s website is available in English, Arabic, Spanish, Burmese, Vietnamese, and Chinese, reflecting its commitment to serving diverse immigrant and Asian communities.", "open_saturday": true, "quality_score": 95, "working_hours": {"friday": "8:00 AM – 5:00 PM", "monday": "8:00 AM – 7:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 7:00 PM", "saturday": "9:00 AM – 5:00 PM", "thursday": "8:00 AM – 7:00 PM", "wednesday": "8:00 AM – 7:00 PM"}, "gallery_images": ["https://static.wixstatic.com/media/d758d1_15dc7161a8714ab3b1b9c52e4502d64c~mv2.webp", "https://static.wixstatic.com/media/14af171bc0f94d2cb62a59465ab1330a.jpg", "https://static.wixstatic.com/media/d758d1_39f62a8f63a941419dcd281be6d25256~mv2.webp", "https://static.wixstatic.com/media/d758d1_25664d77951e4a3f80dd05fd5418ebbbf000.jpg", "https://static.wixstatic.com/media/d758d1_d442025a7fe94bcf9e17e8d3a43ca24f~mv2.jpg", "https://static.wixstatic.com/media/d758d1_efd78a4f339a4e21989ebc8c69f11f71~mv2.jpg", "https://static.wixstatic.com/media/d758d1_5ffd6fd6ee5b4af39b4305349a74d09c~mv2.jpeg", "https://static.wixstatic.com/media/d758d1_d9a5d5cdf65140a487f5608aa8c2bd9a~mv2.jpeg", "https://static.wixstatic.com/media/d758d1_6d46bc969c574cd9b2b76d460d00ce69~mv2.jpeg", "https://static.wixstatic.com/media/d758d1_b56ea7c8c35c4a41a7311eabe81bf758~mv2.jpeg", "https://static.wixstatic.com/media/d758d1_4c96fe17a64149d09dbcc006dc21b05a~mv2.jpeg", "https://static.wixstatic.com/media/d758d1_b1dbe65348b64f89918e77bdb6f61e0b~mv2.jpeg", "https://static.wixstatic.com/media/d758d1_f37554587ec5422699decbc32b50bdbf~mv2.jpg"], "review_profile": {"rating": 3.6, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 3, "sentiment": "Positive", "summary_quote": "Multiple reviewers praise Dr. Nguyen''s thoroughness, kindness, and ability to connect with patients."}, {"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Several reviews highlight the friendly and knowledgeable staff, with special mentions of front desk professionalism."}, {"theme": "Communication", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients consistently note that Dr. Nguyen takes time to listen and explain things clearly without rushing."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "Reviews mention the clinic being clean and organized, contributing to a positive experience."}, {"theme": "Staff Behavior", "mentions": 1, "sentiment": "Negative", "summary_quote": "One review describes an incident of unprofessional behavior by a staff member, contrasting with otherwise positive feedback about the team."}], "summary": "Overall, patients appreciate the caring and professional approach of Dr. Nguyen and the clinical staff, though there are isolated concerns about staff behavior.", "review_count": 510, "concern_themes": [], "positive_themes": ["Friendly and professional staff", "Thorough explanations from providers", "Respectful and patient care", "Welcoming environment"], "featured_reviews": [{"date": "2026-03-31T21:00:44.063660590Z", "text": "Dr. H. Nguyen is an exceptional pediatrician. She is very caring and listens to our concerns and is always helpful. She looks at all the information and continually tries until things get better. We feel incredibly fortunate to have found this pediatrician. She takes the time to listen, explain things thoroughly, and never make us feel rushed or dismissed. What stands out most is her ability to connect with our two kids. She balances professionalism with kindness in a way that builds real trust. Thank you Dr. Nguyen for being such a wonderful doctor and human being and always go over and beyond for our family.", "author": "Tatiana McBride", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100310059357449079081/reviews"}, {"date": "2026-04-01T02:24:50.259365671Z", "text": "Dr. Nguyen has been our pediatrician for years. As a mom, I worry about everything, and having her as our pediatrician has given me so much peace of mind. She’s incredibly kind, patient, and just easy to talk to. I never feel silly asking questions, and she always takes the time to really listen. Visits are calm and positive instead of stressful. I can tell she truly cares about her patients and their families. We’re so grateful we found her. It is very hard to build real connection with doctors these days and with Dr. Nguyen, I know my whole family is in good hands. Thank you, Dr. Nguyen!", "author": "Michelle SG", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114939113055177635841/reviews"}, {"date": "2026-05-21T19:42:50.006940037Z", "text": "Dr. [Name] was very professional, caring, and took the time to listen to all of my concerns. The staff was friendly, and the office was clean and organized. I didn’t feel rushed during my appointment, and everything was explained clearly. I highly recommend this doctor to anyone looking for quality care.”", "author": "Omar Alnaseri", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102923431161801715865/reviews"}, {"date": "2026-05-11T14:50:47.404337220Z", "text": "Gloria, not sure who she is since I only saw her name badge, was extremely rude and unprofessional. She was loudly arguing and practically yelling at the front desk staff right in front of patients, which made the entire environment uncomfortable and chaotic. It’s shocking to see someone act that way in a professional setting, especially around patients. The front desk staff, however, were very kind and handled the situation much more professionally than she did.", "author": "Oscar Sanchez", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/101893484853373881529/reviews"}, {"date": "2026-01-24T19:43:35.312113639Z", "text": "I am writing this review with a lot of gratitude and well being\nThe clinical staff is well trained and knowledgeable\nI received the most amazing and accurate medical treatment.\nI want to congratulate  the entire front desk staff specially Mr Habit.   He is very helpful considerate and most importantly CORDIAL\nconsider your future medical care and well being at HOPE CLINIC ON CORPORATE\nHOUSTON\nGracias a todo el personal medico de la clinica\nEl servicio SIEMPRE es SUPER AMABLE  y conocedor\nGracias NUEVAMENTE y FELICIDADES\nPor proveer  un excellente servicio medico", "author": "Rocio Klock", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101913891814834494979/reviews"}]}, "review_summary": "Overall, patients appreciate the caring and professional approach of Dr. Nguyen and the clinical staff, though there are isolated concerns about staff behavior.", "about_highlight": "HOPE Clinic is a full-service Federally Qualified Health Center (FQHC) offering evidence-based and data-driven healthcare to the Greater Houston community. The clinic believes healthcare should be accessible and affordable, accepting multiple payment options and working with those who are underinsured or uninsured. Recognized as a Patient-Centered Medical Home (PCMH), it provides comprehensive, coordinated care designed around the patient. With a focus on cultural competency and language access, the clinic serves patients from over 90 countries and provides services in over 30 languages, ensuring quality healthcare is delivered in a culturally and linguistically appropriate manner.", "appointment_url": "https://www.hopechc.org/book-appointment", "google_maps_url": "https://maps.google.com/?cid=16065781099048990944&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJI49khsXCQIYR4Pj_F8oe9d4", "quality_missing": ["insurance"], "search_keywords": ["community health center", "community health", "fqhc", "sliding scale", "medicaid", "medicare", "low cost", "trung tâm y tế cộng đồng", "커뮤니티 헬스", "社区医疗中心", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "spanish", "burmese", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "arabic", "adult medicine", "pediatric care", "women''s health (ob/gyn)", "behavioral health", "dental care", "vision care", "laboratory services", "pharmacy", "primary care", "women''s health", "dental", "vision", "diagnostic", "dr. huda tsihira-sengal", "physician", "dr. khoa pham", "dr. krenek", "stephanie gonzalez", "front desk"], "cultural_context": "HOPE Clinic serves patients from over 90 countries and provides services in over 30 languages, with a focus on cultural competency and language access. The clinic''s website is available in English, Arabic, Spanish, Burmese, Vietnamese, and Chinese, reflecting its commitment to serving diverse immigrant and Asian communities.", "services_offered": [{"name": "Adult Medicine", "category": "Primary Care", "description": "Key to maintaining overall health and managing a wide range of medical conditions throughout adulthood.", "is_featured": true, "patient_fit": null}, {"name": "Pediatric Care", "category": "Primary Care", "description": "Essential for monitoring and supporting the health and development of children from infancy through adolescence.", "is_featured": true, "patient_fit": null}, {"name": "Women''s Health (OB/GYN)", "category": "Women''s Health", "description": "Vital for addressing the unique medical needs of women at every stage, and management of common conditions.", "is_featured": true, "patient_fit": null}, {"name": "Behavioral Health", "category": "Behavioral Health", "description": "Specialized services include treatment and medication management, along with counseling, all provided in multiple languages.", "is_featured": true, "patient_fit": null}, {"name": "Dental Care", "category": "Dental", "description": "Routine check-ups, cleanings, and preventive treatments to maintain optimal oral health.", "is_featured": true, "patient_fit": null}, {"name": "Vision Care", "category": "Vision", "description": "Thorough eye exams to assess vision and eye health, prescription eyewear fittings.", "is_featured": true, "patient_fit": null}, {"name": "Laboratory Services", "category": "Diagnostic", "description": "Accurate and timely diagnostic testing to support your health and wellness.", "is_featured": true, "patient_fit": null}, {"name": "Pharmacy", "category": "Pharmacy", "description": "Comprehensive services to meet your medication needs, including prescription fulfillment.", "is_featured": true, "patient_fit": null}], "short_description": "HOPE Clinic is a community health center in Houston, TX, providing affordable, comprehensive healthcare in a culturally and linguistically appropriate manner.", "google_website_url": "http://www.hopechc.org/", "google_primary_type": "Medical Clinic", "provider_credentials": {"education": [], "providers": ["Dr. Huda Tsihira-Sengal", "Dr. Khoa Pham", "Dr. Krenek", "Stephanie Gonzalez"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "accepting_new_patients": true, "google_business_status": "OPERATIONAL", "google_formatted_address": "7001 Corporate Dr Ste 120, Houston, TX 77036, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/104936119872691608796", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUQMq1nWX1Q98ioifsjXzvBEA-K_CFvOBexHLPRcdHynLCTMwM=s100-p-k-no-mo", "displayName": "HOPE Clinic - Main Community Health Center"}], [{"uri": "https://maps.google.com/maps/contrib/112813822105189743601", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUHi5sEZGAr80eoAK_MjFVQTwb682d-GWJH5ttNGmabYR1TNheOEA=s100-p-k-no-mo", "displayName": "Soe Moe"}], [{"uri": "https://maps.google.com/maps/contrib/110634323862891725901", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX7iGBCaz_BO9JHPAP-n_P3FYhdSN8MLzvdbrlR7OfyQQNOYG35=s100-p-k-no-mo", "displayName": "Lina Riano"}], [{"uri": "https://maps.google.com/maps/contrib/112813822105189743601", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUHi5sEZGAr80eoAK_MjFVQTwb682d-GWJH5ttNGmabYR1TNheOEA=s100-p-k-no-mo", "displayName": "Soe Moe"}], [{"uri": "https://maps.google.com/maps/contrib/111576323714006884402", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocLI_Y2QN_HDAre_WiCaqSyEVtQjWl5-m2LAMmCTDvRFQcGwRg=s100-p-k-no-mo", "displayName": "Keyla Godinez"}]]}'::jsonb, '2026-06-25T20:22:39.958421+00:00', 'hope-clinic', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('376441ff-0536-4df9-bdbe-59c91528e210', NULL, 'HCA Houston Healthcare Kingwood', 'HCA Houston Healthcare Kingwood is a full-service, 451-bed acute care hospital proudly serving the Northeast Houston community for over 30 years. As part of HCA Houston Healthcare, a family of 13 hospitals serving over one million patients annually, we are committed to offering advanced healthcare services with a compassionate, patient-focused approach. Our hospital is equipped with a Level II Trauma Center, an accredited Chest Pain Center, a Level III Neonatal Intensive Care Unit (NICU), and is accredited by DNV - Healthcare as the only Comprehensive Stroke Center in Northeast Houston. We offer a wide range of comprehensive services, including complex cardiovascular services, specialized neurological care, orthopedic care, women’s services including high-risk pregnancy care, and pediatric services with access to pediatric specialists.', '22999 Highway 59 N, Kingwood, TX 77339', 'Kingwood', 'TX', '77339', '281-348-8000', ARRAY['English', 'Vietnamese']::text[], 'Hospital', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-kingwood-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-kingwood-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-kingwood-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-kingwood-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-kingwood-google-5.webp"], "rating": 3.8, "reviews": [{"date": "2026-02-24T18:42:59.740564955Z", "text": "I am pleased to say all the nurses were AMAZING in labor and delivery!!! I would like to mention 1 nurse Kay, she always made sure I was comfortable. Kay took very good care of us, I would like to give her a big THANK YOU and a big hug ❤️🫂 I will always remember her. For encouraging me through the contractions and epidural at the same time. Other than that the hospital staff is nice and the food service was great! I am very pleased.", "author": "Rosa Benavidez", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/109041187609217271885/reviews"}, {"date": "2026-03-05T16:34:09.091024797Z", "text": "I would absolutely not trust your love ones with this hospitals er services, I was gaslighted about my condition, no one knew what was going on, i was told 3 different things about what was going on with me, there is absolutely no privacy, no pillows or extra blankets were provided even after staffed was informed, I ened up doing an ama after waiting over 13 hours for someone to tell me there was no plan for surgery for at least a week or two. I even had to waite for almost 2 hours just to get my ama, I ended having to go to another hospital and they actually helped me. Worst experience i have ever had in any medical facilitie.", "author": "Alexandria Dianat", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/106682660683073918018/reviews"}, {"date": "2026-03-05T02:06:04.426060150Z", "text": "Fantastic nurses! Ania and Miss Eleanor on 3rd floor were AMAZING! THE recovery and surgical teams were amazing! They can improve on communication to the family when in a long surgery or recovery though. Need to work on giving updates.", "author": "Micky Martinelli", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/102956581732927069127/reviews"}, {"date": "2026-03-20T10:31:14.415300763Z", "text": "Staff was friendly and happy even early in the morning. Everything was explained to me and all of my questions were answered clearly. From pre-op to post-op they took great care of me. Love a warm blanket they gave me 2! Excellent care worth me driving from Pearland.", "author": "Entyce Me Lyfe", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110088112924803011870/reviews"}, {"date": "2026-04-29T00:24:16.990455948Z", "text": "I was admitted to the South Tower - 4th floor in the early morning hours and was met by Nurse Tara for admitting and getting me settled.  She checked on me several times during the night and as morning came I had Nurse Ronny and he went over everything from the night before in the ER and worked most of the day on helping to get me discharged and locating my doctor I needed a consult with.  On my end of the 4th floor, the employees from Housekeeping to Medical person in charge were so kind and checked on me often and helped me to feel comfortable.  I was so thankful to be in such a caring environment.", "author": "Wendy Perritt", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106861712329301978061/reviews"}], "website": "https://www.hcahoustonhealthcare.com/locations/kingwood", "location": {"latitude": 30.050728099999997, "longitude": -95.25572939999999}, "services": ["Cardiology", "Emergency Care", "Imaging Services", "Neurological Care", "NICU", "Oncology", "Orthopedic Care", "Pediatrics", "Physical Therapy and Rehabilitation", "Sleep Disorders", "Surgery", "Weight Loss Surgery", "Women''s Care"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Level II Trauma Center", "detail": "Equipped with a Level II Trauma Center for emergency care.", "category": "care"}, {"title": "Comprehensive Stroke Center", "detail": "Accredited as the only Comprehensive Stroke Center in Northeast Houston.", "category": "care"}, {"title": "Accredited Chest Pain Center", "detail": "Accredited Chest Pain Center for cardiac care.", "category": "care"}, {"title": "Level III NICU", "detail": "Level III Neonatal Intensive Care Unit for specialized newborn care.", "category": "care"}, {"title": "30+ years of service", "detail": "Serving the Northeast Houston community for more than 30 years.", "category": "care"}, {"title": "Online registration", "detail": "Convenient online registration for surgical procedures, mammograms, and diagnostic tests.", "category": "convenience"}, {"title": "MyHealthONE patient portal", "detail": "Secure patient portal to view health records, schedule follow-ups, and share records.", "category": "technology"}, {"title": "Average ER wait 8 mins", "detail": "Average ER wait time of 8 minutes as of 8:15pm CUT.", "category": "convenience"}], "price_tier": "$$", "source_url": "https://www.hcahoustonhealthcare.com/locations/kingwood?utm_campaign=corp_listings_mgmt&utm_source=google&utm_medium=business_listing", "appointment": {"booking_note": null, "appointment_url": "https://www.hcahoustonhealthcare.com/patient-resources/register-online", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking hospital in Houston, TX", "search_text": "hospital | english | vietnamese | tiếng việt | người việt | bác sĩ việt | cardiology | emergency care | imaging services | neurological care | nicu | oncology | orthopedic care | pediatrics | physical therapy and rehabilitation | sleep disorders | surgery | weight loss surgery | women''s care | emergency | diagnostic imaging | neurology | neonatal | orthopedics | rehabilitation | sleep medicine | women''s health", "google_types": ["hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 4147, "open_saturday": true, "quality_score": 92, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2F533ec34742364030b8ef5e103af18749%3Fv%3D22b0c6ef&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2Fweb-p-c64329891f0b44bea6c55c6249103bf8%3Fv%3D602c691f&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2F98fb568f2219414da9e6c4cd34db8%3Fv%3D71c9ef9e&w=3840&q=75"], "review_profile": {"rating": 3.8, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Clear explanations", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight clear explanations in their feedback."}, {"theme": "Comfortable visits", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight comfortable visits in their feedback."}], "summary": "HCA Houston Healthcare Kingwood has a 3.8 star Google rating from 4147 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "review_count": 4147, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-02-24T18:42:59.740564955Z", "text": "I am pleased to say all the nurses were AMAZING in labor and delivery!!! I would like to mention 1 nurse Kay, she always made sure I was comfortable. Kay took very good care of us, I would like to give her a big THANK YOU and a big hug ❤️🫂 I will always remember her. For encouraging me through the contractions and epidural at the same time. Other than that the hospital staff is nice and the food service was great! I am very pleased.", "author": "Rosa Benavidez", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/109041187609217271885/reviews"}, {"date": "2026-03-05T16:34:09.091024797Z", "text": "I would absolutely not trust your love ones with this hospitals er services, I was gaslighted about my condition, no one knew what was going on, i was told 3 different things about what was going on with me, there is absolutely no privacy, no pillows or extra blankets were provided even after staffed was informed, I ened up doing an ama after waiting over 13 hours for someone to tell me there was no plan for surgery for at least a week or two. I even had to waite for almost 2 hours just to get my ama, I ended having to go to another hospital and they actually helped me. Worst experience i have ever had in any medical facilitie.", "author": "Alexandria Dianat", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/106682660683073918018/reviews"}, {"date": "2026-03-05T02:06:04.426060150Z", "text": "Fantastic nurses! Ania and Miss Eleanor on 3rd floor were AMAZING! THE recovery and surgical teams were amazing! They can improve on communication to the family when in a long surgery or recovery though. Need to work on giving updates.", "author": "Micky Martinelli", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/102956581732927069127/reviews"}, {"date": "2026-03-20T10:31:14.415300763Z", "text": "Staff was friendly and happy even early in the morning. Everything was explained to me and all of my questions were answered clearly. From pre-op to post-op they took great care of me. Love a warm blanket they gave me 2! Excellent care worth me driving from Pearland.", "author": "Entyce Me Lyfe", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110088112924803011870/reviews"}, {"date": "2026-04-29T00:24:16.990455948Z", "text": "I was admitted to the South Tower - 4th floor in the early morning hours and was met by Nurse Tara for admitting and getting me settled.  She checked on me several times during the night and as morning came I had Nurse Ronny and he went over everything from the night before in the ER and worked most of the day on helping to get me discharged and locating my doctor I needed a consult with.  On my end of the 4th floor, the employees from Housekeeping to Medical person in charge were so kind and checked on me often and helped me to feel comfortable.  I was so thankful to be in such a caring environment.", "author": "Wendy Perritt", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106861712329301978061/reviews"}]}, "review_summary": "HCA Houston Healthcare Kingwood has a 3.8 star Google rating from 4147 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "about_highlight": "HCA Houston Healthcare Kingwood is a full-service, 451-bed acute care hospital proudly serving the Northeast Houston community for over 30 years. As part of HCA Houston Healthcare, a family of 13 hospitals serving over one million patients annually, we are committed to offering advanced healthcare services with a compassionate, patient-focused approach. Our hospital is equipped with a Level II Trauma Center, an accredited Chest Pain Center, a Level III Neonatal Intensive Care Unit (NICU), and is accredited by DNV - Healthcare as the only Comprehensive Stroke Center in Northeast Houston. We offer a wide range of comprehensive services, including complex cardiovascular services, specialized neurological care, orthopedic care, women’s services including high-risk pregnancy care, and pediatric services with access to pediatric specialists.", "appointment_url": "https://www.hcahoustonhealthcare.com/patient-resources/register-online", "google_maps_url": "https://maps.google.com/?cid=16049407706787199575&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJ_3pgSMyyQIYRV7p3okbzut4", "quality_missing": ["insurance", "team_members"], "search_keywords": ["hospital", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "cardiology", "emergency care", "imaging services", "neurological care", "nicu", "oncology", "orthopedic care", "pediatrics", "physical therapy and rehabilitation", "sleep disorders", "surgery", "weight loss surgery", "women''s care", "emergency", "diagnostic imaging", "neurology", "neonatal", "orthopedics", "rehabilitation", "sleep medicine", "women''s health"], "services_offered": [{"name": "Cardiology", "category": "Cardiology", "description": "Personalized heart care at your fingertips with our cardiovascular network.", "is_featured": false, "patient_fit": null}, {"name": "Emergency Care", "category": "Emergency", "description": "HCA Houston ER 24/7 in Fall Creek now open to provide safe emergency care when you need it most.", "is_featured": false, "patient_fit": null}, {"name": "Imaging Services", "category": "Diagnostic Imaging", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Neurological Care", "category": "Neurology", "description": "Specialized neurological care.", "is_featured": false, "patient_fit": null}, {"name": "NICU", "category": "Neonatal", "description": "Level III Neonatal Intensive Care Unit.", "is_featured": false, "patient_fit": null}, {"name": "Oncology", "category": "Oncology", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Orthopedic Care", "category": "Orthopedics", "description": "Orthopedic care services.", "is_featured": false, "patient_fit": null}, {"name": "Pediatrics", "category": "Pediatrics", "description": "Pediatric services with access to pediatric specialists.", "is_featured": false, "patient_fit": null}, {"name": "Physical Therapy and Rehabilitation", "category": "Rehabilitation", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Sleep Disorders", "category": "Sleep Medicine", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Surgery", "category": "Surgery", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Weight Loss Surgery", "category": "Surgery", "description": "Redefine clinical weight loss with our bariatric program.", "is_featured": false, "patient_fit": null}, {"name": "Women''s Care", "category": "Women''s Health", "description": "The next generation of care for women is here.", "is_featured": false, "patient_fit": null}], "short_description": "HCA Houston Healthcare Kingwood is a full-service, 451-bed acute care hospital proudly serving the Northeast Houston community for over 30 years.", "google_website_url": "https://www.hcahoustonhealthcare.com/locations/kingwood?utm_campaign=corp_listings_mgmt&utm_source=google&utm_medium=business_listing", "google_primary_type": "Hospital", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "22999 US-59, Kingwood, TX 77339, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/112176192197262289875", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU1QV1kC4R97bXEiMjBar4jPQYP0Nf6BhBt5c5Xp_2rz0zGmg2M=s100-p-k-no-mo", "displayName": "HCA Houston Healthcare Kingwood"}], [{"uri": "https://maps.google.com/maps/contrib/105471246395551179661", "photoUri": "https://lh3.googleusercontent.