INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('1aadbe9d-0816-461f-a535-31ebe5222e70', NULL, 'UTHealth Houston Harris County Psychiatric Center', 'UTHealth Harris County Psychiatric Center (HCPC) is the largest provider of inpatient psychiatric care in Houston, providing compassionate, patient-centered care to 9,000 patients yearly, including adults, adolescents, and children. It also provides outpatient ECT services in its ECT Clinic.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('4c477f42-1d88-4a65-8b4b-27c2cf2b6c06', NULL, 'Dunhuang Periodontics & Dental Implants', 'Dunhuang Periodontics & Dental Implants, located in Houston, TX, provides comprehensive dental care for the whole family. Led by board-certified periodontist and dental implant specialist Dr. Jennifer Chen, along with Dr. Will Wang and Dr. Ruth Yan, the practice offers a wide range of services including periodontal therapy, implant dentistry, children''s cleanings, extractions, root canals, and cosmetic dentistry. The team focuses on treating one patient at a time, ensuring undivided attention and educating patients about their oral health so they can make informed decisions about their care.', '9889 Bellaire Blvd #322, Houston, TX 77036', 'Houston', 'TX', '77036', '(713) 995-0086', ARRAY['English', 'Chinese']::text[], 'Dental', FALSE, '{"email": "drchenimplant@gmail.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dunhuang-periodontics-dental-implants-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dunhuang-periodontics-dental-implants-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dunhuang-periodontics-dental-implants-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dunhuang-periodontics-dental-implants-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dunhuang-periodontics-dental-implants-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2026-05-30T18:58:16.041519269Z", "text": "I got gum infection issues and needed to get specialized treatment. It was a pleasant visit with Dr. Jennifer and this office. Very efficient evaluation and she explained my next steps in details with my xray and photo results. Cost estimates were done quickly as well. The staff here has been trained professionally and they were friendly. I was able to feel that they care about my case and patient care not just the money. My whole family has been visiting this office. My little regret is that I should come here for treatment earlier than now. Thank you for the excellent service. :)", "author": "Silky Wong", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106226027795027322698/reviews"}, {"date": "2026-05-19T18:02:36.477647768Z", "text": "I had a great experience with Dr. Will. I told him that I have anxiety about visiting the dentist, and he was very gentle and patient with me throughout the appointments. After my last visit, I felt that my anxiety had improved significantly. The entire staff was also very friendly and welcoming. I highly recommend booking an appointment at this clinic.", "author": "Kinh Le", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109152567106736312961/reviews"}, {"date": "2026-02-26T00:23:39.716865946Z", "text": "I had a great experience with Dr. Chen for my dental needs. The whole team is so friendly, and the office is super clean and organized. Everything went smoothly during my appointment. If you’re looking for a great clinic, I highly recommend this one! 5 stars from me. Thanks.", "author": "TINA SHAO", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110263554021521049222/reviews"}, {"date": "2026-03-21T01:22:33.401874228Z", "text": "This is a first for me to highly recommend a dentist!\nAs soon as I walked into Dr Hemlani’s office, I felt such a warm welcoming atmosphere. Jason, Ian and Nayla were so  friendly!\nDr. Hemlani is in a class all by herself!!! She is  caring and thorough. Oh, she is the first doctor in my many years that has taken the time to personally walk me to the front desk to say goodbye!!\nNeedless to say, my next appointment for the next few months have already been scheduled 🤩", "author": "Elle Marrero", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103083159154295433997/reviews"}, {"date": "2025-12-17T22:03:31.229303524Z", "text": "Amazing experience very kind and helpful and willing to work with you can’t ask for more from a provider. I personally come here and bring my mom as well.", "author": "maq4533", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114260843407272387698/reviews"}], "website": "http://drchenimplant.com/", "location": {"latitude": 29.7026076, "longitude": -95.5525692}, "services": ["Periodontal Therapy", "Dental Implants", "Cosmetic Dentistry", "Teeth Cleaning", "Children''s Dentistry", "Teen''s Dentistry", "Adult''s Dentistry", "Porcelain Veneers", "Porcelain Crowns", "Composite Fillings", "Teeth Whitening", "Gum Contouring", "Implants", "Porcelain Bridges", "Full or Partial Dentures", "All-on-4® Implants", "Extractions", "Root Canals", "Oral Surgery", "Bone Grafting", "Oral Appliances", "Invisalign®", "ClearCorrect", "Braces", "Oral Sedation", "Laughing Gas", "IV Sedation", "Oral Cancer Screening", "Sealants", "Ortho Screenings"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Board-Certified Periodontist", "detail": "Dr. Jennifer Chen is a board-certified periodontist and dental implant specialist.", "category": "care"}, {"title": "Family Dentistry", "detail": "Care for the whole family, from children''s cleanings to adult cosmetic dentistry.", "category": "care"}, {"title": "One Patient at a Time", "detail": "Each patient receives the dentist''s undivided attention.", "category": "care"}, {"title": "Advanced Technology", "detail": "Uses intra-oral cameras, 3D imaging, digital X-rays, and soft/hard tissue lasers.", "category": "technology"}], "price_tier": "$$", "source_url": "http://drchenimplant.com/", "appointment": {"booking_note": null, "appointment_url": "https://app.nexhealth.com/appt/dunhuang-periodontics-dental-implants?lid=331937", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese dentist in Houston, TX", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | periodontal therapy | dental implants | cosmetic dentistry | teeth cleaning | children''s dentistry | teen''s dentistry | adult''s dentistry | porcelain veneers | porcelain crowns | composite fillings | teeth whitening | gum contouring | implants | porcelain bridges | full or partial dentures | all-on-4® implants | extractions | root canals | oral surgery | bone grafting | oral appliances | invisalign® | clearcorrect | oral sedation | laughing gas | iv sedation | oral cancer screening | sealants | ortho screenings | preventive | tooth replacement | cosmetic | family dentistry | extractions & preservation | orthodontics | sedation dentistry | jennifer chen | board-certified periodontist and dental implant specialist | will wang | ruth yan", "google_types": ["dentist", "dental_clinic", "doctor", "medical_clinic", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 336, "team_members": [{"name": "Jennifer Chen", "role": "Board-Certified Periodontist and Dental Implant Specialist", "bio_snippet": "Dr. Chen’s passion of excellence in restoring people’s dental and periodontal health and beauty has driven her to continued advancement in technology and understanding. Providing minimal invasive yet the most predictable treatment is what she seeks for her patients.", "languages_spoken": []}, {"name": "Will Wang", "role": "Dentist", "bio_snippet": "Dr. Will’s favorite aspect of dentistry is giving his patients a healthy and beautiful smile and is comfortable in all aspects of dentistry. His top priority is to provide the most advanced dental care for his patients in a comfortable atmosphere.", "languages_spoken": []}, {"name": "Ruth Yan", "role": "Dentist", "bio_snippet": "Dr. Yan loves providing the highest quality of cosmetic and family dentistry. She believes that proper dental care can be life-changing and is committed to helping her patients achieve and maintain beautiful, healthy teeth.", "languages_spoken": []}], "open_saturday": true, "quality_score": 95, "working_hours": {"friday": "9:00 AM – 5:30 PM", "monday": "9:00 AM – 5:30 PM", "sunday": "Closed", "tuesday": "9:00 AM – 5:30 PM", "saturday": "9:00 AM – 5:30 PM", "thursday": "Closed", "wednesday": "9:00 AM – 5:30 PM"}, "gallery_images": ["https://images.squarespace-cdn.com/content/v1/5d1fdef7a99f5b0001ee2308/1567633766624-HZ5HFI7Q2EVO9CQVWSTV/HoustonArboretumTX.jpg?format=2500w", "https://images.squarespace-cdn.com/content/v1/5d1fdef7a99f5b0001ee2308/1562616157626-0J6E0141TEMWY9LUJ60Y/AdobeStock_169777837.jpg?format=2500w", "https://images.squarespace-cdn.com/content/v1/5d1fdef7a99f5b0001ee2308/1562370085212-LYQNIH4Q5LWT1NRLUPUU/image-asset.png", "https://images.squarespace-cdn.com/content/v1/5d1fdef7a99f5b0001ee2308/1567633745966-L9F6LCQMNABQSXSFK11Y/image-asset.jpeg", "https://images.squarespace-cdn.com/content/v1/5d1fdef7a99f5b0001ee2308/1567718473062-T7FG2PAEB5IATJ2BTBYO/DrWillWong.jpg", "https://images.squarespace-cdn.com/content/v1/5d1fdef7a99f5b0001ee2308/1567634552533-E3CP664NMNG12S8OEE3Q/DrRuthYan2.jpg"], "review_profile": {"rating": 4.8, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 5, "sentiment": "Positive", "summary_quote": "Every reviewer highlights friendly, knowledgeable staff who create a welcoming atmosphere."}, {"theme": "Clinical Expertise", "mentions": 4, "sentiment": "Positive", "summary_quote": "Dentists are praised for being thorough, caring, and effective in addressing patient needs."}, {"theme": "Patient Care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients feel genuinely cared for, with mentions of personalized attention and detailed explanations."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "The clinic is noted for being clean, organized, and having a warm atmosphere."}, {"theme": "Communication", "mentions": 2, "sentiment": "Positive", "summary_quote": "Clear and detailed communication from the staff and dentists is frequently appreciated."}], "summary": "Patients consistently praise the clinic for its friendly and professional staff, thorough and caring dentists, and welcoming atmosphere, with many highlighting improved experiences and high satisfaction.", "review_count": 336, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-05-30T18:58:16.041519269Z", "text": "I got gum infection issues and needed to get specialized treatment. It was a pleasant visit with Dr. Jennifer and this office. Very efficient evaluation and she explained my next steps in details with my xray and photo results. Cost estimates were done quickly as well. The staff here has been trained professionally and they were friendly. I was able to feel that they care about my case and patient care not just the money. My whole family has been visiting this office. My little regret is that I should come here for treatment earlier than now. Thank you for the excellent service. :)", "author": "Silky Wong", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106226027795027322698/reviews"}, {"date": "2026-05-19T18:02:36.477647768Z", "text": "I had a great experience with Dr. Will. I told him that I have anxiety about visiting the dentist, and he was very gentle and patient with me throughout the appointments. After my last visit, I felt that my anxiety had improved significantly. The entire staff was also very friendly and welcoming. I highly recommend booking an appointment at this clinic.", "author": "Kinh Le", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109152567106736312961/reviews"}, {"date": "2026-02-26T00:23:39.716865946Z", "text": "I had a great experience with Dr. Chen for my dental needs. The whole team is so friendly, and the office is super clean and organized. Everything went smoothly during my appointment. If you’re looking for a great clinic, I highly recommend this one! 5 stars from me. Thanks.", "author": "TINA SHAO", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110263554021521049222/reviews"}, {"date": "2026-03-21T01:22:33.401874228Z", "text": "This is a first for me to highly recommend a dentist!\nAs soon as I walked into Dr Hemlani’s office, I felt such a warm welcoming atmosphere. Jason, Ian and Nayla were so  friendly!\nDr. Hemlani is in a class all by herself!!! She is  caring and thorough. Oh, she is the first doctor in my many years that has taken the time to personally walk me to the front desk to say goodbye!!\nNeedless to say, my next appointment for the next few months have already been scheduled 🤩", "author": "Elle Marrero", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103083159154295433997/reviews"}, {"date": "2025-12-17T22:03:31.229303524Z", "text": "Amazing experience very kind and helpful and willing to work with you can’t ask for more from a provider. I personally come here and bring my mom as well.", "author": "maq4533", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114260843407272387698/reviews"}]}, "review_summary": "Patients consistently praise the clinic for its friendly and professional staff, thorough and caring dentists, and welcoming atmosphere, with many highlighting improved experiences and high satisfaction.", "about_highlight": "Dunhuang Periodontics & Dental Implants, located in Houston, TX, provides comprehensive dental care for the whole family. Led by board-certified periodontist and dental implant specialist Dr. Jennifer Chen, along with Dr. Will Wang and Dr. Ruth Yan, the practice offers a wide range of services including periodontal therapy, implant dentistry, children''s cleanings, extractions, root canals, and cosmetic dentistry. The team focuses on treating one patient at a time, ensuring undivided attention and educating patients about their oral health so they can make informed decisions about their care.", "appointment_url": "https://app.nexhealth.com/appt/dunhuang-periodontics-dental-implants?lid=331937", "google_maps_url": "https://maps.google.com/?cid=6889883224089433598&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJkwHpHs_CQIYR_hXGw0nInV8", "quality_missing": ["insurance"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "periodontal therapy", "dental implants", "cosmetic dentistry", "teeth cleaning", "children''s dentistry", "teen''s dentistry", "adult''s dentistry", "porcelain veneers", "porcelain crowns", "composite fillings", "teeth whitening", "gum contouring", "implants", "porcelain bridges", "full or partial dentures", "all-on-4® implants", "extractions", "root canals", "oral surgery", "bone grafting", "oral appliances", "invisalign®", "cl