INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('2a30a88c-7887-43ec-842e-79a590488062', NULL, 'NextGen Dental Center', 'NextGen Dental Center is a modern family dentistry practice located in Houston, TX, committed to incorporating the latest technologies and techniques to ensure exceptional care for patients. The dental office invests in advanced dental technology for precise diagnostics, minimally invasive treatments, and a comfortable patient experience. The skilled team listens to patient needs and offers personalized dental services designed to fit individual goals and lifestyles, striving to make every visit stress-free and positive. With a focus on ongoing education and ethical care, the center offers a range of dental services that build lasting relationships with patients and the community.', '6833 W Sam Houston pkwy S, Suite 106, Houston, TX 77072', 'Houston', 'TX', '77072', '713-930-1122', ARRAY['English', 'Chinese']::text[], 'Dental', FALSE, '{"email": "info@nextgendentalcenter.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nextgen-dental-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nextgen-dental-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nextgen-dental-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nextgen-dental-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nextgen-dental-center-google-5.webp"], "rating": 5, "pricing": [{"name": "New patient exam", "notes": null, "price": "$49", "category": "Exam", "price_range": null}, {"name": "Limited oral exam", "notes": null, "price": "$39", "category": "Exam", "price_range": null}], "reviews": [{"date": "2025-11-17T15:32:00.276773281Z", "text": "We visited this dental clinic two Sundays ago for an exam and cleaning. The X-ray images were very clear, and the dentist found an impacted wisdom tooth. Since I don’t have dental insurance this year, they provided a detailed cost estimate, and I plan to return next year after getting a new dental insurance plan for the extraction.Dr. Xue also examined my child’s teeth, provided a complimentary fluoride treatment, and filled two early cavities.\nDr. Xue and the assistant were both incredibly warm and attentive. They even prepared sparkling water and drinks for us, and there were small toys for kids to take home.\nThe clinic is very clean and well organized, with all brand-new equipment. Overall, it was an excellent experience, and I highly recommend this place!", "author": "yc Wang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109987193389421437000/reviews"}, {"date": "2026-03-20T05:01:45.249451646Z", "text": "I had an excellent experience at NextGen dental center. Dr. Xue was welcoming, professional, and made me feel comfortable the moment I walked in. The office itself was clean, modern, and well-organized.\n\nI had 2 implants made overseas, now it’s the time to make the top crowns. Dr. Xue was very knowledgeable and took the time to explain everything clearly. At my second appointment, He showed me the tools he ordered only for my case, the materials and laboratory he used are of the highest quality. At the same time, his prices are also very reasonable. The front desk Lulu was very sweet and his assistant was a dental surgeon overseas. It’s clear they truly care about their patients and take pride in their work.\n\nWhat stood out most to me was the attention to detail and the genuine kindness from everyone in the office. Scheduling was easy, wait times were minimal, and the overall atmosphere was calm and reassuring.\n\nI would highly recommend this dental office to anyone looking for quality care and a positive experience. It’s not always easy to find a dentist you can trust, but this team definitely exceeded my expectations.", "author": "H D", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105897627799956983683/reviews"}, {"date": "2026-04-20T17:24:09.073602943Z", "text": "I highly recommend Dr. Xue and his team for anyone considering dental implants. I started my journey with a consultation shortly after they opened last year, and from day one, I was impressed by their brand-new, state-of-the-art equipment and professional atmosphere. Over the six-month process, which included four follow-up visits, Dr. Xue and Dr. Shi were incredibly professional and kind, taking the time to explain the high-quality materials used for my custom crown and abutment. Dr. Xue is truly dedicated to his patients and even offers a guarantee of free treatment for any future issues with the implant. It has been a week since the procedure was completed, and everything feels fantastic. I’m so glad I chose this clinic!", "author": "Haimin Huang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103544677007267539716/reviews"}, {"date": "2026-02-08T22:38:11.654637499Z", "text": "Dr. Xue''s dental skills are exceptionally professional. I am extremely satisfied with the filling of my cavity and the cleaning of my teeth. I feel very fortunate to have met such a professional Chinese dentist in the United States.👍👍👍", "author": "张旭", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100971504215604684879/reviews"}, {"date": "2026-02-07T20:16:05.397116083Z", "text": "I came to NextGen Dental Center and had a great experience. Dr. Xue gave me a very thorough exam and a clear treatment plan. He performed a deep cleaning, and the entire procedure was completely painless thanks to excellent anesthesia. He also used an AI imaging tool to show me the before-and-after results, which was very helpful. After the deep cleaning, there was no calculus left—it was a very complete and professional job. The office is clean, the staff is friendly, and I truly felt at home. I highly recommend this office to all my friends!", "author": "Jin", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117935259020038429347/reviews"}], "website": "https://www.nextgendentalcenter.com/", "location": {"latitude": 29.7032156, "longitude": -95.5561275}, "services": ["New patient exam", "Limited oral exam", "Routine cleanings and exams", "Implants", "Root canals", "Cosmetic enhancements", "Restorative treatments"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Advanced Technology", "detail": "Invests in the latest dental technology for precise diagnostics, minimally invasive treatments, and a comfortable patient experience.", "category": "technology"}, {"title": "Trusted Dental Professionals", "detail": "Skilled dentists and staff dedicated to maintaining high standards of professionalism and integrity with ongoing education.", "category": "care"}, {"title": "Patient-Centered Approach", "detail": "Experienced team listens to patient needs and offers personalized dental services designed to fit goals and lifestyle.", "category": "care"}, {"title": "Comprehensive Services for All Ages", "detail": "Provides a comprehensive range of dental services from preventive check-ups to cosmetic enhancements and restorative treatments for patients of every age.", "category": "care"}, {"title": "Cutting-Edge Dental Technology", "detail": "Benefits from digital imaging, 3D scanning, and minimally invasive treatments for faster, more comfortable visits.", "category": "technology"}, {"title": "Personalized Patient Care", "detail": "Expert team takes time to understand unique needs, providing tailored dental services and compassionate support.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.nextgendentalcenter.com/", "appointment": {"booking_note": null, "appointment_url": "https://www.nextgendentalcenter.com/#d0d33e5b-cc1c-426d-bf68-2027db7a8daf", "new_patient_note": null, "phone_booking_available": null, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Chinese dentist in Houston, TX", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | new patient exam | limited oral exam | routine cleanings and exams | implants | root canals | cosmetic enhancements | restorative treatments | preventive | restorative | cosmetic", "google_types": ["dental_clinic", "medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 21, "open_saturday": false, "quality_score": 92, "working_hours": {"friday": "9:00 AM – 5:00 PM", "monday": "9:00 AM – 6:00 PM", "sunday": "9:00 AM – 6:00 PM", "tuesday": "9:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "9:00 AM – 5:00 PM", "wednesday": "9:00 AM – 6:00 PM"}, "gallery_images": ["https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/OHP_5083.jpg/:/rs=w:365,h:365,cg:true,m/cr=w:365,h:365", "https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/OHP_5092.jpg/:/cr=t:0%25,l:16.66%25,w:66.68%25,h:100%25/rs=w:365,h:365,cg:true", "https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/OHP_5104.jpg/:/cr=t:0%25,l:16.66%25,w:66.68%25,h:100%25/rs=w:365,h:365,cg:true", "https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/IMG_1860.jpg/:/cr=t:0%25,l:0%25,w:100%25,h:100%25", "https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/blob-e6ad593.png/:/cr=t:0%25,l:0%25,w:100%25,h:100%25/rs=w:1300,h:800", "https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/blob.png/:/rs=w:1300,h:800", "https://img1.wsimg.com/isteam/ip/6544192f-e841-43b2-b599-2a473d2e5492/blob-35f8452.png/:/rs=w:1300,h:800"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Clear explanations", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight clear explanations in their feedback."}, {"theme": "Comfortable visits", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight comfortable visits in their feedback."}], "summary": "NextGen Dental Center has a 5.0 star Google rating from 21 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "review_count": 21, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2025-11-17T15:32:00.276773281Z", "text": "We visited this dental clinic two Sundays ago for an exam and cleaning. The X-ray images were very clear, and the dentist found an impacted wisdom tooth. Since I don’t have dental insurance this year, they provided a detailed cost estimate, and I plan to return next year after getting a new dental insurance plan for the extraction.Dr. Xue also examined my child’s teeth, provided a complimentary fluoride treatment, and filled two early cavities.\nDr. Xue and the assistant were both incredibly warm and attentive. They even prepared sparkling water and drinks for us, and there were small toys for kids to take home.\nThe clinic is very clean and well organized, with all brand-new equipment. Overall, it was an excellent experience, and I highly recommend this place!", "author": "yc Wang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109987193389421437000/reviews"}, {"date": "2026-03-20T05:01:45.249451646Z", "text": "I had an excellent experience at NextGen dental center. Dr. Xue was welcoming, professional, and made me feel comfortable the moment I walked in. The office itself was clean, modern, and well-organized.\n\nI had 2 implants made overseas, now it’s the time to make the top crowns. Dr. Xue was very knowledgeable and took the time to explain everything clearly. At my second appointment, He showed me the tools he ordered only for my case, the materials and laboratory he used are of the highest quality. At the same time, his prices are also very reasonable. The front desk Lulu was very sweet and his assistant was a dental surgeon overseas. It’s clear they truly care about their patients and take pride in their work.\n\nWhat stood out most to me was the attention to detail and the genuine kindness from everyone in the office. Scheduling was easy, wait times were minimal, and the overall atmosphere was calm and reassuring.\n\nI would highly recommend this dental office to anyone looking for quality care and a positive experience. It’s not always easy to find a dentist you can trust, but this team definitely exceeded my expectations.", "author": "H D", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105897627799956983683/reviews"}, {"date": "2026-04-20T17:24:09.073602943Z", "text": "I highly recommend Dr. Xue and his team for anyone considering dental implants. I started my journey with a consultation shortly after they opened last year, and from day one, I was impressed by their brand-new, state-of-the-art equipment and professional atmosphere. Over the six-month process, which included four follow-up visits, Dr. Xue and Dr. Shi were incredibly professional and kind, taking the time to explain the high-quality materials used for my custom crown and abutment. Dr. Xue is truly dedicated to his patients and even offers a guarantee of free treatment for any future issues with the implant. It has been a week since the procedure was completed, and everything feels fantastic. I’m so glad I chose this clinic!", "author": "Haimin Huang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103544677007267539716/reviews"}, {"date": "2026-02-08T22:38:11.654637499Z", "text": "Dr. Xue''s dental skills are exceptionally professional. I am extremely satisfied with the filling of my cavity and the cleaning of my teeth. I feel very fortunate to have met such a professional Chinese dentist in the United States.👍👍👍", "author": "张旭", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100971504215604684879/reviews"}, {"date": "2026-02-07T20:16:05.397116083Z", "text": "I came to NextGen Dental Center and had a great experience. Dr. Xue gave me a very thorough exam and a clear treatment plan. He performed a deep cleaning, and the entire procedure was completely painless thanks to excellent anesthesia. He also used an AI imaging tool to show me the before-and-after results, which was very helpful. After the deep cleaning, there was no calculus left—it was a very complete and professional job. The office is clean, the staff is friendly, and I truly felt at home. I highly recommend this office to all my friends!", "author": "Jin", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117935259020038429347/reviews"}]}, "review_summary": "NextGen Dental Center has a 5.0 star Google rating from 21 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "about_highlight": "NextGen Dental Center is a modern family dentistry practice located in Houston, TX, committed to incorporating the latest technologies and techniques to ensure exceptional care for patients. The dental office invests in advanced dental technology for precise diagnostics, minimally invasive treatments, and a comfortable patient experience. The skilled team listens to patient needs and offers personalized dental services designed to fit individual goals and lifestyles, striving to make every visit stress-free and positive. With a focus on ongoing education and ethical care, the center offers a range of dental services that build lasting relationships with patients and the community.", "appointment_url": "https://www.nextgendentalcenter.com/#d0d33e5b-cc1c-426d-bf68-2027db7a8daf", "google_maps_url": "https://maps.google.com/?cid=14971377473199154527&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJcdR9XhLDQIYRXyVSeH0Exc8", "quality_missing": ["insurance", "team_members"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "new patient exam", "limited oral exam", "routine cleanings and exams", "implants", "root canals", "cosmetic enhancements", "restorative treatments", "preventive", "restorative", "cosmetic"], "services_offered": [{"name": "New patient exam", "category": "Preventive", "description": "A comprehensive exam for new patients.", "is_featured": true, "patient_fit": "New patients"}, {"name": "Limited oral exam", "category": "Preventive", "description": "A focused oral examination.", "is_featured": true, "patient_fit": "Patients needing a limited exam"}, {"name": "Routine cleanings and exams", "category": "Preventive", "description": "Regular dental cleanings and check-ups.", "is_featured": false, "patient_fit": "All ages"}, {"name": "Implants", "category": "Restorative", "description": "Dental implant procedures.", "is_featured": false, "patient_fit": "Patients needing tooth replacement"}, {"name": "Root canals", "category": "Restorative", "description": "Endodontic treatment to save a tooth.", "is_featured": false, "patient_fit": "Patients with infected or damaged tooth pulp"}, {"name": "Cosmetic enhancements", "category": "Cosmetic", "description": "Cosmetic dental services to improve smile appearance.", "is_featured": false, "patient_fit": "Patients seeking aesthetic improvements"}, {"name": "Restorative treatments", "category": "Restorative", "description": "Treatments to restore function and health of teeth.", "is_featured": false, "patient_fit": "Patients with damaged or missing teeth"}], "short_description": "NextGen Dental Center is a modern family dentistry practice in Houston, TX, offering advanced dental services with a patient-centered approach.", "google_website_url": "https://www.nextgendentalcenter.com/", "google_primary_type": "Dental Clinic", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "6833 W Sam Houston Pkwy S Ste 106, Houston, TX 77072, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/104324314770127685319", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX1o7qeaw0wdGLsd2MF7rB9wMeLY5upeAfsGy9Cy7rDe-07SfY=s100-p-k-no-mo", "displayName": "NextGen Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/104324314770127685319", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX1o7qeaw0wdGLsd2MF7rB9wMeLY5upeAfsGy9Cy7rDe-07SfY=s100-p-k-no-mo", "displayName": "NextGen Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/104324314770127685319", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX1o7qeaw0wdGLsd2MF7rB9wMeLY5upeAfsGy9Cy7rDe-07SfY=s100-p-k-no-mo", "displayName": "NextGen Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/104324314770127685319", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX1o7qeaw0wdGLsd2MF7rB9wMeLY5upeAfsGy9Cy7rDe-07SfY=s100-p-k-no-mo", "displayName": "NextGen Dental Center"}], [{"uri": "https://maps.google.com/maps/contrib/104324314770127685319", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX1o7qeaw0wdGLsd2MF7rB9wMeLY5upeAfsGy9Cy7rDe-07SfY=s100-p-k-no-mo", "displayName": "NextGen Dental Center"}]]}'::jsonb, '2026-06-25T20:28:43.823981+00:00', 'nextgen-dental-center', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('bfa70f35-57b7-43d2-9d85-46adae135603', NULL, 'Dr. David Nguyen and Associates', 'Dr. David Nguyen and Associates has been serving the San Jose community since 2015. We are committed to providing the best eye care experience for every single patient and answering your questions while explaining our findings using patient friendly terminology. From the latest technology to superior patient care, we specialize in contact lens fittings, the treatment and management of eye disease, eye infections, annual eye exams and more. At Dr. Nguyen and Associates, we are excited for the opportunity to provide you and your family the best vision care solutions for your individual needs. Call today to schedule an appointment for your annual eye exam.', '533 Coleman Ave', 'San Jose', 'CA', '95110', '(408) 220-6025', ARRAY['English', 'Spanish', 'Vietnamese']::text[], 'Ophthalmology', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-david-nguyen-and-associates-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-david-nguyen-and-associates-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-david-nguyen-and-associates-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-david-nguyen-and-associates-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr.-david-nguyen-and-associates-google-5.webp"], "rating": 5, "pricing": [{"name": "Eye Exam Starting Fee", "notes": null, "price": "$129.00", "category": "Exam", "price_range": null}, {"name": "Contact Lens Starting Fee", "notes": "Includes fitting fee and eyeglass exam", "price": "$179.00", "category": "Vision", "price_range": null}, {"name": "Retinal Imaging Fee", "notes": null, "price": "$39.00", "category": "Diagnostic", "price_range": null}], "reviews": [{"date": "2026-03-31T18:20:15.823789032Z", "text": "I had a really good experience. Dr Nguyen was very kind and friendly- he is knowledgable and explained everything he was doing. He took his time with my exam, which was refreshing- I always feel rushed during eye exams and always fear I''ve made the wrong choice then I''m stuck with an incorrect prescription. I did not feel this way during this eye exam at all.\n\nFor an eye exam and contact exam, I was quoted an estimate of somewhere around ~$189-209 ish (something like that), without insurance for FYI.", "author": "Belinda Son", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105270402844721905216/reviews"}, {"date": "2025-11-30T15:36:07.906221995Z", "text": "We had a great experience, Dr. David Nguyen was incredibly thorough and took the time to explain everything clearly during my daughter eye appointment, which made us feel confident and well cared with the explanation. The staff were all warm and welcoming from the moment we walked in. Even wonderful assist for selection of frames from the available plenty of collection. Highly recommend! and Appreciated!", "author": "Manjunath Naik", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111015939818988212866/reviews"}, {"date": "2025-12-26T20:05:10.807501047Z", "text": "Excellent Dr. I have been coming to appointments with him for years and he is always friendly and professional.  He explains everything clearly and is a good listener.\n\nHis staff is always helpful and friendly.\n\nI would highly recommend him to everyone.", "author": "John Brennan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103703470771914514398/reviews"}, {"date": "2026-06-02T22:41:38.289480250Z", "text": "He was great with my kids and patiently answered their many questions :)", "author": "Kristi Zee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104112450435826385249/reviews"}, {"date": "2025-12-11T03:42:01.321541868Z", "text": "The staffs are very friendly and prompt. Dr. David Nguyen asked me some questions to find out which type of glass would suitable for my lifestyle. The exams were very efficient and I was very satisfied.", "author": "Carol Lee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111663077679446724178/reviews"}], "website": "https://doctors.eyeexamsnow.com/optometry/ca/san-jose/dr-david-nguyen-and-associates", "location": {"latitude": 37.3386912, "longitude": -121.90443099999999}, "services": ["Digital Retinal Imaging", "Walk-in Exams", "Same Day Exams", "Medical Eye Exams", "Computer Vision", "Contact Lens Fittings", "Contact Lens Exams", "Ortho-keratology", "Stellest lens", "Myopia Control", "Pediatrics - Min Age 4"], "insurance": {"notes": "Please call to see if your insurance plan covers partial or full exam fees.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": ["Cigna", "EyeMed", "Humana", "Spectera", "Superior Vision"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Digital Retinal Imaging", "detail": "Advanced imaging technology for comprehensive eye exams.", "category": "technology"}, {"title": "Same Day Exams", "detail": "Walk-in and same-day appointments available for urgent needs.", "category": "convenience"}, {"title": "Online Scheduling", "detail": "Real-time availability for booking eye exams online.", "category": "convenience"}, {"title": "Multilingual Staff", "detail": "Services available in English, Spanish, and Vietnamese.", "category": "culture"}, {"title": "Contact Lens Fittings", "detail": "Specialized fittings including ortho-keratology and Stellest lenses.", "category": "care"}, {"title": "5 / 5 Rating", "detail": "2482 reviews from patients.", "category": "reviews"}], "price_tier": "$$", "source_url": "https://doctors.eyeexamsnow.com/optometry/ca/san-jose/dr-david-nguyen-and-associates?cid=yext_odTOOD9669-910000619&y_source=1_Nzg2NTE2Ny03MTUtbG9jYXRpb24ud2Vic2l0ZQ%3D%3D", "appointment": {"booking_note": "Schedule an appointment online or call (408) 220-6025", "appointment_url": "https://www.examappts.com/webapp/wcs/stores/servlet/EyeExamFlow?catalogId=12751&storeId=12001&langId=-1&storeNumber=9669&clearExams=1&cid=yext_odTOOD9669-910000619", "new_patient_note": "Take advantage of your health benefits today!", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese eye clinic in San Jose, CA", "search_text": "ophthalmology | optometry | optometrist | eye doctor | eye exam | cataract | lasik | glasses | nhãn khoa | khám mắt | bác sĩ mắt | 안과 | 검안 | 眼科 | 配镜 | english | spanish | vietnamese | tiếng việt | người việt | bác sĩ việt | digital retinal imaging | walk-in exams | same day exams | medical eye exams | computer vision | contact lens fittings | contact lens exams | ortho-keratology | stellest lens | myopia control | pediatrics - min age 4 | diagnostic | emergency | medical | preventive | vision | pediatric | cigna | eyemed | humana | spectera | superior vision | dr. david nguyen | independent doctor of optometry", "google_types": ["medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 512, "team_members": [{"name": "Dr. David Nguyen", "role": "Independent Doctor of Optometry", "bio_snippet": null, "languages_spoken": ["English", "Spanish", "Vietnamese"]}], "language_note": "The clinic offers services in English, Spanish, and Vietnamese, reflecting a commitment to serving a diverse, multicultural patient population in San Jose.", "open_saturday": true, "quality_score": 100, "working_hours": {"friday": "10:00 AM – 6:00 PM", "monday": "10:00 AM – 6:00 PM", "sunday": "Closed", "tuesday": "Closed", "saturday": "9:00 AM – 5:00 PM", "thursday": "10:00 AM – 6:00 PM", "wednesday": "Closed"}, "gallery_images": ["https://dyn.mktgcdn.com/p/ABX2Xh3TRkN0pxwLvLnF3rl7umFwxdfk2enAJ52VbJc/width=500,height=500"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 4, "sentiment": "Positive", "summary_quote": "Multiple reviewers commend the warm, welcoming, and helpful staff."}, {"theme": "Clinical Expertise", "mentions": 4, "sentiment": "Positive", "summary_quote": "Dr. Nguyen is frequently described as knowledgeable, thorough, and professional."}, {"theme": "Communication", "mentions": 4, "sentiment": "Positive", "summary_quote": "Patients appreciate Dr. Nguyen''s clear explanations and patience in answering questions."}, {"theme": "Patient-Centered Care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Many note the unhurried, attentive exams tailored to individual needs."}, {"theme": "Facility Environment", "mentions": 1, "sentiment": "Positive", "summary_quote": "One reviewer highlights the ample frame selection and efficient service."}], "summary": "Patients consistently praise Dr. David Nguyen and Associates for their friendly, knowledgeable staff and thorough, patient-centered care, with many highlighting Dr. Nguyen''s clear explanations and attentive approach.", "review_count": 512, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-03-31T18:20:15.823789032Z", "text": "I had a really good experience. Dr Nguyen was very kind and friendly- he is knowledgable and explained everything he was doing. He took his time with my exam, which was refreshing- I always feel rushed during eye exams and always fear I''ve made the wrong choice then I''m stuck with an incorrect prescription. I did not feel this way during this eye exam at all.\n\nFor an eye exam and contact exam, I was quoted an estimate of somewhere around ~$189-209 ish (something like that), without insurance for FYI.", "author": "Belinda Son", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105270402844721905216/reviews"}, {"date": "2025-11-30T15:36:07.906221995Z", "text": "We had a great experience, Dr. David Nguyen was incredibly thorough and took the time to explain everything clearly during my daughter eye appointment, which made us feel confident and well cared with the explanation. The staff were all warm and welcoming from the moment we walked in. Even wonderful assist for selection of frames from the available plenty of collection. Highly recommend! and Appreciated!", "author": "Manjunath Naik", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111015939818988212866/reviews"}, {"date": "2025-12-26T20:05:10.807501047Z", "text": "Excellent Dr. I have been coming to appointments with him for years and he is always friendly and professional.  He explains everything clearly and is a good listener.\n\nHis staff is always helpful and friendly.\n\nI would highly recommend him to everyone.", "author": "John Brennan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103703470771914514398/reviews"}, {"date": "2026-06-02T22:41:38.289480250Z", "text": "He was great with my kids and patiently answered their many questions :)", "author": "Kristi Zee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104112450435826385249/reviews"}, {"date": "2025-12-11T03:42:01.321541868Z", "text": "The staffs are very friendly and prompt. Dr. David Nguyen asked me some questions to find out which type of glass would suitable for my lifestyle. The exams were very efficient and I was very satisfied.", "author": "Carol Lee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111663077679446724178/reviews"}]}, "review_summary": "Patients consistently praise Dr. David Nguyen and Associates for their friendly, knowledgeable staff and thorough, patient-centered care, with many highlighting Dr. Nguyen''s clear explanations and attentive approach.", "about_highlight": "Dr. David Nguyen and Associates has been serving the San Jose community since 2015. We are committed to providing the best eye care experience for every single patient and answering your questions while explaining our findings using patient friendly terminology. From the latest technology to superior patient care, we specialize in contact lens fittings, the treatment and management of eye disease, eye infections, annual eye exams and more. At Dr. Nguyen and Associates, we are excited for the opportunity to provide you and your family the best vision care solutions for your individual needs. Call today to schedule an appointment for your annual eye exam.", "appointment_url": "https://www.examappts.com/webapp/wcs/stores/servlet/EyeExamFlow?catalogId=12751&storeId=12001&langId=-1&storeNumber=9669&clearExams=1&cid=yext_odTOOD9669-910000619", "google_maps_url": "https://maps.google.com/?cid=13565703043200639311&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJX3v6nmHLj4ART-FoKgsPQ7w", "quality_missing": [], "search_keywords": ["ophthalmology", "optometry", "optometrist", "eye doctor", "eye exam", "cataract", "lasik", "glasses", "nhãn khoa", "khám mắt", "bác sĩ mắt", "안과", "검안", "眼科", "配镜", "english", "spanish", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "digital retinal imaging", "walk-in exams", "same day exams", "medical eye exams", "computer vision", "contact lens fittings", "contact lens exams", "ortho-keratology", "stellest lens", "myopia control", "pediatrics - min age 4", "diagnosti