INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('8c84bad4-e7f6-4d06-87be-a46c0fe3a8c4', NULL, 'Kokoro Health & Wellness Family Clinic - Abrams Rd.', 'Kokoro Health & Wellness provides evidence-based, patient-centered primary care at two Dallas-area locations, including the Abrams Road clinic. The clinic offers comprehensive family medicine, chronic care management, weight management, and an innovative Essential Direct Care™ membership plan. With board-certified providers, same-day appointments, and a commitment to accessible, compassionate care, Kokoro serves as a medical home for adults 18+ in North Texas.', '8420 Abrams Rd, Suite 208, Dallas, TX 75243', 'Dallas', 'TX', '75243', '972-201-3552', ARRAY['English', 'Vietnamese', 'Korean']::text[], 'Family Medicine', FALSE, '{"fax": "877-658-8663", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kokoro-health-wellness-family-clinic-abrams-rd-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kokoro-health-wellness-family-clinic-abrams-rd-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kokoro-health-wellness-family-clinic-abrams-rd-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kokoro-health-wellness-family-clinic-abrams-rd-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kokoro-health-wellness-family-clinic-abrams-rd-google-5.webp"], "rating": 3.9, "pricing": [{"name": "Essential Direct Care™ Individual Plan", "notes": "Includes 4 comprehensive visits, 4 medical massages, annual flu shot, balance testing, members-only lab pricing, and more. No deductible. No surprise bills.", "price": "$329 per quarter", "category": "membership", "price_range": "$1,116/year"}, {"name": "Essential Direct Care™ Add-On Visit", "notes": "Flat fee for acute visits for Essential Direct Care™ members. Charged at check-in.", "price": "$129", "category": "exam", "price_range": null}, {"name": "Add a Family Member (Essential Direct Care™)", "notes": "Must be paid in full. Same benefits for one additional adult (18+) in household. Limit 1 per primary member.", "price": "$1,000/year", "category": "membership", "price_range": null}, {"name": "Essential Direct Care™ Business Plan", "notes": "Fixed annual cost per employee. Includes 4 quarterly visits, 4 medical massages, annual flu shot, balance testing, members-only lab pricing. Same-day appointments available.", "price": "$1,116/employee/year", "category": "membership", "price_range": null}], "reviews": [{"date": "2025-08-14T18:10:52.323847591Z", "text": "I love going to my appointments at Kokoro health an wellness .Ashli Cindy an Dalylia  are amazing they always make it fun an enjoyable. They make you feel welcome great environment  🥹 Make your appointment with this clinic. You’ll be ready to make your next one as soon as you walk though the door to leave. #AmazingSaff Thank you Kokoro 🫶🏾", "author": "Alonzo Jordan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111032035658991301129/reviews"}, {"date": "2026-03-07T02:39:21.277276067Z", "text": "I have been seeing Dr Nguyen as my primary doctor for probably more than half of my life now. She''s a great physician. I am leaving a poor review here, as the office and billing have become a thorn in my side that I will not allow to continue without saying something about it.\nI have been overcharged multiple times. I have had payments that I made to the office at time of service, get dropped from my bill and invoice actually increase from the already inflated invoice amount. I have made many many calls to the office, and left voicemails, yet be completely ignored. The communication is a one-way street, because the invoices are quite conveniently sent to me via text, email, and regular mail.  Multiple calls are left unreturned even after one successful connection where staff escalated to the billing manager to review my concerns.  No call back.\nI am having to resort to sending a certified letter in order to get anyone''s attention. Let''s see how that goes.\n\nHealth insurance companies and poorly run medical offices like this, give this entire health care industry the bad reputation that it has, while the consumer/patients suffer the financial consequences.  This should be an absolute embarrassment.", "author": "Brigida Ward", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/103205311118293824912/reviews"}, {"date": "2026-01-22T22:07:42.932114702Z", "text": "I have appt today (1/22/2026)with Dr.Ashli Bartolo (Dr.Nguyen''s PA). I am very please with her friendly greeting and her knowlegeable. Plus her medical assistant Daylia is super nice and cheerful. Both of them make my visit so pleasant. Thank you so much.", "author": "Jeff S.", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117990180176016178988/reviews"}, {"date": "2024-03-15T18:25:53.875258Z", "text": "I came in for a physical and my medications were not sent, I’ve called weekly for 4 weeks and left messages via portal. I was informed I would get a call back, I never do. I am an asthmatic patient which March is our worst season due to weather change etc. after 30 days I had to walk in office to request a refill and to speak with the office manager, they informed me that the manager was not available. This is poor malpractice, refills should be sent at the time of routine physicals and I do not reccomend patients come here if you have any medical issues or chronic diseases that requires medication, 4 weeks without an inhaler and trying to avoid urgent care was the worst life experience for me. These are notcontrolled medications, they could be refilled by a nurse.", "author": "Toyyibat Azeez", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/102529889984427536176/reviews"}, {"date": "2026-02-12T03:06:00.349159762Z", "text": "Kokoro Wellness is unprofessional and immoral in the area of billing practices and patient relations. A physician billed a family member’s insurance over $1400.00 for services they did NOT render because my family member discontinued using Kokoro Wellness over a month prior to the date submitted on the claim. I do NOT recommend using Kokoro Wellness for any healthcare needs.", "author": "Joseph Swanson", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/113031951987755710683/reviews"}], "website": "https://www.kokorowellness.org/", "location": {"latitude": 32.8942536, "longitude": -96.73900789999999}, "services": ["Annual Physicals & Wellness Visits", "High Blood Pressure Management", "Diabetes Management", "High Cholesterol Management", "Chronic Pain Management", "Cardiovascular Screenings", "Well Woman Exam & Women''s Health", "Allergies & Ear Infections", "STI Testing & Sexual Health", "Immunizations & Flu Shots", "Joint & Knee Viscosupplementation", "Medical Massage Therapy", "Weight Management", "Chronic Care Management"], "insurance": {"notes": "Providers are not contracted with any Medicaid or Star/Star Plus plans. Medicare and most commercial plans accepted. Self-pay welcome. Essential Direct Care™ membership available for uninsured or high-deductible patients.", "accepts_medicaid": true, "accepts_medicare": true, "accepted_networks": ["Blue Cross Blue Shield", "Blue Choice (PPO/POS)", "Blue Essentials (HMO Blue)", "Aetna", "UnitedHealthcare", "Cigna", "Humana", "Baylor Scott & White", "Multiplan", "PHCS", "First Health Network", "HealthSmart", "Prime Health Network", "Provider Select", "Evolutions Healthcare", "Imagine Health", "Ambetter", "6 Degrees (Ft Worth Firefighters)", "Medicare", "American Health Plan of Texas - Med Av I-SNP", "Molina Healthcare", "TRICARE", "Oscar Marketplace", "Three Rivers Provider Network", "CareWorks (Rockport)", "Texas Mutual", "Travelers", "Sedgwick", "CorVel", "Zurich", "Gallagher Bassett", "Medicaid"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Accepting New Patients", "detail": "Now accepting new patients at the Dallas/Abrams clinic.", "category": "access"}, {"title": "Same-Day Appointments", "detail": "Same-day appointments available for urgent needs.", "category": "convenience"}, {"title": "Medicare & Most Commercial Insurance", "detail": "Accepts Medicare, Medicare Advantage, and most commercial insurance plans.", "category": "insurance"}, {"title": "Self-Pay Welcome", "detail": "Self-pay patients are welcome, with transparent pricing and the Essential Direct Care™ membership option.", "category": "insurance"}, {"title": "Essential Direct Care™", "detail": "A membership-based primary care plan with no deductible, no surprise bills, and predictable annual pricing.", "category": "care"}, {"title": "Board-Certified Providers", "detail": "Care from board-certified family medicine providers who build real relationships with patients.", "category": "care"}], "price_tier": "$", "source_url": "https://www.kokorowellness.org/", "appointment": {"booking_note": "Book online via Healow or call 972-201-3552.", "appointment_url": "https://healow.com/apps/practice/kokoro-health-and-wellness-inc-dallas-tx-20962?v=2&t=1&f=PXGx7DvPZVd0lbZ2", "new_patient_note": "Now accepting new patients.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean speaking medical clinic in Dallas, TX", "search_text": "family medicine | family practice | primary care | bác sĩ gia đình | 가정의학과 | 家庭医学 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | korean | 한국어 | 한인 | 한국말 | annual physicals & wellness visits | high blood pressure management | diabetes management | high cholesterol management | chronic pain management | cardiovascular screenings | well woman exam & women''s health | allergies & ear infections | sti testing & sexual health | immunizations & flu shots | joint & knee viscosupplementation | medical massage therapy | weight management | chronic care management | preventive | chronic care | acute care | sexual health | pain management | therapy | blue cross blue shield | blue choice (ppo/pos) | blue essentials (hmo blue) | aetna | unitedhealthcare | cigna | humana | baylor scott & white | multiplan | phcs | first health network | healthsmart | prime health network | provider select | evolutions healthcare | imagine health | ambetter | 6 degrees (ft worth firefighters) | medicare | american health plan of texas - med av i-snp | molina healthcare | tricare | oscar marketplace | three rivers provider network | careworks (rockport) | texas mutual | travelers | sedgwick | corvel | zurich | gallagher bassett | medicaid | hanhdung nguyen, do | doctor of osteopathic medicine · family medicine | ashli bartolo, pa-c | board-certified physician assistant (nccpa) · family medicine", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "service", "establishment"], "open_weekend": false, "rating_count": 198, "team_members": [{"name": "HanhDung Nguyen, DO", "role": "Doctor of Osteopathic Medicine · Family Medicine", "bio_snippet": "Trained at Nova Southeastern University College of Osteopathic Medicine. Residency in Family Practice at Dallas Southwest Medical Center. Evidence-based, patient-centered care focused on prevention and optimal long-term health.", "languages_spoken": ["English", "Vietnamese"]}, {"name": "Ashli Bartolo, PA-C", "role": "Board-Certified Physician Assistant (NCCPA) · Family Medicine", "bio_snippet": "NCCPA-certified. Master of Physician Assistant Studies, Rocky Vista University. Texas A&M Biology graduate. Dedicated to patient education, strong provider relationships, and compassionate care that empowers patients to lead healthier lives.", "languages_spoken": ["English"]}], "open_saturday": false, "quality_score": 100, "working_hours": {"friday": "7:30 AM – 4:00 PM", "monday": "8:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "8:00 AM – 5:00 PM", "wednesday": "8:00 AM – 5:00 PM"}, "gallery_images": ["https://www.kokorowellness.org/images/photo-01.jpg", "https://www.kokorowellness.org/images/photo-03.jpg", "https://www.kokorowellness.org/images/photo-04.jpg", "https://www.kokorowellness.org/images/Koko_Team_Lobby.png", "https://www.kokorowellness.org/images/KHW_Team_and_koko1_png.png", "https://www.kokorowellness.org/images/photo-02.jpg"], "review_profile": {"rating": 3.9, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight the friendly and knowledgeable staff, making visits enjoyable."}, {"theme": "Billing Practices", "mentions": 2, "sentiment": "Negative", "summary_quote": "Several patients report overcharging and unresolved billing disputes, leading to frustration."}, {"theme": "Communication", "mentions": 2, "sentiment": "Negative", "summary_quote": "Patients cite unreturned calls and ignored messages regarding billing and medication refills."}, {"theme": "Medication Management", "mentions": 1, "sentiment": "Negative", "summary_quote": "One patient experienced a critical delay in receiving asthma medication refills, causing distress."}, {"theme": "Office Management", "mentions": 1, "sentiment": "Negative", "summary_quote": "A reviewer found the office unresponsive when attempting to escalate concerns to management."}], "summary": "Patients appreciate the friendly and knowledgeable staff, but many express frustration with billing issues and poor communication regarding medication refills and office management.", "review_count": 198, "concern_themes": [], "positive_themes": ["Attentive and caring providers", "Helpful and pleasant staff", "Thorough and clear communication", "Seamless check-in process"], "featured_reviews": [{"date": "2025-08-14T18:10:52.323847591Z", "text": "I love going to my appointments at Kokoro health an wellness .Ashli Cindy an Dalylia  are amazing they always make it fun an enjoyable. They make you feel welcome great environment  🥹 Make your appointment with this clinic. You’ll be ready to make your next one as soon as you walk though the door to leave. #AmazingSaff Thank you Kokoro 🫶🏾", "author": "Alonzo Jordan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111032035658991301129/reviews"}, {"date": "2026-03-07T02:39:21.277276067Z", "text": "I have been seeing Dr Nguyen as my primary doctor for probably more than half of my life now. She''s a great physician. I am leaving a poor review here, as the office and billing have become a thorn in my side that I will not allow to continue without saying something about it.\nI have been overcharged multiple times. I have had payments that I made to the office at time of service, get dropped from my bill and invoice actually increase from the already inflated invoice amount. I have made many many calls to the office, and left voicemails, yet be completely ignored. The communication is a one-way street, because the invoices are quite conveniently sent to me via text, email, and regular mail.  Multiple calls are left unreturned even after one successful connection where staff escalated to the billing manager to review my concerns.  No call back.\nI am having to resort to sending a certified letter in order to get anyone''s attention. Let''s see how that goes.\n\nHealth insurance companies and poorly run medical offices like this, give this entire health care industry the bad reputation that it has, while the consumer/patients suffer the financial consequences.  This should be an absolute embarrassment.", "author": "Brigida Ward", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/103205311118293824912/reviews"}, {"date": "2026-01-22T22:07:42.932114702Z", "text": "I have appt today (1/22/2026)with Dr.Ashli Bartolo (Dr.Nguyen''s PA). I am very please with her friendly greeting and her knowlegeable. Plus her medical assistant Daylia is super nice and cheerful. Both of them make my visit so pleasant. Thank you so much.", "author": "Jeff S.", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117990180176016178988/reviews"}, {"date": "2024-03-15T18:25:53.875258Z", "text": "I came in for a physical and my medications were not sent, I’ve called weekly for 4 weeks and left messages via portal. I was informed I would get a call back, I never do. I am an asthmatic patient which March is our worst season due to weather change etc. after 30 days I had to walk in office to request a refill and to speak with the office manager, they informed me that the manager was not available. This is poor malpractice, refills should be sent at the time of routine physicals and I do not reccomend patients come here if you have any medical issues or chronic diseases that requires medication, 4 weeks without an inhaler and trying to avoid urgent care was the worst life experience for me. These are notcontrolled medications, they could be refilled by a nurse.", "author": "Toyyibat Azeez", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/102529889984427536176/reviews"}, {"date": "2026-02-12T03:06:00.349159762Z", "text": "Kokoro Wellness is unprofessional and immoral in the area of billing practices and patient relations. A physician billed a family member’s insurance over $1400.00 for services they did NOT render because my family member discontinued using Kokoro Wellness over a month prior to the date submitted on the claim. I do NOT recommend using Kokoro Wellness for any healthcare needs.", "author": "Joseph Swanson", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/113031951987755710683/reviews"}]}, "review_summary": "Patients appreciate the friendly and knowledgeable staff, but many express frustration with billing issues and poor communication regarding medication refills and office management.", "about_highlight": "Kokoro Health & Wellness provides evidence-based, patient-centered primary care at two Dallas-area locations, including the Abrams Road clinic. The clinic offers comprehensive family medicine, chronic care management, weight management, and an innovative Essential Direct Care™ membership plan. With board-certified providers, same-day appointments, and a commitment to accessible, compassionate care, Kokoro serves as a medical home for adults 18+ in North Texas.", "appointment_url": "https://healow.com/apps/practice/kokoro-health-and-wellness-inc-dallas-tx-20962?v=2&t=1&f=PXGx7DvPZVd0lbZ2", "google_maps_url": "https://maps.google.com/?cid=2932812026415345461&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJ1_oTM00hTIYRNe960_9wsyg", "quality_missing": [], "search_keywords": ["family medicine", "family practice", "primary care", "bác sĩ gia đình", "가정의학과", "家庭医学", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "korean", "한국어", "한인", "한국말", "annual physicals & wellness visits", "high blood pressure management", "diabetes management", "high cholesterol management", "chronic pain management", "cardiovascular screenings", "well woman exam & women''s health", "allergies & ear infections", "sti testing & sexual health", "immunizations & flu shots", "joint & knee viscosupplementation", "medical massage therapy", "weight management", "chronic care management", "preventive", "chronic care", "acute care", "sexual health", "pain management", "therapy", "blue cross blue shield", "blue choice (ppo/pos)", "blue essentials (hmo blue)", "aetna", "unitedhealthcare", "cigna", "humana", "baylor scott & white", "multiplan", "phcs", "first health network", "healthsmart", "prime health network", "provider select", "evolutions healthcare", "imagine health", "ambetter", "6 degrees (ft worth firefighters)", "medicare", "american health plan of texas - med av i-snp", "molina healthcare", "tricare", "oscar marketplace", "three rivers provider network", "careworks (rockport)", "texas mutual", "travelers", "sedgwick", "corvel", "zurich", "gallagher bassett", "medicaid", "hanhdung nguyen, do", "doctor of osteopathic medicine · family medicine", "ashli bartolo, pa-c", "board-certified physician assistant (nccpa) · family medicine"], "services_offered": [{"name": "Annual Physicals & Wellness Visits", "category": "Preventive", "description": "Comprehensive annual exams to assess overall health and prevent disease.", "is_featured": true, "patient_fit": "All adults 18+"}, {"name": "High Blood Pressure Management", "category": "Chronic Care", "description": "Diagnosis, monitoring, and treatment of hypertension.", "is_featured": false, "patient_fit": "Patients with hypertension"}, {"name": "Diabetes Management", "category": "Chronic Care", "description": "Comprehensive diabetes care including medication management and lifestyle coaching.", "is_featured": false, "patient_fit": "Patients with Type 2 Diabetes"}, {"name": "High Cholesterol Management", "category": "Chronic Care", "description": "Management of hyperlipidemia through medication and lifestyle changes.", "is_featured": false, "patient_fit": "Patients with high cholesterol"}, {"name": "Chronic Pain Management", "category": "Chronic Care", "description": "Evidence-based treatment for chronic pain conditions.", "is_featured": false, "patient_fit": "Patients with chronic pain"}, {"name": "Cardiovascular Screenings", "category": "Preventive", "description": "Screening for heart disease risk factors and early detection.", "is_featured": false, "patient_fit": "Adults at risk for heart disease"}, {"name": "Well Woman Exam & Women''s Health", "category": "Preventive", "description": "Comprehensive women''s health exams and preventive care.", "is_featured": false, "patient_fit": "Women 18+"}, {"name": "Allergies & Ear Infections", "category": "Acute Care", "description": "Diagnosis and treatment of allergies and ear infections.", "is_featured": false, "patient_fit": "All adults"}, {"name": "STI Testing & Sexual Health", "category": "Sexual Health", "description": "Confidential testing and treatment for sexually transmitted infections.", "is_featured": false, "patient_fit": "Adults"}, {"name": "Immunizations & Flu Shots", "category": "Preventive", "description": "Annual flu shots and other routine immunizations.", "is_featured": false, "patient_fit": "All adults"}, {"name": "Joint & Knee Viscosupplementation", "category": "Pain Management", "description": "Injection therapy for knee osteoarthritis to improve joint function and reduce pain.", "is_featured": false, "patient_fit": "Patients with knee osteoarthritis"}, {"name": "Medical Massage Therapy", "category": "Therapy", "description": "Therapeutic massage for pain relief and recovery, included in Essential Direct Care™ plan.", "is_featured": false, "patient_fit": "Essential Direct Care™ members"}, {"name": "Weight Management", "category": "Chronic Care", "description": "Comprehensive weight management including GLP-1 medications (semaglutide/tirzepatide), lifestyle coaching, and lab monitoring.", "is_featured": true, "patient_fit": "Adults struggling with obesity or overweight"}, {"name": "Chronic Care Management", "category": "Chronic Care", "description": "Dedicated program for patients with chronic conditions, including monthly check-ins, medication coordination, and personalized care planning.", "is_featured": true, "patient_fit": "Patients with chronic conditions like diabetes, hypertension, heart disease"}], "short_description": "Evidence-based, patient-centered primary care serving the Dallas/Abrams community with same-day appointments, comprehensive family medicine, and an innovative Essential Direct Care™ membership plan.", "google_website_url": "https://www.kokorowellness.org/", "insurance_accepted": ["Blue Cross Blue Shield", "Blue Choice (PPO/POS)", "Blue Essentials (HMO Blue)", "Aetna", "UnitedHealthcare", "Cigna", "Humana", "Baylor Scott & White", "Multiplan", "PHCS", "First Health Network", "HealthSmart", "Prime Health Network", "Provider Select", "Evolutions Healthcare", "Imagine Health", "Ambetter", "6 Degrees (Ft Worth Firefighters)", "Medicare", "American Health Plan of Texas - Med Av I-SNP", "Molina Healthcare", "TRICARE", "Oscar Marketplace", "Three Rivers Provider Network", "CareWorks (Rockport)", "Texas Mutual", "Travelers", "Sedgwick", "CorVel", "Zurich", "Gallagher Bassett", "Medicaid"], "google_primary_type": "Doctor", "provider_credentials": {"education": [], "providers": ["HanhDung Nguyen, DO", "Ashli Bartolo, PA-C"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "accepting_new_patients": true, "google_business_status": "OPERATIONAL", "google_formatted_address": "8420 Abrams Rd #208, Dallas, TX 75243, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/110499984732195794777", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjW5f-XrYgd6bpurhhuaWM1eSqdr7kJIenk0Wa0_hbYzdFvef25y=s100-p-k-no-mo", "displayName": "Kokoro Health & Wellness Family Clinic - Abrams Rd."}], [{"uri": "https://maps.google.com/maps/contrib/110499984732195794777", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjW5f-XrYgd6bpurhhuaWM1eSqdr7kJIenk0Wa0_hbYzdFvef25y=s100-p-k-no-mo", "displayName": "Kokoro Heal