INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('e247ad04-d5bf-473d-bef5-e6dbb1c8bd7c', NULL, 'Chinatown Public Health Center', 'Chinatown Public Health Center (CPHC) has been proudly serving San Franciscans and the Chinese community since 1929. As a San Francisco Health Network clinic located in Chinatown, its mission is to provide quality and cost-effective primary care to patients and to promote the health of San Franciscans of all ages, with expertise and competence in serving immigrants. The center offers a full array of services including primary care for children and adults, team-based care, population health disease registries, integrated behavioral health, pediatric and adult dentistry, podiatry, pharmacy, nurse clinic, and nutrition services. Staff speak English, Cantonese, Toishanese, Mandarin, Vietnamese, and Tagalog, supporting the clinic''s vision of being a patient- and population-centered health home of choice for non- or Limited English Proficient Chinese immigrants and other vulnerable San Franciscans.', '1490 Mason Street, San Francisco, CA 94133', 'San Francisco', 'CA', '94133', '628-217-6500', ARRAY['Cantonese', 'Mandarin', 'English', 'Tagalog', 'Vietnamese', 'Toishanese', 'Chinese']::text[], 'Primary Care', FALSE, '{"fax": "628-217-7510", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinatown-public-health-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinatown-public-health-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinatown-public-health-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinatown-public-health-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinatown-public-health-center-google-5.webp"], "rating": 3.8, "reviews": [{"date": "2025-12-05T18:05:43.180213768Z", "text": "I’m a little disappointed I have been in this clinic approximately 4 years they have changed 3 doctors on me they changed my medication so many times they add some or they they increase the doses some make me sleepy others nausea or other symptoms they only say you will get used to it almost saying get over it and deal with it in a way.\nI wish there was some really good doctors out there doctors that really care for their patients unfortunately I had one but she resigned I guess when you are good and don’t listen to them you become indispensable so sad .", "author": "Gregory S Hyba", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/114005660335264909962/reviews"}, {"date": "2014-12-08T17:31:09.609Z", "text": "Service is fine.  I couldn''t be more whitebread and didn''t feel the service was worse than any other Public Health.  I am grateful this place exists.  Do not drive.  There is zero parking in the neighborhood.", "author": "Anna M. Lincoln", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/118016860931815426183/reviews"}, {"date": "2017-11-02T11:13:29.222Z", "text": "Overall Impression 3 stars (it can get better.), Availability for appointments 2 stars, Prescription Accuracy 2, Waiting time 2 (today was 48 minutes delay), Staff friendliness 3.5, Location convenience 4, Wheel chair convenience 5, Cultural competence 4, Transgender Wellness 1 (I am going to work with them this year so that Asian Pacific Islander LGBTQQIP folks feel at ease at this center as well as PreOp and PostOp care, hormones timely implementation and dosage increase, language sensitivity), Cleansiness 5, Willingness to accommodate 2, Hep B prevention 5, Flu shots 5, Whopping cough 5, Nutritional guide for diabetic 0, Nutritional guide for injuries and pain reduction 0, follow up accuracy and speed 4, Returning calls 1, Acupuncture ??? I''ll let you know, Mental Health Patients sensitivity 1, Affiliations with other Asian wellness services 1, Case Manager accessibility 0, Capacity and Attentiveness 1, Primary Care Physician 4\nMy above rating is from comparing with public health clinics in Honolulu, Hilo, San Jose, Marin, San Mateo, Berkeley, Oakland and Santa Clara.", "author": "Yuki Togawa Strategist", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/108354690492419575562/reviews"}, {"date": "2017-03-25T05:04:19.643Z", "text": "Awesome place for health check up ..such a friendly staff ..doctor Stephene le is very kind polite and nice", "author": "Sammy rulzes", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107713007432664917520/reviews"}, {"date": "2021-08-03T18:21:28.989348Z", "text": "I can always count on this clinic to serve me with impeccable care.", "author": "tod overstreet", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105614185340231736123/reviews"}], "website": "https://www.sf.gov/location--chinatown-public-health-center", "location": {"latitude": 37.7972081, "longitude": -122.4114951}, "services": ["Primary care for children and adults", "Integrated behavioral health", "Pediatric and adult dentistry", "Podiatry", "Pharmacy", "Nurse Clinic", "Nutrition services"], "insurance": {"notes": "No information about insurance is provided on the page.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Serving Since 1929", "detail": "Chinatown Public Health Center has been proudly serving San Franciscans and the Chinese community since 1929.", "category": "care"}, {"title": "Multilingual Staff", "detail": "Staff speak English, Cantonese, Toishanese, Mandarin, Vietnamese, and Tagalog.", "category": "culture"}, {"title": "Full Array of Services", "detail": "Offers primary care, integrated behavioral health, pediatric and adult dentistry, podiatry, pharmacy, nurse clinic, and nutrition services.", "category": "care"}, {"title": "San Francisco Health Network", "detail": "Part of the San Francisco Health Network and the Department of Public Health.", "category": "care"}, {"title": "Public Transit Accessible", "detail": "Nearby bus lines: 1, 8/8AX/8BX/30, 45, 12, 27, and Powell-Mason Cable Car.", "category": "convenience"}], "price_tier": "$$", "source_url": "https://www.sf.gov/location--chinatown-public-health-center", "appointment": {"booking_note": null, "appointment_url": "https://www.sf.gov/get-health-appointment/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese primary care clinic in San Francisco, CA", "search_text": "primary care | family doctor | general practitioner | annual physical | checkup | bác sĩ gia đình | khám tổng quát | nội khoa | 내과 | 가정의학과 | 家庭医生 | 全科医生 | 内科 | cantonese | chinese | 粤语 | 广东话 | tiếng quảng đông | mandarin | 中文 | 普通话 | 国语 | tiếng trung | tiếng phổ thông | english | tagalog | vietnamese | tiếng việt | người việt | bác sĩ việt | toishanese | 华人 | primary care for children and adults | integrated behavioral health | pediatric and adult dentistry | podiatry | pharmacy | nurse clinic | nutrition services | behavioral health | dental | specialty care | preventive | stephanie le, md | medical director | cho tai | practice manager | po lin lui | interim behavioral health supervisor / nurse manager | amir spencer | eligibility supervisor / patient access supervisor", "google_types": ["medic