INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6e941590-55e6-4a8c-a5c2-99043be0781a', NULL, 'Woori Medical Group 우리성모병원', 'Woori Medical Group (우리성모병원) is a Korean-oriented medical clinic located in the Convoy area of San Diego. The clinic follows CDC and San Diego health department guidelines to ensure patient safety through rigorous infection prevention and control measures. They offer both in-person and telehealth services (phone/video consultations) for patient convenience, with same-day appointments available by phone. Walk-ins are not accepted without prior contact.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('1a09cb8a-4ff0-4dd0-9791-6d35b6c6d08f', NULL, 'Centre Dental/中央牙科', 'Centre Dental (中央牙科) is a bilingual implant and cosmetic dentistry practice in Lower Manhattan, established in 2004 and led by Dr. John Shi, a Columbia DDS with over 20 years of clinical expertise. The practice is grounded in evidence-based, 3D-guided implant surgery and offers same-day crowns using CEREC technology. Every patient receives a complimentary 3D iTero Lumina scan, a written treatment plan in plain language, and care in English, Mandarin, or Cantonese—ensuring no translator is needed.
