INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('bd39d8a6-268f-4736-9add-6d3023b43908', NULL, 'CORE ACUPUNCTURE health+wellness', 'CORE ACUPUNCTURE health+wellness is a Buckhead, Atlanta clinic led by Dr. Jennifer Myers, DAc, LAc, Dipl.Ac., offering integrative acupuncture treatments for fertility, IVF support, oncology symptom management, chronic pain relief, migraines, sports injuries, and holistic wellness care. With over a decade of service, the clinic is recognized multiple years through the BusinessRate BEST of Atlanta Awards for excellence in Fertility Care, Sports Medicine, and Acupuncture. Each new patient receives a personalized evaluation and tailored treatment plan, focusing on identifying and treating the root cause of imbalance to support the body’s natural healing systems.', '455 E. Paces Ferry Rd NE #201, Atlanta, GA 30305', 'Atlanta', 'GA', '30305', '(770) 375-5594', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"email": "jennifer@coreacupunctureatlanta.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/core-acupuncture-healthwellness-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/core-acupuncture-healthwellness-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/core-acupuncture-healthwellness-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/core-acupuncture-healthwellness-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/core-acupuncture-healthwellness-google-5.webp"], "rating": 5, "pricing": [{"name": "New Patient Forms (Mini Session)", "notes": "New patient forms available for download for mini session appointments.", "price": null, "category": "New Patient", "price_range": null}, {"name": "New Patient Forms (Initial Acupuncture Session)", "notes": "New patient forms available for download for full initial acupuncture session appointments.", "price": null, "category": "New Patient", "price_range": null}], "reviews": [{"date": "2026-02-20T17:43:50.654508907Z", "text": "Very professional.  Jennifer does a great job explaining the treatment and making me feel comfortable.  Always on time and efficient.  Has been very helpful in facilitating my recovery from major surgery.", "author": "Doug MacGinnitie", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113164682198140983875/reviews"}, {"date": "2026-01-23T20:50:52.004982181Z", "text": "I’ve seen Dr. Jennifer for years for a myriad of conditions and issues - migraines and injuries being my 2 “regulars”.  More recently I’ve been seeing her for microneedling.  I just finished the series of treatments for my face. I originally started microneedling due to hormonal acne issues as well as what I would describe as a dull, unhealthy countenance.  I wasn’t sure what to expect with my series of treatments and how much progress would be possible.  I was ecstatic to finish the series of treatments and see the results.  Breakouts are almost non-existent now! That alone was worth it! But I also feel my face glows again …. There is color and life in my skin and feel like it radiates health.  I’m so happy with the results, I’ve started the treatment series for my neck and chest. Stay tuned for the results!!!", "author": "Brandy", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116541957184838368360/reviews"}, {"date": "2026-02-25T15:41:01.720448601Z", "text": "Delightful experience - very warm and welcoming environment; super informative. I highly recommend if you''re seeking out acupuncture.", "author": "Evelyn Michele Caldwell Barton", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102279142270297937478/reviews"}, {"date": "2025-02-07T17:58:02.839938Z", "text": "I can''t recommend Jennifer enough! She is an exceptional professional with a true vocation for helping others. From the moment I walked into Core Acupuncture, it was clear that Jennifer genuinely cares about her patients'' well-being. Her expertise and attention to detail are unmatched, and she takes the time to listen and understand each individual''s needs.\n\nJennifer has been a key component in my recovery from Bell’s Palsy. I’ve seen noticeable improvements from the very first session, and my smile is getting stronger and looking more like it did before. She already has a clear game plan in place to help restore my eye as well. The movement on the side of my face has improved significantly after each session. I truly feel like I''m on the right path, and I’m so grateful for her care.\n\nHer calming presence and thorough approach make every session feel personalized and effective. She is a great investment for my long-term health plan, and I couldn’t be more grateful for everything she’s done. If you''re looking for someone who not only knows their craft but truly cares, Jennifer is the one to see!", "author": "Laura C. Ortiz", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100540370308140597719/reviews"}, {"date": "2025-01-27T16:44:25.595070Z", "text": "Absolutely thrilled with my experience at Core Acupuncture Atlanta with Jennifer Myers! I had a microneedling session today for my face, lips, and under-eye area, along with acupuncture and red light therapy, and I can already tell I’m in for amazing results!\n\nI’ve been seeing Jenn for years for my acupuncture, and her warm and welcoming demeanor has always put me at ease. She took the time to explain all the procedures thoroughly, addressing all my questions and concerns. Her expertise and attention to detail were evident throughout the treatments, making me feel confident in her hands.\n\nThe microneedling was comfortable, and I’m excited to see how my skin''s texture and tone will improve in the next two weeks. My lips feel plump and rejuvenated, and the delicate under-eye area already looks refreshed. The red light therapy was a fantastic addition, enhancing the microneedling results and promoting healing. Plus, the acupuncture added a wonderful layer of relaxation to the experience, enhancing my overall well-being.\n\nIf you’re considering microneedling, acupuncture, or red light therapy, I wholeheartedly recommend Jennifer at Core Acupuncture Atlanta. Her skill and passion for what she does truly shine through. This place deserves all the recognition—it’s a hidden gem that’s! Thank you, Jennifer, for your incredible work! 🌟", "author": "Gallery Chimera", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100077021106152631671/reviews"}], "website": "http://www.coreacupunctureatlanta.com/", "location": {"latitude": 33.8376044, "longitude": -84.3727474}, "services": ["Acupuncture", "Fertility & Pregnancy Support", "Sports Medicine Acupuncture", "Microneedling & Nanoneedling", "Facial Rejuvenation / Cosmetic Acupuncture", "Oncology Support Care"], "insurance": {"notes": "Accepts HSA/FSA cards. Provides a superbill for patients to submit to their insurance for out-of-network reimbursement. Acupuncture benefits limited in GA; patients should check with their insurance provider.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Best of Atlanta Recognized", "detail": "Multiple years through the BusinessRate BEST of Atlanta Awards honoring excellence in customer satisfaction and service across Fertility Care, Sports Medicine, and Acupuncture.", "category": "reviews"}, {"title": "Personalized Treatment Plans", "detail": "Each new patient receives a personalized evaluation and tailored treatment plan designed to address individual health concerns.", "category": "care"}, {"title": "Over 10 Years Serving Buckhead & Atlanta", "detail": "Serving the Buckhead and greater Atlanta community for over a decade.", "category": "convenience"}, {"title": "HSA/FSA Accepted", "detail": "Accepts HSA and FSA as forms of payment, and provides superbills for insurance reimbursement when acupuncture benefits are available.", "category": "insurance"}], "price_tier": "$$", "source_url": "http://www.coreacupunctureatlanta.com/", "appointment": {"booking_note": "New patients schedule via the ''NEW PATIENTS SCHEDULE HERE'' link on the website. Existing patients use the separate online booking portal.", "appointment_url": "https://ehr.unifiedpractice.com/Public/OnlineBooking?ClinicUid=3a373fd4-9a53-4eed-81f7-09852c9144bc", "new_patient_note": "New patients can schedule online via the dedicated ''NEW PATIENTS SCHEDULE HERE'' page.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese clinic in Atlanta, GA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | fertility & pregnancy support | sports medicine acupuncture | microneedling & nanoneedling | facial rejuvenation / cosmetic acupuncture | oncology support care | reproductive health | sports medicine | aesthetic | oncology support | jennifer myers | owner, clinical director, licensed acupuncturist", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "service", "establishment"], "open_weekend": false, "rating_count": 36, "team_members": [{"name": "Jennifer Myers", "role": "Owner, Clinical Director, Licensed Acupuncturist", "bio_snippet": "Dr. Jennifer Myers, DAc, LAc, Dipl.Ac., earned her Doctor of Acupuncture from Virginia University of Integrative Medicine and Master''s from Academy for Five Element Acupuncture. She holds advanced training in women''s health, fertility, sports medicine, oncology support (including certification through Memorial Sloan Kettering Cancer Center’s Oncology Acupuncture program), and trauma-informed care. Over a decade of service in Buckhead, Atlanta.", "languages_spoken": []}], "open_saturday": false, "quality_score": 95, "working_hours": {"friday": "7:00 AM – 12:00 PM", "monday": "7:00 AM – 2:00 PM", "sunday": "Closed", "tuesday": "12:00 – 5:30 PM", "saturday": "Closed", "thursday": "12:00 – 5:30 PM", "wednesday": "7:00 – 10:30 AM, 1:00 – 3:00 PM"}, "gallery_images": ["https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2019/10/corehealth-white.png", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2024/12/Vertical_Jennifer-Myers_RMOPhotography-website-2.jpeg", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2024/06/Accupuncture-12.jpeg", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2019/12/ryan-franco-8r1hxU8OfXA-unsplash-scaled.jpg", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2019/12/victor-freitas-nA0UDNDbxys-unsplash-scaled.jpg", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2025/02/Microneedling-Nanoneedling.png", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2019/12/21327959_l-scaled.jpg", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2025/03/website-pic-for-oncology-support-1800-x-1200-px.png", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2024/12/Badge_Award.png", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2025/07/2a69494665234acdbf2a069cf9944cef-1__2_-removebg-preview.png", "https://core-health-and-wellness-acupuncture-v1782228117.websitepro-cdn.com/wp-content/uploads/2026/03/Best-of-2026.png"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 5, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight Jennifer''s exceptional skills and noticeable improvements in their conditions."}, {"theme": "Staff Professionalism", "mentions": 4, "sentiment": "Positive", "summary_quote": "Patients frequently mention Jennifer''s professional and thorough approach to treatments."}, {"theme": "Treatment Outcomes", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers report significant health improvements and satisfaction with treatment results."}, {"theme": "Communication", "mentions": 3, "sentiment": "Positive", "summary_quote": "Jennifer is praised for her clear explanations and attentive listening to patient needs."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "The clinic is described as warm and welcoming, enhancing the overall patient experience."}], "summary": "Patients consistently praise Jennifer''s professionalism, expertise, and caring approach, highlighting significant improvements in various conditions and a welcoming clinic environment.", "review_count": 36, "concern_themes": [], "positive_themes": ["Relief from knee pain, back pain, and migraines", "Effective fertility and pregnancy support", "Professional, caring, and attentive practitioner", "Relaxing atmosphere and comfortable treatments", "Excellent microneedling results for skin rejuvenation"],