INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('37e82a5a-f19b-4524-956e-3307e8e32c40', NULL, 'William K Wan, DDS MD', '尹国权医生牙科诊所 (William K Wan, DDS, MD) 位于芝加哥唐人街，是一家致力于为社区提供全方位优质牙科护理的诊所。从您第一次接触诊所开始，您就会发现这不是一家典型的牙科诊所，而是一个由经验丰富、富有爱心且技术精湛的专业团队组成的地方。我们提供从常规洁牙预防、美容牙科、牙周病治疗、种植牙到口腔颌面外科等全面的个性化治疗方案，以满足每位患者独特的需求和期望。我们的使命是提供最高质量的牙科和患者护理，并真诚地希望您能通过本网站了解更多关于我们的实践、牙科状况和治疗建议。', '2262 S Wentworth Ave Floor 2, Chicago, IL 60616', 'Chicago', 'IL', '60616', '(312)791-1013', ARRAY['中文', '英语', 'Chinese']::text[], 'Dental', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/william-k-wan-dds-md-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/william-k-wan-dds-md-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/william-k-wan-dds-md-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/william-k-wan-dds-md-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/william-k-wan-dds-md-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2025-12-22T23:31:26.792705798Z", "text": "I was fortunate to receive dental treatment from Dr. Wan twice within ten days this month, once paid and once free of charge. Both times, he provided meticulous and thoughtful treatment tailored to my needs. He is a very friendly and approachable doctor. During our conversations, I learned that he used to teach at Loyola University and owned three dental clinics. Now in his eighties, he still works full-time at his clinic in Chinatown. He also provides free dental services in India. He is a rare and excellent doctor who doesn''t work for money.", "author": "XUE FUNG", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109485466959541541446/reviews"}, {"date": "2023-11-29T00:48:39.553476Z", "text": "The doctor is an elderly man, but I admire his conscientious and responsible attitude. His filling skills are skillful, delicate, fast and efficient. I was shocked that the filled teeth didn''t look any different from my own teeth. I will come to visit him in the future, and his meticulous work spirit is worthy of my admiration and learning 👍", "author": "Harper", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111346010468637425725/reviews"}, {"date": "2025-01-01T15:37:40.374054Z", "text": "Dr. Wan is the most patient, knowledgeable, caring, honest dentist I have ever met in my life. My teeth are horrible. I have been going to all kinds of dentists since I was a little kid. Of all the dentists I''ve visited, Dr. Wan is the best! His skills are precise, exact, and are executed with care, which was very important to me because I am easily startled and scared especially when it comes to dentists.\n\nDr. Wan removed two difficult wisdom teeth for me with such grace and peace. My recovery is easy and smooth. The whole team at Dr. Wan''s office is phenomenal. They are friendly, welcoming, and very caring. Thank you, Dr. Wan and all the team members!", "author": "Luyang Liu", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110760921777965851304/reviews"}, {"date": "2026-02-13T14:56:33.218387176Z", "text": "I''ve been coming to Dr. Wan''s office for years got to know him very well. He loves my wife and he is an excellent doctor.", "author": "Abram Anderson", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104317260180583627139/reviews"}, {"date": "2025-06-10T19:45:51.603438Z", "text": "I want to share some serious concerns regarding Dr. Wan, the dentist many residents from Hilliard Homes, including my husband, have visited. Unfortunately, the experience has been extremely disappointing and concerning.\n\nDr. Wan advertised a free consultation, which appeared to be more of a tactic to bring in new patients. After the consultation, he recommended a deep cleaning procedure that cost approximately $3,000. My husband underwent this treatment on May 16, 2025, and has been in significant pain since then. He had to take pain medication three times a day for nearly a month following the procedure.\n\nAdditionally, the equipment used in the clinic seemed outdated, and we have heard similar complaints from other Hilliard Homes residents who felt misled or dissatisfied with his services.\n\nI believe this matter deserves further attention, especially since it affects the well-being of our community members.", "author": "Maggie Wei", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/109341632531638003559/reviews"}], "website": "http://williamkwandds.com/", "location": {"latitude": 41.851110399999996, "longitude": -87.6321574}, "services": ["洁牙与预防", "美容牙科", "牙周病治疗", "修复科", "正畸科", "口腔颌面外科", "牙髓病科", "牙科急诊", "儿童牙科"], "insurance": {"notes": "未在网站中明确列出接受的保险计划。建议直接致电诊所咨询保险事宜。", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "中英双语服务", "detail": "网站及诊所提供中文和英文双语沟通，方便华裔患者无障碍交流。", "category": "culture"}, {"title": "经验丰富的专业团队", "detail": "拥有一支技术精湛、经验丰富且充满爱心的牙科专业团队，致力于提供高质量护理。", "category": "care"}, {"title": "全方位牙科服务", "detail": "提供从洁牙预防、美容修复、根管治疗到口腔外科手术的完整牙科治疗选项。", "category": "care"}, {"title": "社区慈善与免费义诊", "detail": "长期为低收入人群、老人、学生提供周末免费义诊和治疗，并每年赴海外贫困山区提供牙科服务。", "category": "reviews"}, {"title": "便捷的预约与联系", "detail": "可通过网站预约或直接致电 (312)791-1013 安排就诊。", "category": "convenience"}], "price_tier