INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('2d0a6331-e218-47b4-ac9e-604a220f0a21', NULL, 'Humboldt Park Health', 'Humboldt Park Health is a community hospital dedicated to providing compassionate, high-quality care to all individuals, regardless of background. With 24/7 emergency services and a commitment to inclusivity, the hospital ensures a safe environment for everyone. Patients can easily find a doctor, access the patient portal, and schedule appointments online. The hospital also supports the community through its Wellness Center and Foundation initiatives.', '1044 N. Francisco Ave', 'Chicago', 'IL', '60622', '(773) 292-8200', ARRAY['English', 'Vietnamese']::text[], 'Hospital', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/humboldt-park-health-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/humboldt-park-health-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/humboldt-park-health-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/humboldt-park-health-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/humboldt-park-health-google-5.webp"], "rating": 2.6, "reviews": [{"date": "2026-05-06T07:56:09.511799444Z", "text": "There are an amazing number of lovely people working here but that doesn''t change the fact that I found the services lacking. In the ER there was no bathroom, no nurse call button, no staff at all at my end of the ER for most of the time I was there.  Once I got to a room, there was a call button but it was rarely answered.  I think these were evidence that the facility has inadequate funding.  Still, as I said, the staff was great and when I got back to my own doctor, I was told that they gave me all the right tests and prescribed the right after care.", "author": "Jeanne Forsberg", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/116879217315510892256/reviews"}, {"date": "2026-03-19T03:01:29.088289718Z", "text": "When I first arrived I had received amazing care from the guy doing triage at the desk. The woman who did my registration was also extremely pleasant.\nHowever , once you reach the back they are so inexperienced , unprofessional , and rude.\nUpon arrival to the back it was so dirty.\nA nurse repeated tried to put an IV in my hand. She tried for blood 2/3 times. When she couldn’t get it she pushed down on the needle to force it to go a certain way creating a lot of trauma to the vein. I was very polite when I asked her to have someone else do it. It was in my hand.  She ripped the if out and blood flew everywhere. It was on the sheet and everything. So once she left I moved to a chair. She noticed and immediately changed the sheet.\nThe charge nurse was the only one who deserved the TRUE 0 rating. She said her name was Nase or Nass. Hispanic short girl with a ponytail. Was EXTREMELY rough with my hand then starting shouting at me. I let her know I no longer wanted to stay and was looking for my nurse for an ice pack. At this point both hands or bruised up. She called security. I was not irate. Then after calling security she reassigned my nurse to a black woman named Celeste. Celeste was just receiving orders from her charge nurse. I decided to leave. I never signed a Refusal of Sevice. I just left. I’m pretty sure she is going to forge my signature. And I will be contacting Human Resources.", "author": "Kira M", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/103675843898006988637/reviews"}, {"date": "2026-06-06T23:49:24.133755665Z", "text": "Provide MORE books to the psych ward  inpatient  patients. PROVIDE MORE BOOKS and stop letting your staff, student doctor or psychiatrists, make fun of the patients. Stop letting your top  staff also manipulate the patients. You will come out the same, if not worse, as you went in. At least provide books to the  patients so they can pass the time.", "author": "Haley Andrusz", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/103176529456069710145/reviews"}, {"date": "2026-04-12T02:53:33.907714937Z", "text": "I was in extreme distress at 3am and literally googled “closest emergency room” and found this place. They were kind. They got me a bed quickly. The nurse who initially tried to put an IV in my arm did give me a GIANT bruise trying to find a vein which I still have two weeks later but I don’t even care because I lived. I was in their emergency room for 10 or so hours and I never heard anyone being anything but kind with a patient. This is a good hospital. But also as slow as a normal emergency room is.", "author": "Johanna Strouse", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117320372586572180803/reviews"}, {"date": "2026-05-14T06:41:32.257477579Z", "text": "I came to HPH due to experiencing extreme back pain. While in triage I met Dr. Andrew R. Williams who dismissed my concerns and quickly diagnosed me with muscle spasms. I requested to have a CT scan done for a peace of mind. Dr. Williams became physically upset that I didn’t agree with him and said having that scan would be doing too much. He walked off and I was left in the triage area. Thankfully the kind nurse advised me to return back to the waiting area. When my test results came back I spoke with Dr. Williams who was very passive aggressive. I asked what should I do about the pain and he started shouting at me saying “ So now you don’t believe the radiologist”. I advised him that he’s been passive aggressive since I’ve been there. Dr.Williams proceeded to shout saying “ Don’t tell me I’m passive aggressive! I don’t have time for this you’re discharged” then he proceeded to walk off. This encounter was very embarrassing considering I was sitting on a stretcher in the hallway. Dr. Williams needs to held accountable for his behavior and not work in healthcare at all! I would like to speak with someone who can put me in connection with the executive office. I’ve never experienced a doctor like him and hope that no one else have this same encounter.", "author": "Kay''e A", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/107193006738828645518/reviews"}], "website": "https://www.hph.care/", "location": {"latitude": 41.900988, "longitude": -87.7000283}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "24/7 Care", "detail": "Open 24 hours a day, every day.", "category": "convenience"}, {"title": "Inclusive Care", "detail": "Committed to providing a safe place for everyone regardless of background.", "category": "care"}, {"title": "Online Scheduling", "detail": "Schedule appointments online for your convenience.", "category": "convenience"}], "price_tier": "$$", "source_url": "https://www.hph.care/", "appointment": {"booking_note": null, "appointment_url": "https://hph.care/schedule-an-appointment/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking hospital in Chicago, IL", "search_text": "hospital | english | vietnamese | tiếng việt | người việt | bác sĩ việt", "google_types": ["general_hospital", "hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 458, "language_note": "The hospital serves a diverse immigrant community and provides a multi-language immigrant rights hotline in English, Spanish, and Polish, reflecting its commitment to inclusivity and language access.", "open_saturday": true, "quality_score": 82, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://hph.care/wp-content/uploads/2026/03/Onecause-Gala-Graphic-3-1024x640.webp", "https://hph.care/wp-content/uploads/2025/08/HPH.Wellness.Center.June_.2022-1024x582.webp", "https://hph.care/wp-content/uploads/2025/08/award-pic-nurses.webp"], "review_profile": {"rating": 2.6, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 4, "sentiment": "Mixed", "summary_quote": "Several reviewers highlight kind staff, but others report unprofessional and rude behavior from healthcare providers."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Negative", "summary_quote": "Patients mention dirty conditions and lack of basic amenities like bathroom access in the ER."}, {"theme": "Clinical Expertise", "mentions": 2, "sentiment": "Negative", "summary_quote": "Multiple reviews cite poor medical procedures, including traumatic IV insertions and dismissive diagnoses."}, {"theme": "Communication", "mentions": 2, "sentiment": "Negative", "summary_quote": "Patients report shouting, passive-aggressive behavior, and lack of responsiveness from staff."}, {"theme": "Treatment Outcomes", "mentions": 2, "sentiment": "Mixed", "summary_quote": "Some patients received correct tests and care, while others felt their conditions were mishandled or ignored."}], "summary": "Patients appreciate the kindness of some staff members but frequently report issues with facility conditions, unprofessional behavior, and inadequate care in certain departments.", "review_count": 458, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-05-06T07:56:09.511799444Z", "text": "There are an amazing number of lovely people working here but that doesn''t change the fact that I found the services lacking. In the ER there was no bathroom, no nurse call button, no staff at all at my end of the ER for most of the time I was there.  Once I got to a room, there was a call button but it was rarely answered.  I think these were evidence that the facility has inadequate funding.  Still, as I said, the staff was great and when I got back to my own doctor, I was told that they gave me all the right tests and prescribed the right after care.", "author": "Jeanne Forsberg", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/116879217315510892256/reviews"}, {"date": "2026-03-19T03:01:29.088289718Z", "text": "When I first arrived I had received amazing care from the guy doing triage at the desk. The woman who did my registration was also extremely pleasant.\nHowever , once you reach the back they are so inexperienced , unprofessional , and rude.\nUpon arrival to the back it was so dirty.\nA nurse repeated tried to put an IV in my hand. She tried for blood 2/3 times. When she couldn’t get it she pushed down on the needle to force it to go a certain way creating a lot of trauma to the vein. I was very polite when I asked her to have someone else do it. It was in my hand.  She ripped the if out and blood flew everywhere. It was on the sheet and everything. So once she left I moved to a chair. She noticed and immediately changed the sheet.\nThe charge nurse was the only one who deserved the TRUE 0 rating. She said her name was Nase or Nass. Hispanic short girl with a ponytail. Was EXTREMELY rough with my hand then starting shouting at me. I let her know I no longer wanted to stay and was looking for my nurse for an ice pack. At this point both hands or bruised up. She called security. I was not irate. Then after calling security she reassigned my nurse to a black woman named Celeste. Celeste was just receiving orders from her charge nurse. I decided to leave. I never signed a Refusal of Sevice. I just left. I’m pretty sure she is going to forge my signature. And I will be contacting Human Resources.", "author": "Kira M", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/103675843898006988637/reviews"}, {"date": "2026-06-06T23:49:24.133755665Z", "text": "Provide MORE books to the psych ward  inpatient  patients. PROVIDE MORE BOOKS and stop letting your staff, student doctor or psychiatrists, make fun of the patients. Stop letting your top  staff also manipulate the patients. You will come out the same, if not worse, as you went in. At least provide books to the  patients so they can pass the time.", "author": "Haley Andrusz", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/103176529456069710145/reviews"}, {"date": "2026-04-12T02:53:33.907714937Z", "text": "I was in extreme distress at 3am and literally googled “closest emergency room” and found this place. They were kind. They got me a bed quickly. The nurse who initially tried to put an IV in my arm did give me a GIANT bruise trying to find a vein which I still have two weeks later but I don’t even care because I lived. I was in their emergency room for 10 or so hours and I never heard anyone being anything but kind with a patient. This is a good hospital. But also as slow as a normal emergency room is.", "author": "Johanna Strouse", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117320372586572180803/reviews"}, {"date": "2026-05-14T06:41:32.257477579Z", "text": "I came to HPH due to experiencing extreme back pain. While in triage I met Dr. Andrew R. Williams who dismissed my concerns and quickly diagnosed me with muscle spasms. I requested to have a CT scan done for a peace of mind. Dr. Williams became physically upset that I didn’t agree with him and said having that scan would be doing too much. He walked off and I was left in the triage area. Thankfully the kind nurse advised me to return back to the waiting area. When my test results came back I spoke with Dr. Williams who was very passive aggressive. I asked what should I do about the pain and he started shouting at me saying “ So now you don’t believe the radiologist”. I advised him that he’s been passive aggressive since I’ve been there. Dr.Williams proceeded to shout saying “ Don’t tell me I’m passive aggressive! I don’t have time for this you’re discharged” then he proceeded to walk off. This encounter was very embarrassing considering I was sitting on a stretcher in the hallway. Dr. Williams needs to held accountable for his behavior and not work in healthcare at all! I would like to speak with someone who can put me in connection with the executive office. I’ve never experienced a doctor like him and hope that no one else have this same encounter.", "author": "Kay''e A", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/107193006738828645518/reviews"}]}, "review_summary": "Patients appreciate the kindness of some staff members but frequently report issues with facility conditions, unprofessional behavior, and inadequate care in certain departments.", "about_highlight": "Humboldt Park Health is a community hospital dedicated to providing compassionate, high-quality care to all individuals, regardless of background. With 24/7 emergency services and a commitment to inclusivity, the hospital ensures a safe environment for everyone. Patients can easily find a doctor, access the patient portal, and schedule appointments online. The hospital also supports the community through its Wellness Center and Foundation initiatives.", "appointment_url": "https://hph.care/schedule-an-appointment/", "google_maps_url": "https://maps.google.com/?cid=439118697422139815&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJY3WRzFXND4gRpzEU9iAQGAY", "quality_missing": ["services", "insurance", "team_members"], "search_keywords": ["hospital", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt"], "cultural_context": "The hospital serves a diverse immigrant community and provides a multi-language immigrant rights hotline in English, Spanish, and Polish, reflecting its commitment to inclusivity and language access.", "short_description": "Humboldt Park Health is a community hospital providing compassionate, quality care 24/7.", "google_website_url": "https://www.hph.care/", "google_primary_type": "General Hospital", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "1044 N Francisco Ave, Chicago, IL 60622, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/108712734882546038968", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX17oOsB40QH35rhLP2A8iUb-2eRGsx-riyI8WF81mUcEfOuAw=s100-p-k-no-mo", "displayName": "Humboldt Park Health"}], [{"uri": "https://maps.google.com/maps/contrib/108712734882546038968", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX17oOsB40QH35rhLP2A8iUb-2eRGsx-riyI8WF81mUcEfOuAw=s100-p-k-no-mo", "displayName": "Humboldt Park Health"}], [{"uri": "https://maps.google.com/maps/contrib/108712734882546038968", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX17oOsB40QH35rhLP2A8iUb-2eRGsx-riyI8WF81mUcEfOuAw=s100-p-k-no-mo", "displayName": "Humboldt Park Health"}], [{"uri": "https://maps.google.com/maps/contrib/108712734882546038968", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX17oOsB40QH35rhLP2A8iUb-2eRGsx-riyI8WF81mUcEfOuAw=s100-p-k-no-mo", "displayName": "Humboldt Park Health"}], [{"uri": "https://maps.google.com/maps/contrib/108712734882546038968", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX17oOsB40QH35rhLP2A8iUb-2eRGsx-riyI8WF81mUcEfOuAw=s100-p-k-no-mo", "displayName": "Humboldt Park Health"}]]}'::jsonb, '2026-06-25T21:18:42.08844+00:00', 'humboldt-park-health', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('dd234389-d3b1-4bd0-b503-697356f2fc00', NULL, 'UChicago Medicine', 'UChicago Medicine is a nationally ranked academic medical center affiliated with the University of Chicago. It offers comprehensive care across primary care, specialty care, urgent care, and 24/7 on-demand virtual urgent care. With a focus on patient-centered medicine, the institution provides access to leading physicians, advanced treatments, and a full range of services at multiple locations in the Chicago area. Patients can easily schedule appointments online through MyChart or by calling the appointment line.', '5841 S. Maryland Avenue Chicago, IL 60637', 'Chicago', 'IL', '60637', '1-888-824-0200', ARRAY['English', 'Vietnamese']::text[], 'Hospital', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/uchicago-medicine-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/uchicago-medicine-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/uchicago-medicine-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/uchicago-medicine-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/uchicago-medicine-google-5.webp"], "rating": 2.9, "reviews": [{"date": "2026-04-21T20:07:17.621947778Z", "text": "Two of my family members beat cancer through the relentless hours, days, months with the care of The University of Chicago.\n\nI know the er gets brought up here (in reviews) mostly — from my experience every ER is chaos and I am just grateful they exist and try their best 😂🙏🤞\n\nIf you want top of the line research, doctors with bedside manner, and understandable patient education — there’s no better experience than U of C Medicine in this state.\n\nForever grateful for all the hard work, communication, and true care for patient choice that we have seen at this hospital. Thank you!! 🙏", "author": "Katy Banks, MPA Realtor", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116114955029289135558/reviews"}, {"date": "2026-06-05T21:56:39.318308304Z", "text": "The surgeon I had, her whole operating team, and the administrative staff there were EXCELLENT. I couldn’t have asked for better care. The caveat is, the hospital, apparently, “redeems the right to charge the patient for post-op services” and doesn’t inform their administrative staff that. Was point blank told that the post-op visit is included in the surgery charge to my insurance, therefore I wouldn’t have to pay a dime, because I was losing that insurance at the end of the month and wouldn’t have been able to afford the visit otherwise. Turns out, the hospital was going to charge me $400 because I didn’t go to the doctors private office for the post op visit, which was not an option given to me.", "author": "Sierra Michel", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/103517946112162939390/reviews"}, {"date": "2025-12-15T06:29:51.822084394Z", "text": "I was hit by a car and rushed to this hospital. The trama center top notched, I felt they did a great job and made me feel my life matter. Once removed to the emergency room, I was put in a hallway for 20 minutes naked and everyone just walking pass me I was so uncomfortable. Then finally I was wheeled in a room by a tech, then left waiting on a nurse to come in pain flat on my back with a neckbrace, for over 30 minutes,  the machine was beeping for so long I found the strength to sit up and then the nurse appeared. The machine beeping for 30 minutes should have been a sign of distress and to come check on a patient.  When she came in the room, Melissa the nurse had a very nasty attitude, I was there for 13hrs, the t.v didn''t work, the remote to call the nurse didn''t work so I had to wait to she come in to check on me. She will pop in every 3hrs..smh im hungry and thirsty. These people need interpersonal skills training how did you become a nurse, I asked her a question and she said \"what\"..I''m like that''s not how you answer a patient..she said oh I didn''t hear your question. Smh After being there to 9pm after arriving at 8am, they decided on a MRI, I was tested out...did many xrays, catskan had a cast put on my hand..so I declined. They was upset cause yes I have good insurance get all the test they paying....so they didn''t give me any discharge instructions at all, no prescriptions or anything mind you..I was hit by a car and have a cast on my hand. I have never experienced a hospital so unprofessional and ghetto in my life. But as I said..The Trama doctor and nurses was great.", "author": "MzFit4aking Tashia", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/113124815976710898923/reviews"}, {"date": "2026-03-15T19:04:18.977588708Z", "text": "I recently had a hospital stay at the University of Chicago Hospital, and I felt compelled to share how exceptional my experience was. From the moment I arrived to the day I was discharged, every member of the team treated me with genuine compassion, professionalism, and respect.\n\nThe nursing staff was absolutely outstanding. They were attentive, patient, and incredibly supportive during a time that could have easily been overwhelming. Every question I had was answered thoroughly, and I always felt like my comfort and well-being truly mattered. Their kindness and dedication did not go unnoticed.\n\nThe doctors and medical team were equally impressive—knowledgeable, communicative, and committed to making sure I understood my care and treatment plan. It was clear that everyone works together as a team with the patient’s best interests at the center.\n\nClean facilities, organized care, and a staff that goes above and beyond made this the best hospital experience I’ve ever had. I am deeply grateful to the entire team at the University of Chicago Hospital for their professionalism and compassionate care. Thank you for helping me feel safe, supported, and on the path to recovery.", "author": "Andrea Smith", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116918855021393478141/reviews"}, {"date": "2025-10-08T17:51:32.490240650Z", "text": "Avoid Reem Jan. Her fellow was great but Reem Jan was content to ignore my husband''s pain for months, and never diagnosed him with anything, despite a long history of disabling symptoms. We switched to Chicago Arthritis who was much better at getting a proper diagnosis and medication. Oh and today I found out that UChicago hired an attorney to bust the resident''s union instead of raising wages. What a shitty hospital.", "author": "Hungry Hungry", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/113018703829626434512/reviews"}], "website": "https://www.uchicagomedicine.org/", "location": {"latitude": 41.7892741, "longitude": -87.60360089999999}, "services": ["Primary Care", "Specialty Care", "Urgent Care", "24/7 On-Demand Virtual Urgent Care"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Comprehensive Care", "detail": "Offers primary care, specialty care, urgent care, and virtual urgent care services.", "category": "care"}, {"title": "Online Scheduling", "detail": "Patients can schedule appointments through MyChart or call 1-888-824-0200.", "category": "convenience"}, {"title": "24/7 Virtual Urgent Care", "detail": "On-demand virtual urgent care available around the clock via MyChart.", "category": "access"}, {"title": "Nationally Ranked", "detail": "Recognized by U.S. News & World Report as a top hospital.", "category": "reviews"}], "price_tier": "$$", "source_url": "https://www.uchicagomedicine.org/", "appointment": {"booking_note": "Schedule an appointment online or call 1-888-824-0200.", "appointment_url": "https://www.uchicagomedicine.org/find-a-physician", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking hospital in Chicago, IL", "search_text": "hospital | english | vietnamese | tiếng việt | người việt | bác sĩ việt | primary care | specialty care | urgent care | 24/7 on-demand virtual urgent care | telehealth", "google_types": ["medical_center", "hospital", "pharmacy", "health", "store", "service", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 856, "open_saturday": true, "quality_score": 92, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://www.uchicagomedicine.org/_next/image?url=https%3A%2F%2Fedge.sitecorecloud.io%2Funichicagomc-81nbqnb3%2Fmedia%2Fimages%2Fucmc%2Fmodule-images%2Fhero-carousel%2Fhomepage-hero%2Fhome-page-banner-map-020425.jpg&w=3840&q=75", "https://www.uchicagomedicine.org/_next/image?url=https%3A%2F%2Fedge.sitecorecloud.io%2Funichicagomc-81nbqnb3%2Fmedia%2Fimages%2Fucmc%2Fmodule-images%2Fmultispotlight%2Fadult-hp%2Fprimary-care-multispot-556x290.jpg&w=3840&q=75"], "review_profile": {"rating": 2.9, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highli