INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('99723752-2ba1-48b6-8346-6195f7294a48', NULL, 'Centro De Medicina China', 'Centro De Medicina China is a provider of Chinese medicine, acupuncture, and Chinese herbal remedies. The clinic is located in Illinois and offers traditional healing services.', '6330 Pacific Blvd Ste 110, Huntington Park, CA 90255', 'Huntington Park', 'CA', '90255', '(323) 582-5921', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/centro-de-medicina-china-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/centro-de-medicina-china-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/centro-de-medicina-china-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/centro-de-medicina-china-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/centro-de-medicina-china-google-5.webp"], "rating": 5, "reviews": [{"date": "2024-11-11T16:01:46.832092Z", "text": "I have been fortunate enough to be introduced to Dr. Ricardo Con about 15 years ago.  Since then, Dr. Con has treated me for many issues including tinnitus, insomnia, migraine headache, colds, sciatica and many other chronic conditions where conventional medications was ineffective for me.  He has almost 30 years of experience in both prescribing herbs and acupuncture so he is very knowledgeable and able to diagnose and prescribe quickly and accurately.  Not only that, He loves what he does and he truly cares for his patients.  If you are thinking about trying oriental medicine, I would highly recommend Dr. Con.", "author": "Sunny H", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108375244051186578494/reviews"}, {"date": "2024-02-17T20:28:07.279716Z", "text": "The care I have and currently receive from Dr Chan is EXCEPTIONAL! He listens to my concerns and provides personalized treatment that has yielded into positive results. Dr. Chan is always available to answer any questions after consultation, which is very rare with any doctor or physician. I am blessed to be under his care and I highly recommend Dr.Chan. 🙏", "author": "Sue A", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109535598756675902198/reviews"}, {"date": "2021-05-22T22:04:17.862150Z", "text": "Ricardo is an excellent and compassionate doctor. He has a lot of experience in both acupuncture and herbs. He is also honest in that he knows what his specialties are and will refer you to someone else if he cannot help you. He is not like other doctors who just wants to make money practicing medicine. He genuinely cares.", "author": "Tina Ting Chen", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115452148187350505754/reviews"}, {"date": "2019-10-03T01:05:59.374557Z", "text": "I have seen and experienced practically miracles. It''s pricey but worth the effort and time. I like the fact that this is taken serious and not ridiculous like many who practice Eastern medicine and make a show or introduce extra activities. Ricardo will tell you about it and see if he can help you.\nRemember this is therapy, not the cure. Even when going with your primary care physician, you are the cure.", "author": "Juan Fierro jr", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103260709557022324943/reviews"}, {"date": "2019-03-14T18:29:35.094403Z", "text": "Very experienced doctor and helpful he is fully bilingual eng/spanish , i recommend him, pay him a  visit your won''t regret it.", "author": "Ricky Reik", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105258018592123075620/reviews"}], "website": "https://m.facebook.com/medicinachinayacupunturahierbaschinas/", "location": {"latitude": 33.982748, "longitude": -118.22493700000001}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "price_tier": "$$", "source_url": "https://m.facebook.com/medicinachinayacupunturahierbaschinas/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Los Angeles, CA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人", "google_types": ["medical_clinic", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 8, "open_saturday": true, "quality_score": 80, "working_hours": {"friday": "10:00 AM – 5:00 PM", "monday": "10:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "10:00 AM – 5:00 PM", "saturday": "10:00 AM – 2:00 PM", "thursday": "10:00 AM – 5:00 PM", "wednesday": "Closed"}, "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 5, "sentiment": "Positive", "summary_quote": "Multiple reviewers commend Dr. Con''s deep knowledge and accurate diagnoses in both acupuncture and herbal medicine."}, {"theme": "Compassionate Care", "mentions": 4, "sentimen