false, "patient_fit": null}, {"name": "Asthma", "category": "Chronic Disease", "description": "Asthma management and care.", "is_featured": false, "patient_fit": "Patients with asthma."}, {"name": "Arthritis", "category": "Chronic Disease", "description": "Arthritis management.", "is_featured": false, "patient_fit": "Patients with arthritis."}, {"name": "Allergies", "category": "Primary Care", "description": "Allergy diagnosis and treatment.", "is_featured": false, "patient_fit": null}], "short_description": "Pham Medical Clinic is a family-oriented primary care practice in Houston, TX, dedicated to providing quality medical care for patients of all ages.", "google_website_url": "http://www.phammedicalclinic.com/", "insurance_accepted": ["Aetna", "Assurant", "Blue Cross Blue Shield", "Boon Chapman", "Cigna", "Entrust", "First Health", "Great West Healthcare (GWH)", "Health Choice of Oklahoma", "Humana", "Meritain", "Multiplan", "Patient/Physician Cooperatives (PPC)", "PHCS", "TRICARE", "UMR", "UnitedHealthcare", "Ambetter", "Community Health Choice", "Molina Healthcare", "Amerigroup (Star, StarPlus)", "Community Health Choice (Star)", "Medicare", "Medicaid"], "google_primary_type": "Medical Clinic", "provider_credentials": {"education": [], "providers": ["Mythanh Hang", "Dr. Bao Thang Pham", "Linh Vu"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "12545 Briar Forest Dr Ste a, Houston, TX 77077, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/115496773199044332607", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXJAT0gDSoVwHQVH0XjTEm8exBvtwcU61K4fTwhf2qF-AnrHJZUxg=s100-p-k-no-mo", "displayName": "Thanh Hai Dinh"}], [{"uri": "https://maps.google.com/maps/contrib/115496773199044332607", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXJAT0gDSoVwHQVH0XjTEm8exBvtw