INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('b088b242-51cd-4400-a819-4aca29137c77', NULL, 'Texas Children''s Hospital', 'Texas Children''s Hospital is a world-renowned pediatric healthcare system with over 80 locations across Texas and the greater Houston area. We are dedicated to pushing the boundaries of what’s possible to change the lives of patients the world over, with a focus on life-saving care, innovative research, and healthcare equity. Our team of experts provides comprehensive care through advanced clinics, cutting-edge research institutions, and a commitment to serving every child''s unique needs.', '6621 Fannin Street, Houston, TX 77030', 'Houston', 'TX', '77030', '832-824-1000', ARRAY['English', 'Korean']::text[], 'Pediatrics', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/texas-childrens-hospital-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/texas-childrens-hospital-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/texas-childrens-hospital-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/texas-childrens-hospital-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/texas-childrens-hospital-google-5.webp"], "rating": 3.5, "reviews": [{"date": "2026-02-18T10:21:03.112843392Z", "text": "The nurses and doctors who took care of Karson were absolutely amazing! They were so patient and friendly, walking us through every step and process. They even went above and beyond, rewarding Karson every time they did something for him. The ladies who did the X-rays and checked his vitals were wonderful too. Despite the long wait, the overall visit was great, and we were comfortable with snacks and warm blankets while we waited.", "author": "Leanna Michelle Miranda Nunez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113106903028267859866/reviews"}, {"date": "2026-03-02T16:52:00.473398668Z", "text": "This place is Amazing! They take great pride in caring for my child, they listen and hear what he has to say as well us parents. As parents we are valued in being a part of the care plan. Also love how they communicate with other teams departments my child receives treatment from.", "author": "Karen Stubbs", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107919150792332681812/reviews"}, {"date": "2026-02-21T15:45:53.042648902Z", "text": "This place would’ve gotten zero stars if it wasn’t for the few wonderful nurses and doctors that we were seen by\n\nTCH EMS (we were transferred from TCH clinic) were trashy and rude\nAccess to hot water to help warm our baby’s bottle was non existent anywhere.\nWhen we tried getting food for our baby, that itself was a struggle, with having to call numerous times, the calls dropping, and being told you can only get This and This and This but nothing else.\nY’all are charging my BCBS insurance that I pay $400 a month for and not even use as much. I do not see how this is an issue\n\nWe are parents (nurses) that are heavily involved and try to do as much possible to relieve the load of the staff. We ask for everything upfront so that staff doesn’t need to go back-and-forth with us. So if we can get simple things like hot water, milk, juices, snacks,etc we do it (like how in other amazing hospitals do)\nAlso unlike other hospitals, you have to fight for dad and mom to get meals\n\nStaffing seems severely understaffed\nAnd you can tell by the attitudes and exhaustion\nI’ve been to other hospitals and their staff is much happier", "author": "Manuel Hernandez", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/110952968656390138434/reviews"}, {"date": "2026-02-23T12:54:44.308545357Z", "text": "I really don''t know how to rate them.  I took my grandson in to the ER on Friday where we waited for hours and were never seen they told us to leave and come back over the weekend if necessary. First of all how do you allow a kid whose complaining of a head injury sit in the waiting area instead of getting a scan immediately? Tell me why we ended up back in the ER Sunday morning. Atleast this time they didn''t make us wait and they did thorough testing.  Thank God my grandson is doing better.  I pray for a better day today.", "author": "Nichole Green", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/101872474308386578301/reviews"}, {"date": "2026-01-21T00:40:40.150143336Z", "text": "I hate doing this but this hospital wasn’t what the doctors in Lubbock said it was going to be. Ever since my daughter was transferred here she has been through nothing but misery, she is very respectful but slowly my daughter, her mother as myself lost that respect even after the stroke that I believe they caused and they still haven’t figured out how to get rid of the infection in her lungs. Specific nurses were awesome in the legacy tower ( Laura, Alexus, Trevor, Stacey, Jordan, Awkafina, a Hispanic that washed her hair I call her Kay and one more)…but hearing how she is doing in the west tower really upsets me. Having to stay up and watch to make sure nurses do their job is unbelievable, I know these are hard times but don’t let these kids down if you had kids you would understand. I hope things get better God bless and oh yea whoever taped my daughters hair to her face you need to be trained again ✌🏽", "author": "Joshua Avila", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/102562713225879325325/reviews"}], "website": "https://www.texaschildrens.org/", "location": {"latitude": 29.707793400000003, "longitude": -95.401314}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "World-Class Pediatric Care", "detail": "Texas Children''s Hospital is a top-ranked pediatric hospital with advanced clinics and research institutions.", "category": "care"}, {"title": "Over 80 Convenient Locations", "detail": "With locations across Texas and the greater Houston area, care is close to home.", "category": "convenience"}, {"title": "Life-Saving Research", "detail": "Through innovative technology and rigorous studies, our dedicated team makes a difference with every discovery.", "category": "technology"}, {"title": "Global Health Network", "detail": "Leading efforts to advance healthcare equity through collaboration in care, education, and research globally.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.texaschildrens.org/", "appointment": {"booking_note": null, "appointment_url": "https://www.texaschildrens.org/patients-families/appointments", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Korean speaking medical clinic in Houston, TX", "search_text": "pediatrics | pediatrician | child doctor | vaccines | newborn | nhi khoa | bác sĩ nhi | khám trẻ em | 소아과 | 소아청소년과 | 儿科 | english | korean | 한국어 | 한인 | 한국말", "google_types": ["hospital", "health", "service", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 1452, "open_saturday": true, "quality_score": 82, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://www.texaschildrens.org/sites/tc/files/styles/coh_small_square/public/2026-04/what-a-year.png?h=c65452c4&itok=cDYaUrEX", "https://www.texaschildrens.org/sites/tc/files/styles/coh_x_large_landscape_webp/public/2022-11/Millions%20Graphic-%20Desktop.png.webp?itok=W8ji1d9q", "https://www.texaschildrens.org/sites/tc/files/styles/coh_x_large_landscape_webp/public/2023-05/GHN-1920px.jpg.webp?itok=JvfU5fBv%201920w"], "review_profile": {"rating": 3.5, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight the amazing, patient, and friendly nurses and doctors who provide excellent care."}, {"theme": "Communication", "mentions": 2, "sentiment": "Positive", "summary_quote": "Parents appreciate being valued in the care plan and effective communication between departments."}, {"theme": "Wait Times", "mentions": 2, "sentiment": "Negative", "summary_quote": "Several reviews mention frustratingly long wait times in the ER and other departments."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Negative", "summary_quote": "Some parents report difficulties accessing basic amenities like hot water and food for their children."}, {"theme": "Inconsistent Care Quality", "mentions": 2, "sentiment": "Negative", "summary_quote": "A few reviews describe concerning inconsistencies in care quality between different departments and staff members."}], "summary": "Texas Children''s Hospital receives mixed reviews, with many praising the caring and professional staff, while others express frustration with long wait times and inconsistent care quality.", "review_count": 1452, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-02-18T10:21:03.112843392Z", "text": "The nurses and doctors who took care of Karson were absolutely amazing! They were so patient and friendly, walking us through every step and process. They even went above and beyond, rewarding Karson every time they did something for him. The ladies who did the X-rays and checked his vitals were wonderful too. Despite the long wait, the overall visit was great, and we were comfortable with snacks and warm blankets while we waited.", "author": "Leanna Michelle Miranda Nunez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113106903028267859866/reviews"}, {"date": "2026-03-02T16:52:00.473398668Z", "text": "This place is Amazing! They take great pride in caring for my child, they listen and hear what he has to say as well us parents. As parents we are valued in being a part of the care plan. Also love how they communicate with other teams departments my child receives treatment from.", "author": "Karen Stubbs", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107919150792332681812/reviews"}, {"date": "2026-02-21T15:45:53.042648902Z", "text": "This place would’ve gotten zero stars if it wasn’t for the few wonderful nurses and doctors that we were seen by\n\nTCH EMS (we were transferred from TCH clinic) were trashy and rude\nAccess to hot water to help warm our baby’s bottle was non existent anywhere.\nWhen we tried getting food for our baby, that itself was a struggle, with having to call numerous times, the calls dropping, and being told you can only get This and This and This but nothing else.\nY’all are charging my BCBS insurance that I pay $400 a month for and not even use as much. I do not see how this is an issue\n\nWe are parents (nurses) that are heavily involved and try to do as much possible to relieve the load of the staff. We ask for everything upfront so that staff doesn’t need to go back-and-forth with us. So if we can get simple things like hot water, milk, juices, snacks,etc we do it (like how in other amazing hospitals do)\nAlso unlike other hospitals, you have to fight for dad and mom to get meals\n\nStaffing seems severely understaffed\nAnd you can tell by the attitudes and exhaustion\nI’ve been to other hospitals and their staff is much happier", "author": "Manuel Hernandez", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/110952968656390138434/reviews"}, {"date": "2026-02-23T12:54:44.308545357Z", "text": "I really don''t know how to rate them.  I took my grandson in to the ER on Friday where we waited for hours and were never seen they told us to leave and come back over the weekend if necessary. First of all how do you allow a kid whose complaining of a head injury sit in the waiting area instead of getting a scan immediately? Tell me why we ended up back in the ER Sunday morning. Atleast this time they didn''t make us wait and they did thorough testing.  Thank God my grandson is doing better.  I pray for a better day today.", "author": "Nichole Green", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/101872474308386578301/reviews"}, {"date": "2026-01-21T00:40:40.150143336Z", "text": "I hate doing this but this hospital wasn’t what the doctors in Lubbock said it was going to be. Ever since my daughter was transferred here she has been through nothing but misery, she is very respectful but slowly my daughter, her mother as myself lost that respect even after the stroke that I believe they caused and they still haven’t figured out how to get rid of the infection in her lungs. Specific nurses were awesome in the legacy tower ( Laura, Alexus, Trevor, Stacey, Jordan, Awkafina, a Hispanic that washed her hair I call her Kay and one more)…but hearing how she is doing in the west tower really upsets me. Having to stay up and watch to make sure nurses do their job is unbelievable, I know these are hard times but don’t let these kids down if you had kids you would understand. I hope things get better God bless and oh yea whoever taped my daughters hair to her face you need to be trained again ✌🏽", "author": "Joshua Avila", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/102562713225879325325/reviews"}]}, "review_summary": "Texas Children''s Hospital receives mixed reviews, with many praising the caring and professional staff, while others express frustration with long wait times and inconsistent care quality.", "about_highlight": "Texas Children''s Hospital is a world-renowned pediatric healthcare system with over 80 locations across Texas and the greater Houston area. We are dedicated to pushing the boundaries of what’s possible to change the lives of patients the world over, with a focus on life-saving care, innovative research, and healthcare equity. Our team of experts provides comprehensive care through advanced clinics, cutting-edge research institutions, and a commitment to serving every child''s unique needs.", "appointment_url": "https://www.texaschildrens.org/patients-families/appointments", "google_maps_url": "https://maps.google.com/?cid=7063316808260179092&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJlfANKnLAQIYRlNRkzDbxBWI", "quality_missing": ["services", "insurance", "team_members"], "search_keywords": ["pediatrics", "pediatrician", "child doctor", "vaccines", "newborn", "nhi khoa", "bác sĩ nhi", "khám trẻ em", "소아과", "소아청소년과", "儿科", "english", "korean", "한국어", "한인", "한국말"], "short_description": "A world-renowned pediatric healthcare network dedicated to life-saving care and groundbreaking research, with convenient locations across Texas.", "google_website_url": "https://www.texaschildrens.org/locations/texas-childrens-hospital/west-tower", "google_primary_type": "Hospital", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "6621 Fannin St, Houston, TX 77030, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/102007231354633057554", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVpYYYnbQxWKG3Mb_SaaX5_0DhKIIWDtRl1fi8s8pZ1YfKELC5nlA=s100-p-k-no-mo", "displayName": "Waleed Al-Ali"}], [{"uri": "https://maps.google.com/maps/contrib/113724146930553726186", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjX9yM4JZGX7nw8Vcl-5psE1yXBGVadcFNzgJ-R1UeTZuQ1_kdhc=s100-p-k-no-mo", "displayName": "Texas Children''s Hospital - West Tower"}], [{"uri": "https://maps.google.com/maps/contrib/109338780377300285763", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUJ5rAMHF4P-EHoYJgineKiR_dUe1y3tCXE3ZUlyJ_s2ZCrgDM=s100-p-k-no-mo", "displayName": "Latina Sabrina"}], [{"uri": "https://maps.google.com/maps/contrib/105175452844124518760", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWph8zFQK-s9Wn8yHnjOE_fKcVW7olTC-fn2v3R1OEnQgIq_J_ddw=s100-p-k-no-mo", "displayName": "Sam Olivares"}], [{"uri": "https://maps.google.com/maps/contrib/102447623052400459966", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVCNtmWmAGRJxHUaPkLWa9-Zg3R5-O4IwM2xo6bUqtW11oO6ZU=s100-p-k-no-mo", "displayName": "Captain Jack"}]]}'::jsonb, '2026-06-26T10:33:42.849277+00:00', 'texas-childrens-hospital', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('00b6132b-3dc4-4942-a118-a2d546aa22a1', NULL, 'Top Acupuncture Clinic', 'Top Acupuncture Clinic in Houston, TX, offers personalized acupuncture treatments for whole-body wellness. Led by Dr. Sylvia Qiaosha He, the clinic provides a calming experience and develops treatment plans based on each patient''s specific circumstances. Services include acupuncture for pain, stress and anxiety reduction, fertility support, fibromyalgia treatment, IBS treatment, weight loss, and alternative medicine. The clinic also offers cupping therapy and herbal medicine in easy-to-use powder form. Patients come for a wide range of conditions including emotional disorders, digestive issues, women''s health, men''s health, skin disorders, anti-aging, and more. The team is dedicated to facilitating a comfortable and healing environment, helping patients experience their own natural healing power.', '2000 Bering Drive Suite 270', 'Houston', 'TX', '77057', '832-779-4486', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/top-acupuncture-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/top-acupuncture-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/top-acupuncture-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/top-acupuncture-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/top-acupuncture-clinic-google-5.webp"], "rating": 4.9, "reviews": [{"date": "2025-07-09T07:10:41.217475066Z", "text": "Absolutely Incredible Healing Experience – Highly Recommend Sylvia!\n\nI injured my knee over the July 4th weekend and was in excruciating pain. My left knee was extremely swollen, couldn’t extend on its own, and couldn’t bear any weight. I desperately searched for help, but no orthopedic clinics were open on the weekend. Thankfully, I found this amazing acupuncture clinic in Houston—open on Saturdays—and that’s when I met Sylvia.\n\nSylvia is truly exceptional. From the moment I stepped into her clean, spacious, and well-equipped office, I felt like I was in good hands. She took the time to thoroughly examine me. She treated me with great care, placing acupuncture needles on various key points, and spent two full hours working to reduce the inflammation and pain. By the time I left, the swelling had gone down quite a bit and the pain reduced.\n\nSylvia is not only deeply knowledgeable—holding a doctorate in Chinese Medicine and Acupuncture—but also incredibly compassionate. You can genuinely feel her joy in healing people. Her dedication and expertise go above and beyond.\n\nIf you’re in pain and need real relief, I highly recommend Sylvia and her clinic. She’s a rare find in Houston, and I’m so grateful for the care I received.", "author": "liyan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115009916768354014609/reviews"}, {"date": "2022-12-16T06:49:53.860442Z", "text": "Dr. He provides professional cares with heart for her patients.  She listens to her patients and treats them with her magic needles.  Her Herbal medicines are fine powders simply mixing with hot water in a cup and ready for use.  It''s simple and easy, much better than the traditional way cooking herbal medicines could take hours to cook.  My family of 4 people benefited from her treatments for the past 3 months from emotional sensitives, body pain, coughing, pressure release, sleeping issue, and etc.  Thanks Dr. He for offering an unique place and her passions to cure each patient.  Love her smile and her optimism personality!", "author": "Lana Lee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117570028181528691014/reviews"}, {"date": "2025-10-21T00:24:24.358726361Z", "text": "So to follow up on my first review, I left coming to top Acupuncture end of June/August of this year after having a life-threatening car accident Dr. Sylvia Qiaosha He has been an absolute blessing to say the least. I’m not sure who had a bad day with some of these questionable reviews, but I had a traumatic brain injury, a skull fracture and a respiratory infection due to a bad climate that I’ve been living in This Dr. Sylvia pinpointed almost immediately when she saw my back, but it was crooked and she knew exactly what to do. She goes out of her way to heal me and make sure that I’m not in pain. I absolutely can feel a difference in the pain from being a one to 10 which was on a 10 before meeting this doctor. It’s subsided immensely I would say I’m at four and this is just in less than two months. She’s been outstanding and I would recommend her to anyone in pain anyone with anxiety or depression. What’s I liked the most as she has a holistic approach with Healing anything wrong with you and your body physically let her know and I guarantee you she will heal it. I’m convinced. I’m beyond surprised after eight months of pain, I finally found her. I cannot believe how quickly she’s helped heal my body thank you. You’re an absolute blessing to me.", "author": "Shae j", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107662716644271649049/reviews"}, {"date": "2025-09-23T00:41:27.093889763Z", "text": "Dr. Sylvia is wonderful! She truly cares about her patients, and it shows from the first time you meet. She takes the time to really get to know your issues and concerns so that she is able to address them accordingly.\n\nMy husband and I are so glad we found her. And the fact that her office takes insurance is the cherry on top!", "author": "Joelle Vargas-Lowe", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107550626454384000775/reviews"}, {"date": "2025-01-09T00:27:13.866187Z", "text": "As a veteran, I was referred to Top Acupuncture by the VA chiropractor to address my chronic fatigue, pain, and PTSD. From the moment I walked into Top Acupuncture, Dr. Sylvia made me feel welcome and understood. She took the time to listen to my concerns and created a customized treatment plan tailored specifically to my needs. Her approach was not only professional but also deeply compassionate, which immediately put me at ease.\n\nAfter completing 12 sessions, the changes I’ve experienced have been nothing short of transformative. My chronic pain has significantly diminished, my energy levels have improved, and I’ve noticed a much more positive outlook on life. Tasks that once felt overwhelming are now manageable, and I’ve even been able to become more active, which has further improved my overall well-being.\n\nWhat truly sets Dr. Sylvia apart is her genuine empathy and dedication to her patients. She doesn’t just treat symptoms; she addresses the whole person. Her knowledge, skill, and kindness create an environment where healing feels possible, even for those like myself who have struggled for years. I cannot recommend her highly enough to anyone seeking pain relief, overall better health and a better quality of life. Dr. Sylvia is truly remarkable, and I’m deeply grateful for the care she has provided.\n\nCharles", "author": "Rusty C", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100300188046171213127/reviews"}], "website": "https://acupuncturisthoustontx.com/", "location": {"latitude": 29.745407399999998, "longitude": -95.480034}, "services": ["Acupuncture", "Acupuncture For Disorders", "Acupuncture For Pain", "Acupuncture For Smoking", "Acupuncture For Weight Loss", "Alternative Medicine", "Fertility Acupuncture", "Fibromyalgia Treatment", "Irritable Bowel Syndrome Treatment", "Stress & Anxiety Reduction", "Cupping Therapy"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Licensed Acupuncturists & Certified Herbalists", "detail": "The clinic is staffed by licensed acupuncturists and certified herbalists who provide professional care.", "category": "care"}, {"title": "Personalized Treatment Plans", "detail": "Treatment plans are developed based on each patient''s specific circumstances.", "category": "care"}, {"title": "Calming Experience", "detail": "The clinic aims to facilitate a calming experience and ensure patient comfort during visits.", "category": "convenience"}, {"title": "Cupping Therapy Available", "detail": "Trusted cupping therapy is offered as an alternative for pain relief and wellness.", "category": "care"}, {"title": "Herbal Medicine in Easy-to-Use Powder Form", "detail": "Herbal medicines are provided as fine powders that mix with hot water, simpler than traditional cooking methods.", "category": "care"}], "price_tier": "$$", "source_url": "https://acupuncturisthoustontx.com/", "appointment": {"booking_note": "Book Now!", "appointment_url": "https://acupuncturisthoustontx.com/contact/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Houston, TX", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 