INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('fb3cd06b-7147-4b29-9aa0-7c4959de177b', NULL, 'I693 Clinic', 'I693 Clinic, led by Dr. Rekha Manghnani, MD, is a USCIS-designated Civil Surgeon practice in San Jose, California, specializing exclusively in Form I-693 immigration medical exams for green card applicants. The clinic offers transparent flat-fee pricing, same-week appointments, and a multilingual staff speaking English, Spanish, Korean, Chinese, Punjabi, Hindi, Marathi, and Gujarati. Dr. Manghnani is board-certified in Pediatrics and a member of the American Academy of Pediatrics, serving families across the Bay Area with patience, clarity, and respect throughout the I-693 process.', '2039 Forest Avenue, Suite 203', 'San Jose', 'CA', '95128', '408-297-9949', ARRAY['Hindi', 'Spanish', 'Marathi', 'English', 'Korean', 'Chinese', 'Gujarati', 'Punjabi', 'Vietnamese']::text[], 'Primary Care', FALSE, '{"email": "doctor@I693uscis.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/i693-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/i693-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/i693-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/i693-clinic-google-4.webp"], "rating": 5, "pricing": [{"name": "I-693 Examination Fee (per person)", "notes": "Covers the I-693 examination, paperwork, and the sealed envelope. Lab tests and vaccinations are billed separately based on what you need.", "price": "$350", "category": "Exam", "price_range": null}, {"name": "Family Discount", "notes": "Families of more than 2 receive $50 off each additional family member.", "price": null, "category": "Exam", "price_range": null}, {"name": "Lab Tests & Vaccinations", "notes": "Billed separately based on what you need; quoted before they are performed.", "price": null, "category": "Exam", "price_range": null}], "reviews": [{"date": "2026-06-08T19:33:18.550421920Z", "text": "Dr. Manghnani was professional, knowledgeable, and very kind. The office was clean, and the staff were friendly and efficient. I especially appreciated that there was very little wait time. Overall, a great experience.", "author": "Monica K", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107431637996701640041/reviews"}, {"date": "2026-06-20T17:46:10.614694715Z", "text": "Dr. Rekha was very thorough and helpful. Would definitely recommend her services.", "author": "Meghana Prabhune", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114707152587808793414/reviews"}, {"date": "2026-06-18T00:24:39.192593026Z", "text": "fast and nice place!", "author": "Bingxin Zhu", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105999554454983796153/reviews"}, {"date": "2026-06-17T17:58:36.525865435Z", "text": "The doctor is highly professional and experienced, and all of the staff members are kind, friendly, and attentive.", "author": "Michelle L", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110553697588965735264/reviews"}, {"date": "2026-06-16T17:05:39.137883716Z", "text": "We had a great experience at Dr Manghnani’s clinic. She is always thorough, patient, answers questions and promptly responds and provides her services. Her staff is also very responsible and responsive. Highly recommend her", "author": "A S", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117126373557453846455/reviews"}], "website": "https://www.i693clinic.com", "location": {"latitude": 37.3273983, "longitude": -121.93418469999999}, "services": ["I-693 Immigration Medical Exam", "TB Screening (IGRA or Skin Test)", "Required Vaccinations"], "insurance": {"notes": "Payment methods: Cash, Card, Zelle, HSA. Self-pay flat fee of $350.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "USCIS-Designated Civil Surgeon", "detail": "Dr. Manghnani is officially designated by USCIS as a Civil Surgeon authorized to perform Form I-693 immigration medical exams.", "category": "care"}, {"title": "Flat Fee – $350 per person", "detail": "$350 covers the examination, paperwork, and sealed envelope; lab tests and vaccinations billed separately.", "category": "insurance"}, {"title": "Multilingual Staff", "detail": "Staff speaks English, Spanish, Korean, Chinese, Punjabi, Hindi, Marathi, and Gujarati.", "category": "culture"}, {"title": "Same-Week Appointments", "detail": "Same-week availability including Saturdays for working applicants and families.", "category": "convenience"}, {"title": "Pediatrician Led", "detail": "Dr. Manghnani is board-certified in Pediatrics, ideal for families with children of any age applying for adjustment of status.", "category": "care"}, {"title": "Sealed Envelope Guarantee", "detail": "Completed Form I-693 is placed in a sealed envelope per USCIS requirements and handed to you.", "category": "access"}], "price_tier": "$$", "source_url": "https://www.i693clinic.com/", "appointment": {"booking_note": "Schedule online or call 408-297-9949. Same-week appointments available.", "appointment_url": "https://healow.com/apps/provider/-nurse-3417366", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese speaking medical clinic i