INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('fe6b6798-0f2c-41f1-b646-bccbe32c7552', NULL, 'Harborview Medical Center', 'Harborview Medical Center is a comprehensive healthcare facility dedicated to providing specialized care for a broad spectrum of patients from throughout the Pacific Northwest, including the most vulnerable residents of King County. As the only designated Level I adult and pediatric trauma and verified burn center in the state of Washington, Harborview serves as the regional trauma and burn referral center for Alaska, Montana and Idaho and the disaster preparedness and disaster control hospital for Seattle and King County. The UW Medicine physicians, staff and other healthcare professionals based at Harborview provide exemplary patient care in leading-edge centers of emphasis, including emergency medicine, trauma and burn care; neurosciences, ophthalmology, vascular surgery, HIV/AIDS and rehabilitation medicine. Patients given priority for care include the non-English speaking poor; the uninsured or underinsured, victims of domestic violence or sexual assault; people incarcerated in King County''s jails; people with mental illness or substance abuse problems, particularly those treated involuntarily; people with sexually transmitted diseases; and those who require specialized emergency, trauma or burn care. Harborview recognizes that delivering quality healthcare is enhanced by a strong commitment to teaching, community service and research. Harborview Medical Center is owned by King County, governed by a county-appointed board of trustees and managed under contract by the University of Washington.', '325 9th Ave, Seattle, WA 98104', 'Seattle', 'WA', '98104', '206.744.3000', ARRAY['English', 'Vietnamese']::text[], 'Hospital', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/harborview-medical-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/harborview-medical-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/harborview-medical-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/harborview-medical-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/harborview-medical-center-google-5.webp"], "rating": 3.6, "pricing": [{"name": "Parking - 0-30 minutes", "notes": "Patient/Visitor rate", "price": "Free", "category": "Parking", "price_range": null}, {"name": "Parking - 31-60 minutes", "notes": "Patient/Visitor rate", "price": "$4", "category": "Parking", "price_range": null}, {"name": "Parking - 1-3 hours", "notes": "Patient/Visitor rate", "price": "$5", "category": "Parking", "price_range": null}, {"name": "Parking - 3-4 hours", "notes": "Patient/Visitor rate", "price": "$7", "category": "Parking", "price_range": null}, {"name": "Parking - 4-6 hours", "notes": "Patient/Visitor rate", "price": "$12", "category": "Parking", "price_range": null}, {"name": "Parking - 6-7 hours", "notes": "Patient/Visitor rate", "price": "$15", "category": "Parking", "price_range": null}, {"name": "Parking - 7-24 hours", "notes": "Patient/Visitor rate", "price": "$20", "category": "Parking", "price_range": null}, {"name": "1-Week Family Pass", "notes": "Patients/Visitors only", "price": "$40", "category": "Parking", "price_range": null}, {"name": "Lost Ticket", "notes": "Patients/Visitors", "price": "$20", "category": "Parking", "price_range": null}, {"name": "Valet Service", "notes": "Regular parking rates apply", "price": "Free", "category": "Parking", "price_range": null}], "reviews": [{"date": "2026-03-16T22:19:18.524211870Z", "text": "Best hospital in the world. I have been there for major surgeries. Everyone that works there is so nice, courteous and helpful. The hardest times of my life and they all help make all the difference. The care and hospitality is the best. Very clean it makes you feel safe. The food is clean and very good. Everything about the place is great. I have had life changing injuries and they saved my life and restored my faith in humanity. 🙏💖", "author": "David Conrad", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110402074144115778537/reviews"}, {"date": "2026-03-27T21:06:44.943252670Z", "text": "I feel that Harborview Medical Center truly deserves a much higher rating.\n\nMy 17-year-old son had a severe leg fracture after a basketball injury, and the orthopedic team here did an absolutely incredible job. The surgery was complex and lasted four hours, but the result was remarkable. We are deeply grateful for their skill and care.\n\nI also want to highlight the nurses and staff on 8 East - an exceptional team. Professional, attentive, warm, and with a great sense of humor, they made a very difficult time feel manageable and even comforting.\n\nWe spent three days in the hospital and felt safe, supported, and genuinely cared for the entire time.\nThank you to everyone at Harborview, you didn’t just fix a broken bone, you truly made a difference in our lives.\n\nWe learned one important lesson from this experience, and now I tell everyone: if, God forbid, you ever have a serious fracture, go straight to Harborview. It is one of the very best hospitals in the United States!", "author": "Yuliya Kramak", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103150290628188736945/reviews"}, {"date": "2026-02-24T11:21:30.435821864Z", "text": "Very nice Doctors and nurses did a good job on my brace, very talkative, and kind, and I thought today was a pretty bad day, but with how talkative all of them were, and how most of em were saying I was a champ with pain tolerance made me feel awesome,", "author": "DYLLAN IBERLUCEA", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103499583524108455639/reviews"}, {"date": "2025-02-06T04:31:03.728010Z", "text": "Just wanted to rate the \"Meditation\" room, love the cozy feel and warm and heated room. It''s slightly separated with a curtain, perfect for wanting a separate space. Great for sisters separating from praying with brothers. There are prayer mats available to use and I saw Meditation pillows.\n\nIt''s really nice to have these available for visitors especially because we could be visiting our loved ones all day or weeks. As a Muslim, I''m happy that they have this for us. Thanks!", "author": "Philicia Saephan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115696973766887549088/reviews"}, {"date": "2026-04-09T17:06:56.131866307Z", "text": "Let’s be clear… this was not a meal deal.\nThis was me curating an experience one item at a time.\nI grabbed the bacon breakfast and built the rest piece by piece like I had a vision—and honestly? The vision came to life.\nFluffy scrambled eggs? Soft and buttery, no complaints.\nBacon? Crispy, flavorful, doing exactly what it needed to do.\nHome potatoes? Golden, seasoned, and not playing around.\nAnd that BBQ sauce on top? Yeah… that was a power move. Smoky, sweet, and pulled the whole plate together like a final chorus.\nNow yes—they do have meal deals…\nBut I went rogue and still ended up with a plate that felt like one.\nFor hospital food, this was surprisingly good. Not sad. Not bland. Not “just get through it.”\nThis was a “hold on… let me enjoy this real quick” kind of breakfast.\nFinal verdict: Built, not bought. And worth every single add-on.", "author": "LuVetra Sunflower", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/116696383901432832898/reviews"}], "website": "https://www.uwmedicine.org/locations/harborview-medical-center", "location": {"latitude": 47.6039167, "longitude": -122.323905}, "services": ["AIDS care", "Amputation/ limb loss", "Burn care", "Care for substance abuse and addiction", "Global health", "Hospital medicine", "Mental health care", "Occupational-Environmental Medicine", "Orthopedic surgery", "Otolaryngology [ENT] - head and neck surgery", "Palliative care", "Pediatric trauma care", "Physical medicine and rehabilitation", "Public health", "Sexually transmitted infection (STI) care", "Sleep medicine", "Trauma care", "Vascular surgery"], "insurance": {"notes": "Billing and insurance information is available via the patient resources page. No specific insurance networks are listed on this page.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Level I Trauma & Burn Center", "detail": "Only designated Level I adult and pediatric trauma and verified burn center in Washington, serving as regional referral center for Alaska, Montana, and Idaho.", "category": "care"}, {"title": "24/7 Emergency Care", "detail": "Open 24 hours a day, 7 days a week for emergency and trauma care.", "category": "access"}, {"title": "Safety-Net Hospital", "detail": "Prioritizes care for the uninsured, underinsured, non-English speaking, and other vulnerable populations.", "category": "access"}, {"title": "Comprehensive Services", "detail": "Offers a wide range of services including trauma care, burn care, neurosciences, HIV/AIDS care, rehabilitation medicine, and more.", "category": "care"}, {"title": "Interpreter Services", "detail": "Interpreter services available for patients.", "category": "culture"}], "price_tier": "$$", "source_url": "https://www.uwmedicine.org/locations/harborview-medical-center?utm_source=extnet&utm_medium=organic&utm_campaign=website_clicks&y_source=1_MTAwNDcxNDM0Ni03MTUtbG9jYXRpb24ud2Vic2l0ZQ%3D%3D", "appointment": {"booking_note": "Returning patients with MyChart: Sign in to book online. New patients or those without MyChart may book as guest or call 206.520.5000.", "appointment_url": "https://mychart.uwmedicine.org/prod01/openscheduling", "new_patient_note": "Please call to schedule your appointment instead. Only patients who have seen a provider within the last three years and have a MyChart account may book online.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking hospital in Seattle, WA", "search_text": "hospital | english | vietnamese | tiếng việt | người việt | bác sĩ việt | aids care | amputation/ limb loss | burn care | care for substance abuse and addiction | global health | hospital medicine | mental health care | occupational-environmental medicine | orthopedic surgery | otolaryngology [ent] - head and neck surgery | palliative care | pediatric trauma care | physical medicine and rehabilitation | public health | sexually transmitted infection (sti) care | sleep medicine | trauma care | vascular surgery | hiv/aids | rehabilitation | mental health | occupational medicine | surgery | trauma & emergency medicine | infectious disease", "google_types": ["hospital", "medical_center", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 872, "language_note": "Patients given priority for care include the non-English speaking poor, reflecting a commitment to language access and serving immigrant and culturally diverse communities.", "open_saturday": true, "quality_score": 92, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://www.uwmedicine.org/sites/stevie/files/styles/clinic_page_576_288/public/Adult-Medicine-Clinic-at-Harborview.jpg?itok=kzmpWVqy"], "review_profile": {"rating": 3.6, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Reviewers frequently commend the staff for being courteous, attentive, and warm, making difficult situations more manageable."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients appreciate the clean and safe environment, with specific mentions of cozy spaces like the meditation room."}, {"theme": "Treatment Outcomes", "mentions": 2, "sentiment": "Positive", "summary_quote": "Many reviewers highlight successful surgeries and treatments, expressing gratitude for life-changing care."}, {"theme": "Communication", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients note the staff''s kindness and talkative nature, which helped improve their mood and experience."}, {"theme": "Food Quality", "mentions": 1, "sentiment": "Positive", "summary_quote": "One reviewer praised the surprisingly good hospital food, describing it as flavorful and enjoyable."}], "summary": "Patients at Harborview Medical Center consistently praise the compassionate and professional care they receive, highlighting the supportive staff, clean facilities, and positive treatment outcomes. Many reviewers express deep gratitude for the hospital''s role in their recovery and overall experience.", "review_count": 872, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-03-16T22:19:18.524211870Z", "text": "Best hospital in the world. I have been there for major surgeries. Everyone that works there is so nice, courteous and helpful. The hardest times of my life and they all help make all the difference. The care and hospitality is the best. Very clean it makes you feel safe. The food is clean and very good. Everything about the place is great. I have had life changing injuries and they saved my life and restored my faith in humanity. 🙏💖", "author": "David Conrad", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110402074144115778537/reviews"}, {"date": "2026-03-27T21:06:44.943252670Z", "text": "I feel that Harborview Medical Center truly deserves a much higher rating.\n\nMy 17-year-old son had a severe leg fracture after a basketball injury, and the orthopedic team here did an absolutely incredible job. The surgery was complex and lasted four hours, but the result was remarkable. We are deeply grateful for their skill and care.\n\nI also want to highlight the nurses and staff on 8 East - an exceptional team. Professional, attentive, warm, and with a great sense of humor, they made a very difficult time feel manageable and even comforting.\n\nWe spent three days in the hospital and felt safe, supported, and genuinely cared for the entire time.\nThank you to everyone at Harborview, you didn’t just fix a broken bone, you truly made a difference in our lives.\n\nWe learned one important lesson from this experience, and now I tell everyone: if, God forbid, you ever have a serious fracture, go straight to Harborview. It is one of the very best hospitals in the United States!", "author": "Yuliya Kramak", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103150290628188736945/reviews"}, {"date": "2026-02-24T11:21:30.435821864Z", "text": "Very nice Doctors and nurses did a good job on my brace, very talkative, and kind, and I thought today was a pretty bad day, but with how talkative all of them were, and how most of em were saying I was a champ with pain tolerance made me feel awesome,", "author": "DYLLAN IBERLUCEA", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103499583524108455639/reviews"}, {"date": "2025-02-06T04:31:03.728010Z", "text": "Just wanted to rate the \"Meditation\" room, love the cozy feel and warm and heated room. It''s slightly separated with a curtain, perfect for wanting a separate space. Great for sisters separating from praying with brothers. There are prayer mats available to use and I saw Meditation pillows.\n\nIt''s really nice to have these available for visitors especially because we could be visiting our loved ones all day or weeks. As a Muslim, I''m happy that they have this for us. Thanks!", "author": "Philicia Saephan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115696973766887549088/reviews"}, {"date": "2026-04-09T17:06:56.131866307Z", "text": "Let’s be clear… this was not a meal deal.\nThis was me curating an experience one item at a time.\nI grabbed the bacon breakfast and built the rest piece by piece like I had a vision—and honestly? The vision came to life.\nFluffy scrambled eggs? Soft and buttery, no complaints.\nBacon? Crispy, flavorful, doing exactly what it needed to do.\nHome potatoes? Golden, seasoned, and not playing around.\nAnd that BBQ sauce on top? Yeah… that was a power move. Smoky, sweet, and pulled the whole plate together like a final chorus.\nNow yes—they do have meal deals…\nBut I went rogue and still ended up with a plate that felt like one.\nFor hospital food, this was surprisingly good. Not sad. Not bland. Not “just get through it.”\nThis was a “hold on… let me enjoy this real quick” kind of breakfast.\nFinal verdict: Built, not bought. And worth every single add-on.", "author": "LuVetra Sunflower", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/116696383901432832898/reviews"}]}, "review_summary": "Patients at Harborview Medical Center consistently praise the compassionate and professional care they receive, highlighting the supportive staff, clean facilities, and positive treatment outcomes. Many reviewers express deep gratitude for the hospital''s role in their recovery and overall experience.", "about_highlight": "Harborview Medical Center is a comprehensive healthcare facility dedicated to providing specialized care for a broad spectrum of patients from throughout the Pacific Northwest, including the most vulnerable residents of King County. As the only designated Level I adult and pediatric trauma and verified burn center in the state of Washington, Harborview serves as the regional trauma and burn referral center for Alaska, Montana and Idaho and the disaster preparedness and disaster control hospital for Seattle and King County. The UW Medicine physicians, staff and other healthcare professionals based at Harborview provide exemplary patient care in leading-edge centers of emphasis, including emergency medicine, trauma and burn care; neurosciences, ophthalmology, vascular surgery, HIV/AIDS and rehabilitation medicine. Patients given priority for care include the non-English speaking poor; the uninsured or underinsured, victims of domestic violence or sexual assault; people incarcerated in King County''s jails; people with mental illness or substance abuse problems, particularly those treated involuntarily; people with sexually transmitted diseases; and those who require specialized emergency, trauma or burn care. Harborview recognizes that delivering quality healthcare is enhanced by a strong commitment to teaching, community service and research. Harborview Medical Center is owned by King County, governed by a county-appointed board of trustees and managed under contract by the University of Washington.", "appointment_url": "https://mychart.uwmedicine.org/prod01/openscheduling", "google_maps_url": "https://maps.google.com/?cid=6803544737971406536&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJ7w3EijcVkFQRyIZDeOQLa14", "quality_missing": ["insurance", "team_members"], "search_keywords": ["hospital", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "aids care", "amputation/ limb loss", "burn care", "care for substance abuse and addiction", "global health", "hospital medicine", "mental health care", "occupational-environmental medicine", "orthopedic surgery", "otolaryngology [ent] - head and neck surgery", "palliative care", "pediatric trauma care", "physical medicine and rehabilitation", "public health", "sexually transmitted infection (sti) care", "sleep medicine", "trauma care", "vascular surgery", "hiv/aids", "rehabilitation", "mental health", "occupational medicine", "surgery", "trauma & emergency medicine", "infectious disease"], "cultural_context": "Patients given priority for care include the non-English speaking poor, reflecting a commitment to language access and serving immigrant and culturally diverse communities.", "services_offered": [{"name": "AIDS care", "category": "HIV/AIDS", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Amputation/ limb loss", "category": "Rehabilitation", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Burn care", "category": "Burn Care", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Care for substance abuse and addiction", "category": "Mental Health", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Global health", "category": "Public Health", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Hospital medicine", "category": "Hospital Medicine", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Mental health care", "category": "Mental Health", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Occupational-Environmental Medicine", "category": "Occupational Medicine", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Orthopedic surgery", "category": "Surgery", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Otolaryngology [ENT] - head and neck surgery", "category": "Surgery", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Palliative care", "category": "Palliative Care", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Pediatric trauma care", "category": "Trauma & Emergency Medicine", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Physical medicine and rehabilitation", "category": "Rehabilitation", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Public health", "category": "Public Health", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Sexually transmitted infection (STI) care", "category": "Infectious Disease", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Sleep medicine", "category": "Sleep Medicine", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Trauma care", "category": "Trauma & Emergency Medicine", "description": null, "is_featured": false, "patient_fit": null}, {"name": "Vascular surgery", "category": "Surgery", "description": null, "is_featured": false, "patient_fit": null}], "short_description": "Harborview Medical Center is a comprehensive healthcare facility and the only designated Level I adult and pediatric trauma and verified burn center in Washington, serving as the regional referral center for the Pacific Northwest.", "google_website_url": "https://www.uwmedicine.org/locations/harborview-medical-center?utm_source=extnet&utm_medium=organic&utm_campaign=website_clicks&y_source=1_MTAwNDcxNDM0Ni03MTUtbG9jYXRpb24ud2Vic2l0ZQ%3D%3D", "google_primary_type": "Hospital", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "325 9th Ave Main Hospital, Seattle, WA 98104, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/100578126400951910266", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWIZZDb5vw0HaDRH3VARPEmxX8PMyVzqH4kof82Vda9kORSHT17=s100-p-k-no-mo", "displayName": "Harborview Medical Center"}], [{"uri": "https://maps.google.com/maps/contrib/118132983015764107408", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXhb6uPa4zrrp2FUZ37F166_P25PrXbdI77_d7g-FfLMhRHNacp=s100-p-k-no-mo", "displayName": "Komu"}], [{"uri": "https://maps.google.com/maps/contrib/102227898200911435799", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXpIO83lf4fY8wQwsfv99IsRbiexXJtafztP_zrdHokxLuBqxT35Q=s100-p-k-no-mo", "displayName": "Smyle K"}], [{"uri": "https://maps.google.com/maps/contrib/111579205409243699538", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWNMlKvR5xoZpex57ISkjWjUilD4RAtUoxt4evIhFqbxKYhesyZ=s100-p-k-no-mo", "displayName": "Keith Cote"}], [{"uri": "https://maps.google.com/maps/contrib/103892548776573346119", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjXpDgSJNMManT3leTKNtw7VGEALO0yFlSSReEJu6dBWxKB5MzaUNQ=s100-p-k-no-mo", "displayName": "Demetrius Gainer (Meech)"}]]}'::jsonb, '2026-06-25T20:33:55.697777+00:00', 'harborview-medical-center', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('259cac4f-9de1-4e31-bf0c-18bdd31a5c30', NULL, 'Emory University Hospital Midtown', 'Emory University Hospital Midtown is a full-service, more than 600-bed specialized care hospital in the heart of Atlanta. Since 1908, it has provided outstanding quality healthcare, consistently ranking among Georgia''s top hospitals for cancer, cardiology and heart surgery, ear/nose/throat, diabetes and endocrinology, gynecology, nephrology, neurology/neurosurgery, geriatrics, and more. The hospital is a Level 1 Emergency Cardiac Care Center, a Certified Primary Stroke Center, a MBSAQIP Accredited Comprehensive Bariatric Center, and has a Level III Neonatal Intensive Care Unit (NICU). With more than 2,000 physicians across a vast array of specialties, its team collaborates to deliver comprehensive care and quality outcomes, supported by advanced research and ties to Emory University.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('eb03d8ec-60a7-4573-b0bf-567590596941', NULL, 'Neighborhood Medical Center. Martin G. McElya, DO', 'Neighborhood Medical Center, led by Dr. Martin G. McElya, DO, is a comprehensive medical practice in Dallas, Texas, offering primary care, urgent care, immigration physicals, wellness services, and more. The clinic focuses on providing accessible, patient-centered care with same-day appointments, telemedicine options, and a wide range of services including chronic disease management, weight loss programs, and aesthetic treatments. Patients benefit from in-house labs, X-rays, and a dedicated team that offers flexible scheduling and texting for quick communication.', '5917 Belt Line Road, Dallas, TX 75254', 'Dallas', 'TX', '75254', '972-726-6464', ARRAY['English', 'Vietnamese']::text[], 'Primary Care', TRUE, '{"fax": "972-726-6444", "email": "info@nmcdallas.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/neighborhood-medical-center.-martin-g.-mcelya-do-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/neighborhood-medical-center.-martin-g.-mcelya-do-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/neighborhood-medical-center.-martin-g.-mcelya-do-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/neighborhood-medical-center.-martin-g.-mcelya-do-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/neighborhood-medical-center.-martin-g.-mcelya-do-google-5.webp"], "rating": 4.1, "reviews": [{"date": "2026-03-03T22:02:02.015847452Z", "text": "I was a patient at this practice for 2–3 years, mainly for annual check-ups. Unfortunately, my experience was consistently frustrating.\n\nEven with scheduled appointments, I was often waiting much longer than expected.\n\nIn the beginning, I rarely saw the doctor at all — only the PA. More recently, the doctor’s visits were brief, essentially just giving a fist bump.\n\nEmails and calls were never returned. When I needed continuity of care and documents for an insurance change, neither my calls nor emails were answered. Even my insurance tried contacting the office, but there was no response.\n\nI ended up having to leave for another provider. The office could have formally denied my services if they chose, but instead, they wasted a lot of my time with continuous delays and unresponsiveness.\n\nOverall, the lack of responsiveness, communication, and meaningful doctor interaction made it impossible to rely on this practice.", "author": "Ivy B", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/116839571409062394294/reviews"}, {"date": "2026-06-01T23:34:22.029682373Z", "text": "Had a very good experience today for my annual exam! I have to give kudos to Payton Smith, she answered all my questions and her care shows in what she says and suggests. To top it all off, Dr McElya dropped in to say hi! I absolutely love them! Don''t hesitate to make this clinic your family clinic! You will NOT regret it!", "author": "Siphiwe Mabuya", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100802157926570508883/reviews"}, {"date": "2025-09-23T21:11:38.787107866Z", "text": "This is my health we’re talking about here! When you send me for a CT scan and it comes back bad enough for you to call me same day, make an appt etc.. I show up to my appt and no one knows what I’m talking about. Front desk lady can’t get my name right, asked me for my birthdate 3x and still had it wrong. Said she doesn’t know anything about my appt etc… This is absurd! I’m left wondering if this is just a glorified doc-in-a-box or a real general practitioner!  This isn’t a single occurrence either. Last year the doc said he wanted to see me back in 6 months and I watched him write that in my file. Tell me how I made it out of the office without the front desk scheduling this?? Oh but they were sure to get their money….", "author": "Brandon Bradshaw", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/116664720164193681322/reviews"}, {"date": "2026-04-29T20:36:04.171237901Z", "text": "Saw Dr. McElya this past week. The entire crew was amazing and friendly. Greeted immediately upon arrival by front desk crew. Was taken back to a room by PA Payton. Super knowledgeable and very friendly. Such a people person and made me feel welcomed and reassured their team was going to get me right as my back was killing me. Finally, I was able to get checked on by Dr. McElya. Extremely nice guy and very outgoing.\n\nI plan to continue to use Neighborhood Medical Center for myself and my family!", "author": "Austin Nelson", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115235541044531925477/reviews"}, {"date": "2026-05-06T23:24:31.525473870Z", "text": "This is a phenomenal place . I needed a Dr last minute . Called set an appointment the gentleman was very polite and knowledgeable. The young lady at the front desk was kind and answered my questions made me feel at ease . Reyna the young lady who took my vitals was amazing . Even the lady who took my blood was a pro! My physician assistant Payton was very clear and explained everything. This was the most amazing experience I have had going to the doctor. So thankful I found this place . I made them my primary care provider!", "author": "Stuart Pearson", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108303972796330138316/reviews"}], "website": "https://www.neighborhoodmedicalcenter.com/contactus", "location": {"latitude": 32.9547455, "longitude": -96.8055947}, "services": ["Primary Care", "Urgent Care", "Immigration Physicals", "Annual Physical", "DOT Physical", "Sports Injuries", "Weight Loss Plans", "Home-Kit Weight Loss Injection Program", "Bioidentical Hormone Replacement Therapy", "Testosterone Therapy", "Peptide Therapy", "Platelet Rich Plasma (PRP) Hair Restoration", "Cryotherapy for Skin Growths", "Flu & Strep Testing", "COVID-19 Testing and Care", "Vaccines & Immunizations", "Telemedicine"], "insurance": {"notes": "Insurance accepted information available on the Insurance page. Self-pay options also offered.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Same-day appointments", "detail": "Urgent care and same-day primary care appointments available.", "category": "convenience"}, {"title": "Telemedicine", "detail": "Telemedicine visits available for remote consultations.", "category": "convenience"}, {"title": "In-house labs and X-rays", "detail": "On-site lab and imaging services for faster results.", "category": "convenience"}, {"title": "Text-based communication", "detail": "Patients can text the clinic for scheduling, questions, and more.", "category": "convenience"}], "price_tier": "$$", "source_url": "https://www.neighborhoodmedicalcenter.com/contactus?utm_source=NEXT&utm_medium=Google_appt", "appointment": {"booking_note": "Book online or call/text to schedule.", "appointment_url": "https://z2-rpw.phreesia.net/selfscheduling.app/#/10dea371-ef67-4b26-a8d6-2bfd097508a9", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese speaking medical clinic in Dallas, TX