INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('85db7cf3-8621-42ed-b395-3887a1528d9b', NULL, 'Chinese Medicine Works', 'Chinese Medicine Works is a clinic dedicated to providing traditional Chinese medicine services. The clinic focuses on holistic health and wellness, offering treatments such as acupuncture, herbal medicine, and other modalities rooted in ancient Chinese healing practices. Patients can expect personalized care aimed at restoring balance and promoting natural healing.', '1201 Noe St, San Francisco, CA 94114', 'San Francisco', 'CA', '94114', '(415) 285-0931', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-medicine-works-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-medicine-works-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-medicine-works-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-medicine-works-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-medicine-works-google-5.webp"], "rating": 5, "reviews": [{"date": "2018-05-07T16:12:41.086Z", "text": "I highly recommend Chinese Medicine Works! Janice Mao is a true professional and has transformed my back pain and stress with her expertise in cupping, acupuncture, and herbal supplements. She is incredibly thorough and kind, and she treats her patients with a integrated, holistic approach that I haven’t witnessed in western medicine. I encourage anyone to make an appointment with Janice, as they won’t be disappointed.", "author": "Adriane McCord", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110233275348268707723/reviews"}], "website": "http://www.chinesemedicineworks.com", "location": {"latitude": 37.7497184, "longitude": -122.4315201}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "price_tier": "$$", "source_url": "http://www.chinesemedicineworks.com/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in San Francisco, CA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人", "google_types": ["consultant", "medical_clinic", "health", "store", "point_of_interest", "service", "establishment"], "open_weekend": false, "rating_count": 1, "language_note": "The clinic specializes in traditional Chinese medicine, providing culturally rooted healing practices such as acupuncture and herbal medicine.", "open_saturday": false, "quality_score": 80, "working_hours": {"friday": "9:00 AM – 5:00 PM", "monday": "9:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "10:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "10:00 AM – 5:00 PM", "wednesday": "9:00 AM – 5:00 PM"}, "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 1, "sentiment": "Positive", "summary_quote": "Janice Mao''s expertise in cupping, acupuncture, and herbal supplements has transformed patients'' health."}, {"theme": "Staff Professionalism", "mentions": 1, "sentiment": "Positive", "summary_quote": "Janice Mao is described as a true professional who treats patients with kindness and thoroughness."}, {"theme": "Holistic Approach", "mentions": 1, "sentiment": "Positive", "summary_quote": "Patients appreciate the integrated, holistic approach that differs from western medicine."}, {"theme": "Treatment Outcomes", "mentions": 1, "sentiment": "Positive", "summary_quote": "Effective treatments have significantly improved patients'' back pain and stress levels."}, {"theme": "Patient Experience", "mentions": 1, "sentiment": "Positive", "summary_quote": "Patients encourage others to make an appointment, assuring they won’t be disappointed."}], "summary": "Patients highly recommend Chinese Medicine Works, praising Janice Mao''s professionalism, holistic approach, and effective treatments for pain and stress.", "review_count": 1, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2018-05-07T16:12:41.086Z", "text": "I highly recommend Chinese Medicine Works! Janice Mao is a true professional and has transformed my back pain and stress with her expertise in cupping, acupuncture, and herbal supplements. She is incredibly thorough and kind, and she treats her patients with a integrated, holistic approach that I haven’t witnessed in western medicine. I encourage anyone to make an appointment with Janice, as they won’t be disappointed.", "author": "Adriane McCord", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110233275348268707723/reviews"}]}, "review_summary": "Patients highly recommend Chinese Medicine Works, praising Janice Mao''s professionalism, holistic approach, and effective treatments for pain and stress.", "about_highlight": "Chinese Medicine Works is a clinic dedicated to providing traditional Chinese medicine services. The clinic focuses on holistic health and wellness, offer