INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('1e9556d4-9c79-40a6-871d-6ad685c55899', NULL, 'San Francisco & Bay Area Korea Center (샌프란시스코 • 베이 지역 한인회)', 'San Francisco & Bay Area Korea Center is a community organization serving the Korean diaspora in Northern California. It hosts cultural events, commemorative ceremonies, and community gatherings to promote Korean heritage and strengthen ties among Korean Americans and the broader community.', '745 Buchanan St, San Francisco, CA 94102', 'San Francisco', 'CA', '94102', '(408) 483-6707', ARRAY['English', 'Korean']::text[], 'Community Center', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-francisco-bay-area-korea-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-francisco-bay-area-korea-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-francisco-bay-area-korea-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-francisco-bay-area-korea-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/san-francisco-bay-area-korea-center-google-5.webp"], "rating": 5, "reviews": [{"date": "2024-02-17T17:19:30.976888Z", "text": "On February 17th, 2024, we extend our heartfelt congratulations and support to the Korea Center in San Francisco and the Bay Area on the occasion of their new beginning.\n\nWe are delighted to celebrate this momentous milestone and look forward to witnessing the Center''s continued success in fostering cultural exchange, promoting community engagement, and strengthening ties between Korea and the Bay Area.\n\nWe wish the Center and its dedicated staff all the best in their future endeavors.\n\nSincerely,\nKorea 24 News Media\nFeb 17, 2024", "author": "Korea 24 News Media Korea 24 News", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101903340701155829643/reviews"}], "website": "https://sfkorea.org/", "location": {"latitude": 37.7769329, "longitude": -122.428277}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "price_tier": "$$", "source_url": "https://sfkorea.org/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean speaking medical clinic in San Francisco, CA", "search_text": "community center | english | korean | 한국어 | 한인 | 한국말", "google_types": ["non_profit_organization", "cultural_center", "community_center", "event_venue", "medical_clinic", "association_or_organization", "health", "educational_institution", "transportation_service", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 2, "language_note": "Korean community center serving the Korean diaspora in the San Francisco Bay Area, with events for Korean heritage and identity.", "open_saturday": true, "quality_score": 80, "working_hours": {"friday": "9:00 AM – 5:00 PM", "monday": "9:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "9:00 AM – 5:00 PM", "saturday": "9:00 AM – 5:00 PM", "thursday": "9:00 AM – 5:00 PM", "wednesday": "9:00 AM – 5:00 PM"}, "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Community Engagement", "mentions": 1, "sentiment": "Positive", "summary_quote": "The review celebrates the Center''s role in fostering cultural exchange and promoting community engagement."}, {"theme": "Staff Dedication", "mentions": 1, "sentiment": "Positive", "summary_quote": "The review wishes the Center''s dedicated staff all the best in their future endeavors."}], "summary": "The review expresses heartfelt congratulations and support for the Korea Center''s new beginning, highlighting its role in cultural exchange and community engagement.", "review_count": 2, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2024-02-17T17:19:30.976888Z", "text": "On February 17th, 2024, we extend our heartfelt congratulations and support to the Korea Center in San Francisco and the Bay Area on the occasion of their new beginning.\n\nWe are delighted to celebrate this momentous milestone and look forward to witnessing the Center''s continued success in fostering cultural exchange, promoting community engagement, and strengthening ties between Korea and the Bay Area.\n\nWe wish the Center and its dedicated staff all the best in their future endeavors.\n\nSincerely,\nKorea 24 News Media\nFeb 17, 2024", "author": "Korea 24 News Media Korea 24 News", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101903340701155829643/reviews"}]}, "review_summary": "The review expresses heartfelt congratulations and support for the Korea Center''s new beginning, highlighting its role in cultural exchange and community engagement.", "about_highlight": "San Francisco & Bay Area Korea Center is a community organization serving the Korean diaspora in Northern California. It hosts cultural events, commemorative ceremonies, and community gatherings to promote Korean heritage and strengthen ties among Korean Americans and the broader community.", "google_maps_url": "https://maps.google.com/?cid=6427137878829508097&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJnbWBulqBhYARASYXLtnHMVk", "quality_missing": ["services", "insurance", "team_members", "appointment_url"], "search_keywords": ["community center", "english", "korean", "한국어", "한인", "한국말"], "cultural_context": "Korean community center serving the Korean diaspora in the San Francisco Bay Area, with events for Korean heritage and identity.", "short_description": "A Korean community center in San Francisco that organizes cultural events, commemorations, and community programs.", "google_website_url": "https://sfkorea.org/", "google_primary_type": "Non-Profit Organization", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "745 Buchanan St, San Francisco, CA 94102, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/103115918898049706384", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVnzqdrwU77Q9wHQO9IR_YC8cstwuYg4jjsemNiGJv3ctMOz_s=s100-p-k-no-mo", "displayName": "San Francsico & Bay Area Korea Center (샌프란시스코 • 베이 지역 한인회)"}], [{"uri": "https://maps.google.com/maps/contrib/103115918898049706384", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVnzqdrwU77Q9wHQO9IR_YC8cstwuYg4jjsemNiGJv3ctMOz_s=s100-p-k-no-mo", "displayName": "San Francsico & Bay Area Korea Center (샌프란시스코 • 베이 지역 한인회)"}], [{"uri": "https://maps.google.com/maps/contrib/103115918898049706384", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVnzqdrwU77Q9wHQO9IR_YC8cstwuYg4jjsemNiGJv3ctMOz_s=s100-p-k-no-mo", "displayName": "San Francsico & Bay Area Korea Center (샌프란시스코 • 베이 지역 한인회)"}], [{"uri": "https://maps.google.com/maps/contrib/103115918898049706384", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVnzqdrwU77Q9wHQO9IR_YC8cstwuYg4jjsemNiGJv3ctMOz_s=s100-p-k-no-mo", "displayName": "San Francsico & Bay Area Korea Center (샌프란시스코 • 베이 지역 한인회)"}