INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('b4a9a7da-ed86-4ba6-a303-165515c836f3', NULL, 'One Medical: Jessica Chan, DO', 'Jessica Chan, DO is an osteopathic family medicine doctor at One Medical''s Noe Valley - 24th St office in San Francisco. She emphasizes a whole-person approach to care, focusing on body, mind, and spirit, and is passionate about primary care, women''s health, obstetrics, osteopathic manipulative treatment (OMT), and stress reduction. She earned her doctoral degree from Midwestern University and is board-certified in family medicine. Outside of work, she enjoys hiking, yoga, cooking, and spending time with family and friends.', '3885 24th Street, San Francisco, CA 94114', 'San Francisco', 'CA', '94114', '888-663-6331', ARRAY['English', 'Korean']::text[], 'Family Medicine', FALSE, '{"email": "admin@onemedical.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/one-medical-jessica-chan-do.webp"], "rating": 5, "reviews": [{"date": "2024-10-17T19:15:01.639649Z", "text": "Jessica Chan is a stellar doctor. She’s kind, thorough, and cares deeply about her patients. She will not rush through an exam and she really listens to a patient’s concerns. She does not work full time, so it’s not always easy to see her for an urgent medical problem. But the urgent care docs and nurses ay One Medical are uniformly excellent. And Dr. Chan is always aware of my situation, monitors my progress and handles follow up visits. I have had  only positive experiences at One Medical.", "author": "Wendy Miller", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107399958909875910602/reviews"}], "website": "https://www.onemedical.com/providers/jessica-chan/", "location": {"latitude": 3