INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('23f6f20d-f59f-4ba2-bf2f-9649d14ffbbd', NULL, 'Southcenter Medical Clinic', 'Southcenter Medical Clinic is a family medicine practice in Tukwila, WA dedicated to providing personalized, compassionate care for the whole family. The clinic treats patients like family, taking the time to understand each individual''s unique health needs. Conveniently located minutes from Southcenter Mall near the I-5/I-405 interchange, the clinic emphasizes quality of care and collaboration to build a path to wellness that fits each patient''s lifestyle. They accept new patients, walk-ins, and offer telemedicine video visits.', '15215 52nd Ave S, #204, Tukwila, WA, 98188', 'Tukwila', 'WA', '98188', '206-414-9412', ARRAY['English', 'Vietnamese']::text[], 'Family Medicine', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southcenter-medical-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southcenter-medical-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southcenter-medical-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southcenter-medical-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southcenter-medical-clinic-google-5.webp"], "rating": 4.6, "reviews": [{"date": "2025-11-05T19:49:57.577958066Z", "text": "Dr. Danh was amazing! I hadn’t visited a doctor in over 10 years, and he took the time to explain my blood work in clear, detailed terms. The entire staff, including the receptionists, were incredibly kind and accommodating with my schedule.", "author": "Keith", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112693841198225170759/reviews"}, {"date": "2025-12-11T20:11:44.135747440Z", "text": "I absolutely love this doctor and his entire office staff. He takes the time to truly listen to every single one of my concerns and always explains things in a way that’s easy to understand. What I appreciate most is that he remembers my previous concerns and keeps them in mind as we continue any treatment, nothing ever feels rushed or overlooked.\n\nThe office staff is always friendly, kind, and welcoming, making every visit a great experience from start to finish. This has genuinely been the best experience I’ve ever had with a doctor in my whole life. I’m so grateful to have found this office and couldn’t recommend them more!", "author": "Jennifer Perez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108547263293762899613/reviews"}, {"date": "2025-12-08T19:32:10.951584413Z", "text": "Dr. Danh is very knowledgeable and always takes the time to explain things in clear details. I have been taking my mother here and we are very pleased with the care we receive. They speak Vietnamese which is a bonus for my mom to actively participate in her treatment plan.", "author": "Nhu Pham", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103774736713346559997/reviews"}, {"date": "2025-12-09T06:36:13.761169916Z", "text": "Amazing clinic with same week availability always, have made sure to stay even when switching insurances. I appreciate the entire team here!", "author": "Julia", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100055044589577477747/reviews"}, {"date": "2025-10-17T20:11:48.238035677Z", "text": "Long wait times to complete a form, ev