INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('66051341-315f-4858-a8a9-150874d43d75', NULL, 'Duong (Young) Tran, PA-C', 'Young Tran, PA-C, is an orthopaedic surgery physician assistant at Optum - Madison Center in Seattle, Washington. He treats a wide range of sports-related conditions and joint replacements, with a philosophy of care that starts with listening to the patient''s concerns and goals. He explains diagnoses and treatment plans in an easily understood manner, personalizing the approach based on each patient''s hobbies and lifestyle to help them live healthier, more active lives. Young enjoys contributing to people''s well-being and, outside of work, enjoys traveling, golf, boating, fishing, and hiking.', '904 7th Ave, Seattle, WA 98104', 'Seattle', 'WA', '98104', '1-206-860-5578', ARRAY['English', 'Vietnamese']::text[], 'Orthopedics', FALSE, '{"fax": "1-206-860-2201", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/duong-young-tran-pa-c.webp"], "rating": 5, "reviews": [{"date": "2024-12-17T17:46:23.156345Z", "text": "Talk about awesome doctors! Tran was incredible with my rambunctious 5 year old daughter, who broke her elbow. He was super knowledgeable, super skilled. He was also nice, kind, and funny to boot! My daughter was so stubborn about following the instructions and resting her body, but he was able to, through humor, friendship, and a little bit of m&m’s magic, help her learn to do what she needed to heal. Highly recommend this doctor for all your children & adult ortho needs.", "author": "Sarah Yerkan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114754329412652191142/reviews"}, {"date": "2024-04-12T23:47:15.068492Z", "text": "Young Tran is a very skilled, knowledgeable and personable orthopedic clinician.  He keeps up with the literature and spends time with you to explain different treatment options.  He’s very good with steroid injections, I’ve always had good relief when he did them.  One time, another clinician gave it to me, and the pain did not improve, so I appreciate the skill and care Young takes to identify the right spot to make the injection.  He''s also a very kind person, all the staff say the nicest things about him!", "author": "Cynthia Sung", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110700474836028475926/reviews"}, {"date": "2023-05-17T00:27:27.663854Z", "text": "He is really good with knee ejection. A skill that help pacitent to reduce pain and fast recovery from condition", "author": "KJ Chan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106203167301607693403/reviews"}], "website": "https://www.polyclinic.com/provider-lookup/provider-detail-page.html?npi=1821140054", "location": {"latitude": 47.6074762, "longitude": -122.329045}, "services": ["Orthopaedic Surgery"], "insurance": {"notes": "Please contact the clinic directly to verify accepted insurance plans.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Accepting New Patients", "detail": "This provider is currently accepting new patients.", "category": "access"}, {"title": "Bilingual Provider", "detail": "Speaks English and Vietnamese.", "category": "culture"}, {"title": "Orthopaedic Surgery Specialist", "detail": "Treats sports-related conditions and joint replacements.", "category": "care"}, {"title": "High Patient Ratings", "detail": "4.6 out of 5 stars from over 500 ratings.", "category": "reviews"}], "price_tier": "$$", "source_url": "https://www.polyclinic.com/provider-lookup/provider-detail-page.html?npi=1821140054&utm_campaig