INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('1c794003-2931-44b1-88dd-e331388bc6e8', NULL, 'Edmonds Medical Clinic', 'Edmonds Medical Clinic provides primary care for the whole family, with a team of American Board certified physicians and outstanding staff. The clinic is committed to seeing patients when they need care most, offering same-day appointments for unexpected illness and scheduling for chronic conditions. Services include primary care, preventative care, adult health/internal medicine, women’s health, pediatrics, work/school/travel exams, minor ambulatory procedures, lab tests, EKG, breathing treatments, virtual telemedicine, and USCIS authorized exams. The clinic aims to offer warmth, respect, and direct human contact in combination with modern and alternative medicine, with a mission to help everyone enjoy a healthier and happier life.', '21600 Highway 99 Suite 280, Edmonds, WA 98026', 'Edmonds', 'WA', '98026', '(425) 582-7753', ARRAY['English', 'Korean']::text[], 'Primary Care', TRUE, '{"fax": "(425) 740-0078", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/edmonds-medical-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/edmonds-medical-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/edmonds-medical-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/edmonds-medical-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/edmonds-medical-clinic-google-5.webp"], "rating": 4.7, "reviews": [{"date": "2026-03-10T06:13:07.257765135Z", "text": "Dr. Koh was incredibly kind and the service was exceptional. I am so grateful to him and the entire team for making me feel comfortable and well cared for throughout the experience", "author": "Mariangel Oviedo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100103520568483505309/reviews"}, {"date": "2026-03-25T18:12:26.139662877Z", "text": "Dr. Park is the kindest doctor I have ever met. As someone who is still not familiar with the U.S. healthcare system, I truly appreciated how she took the time to explain additional information in a clear and easy-to-understand way. I feel very grateful to have her as my primary care doctor.", "author": "joanneforu93", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100691324394292880263/reviews"}, {"date": "2026-05-06T17:24:46.110327566Z", "text": "Just had my first experience with the EMC and can honestly say it was very positive!  Dr. Park and her staff were exceptionally efficient.  I look forward to continuing my health care with them!", "author": "Carrie Higley", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105157405623610635902/reviews"}, {"date": "2026-01-02T15:09:38.078265589Z", "text": "Dr. Koh is knowledgeable and patient. He has been my primary care provider for 3 years now and always go to him whenever I have health problems. I can easily send out refill medication requests and get it approved in the same day. He also answered your questions on Mychart message well and patiently. Highly recommend Dr. Koh for everyone", "author": "Dat Le", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108686838751343587220/reviews"}, {"date": "2025-11-25T13:24:14.875465624Z", "text": "My direct contact with Dr. Koh was very good. The treatments I''ve received were excellent. He explain