INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('2ea282d9-c99b-43cc-b812-b63112c3d34d', NULL, 'Joo Family Clinic', 'Joo Family Clinic is a primary care and family medicine practice based in Edmonds, WA, offering preventive, personalized, and accessible care for patients of all ages. The clinic provides annual physical exams, well child check-ups, chronic disease management, acute care visits, and telemedicine for established patients, alongside a full range of aesthetic treatments including Ultherapy, Botox/Fillers, laser treatments, Plexr, hydration/skin quality treatments, weight management, micro needling, and PRP. Their comprehensive care also highlights preventive care, women’s health, pediatric care, and chronic care management, all delivered with a focus on patient-centered wellness.', '22618 Hwy 99 ste 106, Edmonds, WA 98026, USA', 'Edmonds', 'WA', '98026', '(425) 409-9247', ARRAY['English', 'Korean', 'Mandarin']::text[], 'Family Medicine', TRUE, '{"fax": "(206) 535-2442", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/joo-family-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/joo-family-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/joo-family-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/joo-family-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/joo-family-clinic-google-5.webp"], "rating": 4.1, "reviews": [{"date": "2025-12-04T03:37:04.553164014Z", "text": "Dr. Joo is an outstanding provider. She takes the time to explain the diagnosis clearly and ensures that all questions are answered. What stands out most is how genuinely she listens and cares for her patients. I would have gladly given her more than five stars if possible.\nI highly recommend going here if you’re looking for a reliable and empathetic health care provider.", "author": "Hanna Kim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102213143186339192806/reviews"}, {"date": "2025-02-07T22:36:13.277911Z", "text": "Dr. Joo is an outstanding doctor! She is knowledgeable, attentive, and genuinely cares about her patients. She takes the time to listen, explains everything clearly, and ensures you feel comfortable with your care. The office staff is friendly and efficient, making every visit a great experience. My wife and parents also see Dr. Joo, and we all trust her completely. I highly recommend her to anyone!", "author": "Chang Oh", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104127924191209090334/reviews"}, {"date": "2025-10-15T23:21:58.234878017Z", "text": "Joo NP, If you didn''t know, you should have told me honestly \"I don''t know.\"\nShe couldn''t find the reason of my legs pain and made a huge mistake, it was a misdiagnosis.\nWe decided to change the PCP when I couldn''t even stand up. Eventually, the cause was found and treated by a doctor at another hospital. It wasn''t an allergy, it was a more serious problem.\nWorst ever. Never again.", "author": "Lia", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/117396004445648558573/reviews"}, {"date": "2025-02-13T06:01:27.382025Z", "text": "Dr. Song was fantastic! They were incredibly friendly, made me feel comfortable, and handled everything efficiently. I really appreciated their professionalism and warm demeanor. Highly recommend!", "author": "H_ Young", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102574422184882538212/reviews"}, {"date": "2025-02-13T19:57:46.564064Z", "text": "Doctor Joo was very knowledgeable and friendly and the staff are very experienced and professional. Glad I finally found a PCP and a clinic I can go to for any and all medical problems.\nIf they are accepting new patients, highly recommend!", "author": "Eun-Sung Kim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113368218892238160288/reviews"}], "website": "http://www.joofamilyclinic.com/", "location": {"latitude": 47.7935178, "longitude": -122.3371585}, "services": ["Primary Care", "Aesthetic Treatments", "Preventive Care", "Women’s Health", "Pediatric Care", "Chronic Care Management", "Ultherapy", "Botox / Fillers", "Laser Treatments", "Plexr", "Hydration / Skin Quality", "Weight Management", "Micro Needling", "PRP", "Event | Gift Card"], "insurance": {"notes": "Accepts most in-network insurance plans. Details available on the In-network Insurances page.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Comprehensive Primary Care", "detail": "Annual physicals, well child check-ups, chronic disease management, acute care, and telemedicine for established patients.", "category": "care"}, {"title": "Full Aesthetic Services", "detail": "Ultherapy, Botox/Fillers, laser treatments, Plexr, hydration/skin quality, weight management, micro needling, and PRP.", "category": "care"}, {"title": "Multilingual Medical Services", "detail": "Medical services are available in English, Korean, and Mandarin.", "category": "culture"}, {"title": "In-Network Insurance", "detail": "Accepts most in-network insurance plans. Details available on their Insurance Details page.", "category": "insurance"}, {"title": "Convenient Hours", "detail": "Open Monday–Friday 8 AM–5 PM, Sa