INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('7b7924b0-6749-4f0f-9a37-dd35ac58436e', NULL, 'Seattle Chinese Medical Center', 'Seattle Chinese Medical Center, under the direction of Dr. Xindong (Rosey) Ma, is a clinic specializing in women''s health care, acupuncture, infertility treatment, and internal medicine. Dr. Ma brings extensive academic and clinical experience as a professor and clinical instructor at the Northwest Institute of Acupuncture & Oriental Medicine, a GYN professor at Bastyr University, and a researcher at the Asian Women Cervical Cancer Prevention Center. The clinic focuses on integrating traditional Chinese medicine with modern healthcare needs in a culturally supportive environment.', '326 Queen Ann Ave. N, C-101, Seattle, WA 98109', 'Seattle', 'WA', '98109', '(206)363-8160', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"email": "seattlechinesemedicalcenter@yahoo.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/seattle-chinese-medical-center-google-1.webp"], "rating": 4.6, "reviews": [{"date": "2024-10-20T17:57:16.357081Z", "text": "I had a great experience with Dr. Ma. She is very attentive, caring, and her acupuncture and herbal treatment helped my gastrointestinal condition. She also brought attention to mental factors that could have been contributing to the issue, and in retrospect I think she was spot on.", "author": "Paul Roy", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110247392516324294253/reviews"}, {"date": "2024-10-21T20:46:57.560366Z", "text": "Been seeing dr. ma for a few months now to shrink my fibroids Haven''t measured again to confirm yet but I think it is working. She treated my bronchitis too. She will make you drink some nasty herbs but they work!", "author": "Jaime Scott", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101810255285617993014/reviews"}, {"date": "2023-10-30T02:52:50.386725Z", "text": "My father has a lower back problem for years, Dr. Ma did the acupuncture for his back and special light heating as well, it is so amazing,  pain is gone. My daughter has back pain because she was in a gymnastic team, she is afraid of needles. Dr. Ma did acupuncture on her, she did not feel the pain, she was falling sleep on her acupuncture bed, she said there is NO pain at all, it is so comfortable. Dr. Ma even deliver the medicine to our door, we never see such responsible under kind heart doctor before.", "author": "Lily Ko", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101825328614908361650/reviews"}, {"date": "2020-12-19T19:12:09.778202Z", "text": "Dr. Ma is a trusted Chinese medical naturopath of many years with me.  There are not many real naturopath doctors who can really cure illness out there, but she is exceptional.  She has not only cured my chronic respiratory issue, but has taught me a great deal about how to take care the human body and immunity.  Her knowledge and experience far exceeds the level of care from your normal western primary care, who is really just interested to charge you and give you prescriptions rather than really cure you, so you don''t need anymore drugs!", "author": "Pearl Li", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117592517251602898779/reviews"}, {"date": "2021-05-14T10:37:36.523320Z", "text": "Dr Ma had helped me and my family tremendously the past 6 years or so. She literally changed our lives by pin pointing exact health issues and providing effective treatments as well as empowering us to make healthy choices for our bodies.", "author": "Ron Au", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111597472473911085084/reviews"}], "website": "https://www.seattlechinesemedicalcenter.com", "location": {"latitude": 47.621740800000005, "longitude": -122.3564478}, "services": ["Acupuncture", "Infertility Treatment", "Internal Medicine"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Experienced Provider", "detail": "Dr. Ma holds credentials as both an M.D., O.M.D., and L.AC with decades of teaching and clinical experience.", "category": "care"}, {"title": "Specializing in Women''s Health", "detail": "The clinic is named ''Woman''s Health Care Center'' and Dr. Ma has served as a GYN professor at Bastyr University.", "category": "care"}, {"title": "Academic Background", "detail": "Dr. Ma is a professor and clinical instructor at Northwest Institute of Acupuncture & Oriental Medicine.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.seattlechinesemedicalcenter.com/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Seattle, WA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | infertility treatment | internal medicine | women''s health | dr. xin-dong (rosey) ma | m.d., o.m.d., l.ac", "google_types": ["medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 19, "team_members": [{"name": "Dr. Xin-dong (Rosey) Ma", "role": "M.D., O.M.D., L.AC", "bio_snippet": "Professor/Clinical Instructor of Northwest Institute of Acupuncture & Oriental Medicine, GYN Professor of Bastyr University, Researcher at Asian Women Cervical Cancer Prevention Center, and Director of Seattle Chinese Medical Center.", "languages_spoken": ["English", "Chinese"]}], "language_note": "The clinic addresses the needs of Asian and immigrant populations, with Dr. Ma''s background as a researcher at the Asian Women Cervical Cancer Prevention Center showing a commitment to culturally responsive care. The clinic''s name and location in Seattle''s Asian community also suggest a focus on serving Asian-American patients.", "open_saturday": true, "quality_score": 93, "working_hours": {"friday": "9:00 AM – 6:00 PM", "monday": "9:00 AM – 6:00 PM", "sunday": "Closed", "tuesday": "9:00 AM – 6:00 PM", "saturday": "9:00 AM – 4:00 PM", "thursday": "9:00 AM – 6:00 PM", "wednesday": "9:00 AM – 6:00 PM"}, "gallery_images": ["http://www.seattlechinesemedicalcenter.com/p1.jpg"], "review_profile": {"rating": 4.6, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 5, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight Dr. Ma''s exceptional knowledge and effective treatments for various conditions."}, {"theme": "Treatment Outcomes", "mentions": 5, "sentiment": "Positive", "summary_quote": "Patients report significant improvements in conditions like gastrointestinal issues, fibroids, back pain, and respiratory problems."}, {"theme": "Holistic Approach", "mentions": 3, "sentiment": "Positive", "summary_quote": "Reviewers appreciate Dr. Ma''s attention to mental factors and teaching patients about body care and immunity."}, {"theme": "Patient Care", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients describe Dr. Ma as attentive, caring, and going above expectations with home deliveries of medicine."}, {"theme": "Communication", "mentions": 2, "sentiment": "Positive", "summary_quote": "Reviewers mention Dr. Ma''s ability to explain health issues clearly and empower patients with knowledge."}], "summary": "Patients consistently praise Dr. Ma for her attentive care, effective treatments, and holistic approach to health, with many noting significant improvements in their conditions.", "review_count": 19, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2024-10-20T17:57:16.357081Z", "text": "I had a great experience with Dr. Ma. She is very attentive, caring, and her acupuncture and herbal treatment helped my gastrointestinal condition. She also brought attention to mental factors that could have been contributing to the issue, and in retrospect I think she was spot on.", "author": "Paul Roy", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110247392516324294253/reviews"}, {"date": "2024-10-21T20:46:57.560366Z", "text": "Been seeing dr. ma for a few months now to shrink my fibroids Haven''t measured again to confirm yet but I think it is working. She treated my bronchitis too. She will make you drink some nasty herbs but they work!", "author": "Jaime Scott", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101810255285617993014/reviews"}, {"date": "2023-10-30T02:52:50.386725Z", "text": "My father has a lower back problem for years, Dr. Ma did the acupuncture for his back and special light heating as well, it is so amazing,  pain is gone. My daughter has back pain because she was in a gymnastic team, she is afraid of needles. Dr. Ma did acupuncture on her, she did not feel the pain, she was falling sleep on her acupuncture bed, she said there is NO pain at all, it is so comfortable. Dr. Ma even deliver the medicine to our door, we never see such responsible under kind heart doctor before.", "author": "Lily Ko", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101825328614908361650/reviews"}, {"date": "2020-12-19T19:12:09.778202Z", "text": "Dr. Ma is a trusted Chinese medical naturopath of many years with me.  There are not many real naturopath doctors who can really cure illness out there, but she is exceptional.  She has not only cured my chronic respiratory issue, but has taught me a great deal about how to take care the human body and immunity.  Her knowledge and experience far exceeds the level of care from your normal western primary care, who is really just interested to charge you and give you prescriptions rather than really cure you, so you don''t need anymore drugs!", "author": "Pearl Li", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117592517251602898779/reviews"}, {"date": "2021-05-14T10:37:36.523320Z", "text": "Dr Ma had helped me and my family tremendously the past 6 years or so. She literally changed our lives by pin pointing exact health issues and providing effective treatments as well as empowering us to make healthy choices for our bodies.", "author": "Ron Au", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111597472473911085084/reviews"}]}, "review_summary": "Patients consistently praise Dr. Ma for her attentive care, effective treatments, and holistic approach to health, with many noting significant improvements in their conditions.", "about_highlight": "Seattle Chinese Medical Center, under the direction of Dr. Xindong (Rosey) Ma, is a clinic specializing in women''s health care, acupuncture, infertility treatment, and internal medicine. Dr. Ma brings extensive academic and clinical experience as a professor and clinical instructor at the Northwest Institute of Acupuncture & Oriental Medicine, a GYN professor at Bastyr University, and a researcher at the Asian Women Cervical Cancer Prevention Center. The clinic focuses on integrating traditional Chinese medicine with modern healthcare needs in a culturally supportive environment.", "google_maps_url": "https://maps.google.com/?cid=13034502712726993552&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJ-dGkjkQVkFQRkDr1Tyjb47Q", "quality_missing": ["insurance", "appointment_url"], "search_keywords": ["acupuncture & tcm", "acupuncture", "chinese medicine", "tcm", "herbal medicine", "cupping", "pain relief", "châm cứu", "đông y", "y học cổ truyền", "한의원", "침술", "한약", "中医", "针灸", "中药", "english", "chinese", "mandarin", "cantonese", "中文", "普通话", "国语", "粤语", "广东话", "华人", "infertility treatment", "internal medicine", "women''s health", "dr. xin-dong (rosey) ma", "m.d., o.m.d., l.ac"], "cultural_context": "The clinic addresses the needs of Asian and immigrant populations, with Dr. Ma''s background as a researcher at the Asian Women Cervical Cancer Prevention Center showing a commitment to culturally responsive care. The clinic''s name and location in Seattle''s Asian community also suggest a focus on serving Asian-American patients.", "services_offered": [{"name": "Acupuncture", "category": "Acupuncture", "description": "Traditional Chinese acupuncture treatments.", "is_featured": false, "patient_fit": null}, {"name": "Infertility Treatment", "category": "Women''s Health", "description": "Specialized care for infertility using integrated approaches.", "is_featured": false, "patient_fit": "Women experiencing fertility challenges"}, {"name": "Internal Medicine", "category": "Internal Medicine", "description": "General internal medicine consultations and treatments.", "is_featured": false, "patient_fit": null}], "short_description": "Seattle Chinese Medical Center offers acupuncture, infertility treatment, and internal medicine with a focus on women''s health, led by Dr. Xindong (Rosey) Ma.", "google_website_url": "https://www.seattlechinesemedicalcenter.com/", "google_primary_type": "Medical Clinic", "provider_credentials": {"education": [], "providers": ["Dr. Xin-dong (Rosey) Ma"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "326 Queen Anne Ave N #101, Seattle, WA 98109, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/107499121489781511309", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWofWSHoJBGuT92rr6WEkTW2Mk3g6AWzGjkXYmkKGrU4BXnzKb2-A=s100-p-k-no-mo", "displayName": "Wenvi Hidayat"}]]}'::jsonb, '2026-06-26T11:37:18.478191+00:00', 'seattle-chinese-medical-center', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('96987f8d-97ef-481b-b1e2-8ca1e1a0f820', NULL, 'Chamblee Family Medical Clinic', 'Chamblee Family Medical Clinic is a multilingual medical clinic located in the Orient Center in Chamblee, GA. The clinic offers primary care services with same-day appointments and walk-in availability. They accept new patients and have a patient-first approach in a welcoming environment. The staff speaks English, Vietnamese, and Spanish, reflecting the diverse community they serve.', '4897 Buford Hwy NE #167, Chamblee, GA 30341', 'Chamblee', 'GA', '30341', '770-872-8141', ARRAY['English', 'Spanish', 'Vietnamese']::text[], 'Family Medicine', FALSE, '{"fax": "770-872-8142", "email": "admin@chambleefmc.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chamblee-family-medical-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chamblee-family-medical-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chamblee-family-medical-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chamblee-family-medical-clinic-google-5.webp"], "rating": 4.9, "reviews": [{"date": "2026-03-05T22:46:04.074017133Z", "text": "I recently lost my health insurance and was searching for an affordable doctor where I could start new care. My girlfriend recommended a doctor named Vincent, saying he was really good, so I decided to schedule a consultation.\n\nAfter meeting with him today, I’m honestly very excited about continuing care here. Dr. Vincent took his time, asked a lot of questions, and made sure he really understood all of my concerns. I never felt rushed, which is something I really appreciated.\n\nIt also seems like he runs a very well-organized practice, and the people at the front desk were extremely friendly and welcoming.\n\nOverall, I feel like I found a great place for my healthcare going forward, and I highly recommend him to anyone looking for a doctor who actually listens and takes the time to care about his patients.", "author": "Javier", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102892078622589565351/reviews"}, {"date": "2026-03-02T16:15:18.306801935Z", "text": "Lovely staff! Very clean, professional and friendly environment. Dr. Nguyen makes you feel welcomed and genuinely shows care for his patients. Their phlebotomist is amazing, the needle basically nonexistent. Definitely recommend anyone coming in, prices are also great compared to other places! 🙌🏼", "author": "Ceyla", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107346880088716416247/reviews"}, {"date": "2025-12-06T16:03:52.011920373Z", "text": "since my first visit everyone was super kind and welcoming. The doctors answers all questions and listens to my concerns. The receptionist are also super kind. I will definitely make this my go to place. Thank you!", "author": "Yami Jarquin", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112341777671815728962/reviews"}, {"date": "2025-12-18T23:19:23.597336051Z", "text": "This was my first time coming to this clinic, I love it and will be coming back the staffs are amazing and it was a fast process as well. Especially Jaquelin she answered all my  questions, is very helpful.", "author": "Maria Meraz", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117462512986050275160/reviews"}, {"date": "2026-05-01T15:30:11.425764348Z", "text": "Amazin