INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('0317635a-7e9f-4bde-bf35-40fd9b5850a7', NULL, 'HCA Houston Healthcare Medical Center', 'HCA Houston Healthcare Medical Center, a 372-bed acute care facility located in Houston''s Museum District, has served the community for over 45 years. Accredited by The Joint Commission, this boutique surgical hospital emphasizes high-quality heart care and heart surgery while offering a range of related services including emergency care, imaging, oncology, orthopedic care, and bariatric surgery. Our multidisciplinary teams partner with you to create personalized care plans, so that you feel confident and comfortable with your treatment. We are part of HCA Houston Healthcare, a family of hospitals serving over one million patients yearly at 13 hospitals in the greater Houston area, providing more resources, solutions, and possibilities for everyone who receives care at our facilities.', '1313 Hermann Dr, Houston, TX 77004', 'Houston', 'TX', '77004', '713-527-5000', ARRAY['English']::text[], 'Hospital', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-medical-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-medical-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-medical-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-medical-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/hca-houston-healthcare-medical-center-google-5.webp", "https://www.hcadam.com/api/public/content/5294f4dc8ce945e4a65349b1181e7684?v=c572fb81", "https://www.hcadam.com/api/public/content/199c64e7fdf34275901a146f60b25eee?v=0dd81f0e", "https://www.hcadam.com/api/public/content/21d46f9a4ce44ec58634834eed67e9e9?v=bbab5341", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2Fhca-banner-crop-01cca805f6f749e29cb27dbdfdd11428%3Fv%3Dd60fd24c&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/static/media/mho-logo-stacked.cc794e44.svg", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2Fweb-p-c64329891f0b44bea6c55c6249103bf8%3Fv%3Dfe7d571d&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2F352a1b7f3fff4441a2e0d02f0c912428%3Fv%3Dba6945dd&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2F3d331f5673014ca7b944b65f6f760590%3Fv%3Dc60d10d0&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2Fc5ece1c7c97a4bf991fdf2f2d0dc072e%3Fv%3D8a2d8873&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2F22fc221c85194d0d841d8ebe8e63ae1c%3Fv%3D32509bc2&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2Fedb53e4cfc8b4a318efb2e92e7da0d3d%3Fv%3Df2553744&w=3840&q=75", "https://www.hcahoustonhealthcare.com/_next/image?url=https%3A%2F%2Fwww.hcadam.com%2Fapi%2Fpublic%2Fcontent%2Fb548edfcd8b148a3a5958788184f1e50%3Fv%3Dadfac3e0&w=3840&q=75"], "rating": 4.2, "pricing": [{"name": "Patient Payment Estimator", "notes": "Get estimated pricing information on top services via the Patient Payment Estimator tool.", "price": null, "category": "estimate", "price_range": null}, {"name": "Texas Pricing Transparency", "notes": "Refer to the CMS required file of standard charges as part of pricing transparency.", "price": null, "category": "transparency", "price_range": null}], "reviews": [{"date": "2026-05-23T14:00:47.321889999Z", "text": "Hands down the best Team and Place  They treat you Like you matter !! Take your health Seriously and do Ct scans and Everything staff All is very nice Shout out to the patient Coordinator in the ER shes new started a Month ago She Was The BEST . The nurse that helped me ANC and The doctor Ryan K and Ct scan guy . Every Staff member was AMAZINGGG !", "author": "Dion Dominguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116366408680130756450/reviews"}, {"date": "2026-06-11T17:29:31.084209630Z", "text": "I was in for a ventral hernia procedure. Everything seemed to go smoothly. I especially love that the care team stayed with me until certain bodily functions could be verified after the procedure. I very much appreciate their dedication to their jobs and to me.", "author": "Stephen Mitchell", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108592434682669901639/reviews"}, {"date": "2026-05-05T04:47:22.187381398Z", "text": "I don’t usually post things like this, but I can’t stay quiet after what we are currently experiencing.\n\nMy dad was transferred from a sister hospital location with pneumonia and gallstones after already having labs and imaging completed — just to arrive here and have everything repeated with no clear communication as to why. Not once did anyone come in to thoroughly explain his ultrasound results or what the actual plan of care was.\n\nInstead, we were met with dismissive attitudes and a nurse who was incredibly rude, brushing off concerns and saying the doctor was considering discharging him — completely contradicting what we were told at the previous hospital, where admission was strongly recommended.\n\nOn top of that, the condition of the facility was unacceptable. Trash left on the floor, lack of cleanliness, and an overall environment that did not feel safe or cared for — especially for someone already sick and vulnerable.\n\nOh and don’t bother pressing the nurse button because it either does not work or they completely ignore it. What if it were an actual emergency?\n\nAlso, no bandage wrap??? It took 10 minutes to find bandage wrap so he can take out my father’s IVs. I literally am baffled.\n\nThis is not okay. Patients deserve clear communication, consistency in care, compassion, and a clean environment — bare minimum.\n\nDo better.", "author": "Savannah Stephatos", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/116292735732135088455/reviews"}, {"date": "2026-02-20T01:04:40.454606686Z", "text": "My husband had open heart surgery with a triple bypass. All of the doctors, nurses, and entire staff worked together seamlessly in a very professional, compassionate manner. I feel like they are extended family and they saved his life. If I could give them a rating higher than five stars I would. God bless all of them and thank you for all that you did for us and the others that you take care of every single day and night.", "author": "avidreader", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109822251131892553776/reviews"}, {"date": "2026-01-19T18:24:30.797774894Z", "text": "I had double jaw surgery here last week and could not be more satisfied with my care. Everything from admission to discharge went smoothly and the nursing staff was great. Erika especially was phenomenal at caring for me and went above and beyond when I was switched into a different room that was overly warm and was not helping the healing process for me. I was extremely uncomfortable and she would not settle until maintenance has resolved the issue and reset the room temperature. 10/10 service.", "author": "Kelsey Smith", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115962834600584414973/reviews"}], "website": "https://www.hcahoustonhealthcare.com/locations/medical-center", "location": {"latitude": 29.722720000000002, "longitude": -95.3875427}, "services": ["Cardiology / Heart Care", "Emergency Care", "Imaging Services", "Oncology", "Orthopedic Care", "Surgery", "Weight Loss Surgery (Bariatric)", "Gastroenterology", "Vascular Surgery"], "insurance": {"notes": "Insurance information is available on the website. Patient financial resources including pricing estimates are offered.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Proudly serving the Museum District", "detail": "Located in Houston''s world-class Museum District, committed to offering advanced healthcare services with a compassionate, patient-focused approach.", "category": "convenience"}, {"title": "More than 50 years of service", "detail": "372-bed acute care facility serving the Houston community for over 45 years.", "category": "care"}, {"title": "Accredited by The Joint Commission", "detail": "Recognized as an accredited Metabolic and Bariatric Surgery Center and consistently recognized for outstanding performance.", "category": "care"}, {"title": "Cardiac specialty", "detail": "Emphasis on heart care and heart surgery with a cardiovascular network.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.hcahoustonhealthcare.com/locations/medical-center?utm_campaign=corp_listings_mgmt&utm_source=google&utm_medium=business_listing", "appointment": {"booking_note": "Online registration available for services such as surgical procedures, mammograms and diagnostic tests and treatments.", "appointment_url": "https://www.hcahoustonhealthcare.com/patient-resources/register-online", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": true, "scout_query": "hospitals that speak Korean in Houston, Texas", "search_text": "hospital | english | cardiology / heart care | emergency care | imaging services | oncology | orthopedic care | surgery | weight loss surgery (bariatric) | gastroenterology | vascular surgery | cardiology | emergency | imaging | orthopedic | weight loss", "google_types": ["medical_center", "hospital", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 1609, "open_saturday": true, "quality_score": 87, "working_hours": {"friday": "Open 24 hours", "monday": "Open 24 hours", "sunday": "Open 24 hours", "tuesday": "Open 24 hours", "saturday": "Open 24 hours", "thursday": "Open 24 hours", "wednesday": "Open 24 hours"}, "gallery_images": ["https://www.hcadam.com/api/public/content/352a1b7f3fff4441a2e0d02f0c912428?v=ba6945dd", "https://www.hcadam.com/api/public/content/hca-banner-crop-01cca805f6f749e29cb27dbdfdd11428?v=d60fd24c", "https://www.hcadam.com/api/public/content/web-p-c64329891f0b44bea6c55c6249103bf8?v=fe7d571d"], "review_profile": {"rating": 4.2, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 4, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight the friendly, dedicated, and compassionate staff."}, {"theme": "Treatment Outcomes", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients express satisfaction with successful procedures and attentive post-operative care."}, {"theme": "Communication", "mentions": 1, "sentiment": "Negative", "summary_quote": "One reviewer noted dismissive attitudes and unclear explanations regarding care plans."}, {"theme": "Facility Environment", "mentions": 1, "sentiment": "Negative", "summary_quote": "A patient reported unclean conditions and an overall poorly maintained environment."}, {"theme": "Clinical Expertise", "mentions": 2, "sentiment": "Positive", "summary_quote": "Reviewers commend the seamless teamwork and life-saving expertise of the medical staff."}], "summary": "Most patients report highly positive experiences with the care team, praising their professionalism and compassion, though some mention issues with communication and facility conditions.", "review_count": 1609, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-05-23T14:00:47.321889999Z", "text": "Hands down the best Team and Place  They treat you Like you matter !! Take your health Seriously and do Ct scans and Everything staff All is very nice Shout out to the patient Coordinator in the ER shes new started a Month ago She Was The BEST . The nurse that helped me ANC and The doctor Ryan K and Ct scan guy . Every Staff member was AMAZINGGG !", "author": "Dion Dominguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116366408680130756450/reviews"}, {"date": "2026-06-11T17:29:31.084209630Z", "text": "I was in for a ventral hernia procedure. Everything seemed to go smoothly. I especially love that the care team stayed with me until certain bodily functions could be verified after the procedure. I very much appreciate their dedication to their jobs and to me.", "author": "Stephen Mitchell", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108592434682669901639/reviews"}, {"date": "2026-05-05T04:47:22.187381398Z", "text": "I don’t usually post things like this, but I can’t stay quiet after what we are currently experiencing.\n\nMy dad was transferred from a sister hospital location with pneumonia and gallstones after already having labs and imaging completed — just to arrive here and have everything repeated with no clear communication as to why. Not once did anyone come in to thoroughly explain his ultrasound results or what the actual plan of care was.\n\nInstead, we were met with dismissive attitudes and a nurse who was incredibly rude, brushing off concerns and saying the doctor was considering discharging him — completely contradicting what we were told at the previous hospital, where admission was strongly recommended.\n\nOn top of that, the condition of the facility was unacceptable. Trash left on the floor, lack of cleanliness, and an overall environment that did not feel safe or cared for — especially for someone already sick and vulnerable.\n\nOh and don’t bother pressing the nurse button because it either does not work or they completely ignore it. What if it were an actual emergency?\n\nAlso, no bandage wrap??? It took 10 minutes to find bandage wrap so he can take out my father’s IVs. I literally am baffled.\n\nThis is not okay. Patients deserve clear communication, consistency in care, compassion, and a clean environment — bare minimum.\n\nDo better.", "author": "Savannah Stephatos", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/116292735732135088455/reviews"}, {"date": "2026-02-20T01:04:40.454606686Z", "text": "My husband had open heart surgery with a triple bypass. All of the doctors, nurses, and entire staff worked together seamlessly in a very professional, compassionate manner. I feel like they are extended family and they saved his life. If I could give them a rating higher than five stars I would. God bless all of them and thank you for all that you did for us and the others that you take care of every single day and night.", "author": "avidreader", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109822251131892553776/reviews"}, {"date": "2026-01-19T18:24:30.797774894Z", "text": "I had double jaw surgery here last week and could not be more satisfied with my care. Everything from admission to discharge went smoothly and the nursing staff was great. Erika especially was phenomenal at caring for me and went above and beyond when I w