INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('8a319b8c-524b-4e6f-81de-a6e19d3db95a', NULL, 'River Oaks Hospital & Clinics', 'As the largest facility in the Advanced Diagnostics network, River Oaks Hospital & Clinics delivers complete, physician-led care. Patients have access to a 24-hour ER, advanced imaging (MRI, CT, ultrasound), surgical suites, pharmacy, and multispecialty clinics—all under one roof with private rooms and valet parking. Private inpatient suites, complimentary valet parking, and concierge support ensure a comfortable experience. Care teams are fully connected: your diagnosis, treatment, and follow-up happen with the same physicians, reducing delays and repeat visits.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('3fda2ec7-169c-440c-952c-ec5b9108fe03', NULL, 'Fairfax Clinic', 'Fairfax Clinic, proudly part of Privia Health, is a primary care practice located in Falls Church and Tysons, Virginia, dedicated to providing high-quality, personalized medical care for patients of all ages. The clinic offers a range of services including in-person and virtual visits, same-day appointments, and online scheduling through an easy-to-use patient portal. With a focus on coordinated, patient-centered care, the team at Fairfax Clinic works with leading doctors in the community to ensure comprehensive health and wellness support.', '8219 Leesburg Pike, Suite 201, Tysons, VA 22182', 'Tysons', 'VA', '22182', '(703) 532-1909', ARRAY['English', 'Vietnamese']::text[], 'Primary Care', TRUE, '{"fax": "(703) 532-5868", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/fairfax-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/fairfax-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/fairfax-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/fairfax-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/fairfax-clinic-google-5.webp"], "rating": 4.6, "reviews": [{"date": "2026-03-02T20:41:52.491318048Z", "text": "Dr Viet helped me lose weight.  My joint pains are much better.  The Tysons office is convenient for me.", "author": "Ana Alvarado", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101186676152749831261/reviews"}, {"date": "2026-03-02T20:35:07.879217031Z", "text": "I trust Dr Viet Nguyen with my family.  He helped my son with his mental health.  His new office in Tysons Corner is bright and beautiful.", "author": "NORA PARRA", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110695645847497723221/reviews"}, {"date": "2025-11-23T01:20:01.828141504Z", "text": "Caring, compassionate, and knowledgeable - Dr. Nguyen is the best!  The new office location in Tyson''s Corner is very nice and convenient.", "author": "Kat Rina", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115239061590781739336/reviews"}, {"date": "2024-05-09T18:35:37.986926Z", "text": "Dr. Nguyen has been my  primary care physician for over six years now. I can’t thank Dr. Nguyen and his assistant, Nora enough for their dedication, knowledge, compassion, care and kindness. I’m very grateful to them for keeping me in good health.  Dr. Nguyen has my total loyalty as a patient and will continue to do so.", "author": "Maria S", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112625928048570318759/reviews"}, {"date": "2017-12-21T22:29:19.425Z", "text": "Dr. Nguyen is by far the best doctor that I’ve been to. He is very friendly and extremely patient, and he listens to my concerns thoroughly. I truly feel that he cares about his patients. The staff and nurses are friendly, there are plenty of parking spots, and the online appointment is very convenient.", "author": "Eiji Goto", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101201504692601330513/reviews"}], "website": "http://fairfaxclinic.org/", "location": {"latitude": 38.9164204, "longitude": -77.2308827}, "services": ["Primary Care", "Virtual Care", "Same-Day Appointments"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Convenient Locations", "detail": "Two offices serving the Falls Church and Tysons Corner areas in Virginia.", "category": "convenience"}, {"title": "Same Day Appointments", "detail": "Same day appointments are available alongside online visits.", "category": "access"}, {"title": "Online Waiting Room", "detail": "Patients can join an online waiting room for virtual visits.", "category": "technology"}, {"title": "Proudly Part of Privia Health", "detail": "Connected to a large network of high-quality healthcare providers and 50+ specialties.", "category": "care"}, {"title": "Patient Portal & Mobile App", "detail": "Stay connected to your care team with the myPrivia mobile app and patient portal.", "category": "technology"}, {"title": "24/7 Virtual Care", "detail": "Access to on-demand, 24/7 virtual clinic services.", "category": "access"}], "price_tier": "$$", "source_url": "http://fairfaxclinic.org/", "appointment": {"booking_note": null, "appointment_url": "https://providers.priviahealth.com/search?affiliation_search=true&sort=relevance%2Cnetworks%2Cavailability_density_best&filter=network_affiliations.name%3AFairfax%20Clinic", "new_patient_note": null, "phone_booking_available": null, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese speaking medical clinic in Washington, D.C.", "search_text": "primary care | family doctor | general practitioner | annual physical | checkup | bác sĩ gia đình | khám tổng quát | nội khoa | 내과 | 가정의학과 | 家庭医生 | 全科医生 | 内科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | virtual care | same-day appointments | telehealth", "google_types": ["medical_clinic", "spa", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 33, "open_saturday": false, "quality_score": 9