INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('1695192d-0973-44f4-9991-e287e18576cf', NULL, 'La Clinica del Pueblo', 'La Clínica del Pueblo is a community health center serving Washington, D.C., and Maryland with a mission to provide high-quality, culturally responsive healthcare. Founded by and for the Latino immigrant community, the clinic offers a comprehensive range of services including primary care, behavioral health, substance use treatment, and LGBTQ health. With a patient-centered medical home model, they emphasize health equity, community action, and access to care for all, regardless of insurance status or ability to pay.', '2831 15th St NW, Washington, DC 20009', 'Washington', 'DC', '20009', '(202) 462-4788', ARRAY['English', 'Spanish', 'Vietnamese']::text[], 'Community Health Center', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/la-clinica-del-pueblo-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/la-clinica-del-pueblo-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/la-clinica-del-pueblo-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/la-clinica-del-pueblo-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/la-clinica-del-pueblo-google-5.webp"], "rating": 3.4, "pricing": [{"name": "Sliding Fee Scale", "notes": "Available for uninsured and underinsured patients based on family size and income.", "price": "0", "category": "self-pay", "price_range": "Varies by income"}], "reviews": [{"date": "2026-06-03T16:35:52.536412009Z", "text": "I am writing to express my frustration regarding the difficulty I have been experiencing when trying to contact the clinic and schedule or follow up on appointments.\n\nFirst, I am unable to use the patient portal because it does not function properly. Every time I log in and try to check information, the system logs me out, making it impossible to access my account or communicate through the portal.\n\nIn addition, I have spent hours on the phone both yesterday and today trying to reach someone. The automated system repeatedly informed me that there was only one caller ahead of me, but despite waiting for a long time, no one answered my call.\n\nAt this point, I would like to know what the best way is to reach the clinic. I need assistance, but I have been unable to get through by phone or through the patient portal.\n\nI would appreciate a response with guidance on how I can successfully contact your office and receive assistance.", "author": "Sanam delawar", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/106329188529765056217/reviews"}, {"date": "2025-12-11T20:56:15.466273736Z", "text": "There’s this obnoxious big girl up front as receptionist with a bunch of tattoos on her arm and pinkish hair. So loud and rude announcing how much we owe to the clinic and had to embarrass us like that when I came here for an event. Please be respectful and no so loud and obnoxious. Aside from her love the therapist and doctors.", "author": "Liz Siliezar", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/112326095886116230481/reviews"}, {"date": "2026-02-17T16:57:07.906349479Z", "text": "“I’ve been coming to this clinic for a while now, and every visit has been consistently positive. The team is knowledgeable, caring, and efficient. The atmosphere is welcoming and well-managed. Jazmin at the front desk deserves special recognition — she is attentive, polite, and always goes above and beyond to make sure everything runs smoothly. Truly excellent service.”", "author": "Alfonso Martinez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113026467582703154193/reviews"}, {"date": "2026-02-17T19:54:48.396811578Z", "text": "Good physicians, but as the reviews mention, the front desk responsiveness leaves a lot to be desired", "author": "Onbrand", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/114275455912684284948/reviews"}, {"date": "2026-05-13T11:56:00.899682324Z", "text": "The best community clinic. Newley remodule reception and friendly staff.", "author": "M B", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113218410519541585665/reviews"}], "website": "http://www.lcdp.org", "location": {"latitude": 38.9258957, "longitude": -77.0351039}, "services": ["Primary Care", "Substance Use Treatment", "Behavioral Health", "Domestic Violence Prevention", "LGBTQ Health", "Mental Health in Schools", "Community Resources"], "insurance": {"notes": "Accepts most insurances. Offers a sliding fee scale for uninsured/underinsured patients.", "accepts_medicaid": true, "accepts_medicare": null, "accepted_networks": ["Medicaid"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Sliding Fee Scale", "detail": "Offers a sliding fee scale based on income and family size for uninsured or underinsured patients.", "category": "insurance"}, {"title": "Accepting New Patients", "detail": "Currently accepting new patients in Maryland and Washington, D.C.", "category": "access"}, {"title": "Culturally Responsive Care", "detail": "Founded by and for the Latino community, providing care in Spanish and English with a deep understanding of immigrant health needs.", "category": "culture"}, {"title": "Patient-Centered Medical Home", "detail": "NCQA-recognized Patient-Centered Medical Home delivering coordinated, comprehensive care.", "category": "care"}, {"title": "Expanded Services for Children", "detail": "Now offering expanded primary care and preventive services for children.", "category": "care"}, {"title": "Community Resources Beyond the Exam Room", "detail": "Resources for food, housing, and employment available through SaludEs.", "category": "access"}], "price_tier": "$", "source_url": "http://www.lcdp.org/", "appointment": {"booking_note": "Call or use the online form to request an appointment.", "appointment_url": "https://www.lcdp.org/patients/request-an-appointment", "new_patient_note": "Accepting new patients in Maryland and Washington, D.C.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese speaking medical clinic in Washington, D.C.", "search_text": "community health center | community health | fqhc | sliding scale | medicaid | medicare | low cost | trung tâm y tế cộng đồng | 커뮤니티 헬스 | 社区医疗中心 | english | spanish | vietnamese | tiếng việt | người việt | bác sĩ việt | primary care | substance use treatment | behavioral health | domestic violence prevention | lgbtq health | mental health in schools | community resources | preventive", "google_types": ["medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 127, "language_note": "Founded by and for the Latino immigrant community, La Clínica del Pueblo is deeply rooted in providing linguistically and culturally competent care. All services are available in Spanish and English, and the clinic actively advocates for immigrant health rights and access to care.", "open_saturday": false, "quality_score": 97, "working_hours": {"friday": "8:00 AM – 4:30 PM", "monday": "8:00 AM – 6:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 6:00 PM", "saturday": "Closed", "thursday": "8:00 AM – 6:00 PM", "wednesday": "8:00 AM – 6:00 PM"}, "gallery_images": ["https://www.lcdp.org/imgs/home/2026-Signage-21-Socials-3.png"], "review_profile": {"rating": 3.4, "source": "google", "themes": [{"theme": "Communication", "mentions": 2, "sentiment": "Negative", "summary_quote": "Patients report difficulties with the patient portal and phone system, making it hard to schedule or follow up on appointments."}, {"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Mixed", "summary_quote": "While some staff members are praised for being attentive and polite, others are criticized for being loud and unprofessional."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients appreciate the welcoming atmosphere and newly remodeled reception area."}, {"theme": "Clinical Expertise", "mentions": 2, "sentiment": "Positive", "summary_quote": "Reviewers highlight the knowledgeable and caring physicians, with some calling it the best community clinic."}, {"theme": "Front Desk Responsiveness", "mentions": 2, "sentiment": "Negative", "summary_quote": "Several reviews mention dissatisfaction with the front desk''s responsiveness and service."}], "summary": "Reviews for La Clinica del Pueblo are mixed, with some patients praising the knowledgeable and caring staff, while others express frustration with communication and front desk responsiveness.", "review_count": 127, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-06-03T16:35:52.536412009Z", "text": "I am writing to express my frustration regarding the difficulty I have been experiencing when trying to contact the clinic and schedule or follow up on appointments.\n\nFirst, I am unable to use the patient portal because it does not function properly. Every time I log in and try to check information, the system logs me out, making it impossible to access my account or communicate through the portal.\n\nIn addition, I have spent hours on the phone both yesterday and today trying to reach someone. The automated system repeatedly informed me that there was only one caller ahead of me, but despite waiting for a long time, no one answered my call.\n\nAt this point, I would like to know what the best way is to reach the clinic. I need assistance, but I have been unable to get through by phone or through the patient portal.\n\nI would appreciate a response with guidance on how I can successfully contact your office and receive assistance.", "author": "Sanam delawar", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/106329188529765056217/reviews"}, {"date": "2025-12-11T20:56:15.466273736Z", "text": "There’s this obnoxious big girl up front as receptionist with a bunch of tattoos on her arm and pinkish hair. So loud and rude announcing how much we owe to the clinic and had to embarrass us like that when I came here for an event. Please be respectful and no so loud and obnoxious. Aside from her love the therapist and doctors.", "author": "Liz Siliezar", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/112326095886116230481/reviews"}, {"date": "2026-02-17T16:57:07.906349479Z", "text": "“I’ve been coming to this clinic for a while now, and every visit has been consistently positive. The team is knowledgeable, caring, and efficient. The atmosphere is welcoming and well-managed. Jazmin at the front desk deserves special recognition — she is attentive, polite, and always goes above and beyond to make sure everything runs smoothly. Truly excellent service.”", "author": "Alfonso Martinez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113026467582703154193/reviews"}, {"date": "2026-02-17T19:54:48.396811578Z", "text": "Good physicians, but as the reviews mention, the front desk responsiveness leaves a lot to be desired", "author": "Onbrand", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/114275455912684284948/reviews"}, {"date": "2026-05-13T11:56:00.899682324Z", "text": "The best community clinic. Newley remodule reception and friendly staff.", "author": "M B", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113218410519541585665/reviews"}]}, "review_summary": "Reviews for La Clinica del Pueblo are mixed, with some patients praising the knowledgeable and caring staff, while others express frustration with communication and front desk responsiveness.", "about_highlight": "La Clínica del Pueblo is a community health center serving Washington, D.C., and Maryland with a mission to provide high-quality, culturally responsive healthcare. Founded by and for the Latino immigrant community, the clinic offers a comprehensive range of services including primary care, behavioral health, substance use treatment, and LGBTQ health. With a patient-centered medical home model, they emphasize health equity, community action, and access to care for all, regardless of insurance status or ability to pay.", "appointment_url": "https://www.lcdp.org/patients/request-an-appointment", "google_maps_url": "https://maps.google.com/?cid=1203481074285856410&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJmwcOkd-3t4kRmsa2JqmfsxA", "quality_missing": ["team_members"], "search_keywords": ["community health center", "community health", "fqhc", "sliding scale", "medicaid", "medicare", "low cost", "trung tâm y tế cộng đồng", "커뮤니티 헬스", "社区医疗中心", "english", "spanish", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "primary care", "substance use treatment", "behavioral health", "domestic violence prevention", "lgbtq health", "mental health in schools", "community resources", "preventive"], "cultural_context": "Founded by and for the Latino immigrant community, La Clínica del Pueblo is deeply rooted in providing linguistically and culturally competent care. All services are available in Spanish and English, and the clinic actively advocates for immigrant health rights and access to care.", "services_offered": [{"name": "Primary Care", "category": "Primary Care", "description": "Comprehensive medical services for adults and children.", "is_featured": true, "patient_fit": "Adults and children in need of primary and preventive care."}, {"name": "Substance Use Treatment", "category": "Behavioral Health", "description": "Treatment programs for substance use disorders, including Volviendo a Vivir.", "is_featured": true, "patient_fit": "Individuals seeking recovery from substance use."}, {"name": "Behavioral Health", "category": "Behavioral Health", "description": "Mental health services including therapy and psychiatry.", "is_featured": true, "patient_fit": "Patients experiencing mental health challenges."}, {"name": "Domestic Violence Prevention", "category": "Preventive", "description": "Prevention and support services, including the Entre Amigas program.", "is_featured": true, "patient_fit": "Individuals affected by domestic violence."}, {"name": "LGBTQ Health", "category": "Primary Care", "description": "Affirming healthcare services for the LGBTQ community, including the Empoderate program.", "is_featured": true, "patient_fit": "LGBTQ+ individuals seeking inclusive care."}, {"name": "Mental Health in Schools", "category": "Behavioral Health", "description": "School-based mental health services through the Mi Refugio program.", "is_featured": true, "patient_fit": "Children and adolescents in school settings."}, {"name": "Community Resources", "category": "Community Health", "description": "Navigation and referral to resources for food, housing, and employment.", "is_featured": true, "patient_fit": "Community members needing social support."}], "short_description": "La Clínica del Pueblo provides culturally responsive, integrated healthcare for the Latino and immigrant communities in Washington, D.C., and Maryland.", "google_website_url": "http://www.lcdp.org/", "insurance_accepted": ["Medicaid"], "google_prim