INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('9993157f-2a8e-4d2c-9beb-032cc1ef0eac', NULL, 'One Medical Primary Care Clinic - Metro Center', 'Our Metro Center office offers exceptional primary care for adults of all ages, including seniors on Medicare. We focus on building real relationships with patients and using technology to simplify every aspect of getting care. And we’re not just here for when you’re sick or injured. We can also help you meet physical and mental health goals, manage chronic illnesses, and live a happier, healthier life. Plus, you can expect improved coordination of specialty care through our affiliation with MedStar Health. Think of us as your home for healthcare.', '1001 G Street NW, Suite 200 East, Washington, DC 20001', 'Washington', 'DC', '20001', '888-663-6331', ARRAY['English', 'Korean']::text[], 'Primary Care', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/one-medical-primary-care-clinic-metro-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/one-medical-primary-care-clinic-metro-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/one-medical-primary-care-clinic-metro-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/one-medical-primary-care-clinic-metro-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/one-medical-primary-care-clinic-metro-center-google-5.webp"], "rating": 4.3, "reviews": [{"date": "2026-02-04T21:14:06.134659573Z", "text": "Dr. Roth has made a real difference in my life. She is kind, attentive, and truly care about my health . I never felt dismissed or rushed, and every concern was taken seriously. It’s rare to find a doctor who combines expertise with genuine compassion. I’m very grateful to be under her care.", "author": "Celicia", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110165665568078562130/reviews"}, {"date": "2026-04-23T02:36:20.229644456Z", "text": "I recently was accidentally knocked over by another visitor to a museum.  Days after the incident, I began to experience growing pain and tenderness in my knee.  Thorough, professional and friendly, Dr. Padilla asked a series of questions during our video call that enabled her to assess the situation and lay out several options for my consideration concerning treatment.  I am so pleased with her performance and with the outcome of my treatment.", "author": "Dan Mozena", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/118420759176381924621/reviews"}, {"date": "2025-12-12T20:01:54.773353750Z", "text": "My appointment with One Medical was right on time. Waiting area is spacious with only one other patient. Lab work done on site - quick and easy. Love Dr. Buchwalter. She spends time with me, listens to my concerns and discusses options.", "author": "Carla Luggiero", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112948014098116582145/reviews"}, {"date": "2025-10-29T22:08:28.343678828Z", "text": "Visited this location for my annual physical yesterday and it was a great experience. I saw Rebecca Roth, NP, who had excellent bedside manner and was thorough. I never felt rushed throughout my visit. The receptionists were super nice as well! The office is modern and beautifully designed. It is also a super convenient location from the Metro Center station.\n\nThe best part is is I was done with my visit, flu shot, AND labs in under 30 minutes. This morning, I got my lab results and a message from my provider. Very quick turnaround time! They have always started on time here and are highly efficient. Thank you OM Metro Center!", "author": "Jay Lee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113758456343582125650/reviews"}, {"date": "2026-01-31T14:23:35.319838616Z", "text": "I have had a few disappointing visit with Dr. Garfinkel. Last time, during a video session, he seemed quite distracted by a broken nail or cuticle. He eventually picked a nail clipper to trim whatever it was, on the camera.\nLast session, again he failed active listening and he talked to me with an infantilizing tone like my symptoms were excuses.\nI definitely won’t see Dr. Garfinkel again. I may actually move away from One Medical.", "author": "Shideh", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/107603145567084564846/reviews"}], "website": "https://onemedical.com/locations/dc/1001g", "location": {"latitude": 38.8985079, "longitude": -77.02614059999999}, "services": ["Everyday and preventative care", "Physical exams (Live Well visits)", "Women''s health", "Mental health (Mindset by One Medical)", "Lab work"], "insurance": {"notes": "We take most commercial plans as well as Original Medicare with or without most Medicare supplement plans and select Medicare Advantage plans. Self-pay accepted for those without insurance or with out-of-network insurance.", "accepts_medicaid": null, "accepts_medicare": true, "accepted_networks": ["Most commercial plans", "Medicare"], "out_of_network_available": true, "accepts_private_insurance": true}, "highlights": [{"title": "Same/next-day appointments", "detail": "Book online, no membership needed. Appointments are billed to you or your insurance; copays or deductibles may apply.", "category": "convenience"}, {"title": "Affiliated with MedStar Health", "detail": "Improved coordination of specialty care through our affiliation with MedStar Health.", "category": "care"}, {"title": "Original Medicare accepted", "detail": "We accept Original Medicare with or without most Medicare supplement plans and select Medicare Advantage plans.", "category": "insurance"}], "price_tier": "$$", "source_url": "https://onemedical.com/locations/dc/1001g?y_source=1_MTA1Mzk0OTM4NS03MTUtbG9jYXRpb24ud2Vic2l0ZQ%3D%3D", "appointment": {"booking_note": "Book online, no membership needed. Appointments are billed to you or your insurance; copays or deductibles may apply.", "appointment_url": "https://health.amazon.com/onemedical/service-areas/dc?cta=omdc_office_gs_hl_dc_kst", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean speaking medical clinic in Washington, D.C.", "search_text": "primary care | family doctor | general practitioner | annual physical | checkup | bác sĩ gia đình | khám tổng quát | nội khoa | 내과 | 가정의학과 | 家庭医生 | 全科医生 | 内科 | english | korean | 한국어 | 한인 | 한국말 | everyday and preventative care | physical exams (live well visits) | women''s health | mental health (mindset by one medical) | lab work | preventive | mental health | diagnostic | most commercial plans | medicare | rachel barr | pa-c | jean-luc doan | carolyn cabrey | maren ketcham | md | rebecca roth | np | patricia evans | kelly thelin | alicia buchwalter | daniel garfinkel | deborah grorud", "google_types": ["medical_clinic", "medical_center", "hospital", "doctor", "health", "point_of_interest", "service", "establishment"], "open_weekend": false, "rating_count": 108, "team_members": [{"name": "Rachel Barr", "role": "PA-C", "bio_snippet": null, "languages_spoken": ["English"]}, {"name": "Jean-Luc Doan", "role": "PA-C", "bio_snippet": null, "languages_spoken": ["English"]}, {"name": "Carolyn Cabrey", "role": "PA-C", "bio_snippet": null, "languages_spoken": ["English"