INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('2ca66011-720a-4a67-a8a8-2739512ea486', NULL, 'Danh C Truong Medical Office', 'Danh C Truong Medical Office provides physician services in the San Diego community. Located at 4310 Euclid Ave, the practice offers a range of insurance options including acceptance of all PPO insurance. The office helps uninsured patients by providing cash discounts and discounts for those without insurance coverage.', '4310 Euclid Ave', 'San Diego', 'CA', '92115', '(619) 584-4048', ARRAY['English', 'Vietnamese']::text[], 'Primary Care', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/danh-c-truong-medical-office-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/danh-c-truong-medical-office-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/danh-c-truong-medical-office-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/danh-c-truong-medical-office-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/danh-c-truong-medical-office-google-5.webp"], "rating": 4.4, "pricing": [{"name": "Cash Discount", "notes": "Cash discount is available for patients paying out-of-pocket.", "price": null, "category": "discount", "price_range": null}, {"name": "Discount for Uninsured", "notes": "Discounted rates are available for patients without health insurance.", "price": null, "category": "discount", "price_range": null}], "reviews": [{"date": "2026-02-18T22:42:22.457019423Z", "text": "Dr. Danh C. Truong and his receptionist Evelyn have been amazing in caring for my mom. Dr. Truong is kind, thorough, and truly understands her needs with patience and expertise. Evelyn makes every visit easier with her helpful, friendly demeanor. Grateful for their compassionate care thank you!”", "author": "Rick Rodriguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115509017226299972762/reviews"}, {"date": "2025-03-07T15:30:07.441293Z", "text": "My family has been visiting him for years, he goes stray to the point , efficient and had diagnosed everyone in our family  correctly and had given the right medication or solution to solve any of our family members health concerns or situation.\n\nHis primary interventions had help us be in peace and not only guiding us to get better but to prevent getting sick again with general advices to do changes for healthy habits.\n\nBut you have to be patience and understanding for the long waiting list and procedure for an appointment, if that is the case this is the right place for you.", "author": "Nadia Babukas-Galvan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112453512936200345900/reviews"}, {"date": "2018-10-25T23:24:04.541870962Z", "text": "He is a great Doctor. He is really kind, and smart. Yes there is a long wait all the time because his prices are about the best in San Diego that I have seen, but you can pre pay for the visit, leave your phone# and they will call you 35-45 minutes before your turn is up. I really liked that they offer that. All the staff is super friendly. Thank You!", "author": "Carlita Terrones", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117445390909597009987/reviews"}, {"date": "2021-12-28T01:49:57.677602Z", "text": "I’ve been coming to Danh C Truong Medical Office since I was a young girl. The wait is very long. However, this doctor has healed my family and I more times than I can count. He gets straight the point and heals us back to health. May good fortune come his way. I highly recommend and will continue to return whenever I am ill.", "author": "Serena Espinosa", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114444260323184292387/reviews"}, {"date": "2023-04-13T09:27:45.216372Z", "text": "Here is the thing, firts time was awful 😣, you need to wait long time 3-5 hours, BUT as you come along you get to now there system, first you need to put your name down at the list between 1am- 4am and go back to sleep for about 2 1/2 be back at the office at 7am other way you will loose your place on line. And yo will l be able to get out there around 9am-10am which is fine for me but many people don’t want get up that early doctor take literally 2 minutes which each patient which if fine for me as long I got my Healt back who cares Thank you for your  hard work doctor you’re the best\nThe baker right here 👋…!!!", "author": "Ernesto Quijada", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108396833817436683893/reviews"}], "website": "https://weence.com/medical/doctors/san-diego/danh-c-truong-medical-office/", "location": {"latitude": 32.755119799999996, "longitude": -117.09261579999999}, "services": ["Physician Services"], "insurance": {"notes": "Accepts all PPO insurance. Cash discount and discount for uninsured patients are available.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": ["PPO Insurance"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Accepts All PPO Insurance", "detail": "The practice accepts all PPO insurance plans.", "category": "insurance"}, {"title": "Cash Discount", "detail": "Cash discount is available for patients paying out-of-pocket.", "category": "convenience"}, {"title": "Discount for Uninsured", "detail": "Discounted rates are offered for patients witho