INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('8fff9485-fbc6-483c-a405-cfcc91156525', NULL, 'JK Internal Medicine & Geriatrics, PC', 'JK Internal Medicine & Geriatrics, PC opened in 2005 with the goal of serving the community with the most up-to-date and high standard medicine in a comfortable, relaxing environment. The clinic provides care for all aspects of adult medicine, from treating chronic to acute illnesses, with a focus on preventative, diagnostic, and treatment services. The team includes multiple physicians and nurse practitioners, and the clinic is known for its bilingual Korean-speaking staff, making it a welcoming choice for Korean-American and immigrant patients in the Suwanee area.', '1325 Satellite BLVD. NW Suite 701A, Suwanee, GA 30024', 'Suwanee', 'GA', '30024', '(678) 417-1255', ARRAY['English', 'Korean']::text[], 'Internal Medicine', TRUE, '{"fax": "(678) 417-1258", "email": "main@jkinternalmedicine.net", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jk-internal-medicine-geriatrics-pc-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jk-internal-medicine-geriatrics-pc-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jk-internal-medicine-geriatrics-pc-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jk-internal-medicine-geriatrics-pc-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jk-internal-medicine-geriatrics-pc-google-5.webp"], "rating": 4.4, "reviews": [{"date": "2026-04-17T13:40:31.918152823Z", "text": "I had a really good experience at JK Internal Medicine during my immigration medical exam. From the moment I walked in, I was welcomed with a warm reception that made the whole process feel comfortable and stress-free.\n\nThe visit was very efficient and swift, which I really appreciated. Everything was handled in an organized way without long waiting times.\n\nThe staff were all very polite and professional. The nurses, the front desk team, and especially the lady who drew my blood were kind, gentle, and made sure I was at ease throughout the process.\n\nTo top it off, my results came back earlier than expected. Their office  manager David Kang even helped expedite my case without me paying for any expedited service, which really showed how reliable and considerate they are.\n\nOverall, it was a smooth and pleasant experience, and I would definitely recommend JK Internal Medicine to anyone needing their services.", "author": "Winnifred Boahene", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107479674795483072148/reviews"}, {"date": "2025-03-26T18:57:27.711052Z", "text": "This doctors office is great. They actually run on time! I’m sticking with Korean docs from here on out. Very thorough.", "author": "The Medicaid Firm", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107663189890371452358/reviews"}, {"date": "2025-04-16T13:56:22.989997Z", "text": "Nurse Lee was incredibly kind, professional, and attentive throughout my visit. Her friendly attitude made me feel comfortable and well cared for. I truly appreciated her warm demeanor and excellent service. Thank you, Nurse Lee!", "author": "Tien Tran", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114301671443638250778/reviews"}, {"date": "2025-08-06T21:21:58.663974505Z", "text": "There was an old lady who asked me where I got the immunization document from, but she wasn’t friendly at all, it felt more like an interrogation. I ended up sharing things that felt too personal to me. I hope HIPAA regulations are being properly followed.", "author": "esther yu", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/111295034075361045963/reviews"}, {"date": "2026-02-21T23:52:19.668066846Z", "text": "The young female receptionist is extremely rude and unprofessional. Even after I provided my information and explained the reason for my visit, she gave no response — no instruction to wait, no explanation, nothing at all. She just stood there expressionless without saying a word. It was awkward and uncomfortable, and another staff member next to her had to step in to assist me instead.\n\nEvery time I visit, this particular receptionist negatively affects my experience. The doctors themselves are kind and professional, but because of her attitude, I am seriously considering changing clinics. Although she is young, her way of dealing with patients feels outdated and lacks basic courtesy. I believe it may be better not to return.", "author": "Katie", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/110708163842282847639/reviews"}], "website": "https://jkmedi.com/", "location": {"latitude": 34.007671699999996, "longitude": -84.0756512}, "services": ["Internal Medicine", "Geriatrics", "Preventative Care", "Televisits", "Green Card Physical Exams (영주권 신체검사)"], "insurance": {"notes": "JK Internal Medicine accepts most insurance plans, but benefit and coverage varies with each patient and insurance company.", "accepts_medicaid": true, "accepts_medicare": true, "accepted_networks": ["Athena", "Ambetter", "Blue Cross Blue Shield", "Cigna", "Assurant Health", "Alliant Health Plan", "Allied Benefit Plans", "Conventry", "CareSource", "FirstHealth", "Humana", "Medicare", "Medicaid", "PHCS", "TRICARE", "UnitedHealthcare", "Wellcare"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Bilingual Staff (Korean/English)", "detail": "Supports Korean-speaking patients with full language access.", "category": "culture"}, {"title": "Serving Since 2005", "detail": "Over 20 years of experience in the Metro Atlanta area.", "category": "care"}, {"title": "Televisits Available", "detail": "Now offering virtual visits for convenient care.", "category": "technology"}, {"title": "Comprehensive Adult Care", "detail": "Preventative, diagnostic, and treatment services for chronic and acute conditions.", "category": "care"}], "price_tier": "$", "source_url": "https://jkmedi.com/", "appointment": {"booking_note": "Book a Visit via the website.", "appointment_url": "https://jkmedi.com/appointment/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean speaking medical clinic in Atlanta, GA", "search_text": "internal medicine | internist | primary care | nội khoa | bác sĩ nội | 내과 | 内科 | english | korean | 한국어 | 한인 | 한국말 | geriatrics | preventative care | televisits | green card physical exams (영주권 신체검사) | preventive | telehealth | physical exam | athena | ambetter | blue cross blue shield | cigna | assurant health | alliant health plan | allied benefit plans | conventry | caresource | firsthealth | humana | medicare | medicaid | phcs | tricare | unitedhealthcare | wellcare | jinahn kim | physician | jaeyoung lee | young s chang | min jeong kim | nurse practitioner | john kwon | anna woo", "google_types": ["medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 275, "team_members": [{"name": "JINAHN KIM", "role": "Physician", "bio_snippet": "MD, PhD", "languages_spoken": ["Korean", "English"]}, {"name": "JAEYOUNG LEE", "role": "Physician", "bio_snippet": "MD, PhD", "languages_spoken": ["Korean", "English"]}, {"name": "YOUNG S CHANG", "role": "Physician", "bio_snippet": "MD", "languages_spoken": ["Korean", "English"]}, {"name": "MIN JEONG KIM", "role": "Nurse Practitioner", "bio_snippet": "AGPCNP-C", "languages_spoken": ["Korean", "English"]}, {"name": "JOHN KWON", "role": "Nurse Practitioner", "bio_snippet": "AGPCNP-C", "languages_spoken": ["Korean", "English"]}, {"name": "ANNA WOO", "role": "Nurse Practitioner", "bio_snippet": "FNP-C", "languages_spoken": ["Korean", "English"]}], "language_note": "The clinic is strongly oriented toward the Korean-American community, with bilingual Korean-speaking providers and staff, a Korean-language version of the website, and several Korean-language patient reviews praising the friendly, efficient, and culturally sensitive care. The clinic''s name in Korean (김진안,이재영 내과) further signals its cultural focus.", "open_saturday": true, "quality_score": 100, "working_hours": {"friday": "9:00 AM – 5:00 PM", "monday": "9:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "9:00 AM – 5:00 PM", "saturday": "9:00 AM – 1:00 PM", "thursday": "9:00 AM – 5:00 PM", "wednesday": "9:00 AM – 5:00 PM"}, "gallery_images": ["https://jkmedi.com/wp-content/uploads/2021/10/slider_jkinternal_medicine.png", "https://jkmedi.com/wp-content/uploads/2021/10/slider_jakim.png", "https://jkmedi.com/wp-content/uploads/2021/10/slider_jykim.png", "https://jkmedi.com/wp-content/uploads/2021/10/slider_care-03.png", "https://jkmedi.com/wp-content/uploads/2021/10/slider_care-02.png", "https://jkmedi.com/wp-content/uploads/2021/10/welcome-e1634241096450.jpg", "https://jkmedi.com/wp-content/uploads/2021/10/jkim.jpg", "https://jkmedi.com/wp-content/uploads/2021/10/jyoung.jpg", "https://jkmedi.com/wp-content/uploads/Young_s_Chang.jpg", "https://jkmedi.com/wp-content/uploads/2021/10/mjkim.jpg", "https://jkmedi.com/wp-content/uploads/John-_kwon.jpg", "https://jkmedi.com/wp-content/uploads/anna-wu.jpg", "https://jkmedi.com/wp-content/uploads/2021/10/LOGO-2.png"], "review_profile": {"rating": 4.4, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Multiple reviewers highlight the polite, professional, and kind nature of the staff, including nurses and front desk personnel."}, {"theme": "Efficiency", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients appreciate the swift and organized service, with minimal waiting times."}, {"theme": "Communication", "mentions": 2, "sentiment": "Negative", "summary_quote": "Some reviews mention uncomfortable interactions with staff, including perceived rudeness and lack of responsiveness."}, {"theme": "Facility Environment", "mentions": 1, "sentiment": "Positive", "summary_quote": "The welcoming and stress-free atmosphere is noted by patients as a positive aspect of their visit."}, {"theme": "Clinical Expertise", "mentions": 1, "sentiment": "Positive", "summary_quote": "Reviewers commend the thoroughness and professionalism of the doctors."}], "summary": "Most patients report positive experiences at JK Internal Medicine & Geriatrics, praising the efficient service, professional staff, and comfortable environment, though some mention isolated issues with staff behavior.", "review_count": 275, "concern_themes": [], "positive_themes": ["Friendly staff", "Thorough care", "Kind and detailed explanations", "Efficient and quick service", "Comfortable experience"], "featured_reviews": [{"date": "2026-04-17T13:40:31.918152823Z", "text": "I had a really good experience at JK Internal Medicine during my immigration medical exam. From the moment I walked in, I was welcomed with a warm reception that made the whole process feel comfortable and stress-free.\n\nThe visit was very efficient and swift, which I really appreciated. Everything was handled in an organized way without long waiting times.\n\nThe staff were all very polite and professional. The nurses, the front desk team, and especially the lady who drew my blood were kind, gentle, and made sure I was at ease throughout the process.\n\nTo top it off, my results came back earlier than expected. Their office  manager David Kang even helped expedite my case without me paying for any expedited service, which really showed how reliable and considerate they are.\n\nOverall, it was a smooth and pleasant experience, and I would definitely recommend JK Internal Medicine to anyone needing their services.", "author": "Winnifred Boahene", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107479674795483072148/reviews"}, {"date": "2025-03-26T18:57:27.711052Z", "text": "This doctors office is great. They actually run on time! I’m sticking with Korean docs from here on out. Very thorough.", "author": "The Medicaid Firm", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107663189890371452358/reviews"}, {"date": "2025-04-16T13:56:22.989997Z", "text": "Nurse Lee was incredibly kind, professional, and attentive throughout my visit. Her friendly attitude made me feel comfortable and well cared for. I truly appreciated her warm demeanor and excellent service. Thank you, Nurse Lee!", "author": "Tien Tran", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114301671443638250778/reviews"}, {"date": "2025-08-06T21:21:58.663974505Z", "text": "There was an old lady who asked me where I got the immunization document from, but she wasn’t friendly at all, it felt more like an interrogation. I ended up sharing things that felt too personal to me. I hope HIPAA regulations are being properly followed.", "author": "esther yu", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/111295034075361045963/reviews"}, {"date": "2026-02-21T23:52:19.668066846Z", "text": "The young female receptionist is extremely rude and unprofessional. Even after I provided my information and explained the reason for my visit, she gave no response — no instruction to wait, no explanation, nothing at all. She just stood there expressionless without saying a word. It was awkward and uncomfortable, and another staff member next to her had to step in to assist me instead.\n\nEvery time I visit, this particular receptionist negatively affects my experience. The doctors themselves are kind and professional, but because of her attitude, I am seriously considering changing clinics. Although she is young, her way of dealing with patients feels outdated and lacks basic courtesy. I believe it may be better not to return.", "author": "Katie", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/110708163842282847639/reviews"}]}, "review_summary": "Most patients report positive experiences at JK Internal Medicine & Geriatrics, praising the efficient service, professional staff, and comfortable environment, though some mention isolated issues with staff behavior.", "about_highlight": "JK Internal Medicine & Geriatrics, PC opened in 2005 with the goal of serving the community with the most up-to-date and high standard medicine in a comfortable, relaxing environment. The clinic provides care for all aspects of adult medicine, from treating chronic to acute illnesses, with a focus on preventative, diagnostic, and treatment services. The team includes multiple physicians and nurse practitioners, and the clinic is known for its bilingual Korean-speaking staff, making it a welcoming choice for Korean-American and immigrant patients in the Suwanee area.", "appointment_url": "https://jkmedi.com/appointment/", "google_maps_url": "https://maps.google.com/?cid=12837205892421004001&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJP22H1WO99YgR4SpOpr7qJrI", "quality_missing": [], "search_keywords": ["internal medicine", "internist", "primary care", "nội khoa", "bác sĩ nội", "내과", "内科", "english", "korean", "한국어", "한인", "한국말", "geriatrics", "preventative care", "televisits", "green card physical exams (영주권 신체검사)", "p