INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('21f8973d-6e70-48e7-aa01-539e025f1a2a', NULL, 'Kuraoka Clinic', '倉岡クリニックは、一般内科と小児科の診察と治療、人間ドックや小児科健診、婦人科検診、禁煙外来、ペイン・クリニック、カウンセリングを、日本語と英語で行う最先端医療サービスです。現在ジョージア州とオハイオ州、テキサス州にクリニックがあり、アメリカにお住いの日本人の皆様の健康管理をお手伝いしております。日本人医師とスタッフが、日本語で丁寧にご説明しますので、安心です。オンラインで行う便利な遠隔診療もおこなっております。', 'Governors Ridge Office Park Bldg. 30, 1640 Powers Ferry Rd Ste 100, Marietta, GA 30067', 'Marietta', 'GA', '30067', '770-980-0000', ARRAY['English', 'Japanese', 'Korean']::text[], 'Pediatrics', TRUE, '{"email": "info@kuraokaclinic.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/kuraoka-clinic-google-1.webp"], "rating": 3.8, "reviews": [{"date": "2025-07-22T11:37:17.097193138Z", "text": "Physician Assistant STEPHANIE, Miss AYAKA, and Mariko!!!!...and the rest of the beautiful and caring crew (too many to name), thank you!!!\nThank you for being my safe haven, place of complete love and care! Please leave the obnoxious mega health systems and go to a practice that feels like a family! I love you all, Dr. Maki! Thanks for the continued health support these past few years!!!", "author": "Eboni Cheri", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107141706716729116029/reviews"}, {"date": "2020-07-21T18:59:19.854017Z", "text": "I have been around a doctor and doctor''s offices a time or two. In fact, that''s my profession. I''ve met with literally hundreds if not thousands of doctor''s and their staffs. Dr. Maki and her team are simply put, tremendous. Attentive, caring, excellent communicators. You really won''t find a better family medicine practice anywhere. They took excellent care of my son.\n\nOne watch-out, though. I think Google Maps has the wrong building in their photo and the location is off in the map portion if you search for \"Kuraoka Clinic\". It''s in the right office building complex, though. Furthermore, if you put their address in Google Maps (1640 Powers Ferry Rd. Building 30 Suite 100 Marietta, GA 30067) for some reason it is pretty far off, a good bit north on Powers Ferry. If you schedule an appointment, they will email a confirmation and the email signature has a small map which will lead you right to their office.\n\nHighly recommended!", "author": "Jeff Bullis", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102861449225143577587/reviews"}, {"date": "2023-01-24T18:43:35.276013Z", "text": "Moon Sensei was so gentle and speak Japanese to me and English to my son.  She did not rush out o the room and she listened to all my concerns and answered all of my questions!", "author": "Punch Double", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108212290087734719543/reviews"}, {"date": "2023-04-11T17:21:28.322360Z", "text": "Dr Maki have a nasty attitude when she is good and ready tell her you don’t agree with her method and you will see 😳 and you the patient is just crazy", "author": "Love Jones", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/115574266583628309749/reviews"}, {"date": "2020-08-24T14:58:27.968661Z", "text": "Extremely impressed, super professional, clean , and very detailed. I never want to go anywhere else. Today was my first visit.", "author": "Maria Maria", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109119612784687569698/reviews"}], "website": "http://kuraokaclinic.com/", "location": {"latitude": 33.9125284, "longitude": -84.46748}, "services": ["General Internal Medicine & Pediatrics", "Ningen Dock (Comprehensive Health Checkup)", "Gynecological Exam", "Pediatric Exam", "Vaccinations", "Pain Clinic", "Smoking Cessation", "Counseling / Psychiatry", "Telemedicine", "Medical Spa / Aesthetics"], "insurance": {"notes": "Japanese travel insurance accepted with cashless payment. Insurance information page available at https://kuraokaclinic.com/hoken/", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Bilingual Staff", "detail": "Japanese and English speaking doctors and staff for comfortable care.", "category": "culture"}, {"title": "Telemedicine Available", "detail": "Convenient online consultations available for those who cannot visit the clinic.", "category": "convenience"}, {"title": "Annual Checkup (Ningen Dock)", "detail": "Comprehensive health checkup to detect diseases early, including adult, pediatric, and gynecological packages.", "category": "care"}, {"title": "Pain Clinic & Smoking Cessation", "detail": "Specialized pain management and smoking cessation treatments available.", "category": "care"}], "price_tier": "$$", "source_url": "http://kuraokaclinic.com/", "appointment": {"booking_note": null, "appointment_url": "http://kuraokaclinic.com/services/tele-medicine/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean speaking medical clinic in Atlanta, GA", "search_text": "pediatrics | pediatrician | child doctor | vaccines | newborn | nhi khoa | bác sĩ nhi | khám trẻ em | 소아과 | 소아청소년과 | 儿科 | english | japanese | korean | 한국어 | 한인 | 한국말 | general internal medicine & pediatrics | ningen dock (comprehensive health checkup) | gynecological exam | pediatric exam | vaccinations | pain clinic | smoking cessation | counseling / psychiatry | telemedicine | medical spa / aesthetics | primary care | preventive | specialty | mental health | convenience | cosmetic", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 26, "language_note": "日本人コミュニティ向けに、バイリンガル（日本語・英語）で診療。日本人医師とスタッフが日本語で丁寧に説明。日本の旅行者保険をキャッシュレスで利用可能。", "open_saturday": true, "quality_score": 92, "working_hours": {"friday": "8:30 AM – 4:30 PM", "monday": "8:30 AM – 4:30 PM", "sunday": "Closed", "tuesday": "8:30 AM – 4:30 PM", "saturday": "8:30 AM – 12:00 PM", "thursday": "8:30 AM – 4:30 PM", "wednesday": "Closed"}, "gallery_images": ["https://kuraokaclinic.com/wp-content/uploads/2023/01/Kuraoka-Clinic-logo-230px.png", "https://kuraokaclinic.com/wp-content/uploads/2023/01/page-1_slide-fam-1920x715.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/02/page-1_slide-fam2-1920x715.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/02/page-1_slide-telened2-1920x715.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/03/ningendoc-eyecatch.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/02/home-850x567-spa.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/02/home-850x567-yohtu.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/02/Atlanta-Staff-2022.jpg", "https://kuraokaclinic.com/wp-content/uploads/2026/03/Dallas-Group-Photo-Feb-2026-2-.jpg", "https://kuraokaclinic.com/wp-content/uploads/2023/06/Ohio-202306-staff.jpg"], "review_profile": {"rating": 3.8, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Multiple reviewers commend the staff for being attentive, caring, and excellent communicators."}, {"theme": "Facility Environment", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients describe the clinic as clean, professional, and welcoming."}, {"theme": "Communication", "mentions": 2, "sentiment": "Neutral", "summary_quote": "While many appreciate the staff''s communication, one reviewer noted concerns about Dr. Maki''s attitude."}, {"theme": "Clinical Expertise", "mentions": 1, "sentiment": "Positive", "summary_quote": "Patients express confidence in the clinic''s medical care and detailed approach."}, {"theme": "Patient Experience", "mentions": 1, "sentiment": "Positive", "summary_quote": "Reviewers describe the clinic as a ''safe haven'' and emphasize the family-like atmosphere."}], "summary": "Patients generally praise Kuraoka Clinic for its caring and professional staff, with many highlighting the family-like atmosphere and attentive care. However, there are occasional concerns about communication and attitudes.", "review_count": 26, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2025-07-22T11:37:17.097193138Z", "text": "Physician Assistant STEPHANIE, Miss AYAKA, and Mariko!!!!...and the rest of the beautiful and caring crew (too many to name), thank you!!!\nThank you for being my safe haven, place of complete love and care! Please leave the obnoxious mega health systems and go to a practice that feels like a family! I love you all, Dr. Maki! Thanks for the continued health support these past few years!!!", "author": "Eboni Cheri", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107141706716729116029/reviews"}, {"date": "2020-07-21T18:59:19.854017Z", "text": "I have been around a doctor and doctor''s offices a time or two. In fact, that''s my profession. I''ve met with literally hundreds if not thousands of doctor''s and their staffs. Dr. Maki and her team are simply put, tremendous. Attentive, caring, excellent communicators. You really won''t find a better family medicine practice anywhere. They took excellent care of my son.\n\nOne watch-out, though. I think Google Maps has the wrong building in their photo and the location is off in the map portion if you search for \"Kuraoka Clinic\". It''s in the right office building complex, though. Furthermore, if you put their address in Google Maps (1640 Powers Ferry Rd. Building 30 Suite 100 Marietta, GA 30067) for some reason it is pretty far off, a good bit north on Powers Ferry. If you schedule an appointment, they will email a confirmation and the email signature has a small map which will lead you right to their office.\n\nHighly recommended!", "author": "Jeff Bullis", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102861449225143577587/reviews"}, {"date": "2023-01-24T18:43:35.276013Z", "text": "Moon Sensei was so gentle and speak Japanese to me and English to my son.  She did not rush out o the room and she listened to all my concerns and answered all of my questions!", "author": "Punch Double", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108212290087734719543/reviews"}, {"date": "2023-04-11T17:21:28.322360Z", "text": "Dr Maki have a nasty attitude when she is good and ready tell her you don’t agree with her method and you will see 😳 and you the patient is just crazy", "author": "Love Jones", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/115574266583628309749/reviews"}, {"date": "2020-08-24T14:58:27.968661Z", "text": "Extremely impressed, super professional, clean , and very detailed. I never want to go anywhere else. Today was my first visit.", "author": "Maria Maria", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109119612784687569698/reviews"}]}, "review_summary": "Patients generally praise Kuraoka Clinic for its caring and professional staff, with many highlighting the family-like atmosphere and attentive care. However, there are occasional concerns about communication and attitudes.", "about_highlight": "倉岡クリニックは、一般内科と小児科の診察と治療、人間ドックや小児科健診、婦人科検診、禁煙外来、ペイン・クリニック、カウンセリングを、日本語と英語で行う最先端医療サービスです。現在ジョージア州とオハイオ州、テキサス州にクリニックがあり、アメリカにお住いの日本人の皆様の健康管理をお手伝いしております。日本人医師とスタッフが、日本語で丁寧にご説明しますので、安心です。オンラインで行う便利な遠隔診療もおこなっております。", "appointment_url": "http://kuraokaclinic.com/services/tele-medicine/", "google_maps_url": "https://maps.google.com/?cid=8222461425991703064&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJZf0LkEgQ9YgRGFqWOxoNHHI", "quality_missing": ["insurance", "team_members"], "search_keywords": ["pediatrics", "pediatrician", "child doctor", "vaccines", "newborn", "nhi khoa", "bác sĩ nhi", "khám trẻ em", "소아과", "소아청소년과", "儿科", "english", "japanese", "korean", "한국어", "한인", "한국말", "general internal medicine & pediatrics", "ningen dock (comprehensive health checkup)", "gynecological exam", "pediatric exam", "vaccinations", "pain clinic", "smoking cessation", "counseling / psychiatry", "telemedicine", "medical spa / aesthetics", "primary care", "preventive", "specialty", "mental health", "convenience", "cosmetic"], "cultural_context": "日本人コミュニティ向けに、バイリンガル（日本語・英語）で診療。日本人医師とスタッフが日本語で丁寧に説明。日本の旅行者保険をキャッシュレスで利用可能。", "services_offered": [{"name": "General Internal Medicine & Pediatrics", "category": "Primary Care", "description": "Diagnosis and treatment for common illnesses for adults and children.", "is_featured": true, "patient_fit": "All ages"}, {"name": "Ningen Dock (Comprehensive Health Checkup)", "category": "Preventive", "description": "Annual comprehensive health checkup with detailed testing to detect diseases early.", "is_featured": true, "patient_fit": "Adults, children, and women (separate packages)"}, {"name": "Gynecological Exam", "category": "Preventive", "description": "Women''s health screening package.", "is_featured": false, "patient_fit": "Women"}, {"name": "Pediatric Exam", "category": "Preventive", "description": "Pediatric health screening package.", "is_featured": false, "patient_fit": "Children"}, {"name": "Vaccinations", "category": "Preventive", "description": "Immunization services.", "is_featured": false, "patient_fit": "All ages"}, {"name": "Pain Clinic", "category": "Specialty", "description": "Specialized treatment for acute and chronic pain including back pain, frozen shoulder, neck pain, and joint pain.", "is_featured": true, "patient_fit": "Adults suffering from pain"}, {"name": "Smoking Cessation", "category": "Specialty", "description": "Treatment to help patients quit smoking.", "is_featured": true, "patient_fit": "Smokers wanting to quit"}, {"name": "Counseling / Psychiatry", "category": "Mental Health", "description": "Telehealth psychiatry and counseling provided in Japanese by Dr. Takashi Matsuki (New York-based), covering Texas, Georgia, and Alabama.", "is_featured": true, "patient_fit": "Patients needing mental health support"}, {"name": "Telemedicine", "category": "Convenience", "description": "Online remote medical consultations for convenience.", "is_featured": true, "patient_fit": "Patients unable to visit the clinic"}, {"name": "Medical Spa / Aesthetics", "category": "Cosmetic", "description": "Laser treatments for skin concerns, lifting, hair removal, tattoo removal, Botox, and hyaluronic acid injections. Also offers hair transplant.", "is_featured": false, "patient_fit": "Patients seeking cosmetic treatments"}], "short_description": "倉岡クリニックは、一般内科と小児科の診察と治療、人間ドックや各種検診、ペインクリニック、禁煙外来などを、日本語と英語で提供する先進医療サービスです。", "google_website_url": "http://kuraokaclinic.com/", "google_primary_type": "Doctor", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "Governors Ridge Office Park Bldg. 30, 1640 Powers Ferry Rd Ste 100, Marietta, GA 30067, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/103727931878877408222", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjVR0YOMDciPHrQ1AzdFgyyHQwcaLfgGTFMdi8U3LuMeQcjoRqI=s100-p-k-no-mo", "displayName": "藍那 純"}]]}'::jsonb, '2026-06-26T12:14:00.291168+00:00', 'kuraoka-clinic', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('39d85bc5-460b-4344-8c15-b57d74d67afb', NULL, 'MyCare Clinic', 'Located in Peachtree Corners and serving Metro Atlanta, MyCare Clinic offers a full range of medical services tailored to your needs. From preventive care to specialized treatments, we’re here to support your health journey. As a family-owned, local clinic, we provide holistic, personalized healthcare in a welcoming, family-oriented environment. Our modern facility and dedicated team are committed to supporting the health and wellbeing of our community through innovative and compassionate care.', '3941 Holcomb Bridge Rd. Suite 100, Peachtree Corners, GA 30092', 'Peachtree Corners', 'GA', '30092', '+1 (678) 221-3333', ARRAY['English', 'Korean']::text[], 'Primary Care', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/mycare-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/mycare-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/mycare-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/mycare-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/mycare-clinic-google-5.webp"], "rating": 5, "reviews": [{"date": "2026-02-26T14:55:11.330851384Z", "text": "I had a great experience at My Care Clinic. The staff showed so much patience and took the time to answer all of my questions clearly. I never felt rushed, and they made sure to fully address all of my concerns.  NP Rasa Teytel was especially kind, professional, and attentive throughout my visit.", "author": "Jeannie Augustin", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113561506661397268630/reviews"}, {"date": "2026-02-27T05:32:37.644493234Z", "text": "Dr. Rasa is very nice and knowledgeable. Her staff is very nice . I would recommend friends and family for any medical needs . She is a all-around doctor that does everything.  she does Botox,  OBGYN, a primary care doctor and she also deal with people that have  very bad allergy problems. I like her a lot. She listens to her clients ,take notes and discuss what we should do to help me.", "author": "Sabrina Kochan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109657911589836499982/reviews"}, {"date": "2026-03-12T18:40:31.830892459Z", "text": "I had such a positive experience at MyCare Clinical. The staff was welcoming, professional, and very attentive. They made the entire process smooth and comfortable, and I never felt rushed. You can tell they genuinely care about their patients. Rasa took amazing care of us and made us feel so comfortable throughout the visit. I’m very grateful for the great care I received and will definitely be bringing my loved ones here. I would highly recommend this clinic!", "author": "Emily Escobar", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108371814011862234551/reviews"}, {"date": "2026-03-09T15:21:18.713330074Z", "text": "doctor Rasa Teytel is my favorite, every time she is so attentive, kind and positive", "author": "Яна Абрамчук", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103758295390125418570/reviews"}, {"date": "2026-03-05T18:10:28.802405004Z", "text": "very friendly and personable staff. very quick easy. i’ve seen dr. daniel cohen and dr rasa teytel so far and they’ve both been wonderful! 100% recommend", "a