INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('9edf74cc-cb64-46da-a951-fe2dfd4e69fd', NULL, 'North East Medical Services (NEMS) - 1870 Lundy Clinic', 'North East Medical Services (NEMS) is a non-profit community health center that offers comprehensive health care services to a variety of patients, a majority of whom are uninsured or low income. The 1870 Lundy Clinic in San Jose provides a wide range of services including Internal Medicine, Family Practice, Pediatrics, Acupuncture, Chiropractic, Dental, Optometry, Laboratory, Radiology, Pharmacy, Endocrinology, Behavioral Health, Health Education, and Member Services. With over 250 health care providers across 32 sites, NEMS is one of the largest community health centers in the United States targeting the medically underserved population.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('a6705db5-a3e7-45d8-badb-4b2992b20920', NULL, 'Tian Chao Herbs & Acupuncture', 'Tian Chao Herbs & Acupuncture brings the ancient wisdom of Traditional Chinese Medicine to the Sacramento area with two convenient locations in Fair Oaks and Downtown Sacramento. With decades of experience, the clinic specializes in custom herbal formulas from the area''s largest herbal pharmacy and offers comprehensive acupuncture and related therapies. Patients turn to Tian Chao when traditional treatment has failed them, finding relief for a wide range of conditions from chronic pain and migraines to digestive disorders and stress.', '4125 Temescal Street, Fair Oaks, CA 95628', 'Fair Oaks', 'CA', '95628', '(916) 866-2877', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tian-chao-herbs-acupuncture-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tian-chao-herbs-acupuncture-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tian-chao-herbs-acupuncture-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tian-chao-herbs-acupuncture-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/tian-chao-herbs-acupuncture-google-5.webp"], "rating": 4.9, "pricing": [{"name": "Initial Consultation", "notes": "Special initial consultation for new patients. Must be paid in full prior to scheduling.", "price": "$50", "category": "consultation", "price_range": null}], "reviews": [{"date": "2026-02-02T23:18:58.191319151Z", "text": "I always leave feeling rejuvenated! The customer service is consistently amazing, from the moment you walk in, you’re greeted by such kind and professional front office staff. The doctors are wonderful, knowledgeable, and truly make you feel cared for. Every visit is a great experience, and I always feel well taken care of. Highly recommend!", "author": "Krista Hambly", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115681043771977962205/reviews"}, {"date": "2025-11-03T22:41:12.089524933Z", "text": "Every time I walk in the doors of V W S, I’m always greeted with warmth by their friendly staff.\nWait time is very brief for scheduled appointments and staff is professional. Treatment rooms are always clean, temperature is comfortable, and “zen” audio provides relaxation.\nI signed up for memberships (acupuncture and spa treatments)  with significant price reductions.", "author": "Carolyn Streng", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111959729667344860362/reviews"}, {"date": "2026-04-11T18:58:17.228154859Z", "text": "Wonderful treatment from Dr. Ye and Dr. Tian. I’m seeing improvements with my overall health and allergies even after a few sessions. They are very caring and thoughtful about their practice. Office staff are also very professional and friendly!", "author": "Stephanie", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117722670898452850929/reviews"}, {"date": "2026-02-11T18:50:37.202005701Z", "text": "I’ve been coming here throughout my pregnancy and it’s made my pregnancy so much smoother and easier! The doctors here are wonderful and very attentive. I highly recommend their classes as well.\n\nEditing to add that I had a really smooth and easy delivery and recovery thanks to Dr. Wesley’s care!", "author": "Meryl Charleston", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102442008347107008465/reviews"}, {"date": "2025-11-05T18:05:46.359076323Z", "text": "I trust Tian Chao with all my health concerns… the treatments are specifically tailored to treat root causes of imbalances, not simply treatments for symptom relief… And I do get symptom relief….. my wealth is my health and Tian and her impeccably trained staff have kept me well my whole life….", "author": "M Brooks Motl", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100364664893125682356/reviews"}], "website": "https://www.tianchaoherbs.com/", "location": {"latitude": 38.6411093, "longitude": -121.26901939999999}, "services": ["Acupuncture", "Herbal Pharmacy", "Cupping Therapy", "Seasonal Treatment"], "insurance": {"notes": "No insurance information mentioned on the page. Special initial consultation for $50 for new patients.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Best in Sacramento", "detail": "Voted Best in Sacramento on CityVoter''s A-List competition.", "category": "reviews"}, {"title": "Largest Herbal Pharmacy in the Area", "detail": "Specializes in custom herbal formulas in pill and powder form based on client''s specific needs.", "category": "care"}, {"title": "Special Initial Consultation for $50", "detail": "New patients receive a special initial consultation for $50, must be paid in full prior to scheduling.", "category": "insurance"}, {"title": "Featured on ABC 10 and Fox 40", "detail": "Media appearances on ABC 10 and Fox 40 discussing cupping and alternative health approaches.", "category": "reviews"}, {"title": "Treats All Ages", "detail": "Treatments provided for family members ranging from 7 years old to 90 years old.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.tianchaoherbs.com/", "appointment": {"booking_note": "New patients call to schedule. Existing patients book online.", "appointment_url": "https://tianchaoherbsacupuncture.janeapp.com/", "new_patient_note": "New patients receive a special initial consultation for $50. Must be paid in full prior to scheduling.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Sacramento, CA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | herbal pharmacy | cupping therapy | seasonal treatment | traditional chinese medicine | tian | practitioner", "google_types": ["health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 54, "team_members": [{"name": "Tian", "role": "Practitioner", "bio_snippet": "Lead practitioner at Tian Chao Herbs & Acupuncture with decades of experience in Traditional Chinese Medicine.", "languages_spoken": []}], "language_note": "Traditional Chinese Medicine practice rooted in ancient healing wisdom, offering culturally responsive care with a focus on herbal medicine and acupuncture.", "open_saturday": true, "quality_score": 95, "working_hours": {"friday": "9:00 AM – 6:00 PM", "monday": "9:00 AM – 6:00 PM", "sunday": "Closed", "tuesday": "9:00 AM – 6:00 PM", "saturday": "9:00 AM – 6:00 PM", "thursday": "9:00 AM – 6:00 PM", "wednesday": "9:00 AM – 6:00 PM"}, "gallery_images": ["https://images.squarespace-cdn.com/content/v1/63d97bae409fe07bc6831bb5/979fa6b4-f0c1-4747-9fd7-13219ee53e50/TCHA+web+pic+%281%29.png", "https://images.squarespace-cdn.com/content/v1/63d97bae409fe07bc6831bb5/1724780607169-H86II6N1IWR5DT9WBR5R/unsplash-image-CwVE4xCAA8Y.jpg", "https://images.squarespace-cdn.com/content/v1/63d97bae409fe07bc6