INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('f91c676b-af11-4ca0-9dc3-fcd035e7429b', NULL, 'Dr Tam Medical Spa', 'Dr Tam Medical Spa provides a luxury medspa environment in Garden Grove, CA, offering IV therapy and a range of medical injection, body contour, and skin care services. Their IV therapy services are administered by registered nurses and aim to address fatigue, immune support, workout recovery, and anti-aging through direct vitamin and nutrient infusion. The spa emphasizes a relaxing, high-end experience with personalized consultations before treatment.', '10226 Westminster Ave, Garden Grove, CA 92843', 'Garden Grove', 'CA', '92843', '(949) 618-6993', ARRAY['English', 'Vietnamese']::text[], 'Primary Care', FALSE, '{"email": "info@drtam-medspa.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr-tam-medical-spa-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr-tam-medical-spa-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr-tam-medical-spa-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr-tam-medical-spa-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/dr-tam-medical-spa-google-5.webp"], "rating": 5, "reviews": [{"date": "2026-04-25T22:16:54.522582429Z", "text": "Shareem at Dr. Tam’s is the best!! She’s so sweet, and very very patient. I have very sensitive skin and have been to many clinics, but have never met a technician as caring as Shareem! Nice office and office staff is also very nice and accommodating.", "author": "Deea Gandotra", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103180961243484853746/reviews"}, {"date": "2026-03-15T20:03:25.514725054Z", "text": "I recently walked by DR.TAM MED SPA CLINIC and decided to stop in to check it out. The clinic looks very professional, clean, and well organized. I also learned that they are currently preparing for their soft opening, which is exciting for the community.\n\nThey offer senior discounts for massage and IV therapy, which is really great. My mom has Medicare, and they helped her sign up for a membership program that only costs $1 per month. The membership comes with many discounts on services, and the IV therapy prices are very reasonable as well.\n\nThe staff was friendly and informative, and they took the time to explain the services and membership options clearly. It’s not easy to find a place that offers both wellness services and affordable options for seniors.\n\nWe are really looking forward to their grand opening and trying more of their services soon. Highly recommend checking this place out! ⭐⭐⭐⭐⭐", "author": "Kae Cyrus", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107091112719119038153/reviews"}], "website": "https://drtam-medspa.com/", "location": {"latitude": 33.7593092, "longitude": -117.95079209999999}, "services": ["IV Therapy", "Semaglutide", "Stem Cell Therapy", "PRP Rejuvenation Facial", "Kybella", "Botox", "Dermal Fillers", "Vitamin B12 Shot", "CoolSculpting", "Venus Legacy", "Tri-Action Body Slimming", "Parafango Anti-Cellulite Therapy", "Rejuvenation Facial", "Micro-Needling Facial", "Venus Freeze Tightening Facial", "Gold Facial Detox Therapy"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Luxury Sp