INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('14d35748-eecf-4343-b89a-75ecd6ef2b62', NULL, 'Symphony Dental', 'Symphony Dental is a modern dental clinic in Los Angeles where technology and artistry meet to create a harmonious patient experience. Led by Dr. Yoon, the clinic offers advanced general, cosmetic, implant, and pediatric dentistry in a relaxing state-of-the-art office designed by renowned medical design firm Saunders + Wiant Architects. The team is known for being kind, professional, and gentle, and they work with patients to understand insurance and billing costs ahead of time.', '520 S. Virgil Ave., Suite 101, Los Angeles, CA 90020', 'Los Angeles', 'CA', '90020', '(213) 383-0010', ARRAY['English', 'Korean']::text[], 'Dental', FALSE, '{"email": "sdental101@yahoo.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/symphony-dental-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/symphony-dental-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/symphony-dental-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/symphony-dental-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/symphony-dental-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2026-03-30T21:20:45.393605408Z", "text": "I have been coming to Symphony Dental since 2012 and have nothing but love for the staff. Julie and Victoria takes care of ALL their patients with genuine concern and are the most hospitable human beings! Even though I change my appointments last minute or arrive a little late, they have great consideration! Cindy, the hygienist, makes your stay at ease, thorough,  with a good work ethic. The office and patient rooms are spic and span, while the sights and sounds bring a zen-like peace from beginning to end.", "author": "Mark A.", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110128758238286779482/reviews"}, {"date": "2026-04-21T21:30:18.213309441Z", "text": "I usually hate the dentist but I can confidently say I did not hate my experience at Symphony dental today. My boyfriend found this place for me after experiencing 2 weeks of jaw pain and another dental office not communicating with me about insurance. So I was left to try to find a dentist before Thursday as I’m leaving for a trip. The front desk was great about assuring me that they could treat me and they squeezed me in for today and I was relatively quickly.\nThe staff was extremely kind and communicated well about pricing and was willing to work with my budget for treatment. The dentist himself was also very kind, gentle, and communicative with me through the process of treating my tooth and placing a crown on it.\nIf more dental practices were this precise and convenient without judgment, I probably wouldn’t have waited 3 years.", "author": "Nolan Pazyra", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111804404611523016259/reviews"}, {"date": "2025-11-11T20:03:43.026512818Z", "text": "I’ve been coming to this dental office probably for the last 4 years. Probably the cleanest I’ve ever been to. The ladies at the front desk are very sweet and polite. The dentist is gentle when working and the dental hygienist Anna is great. If she ever gives you any dental recommendations (toothbrush floss, toothpaste) definitely take it! It has helped improved my dental care routine and have seen improvements!", "author": "Rosalie Marquez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116450635574628099306/reviews"}, {"date": "2026-05-05T16:52:23.820414350Z", "text": "Been coming to Symphony Dental for over 10 years and I''ve never had any issues with them. Everyone on staff have a positive attitude and they make sure to always make sure they''re customers are safe and happy with them. I would highly recommend anyone and everyone to come to Symphony Dental.", "author": "Joseph Morales", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106245215522417428449/reviews"}, {"date": "2026-02-06T23:43:01.689261698Z", "text": "The best. My wife and I have been going here for years. In LA its hard to find a good dentist, that doesn’t try to upsell everything. Symphony is the most honest, professional, and provides the best cleaning I have ever had. Highly recommend them and they always have parking!", "author": "PD Shindell", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107591881945471902808/reviews"}], "website": "http://symphony.dental/", "location": {"latitude": 34.064528599999996, "longitude": -118.2869259}, "services": ["General Dentistry", "Cosmetic Dentistry", "Implant Dentistry", "Pediatric Dentistry", "Orthodontics", "Endodontics", "Periodontics", "Oral Surgery"], "insurance": {"notes": "Staff will work with you and your insurance to understand costs ahead of time.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "Modern State-of-the-Art Facility", "detail": "Facilities designed by renowned medical and dental design firm Saunders + Wiant Architects.", "category": "convenience"}, {"title": "Longstanding Patient Trust", "detail": "Many patients have been visiting for nearly a decade or since the clinic opened.", "category": "reviews"}, {"title": "Fair Billing & Insurance Help", "detail": "Staff will work with you and your insurance to understand costs ahead of time.", "category": "insurance"}, {"title": "Gentle & Caring Care", "detail": "Dr. Yoon is described as patient, gentle, and soothing, especially during sensitive procedures.", "category": "care"}, {"title": "Comprehensive Services", "detail": "Offers general, cosmetic, implant, pediatric dentistry, orthodontics, endodontics, periodontics, and oral surgery.", "category": "care"}, {"title": "Two Convenient Locations", "detail": "Located at 520 S. Virgil Ave., Suite 101 and 500 S. Virgil Ave., Suite 305, Los Angeles.", "category": "convenience"}], "price_tier": "$$", "source_url": "http://symphony.dental/", "appointment": {"booking_note": "Make an appointment online by agreeing to data collection and storage on the form.", "appointment_url": "http://symphony.dental/appointments/", "new_patient_note": null, "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean dentist in Los Angeles, CA", "search_text": "dental | dentist | nha khoa | nha sĩ | trồng răng | implant | root canal | crowns | veneers | braces | invisalign | toothache | 치과 | 치과의사 | 임플란트 | 牙医 | 牙科 | 种植牙 | english | korean | 한국어 | 한인 | 한국말 | general dentistry | cosmetic dentistry | implant dentistry | pediatric dentistry | orthodontics | endodontics | periodontics | oral surgery | cosmetic | dr. yoon | julie | front desk", "google_types": ["dental_clinic", "medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 80, "team_members": [{"name": "Dr. Yoon", "role": "Dentist", "bio_snippet": "Described as very patient and gentle, especially during sensitive procedures. Patients feel comfortable and often fall asleep in his chair.", "languages_spoken": []}, {"name": "Julie", "role": "Front Desk", "bio_snippet": "Front desk staff member praised for being a pleasure to see.", "