: "https://maps.google.com/?cid=5076348398369877839&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJIQxHj3DHwoART6_1APnPckY", "quality_missing": ["insurance"], "search_keywords": ["dental", "dentist", "nha khoa", "nha sĩ", "trồng răng", "implant", "root canal", "crowns", "veneers", "braces", "invisalign", "toothache", "치과", "치과의사", "임플란트", "牙医", "牙科", "种植牙", "english", "korean", "한국어", "한인", "한국말", "general dentistry", "cosmetic dentistry", "implant dentistry", "pediatric dentistry", "orthodontics", "endodontics", "periodontics", "oral surgery", "cosmetic", "dr. yoon", "julie", "front desk"], "services_offered": [{"name": "General Dentistry", "category": "Dental", "description": "Routine dental care including cleanings, exams, fillings, and preventive treatments.", "is_featured": true, "patient_fit": null}, {"name": "Cosmetic Dentistry", "category": "Cosmetic", "description": "Enhancement of smile aesthetics through procedures such as whitening, veneers, and bonding.", "is_featured": true, "patient_fit": null}, {"name": "Implant Dentistry", "category": "Dental", "description": "Replacement of missing teeth with dental implants for natural-looking results.", "is_featured": true, "patient_fit": null}, {"name": "Pediatric Dentistry", "category": "Dental", "description": "Dental care tailored for children and adolescents.", "is_featured": true, "patient_fit": "Children and teens"}, {"name": "Orthodontics", "category": "Dental", "description": "Straightening teeth and correcting bite issues, including Invisalign treatment.", "is_featured": false, "patient_fit": null}, {"name": "Endodontics", "category": "Dental", "description": "Treatment of tooth pulp and root canals.", "is_featured": false, "patient_fit": null}, {"name": "Periodontics", "category": "Dental", "description": "Care for gum health, including treatment of gum disease.", "is_featured": false, "patient_fit": null}, {"name": "Oral Surgery", "category": "Dental", "des