INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('cb9bbbc2-3827-4791-baf5-eaedb5bfe236', NULL, 'Acupuncture & Herb Clinic', 'Acupuncture & Herb Clinic is a traditional Chinese medicine practice that combines acupuncture and herbal therapies to support patient wellness. Located in the Dallas-Fort Worth area, the clinic offers acupuncture treatments, herbal formulations, therapy sessions, and wellness products designed to restore balance and alleviate a variety of health concerns. The clinic is led by experienced practitioners who emphasize a holistic, patient-centered approach to healing.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('7cc86510-6965-4644-9959-ed95ce203c0c', NULL, 'Nina Nguy, Psy.D., PMH-C', 'Dr. Nina Nguy is a Vietnamese-speaking Psychologist in Orange County specializing in neurodiversity-affirming therapy, marriage counseling, and immigration evaluations. She works with individuals and couples who are ready to break free from cycles of anger, hurt, and disconnection. Her practice is deeply rooted in cultural competence, serving Asian professionals, cycle breakers, and those navigating intergenerational trauma, with both in-person and online therapy available in California.', '2900 Bristol St. Ste D106, Costa Mesa, CA 92626', 'Costa Mesa', 'CA', '92626', '(626) 991-2099', ARRAY['English', 'Vietnamese']::text[], 'Mental Health', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nina-nguy-psy.d.-pmh-c-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/nina-nguy-psy.d.-pmh-c-google-2.webp"], "rating": 5, "reviews": [{"date": "2026-01-30T22:25:57.681808974Z", "text": "I cannot say enough positive things about Nina and the work she does. She is an exceptionally skilled, thoughtful, and compassionate attachment-based and psychodynamic therapist with a depth of clinical experience that is immediately evident in her work. Her presence is warm, grounded, and deeply attuned, and she brings a level of care and intentionality to her clients that truly sets her apart.\n\nShe does beautiful, meaningful work with both individuals and couples and has a nuanced, embodied understanding of trauma and the healing process. She is a true trauma healer—able to hold clients with compassion while also guiding them through transformative work. Her extensive training and experience in evidence-based modalities, particularly trauma work using Accelerated Resolution Therapy (ART) and couples therapy through Emotionally Focused Couples Therapy, allow her to support clients in ways that are both clinically effective and deeply human.\n\nI trust her completely and would never hesitate to refer clients, as well as family and friends, knowing they will be in excellent hands. Her passion, skill, and integrity as a therapist make her an invaluable resource and an outstanding therapist!", "author": "Morgan Silverman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104323142186627358759/reviews"}, {"date": "2024-06-07T20:47:49.901160Z", "text": "I saw Dr. Nguy for one ART session last month. I''ve been carrying a heavy burden of grief since my mom passed away 7 years ago. I''ve had emdr therapy to help with the ptsd, but the grief surrounded me like a shroud. I got used to it and it became the new normal - until my session with Dr. Nguy.\n\nI went in with an open mind but worried that this might not help since the grief has been all encompassing.\n\nIt has been a little while since our session and I can''t believe how much better I feel. There''s a lightness in my chest that I haven''t felt in over a decade. I''m now able to handle conflicts and challenges objectively without feeling the weight of the world on my shoulders. I am able to talk about my mom and even her passing without crying or feeling that trauma all over again. I wish I had known about this sooner.\n\nIf you''re wanting a significant change, give Dr. Nguy a try for ART therapy. One session is a worth a try. It could improve your quality of life immensely.", "author": "V. Whittaker", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103376423603115256925/reviews"}, {"date": "2024-07-20T03:40:44.102323Z", "text": "I saw Dr. Nguy for an ART session this week. I was struggling with a deep insecurity issue that had been plaguing me since early childhood. After one session with her using ART, I am now free from this burden that has infected my life for over 3 decades!!! Thank Dr. Nguy for helping me overcome this challenge, you really made a difference and now I feel so confident and relaxed in myself.", "author": "shelli bailey", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107764242609317709321/reviews"}], "website": "http://www.ocaapsych.com/", "location": {"latitude": 33.6761639, "longitude": -117.8868684}, "services": ["Marriage Counseling", "Neurodiversity-Affirming Therapy", "Vietnamese Services", "Psychological Evaluation for Immigration", "Anxiety Therapy for Asian Professionals", "Trauma Therapy with Accelerated Resolution Therapy", "Perinatal Mental Health", "Asian Parenting"], "insurance": {"notes": "Dr. Nguy does not accept insurance. She explains that insurance companies compromise confidentiality, dictate treatment, and pay low rates, which can lead to provider burnout. Clients can use out-of-network benefits if their plan allows.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Vietnamese-speaking Psychologist", "detail": "Fluent in Vietnamese, serving the local community in Orange County.", "category": "culture"}, {"title": "Free Consultation Available", "detail": "Offers a free consultation for prospective clients.", "category": "access"}, {"title": "Cycle Breaker Focus", "detail": "Specializes in helping individuals and couples break intergenerational cycles of trauma.", "category": "care"}, {"title": "Neurodiversity-Affirming", "detail": "Provides affirming therapy for neurodivergent individuals, including parents, adults, and teens.", "category": "care"}, {"title": "Online & In-Person", "detail": "Offers both in-person sessions in Costa Mesa and online therapy throughout California.", "category": "convenience"}, {"title": "PMH-C Certified", "detail": "Holds the Perinatal Mental Health Certification (PMH-C).", "category": "care"}], "price_tier": "$$", "source_url": "http://www.ocaapsych.com/", "appointment": {"booking_note": "Schedule a free consultation via the contact page.", "appointment_url": "http://www.ocaapsych.com/contact", "new_patient_note": "Free consultation available for new clients.", "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": true}, "open_sunday": false, "scout_query": "Vietnamese mental health counseling in Orange County, CA", "search_text": "mental health | psychiatry | psychiatrist | psychology | therapist | counseling | depression | anxiety | tâm lý | tâm thần | trầm cảm | 정신과 | 심리상담 | 心理医生 | 精神科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | marriage counseling | neurodiversity-affirming therapy | vietnamese services | psychological evaluation for immigration | anxiety therapy for asian professionals | trauma therapy with accelerated resolution therapy | perinatal mental health | asian parenting | evaluation | nina nguy | psychologist", "google_types": ["medical_clinic", "health", "point_of_interest", "service", "establishment"], "open_weekend": false, "rating_count": 3, "team_members": [{"name": "Nina Nguy", "role": "Psychologist", "bio_snippet": "Dr. Nina Nguy, Psy.D., PMH-C, is a 1.5-generation Vietnamese-speaking Psychologist in Orange County. She specializes in cycle-breaking therapy, marriage counseling, neurodiversity-affirming therapy, and immigration evaluations.", "languages_spoken": ["Vietnamese", "English"]}], "language_note": "Dr. Nina Nguy is a 1.5-generation Vietnamese-speaking psychologist who understands the unique struggles of navigating cultural expectations and the stigma around mental health. She emphasizes breaking intergenerational cycles of trauma common in many Asian families and provides culturally competent care for Vietnamese and Asian clients in Orange County.", "open_saturday": false, "quality_score": 95, "working_hours": {"friday": "Closed", "monday": "9:00 AM – 3:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 7:00 PM", "saturday": "Closed", "thursday": "8:00 AM – 7:00 PM", "wednesday": "8:00 AM – 7:00 PM"}, "gallery_images": ["http://images.squarespace-cdn.com/content/v1/636065a1dd7bb01f92c99305/41f6aec0-8105-4e2a-af23-3982d21d7659/Untitled+design+%2810%29.png?format=1500w", "https://images.squarespace-cdn.com/content/v1/636065a1dd7bb01f92c99305/528ef55d-4dd5-4bcb-a1c1-777b59876b2a/Crystal-Ice-4-imgg-gi3-zvh_fz_z.png", "https://images.squarespace-cdn.com/content/v1/636065a1dd7bb01f92c99305/ec931e0b-8a20-44fe-baf7-3dd33d5b79cb/2024.03.24.13.20.50_003.jpg", "https://images.squarespace-cdn.com/content/v1/636065a1dd7bb01f92c99305/1671591612475-SYVDHZFCOYLBNI74HERP/unsplash-image-_6HzPU9Hyfg.jpg"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 3, "sentiment": "Positive", "summary_quote": "Reviewers highlight Dr. Nguy''s exceptional skills, depth of clinical experience, and expertise in trauma and couples therapy."}, {"theme": "Treatment Outcomes", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients report significant improvements in trauma, grief, and long-standing insecurities after ART sessions."}, {"theme": "Compassion and Attunement", "mentions": 2, "sentiment": "Positive", "summary_quote": "Dr. Nguy is described as warm, grounded, and deeply attuned, with a level of care that sets her apart."}, {"theme": "Accelerated Resolution Therapy (ART)", "mentions": 2, "sentiment": "Positive", "summary_quote": "Multiple patients credit ART sessions with Dr. Nguy for life-changing relief from long-term emotional burdens."}, {"theme": "Grief and Trauma Healing", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients emphasize Dr. Nguy''s ability to help them process grief and trauma effectively, leading to lasting emotional relief."}], "summary": "Patients consistently praise Dr. Nina Nguy for her exceptional skills, compassionate approach, and transformative results, particularly with trauma and grief using Accelerated Resolution Therapy (ART).", "review_count": 3, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-01-30T22:25:57.681808974Z", "text": "I cannot say enough positive things about Nina and the work she does. She is an exceptionally skilled, thoughtful, and compassionate attachment-based and psychodynamic therapist with a depth of clinical experience that is immediately evident in her work. Her presence is warm, grounded, and deeply attuned, and she brings a level of care and intentionality to her clients that truly sets her apart.\n\nShe does beautiful, meaningful work with both individuals and couples and has a nuanced, embodied understanding of trauma and the healing process. She is a true trauma healer—able to hold clients with compassion while also guiding them through transformative work. Her extensive training and experience in evidence-based modalities, particularly trauma work using Accelerated Resolution Therapy (ART) and couples therapy through Emotionally Focused Couples Therapy, allow her to support clients in ways that are both clinically effective and deeply human.\n\nI trust her completely and would never hesitate to refer clients, as well as family and friends, knowing they will be in excellent hands. Her passion, skill, and integrity as a therapist make her an invaluable resource and an outstanding therapist!", "author": "Morgan Silverman", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104323142186627358759/reviews"}, {"date": "2024-06-07T20:47:49.901160Z", "text": "I saw Dr. Nguy for one ART session last month. I''ve been carrying a heavy burden of grief since my mom passed away 7 years ago. I''ve had emdr therapy to help with the ptsd, but the grief surrounded me like a shroud. I got used to it and it became the new normal - until my session with Dr. Nguy.\n\nI went in with an open mind but worried that this might not help since the grief has been all encompassing.\n\nIt has been a little while since our session and I can''t believe how much better I feel. There''s a lightness in my chest that I haven''t felt in over a decade. I''m now able to handle conflicts and challenges objectively without feeling the weight of the world on my shoulders. I am able to talk about my mom and even her passing without crying or feeling that trauma all over again. I wish I had known about this sooner.\n\nIf you''re wanting a significant change, give Dr. Nguy a try for ART therapy. One session is a worth a try. It could improve your quality of life immensely.", "author": "V. Whittaker", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103376423603115256925/reviews"}, {"date": "2024-07-20T03:40:44.102323Z", "text": "I saw Dr. Nguy for an ART session this week. I was struggling with a deep insecurity issue that had been plaguing me since early childhood. After one session with her using ART, I am now free from this burden that has infected my life for over 3 decades!!! Thank Dr. Nguy for helping me overcome this challenge, you really made a difference and now I feel so confident and relaxed in myself.", "author": "shelli bailey", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107764242609317709321/reviews"}]}, "review_summary": "Patients consistently praise Dr. Nina Nguy for her exceptional skills, compassionate approach, and transformative results, particularly with trauma and grief using Accelerated Resolution Therapy (ART).", "about_highlight": "Dr. Nina Nguy is a Vietnamese-speaking Psychologist in Orange County specializing in neurodiversity-affirming therapy, marriage counseling, and immigration evaluations. She works with individuals and couples who are ready to break free from cycles of anger, hurt, and disconnection. Her practice is deeply rooted in cultural competence, serving Asian professionals, cycle breakers, and those navigating intergenerational trauma, with both in-person and online therapy available in California.", "appointment_url": "http://www.ocaapsych.com/contact", "google_maps_url": "https://maps.google.com/?cid=9935757009624987325&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJK0SghMbb3IARvXZLvVvm4ok", "quality_missing": ["insurance"], "search_keywords": ["mental health", "psychiatry", "psychiatrist", "psychology", "therapist", "counseling", "depression", "anxiety", "tâm lý", "tâm thần", "trầm cảm", "정신과", "심리상담", "心理医生", "精神科", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt", "marriage counseling", "neurodiversity-affirming therapy", "vietnamese services", "psychological evaluation for immigration", "anxiety therapy for asian professionals", "trauma therapy with accelerated resolution therapy", "perinatal mental health", "asian parenting", "evaluation", "nina nguy", "psychologist"], "cultural_context": "Dr. Nina Nguy is a 1.5-generation Vietnamese-speaking psychologist who understands the unique struggles of navigating cultural expectations and the stigma around mental health. She emphasizes breaking intergenerational cycles of trauma common in many Asian families and provides culturally competent care for Vietnamese and Asian clients in Orange County.", "services_offered": [{"name": "Marriage Counseling", "category": "Mental Health", "description": "Couples therapy to break cycles of anger, hurt, and disconnection.", "is_featured": false, "patient_fit": "Couples seeking to improve their relationship and communication."}, {"name": "Neurodiversity-Affirming Therapy", "category": "Mental Health", "description": "Support for neurodivergent individuals including parents, adults, and teens.", "is_featured": false, "patient_fit": "Neurodivergent individuals and their families."}, {"name": "Vietnamese Services", "category": "Mental Health", "description": "Therapy provided in Vietnamese for the local community.", "is_featured": false, "patient_fit": "Vietnamese-speaking individuals and families."}, {"name": "Psychological Evaluation for Immigration", "category": "Evaluation", "description": "Psychological assessments to support immigration cases.", "is_featured": false, "patient_fit": "Individuals needing evaluations for immigration purposes."}, {"name": "Anxiety Therapy for Asian Professionals", "category": "Mental Health", "description": "Targeted therapy for anxiety experienced by Asian professionals.", "is_featured": false, "patient_fit": "Asian professionals dealing with work-related anxiety."}, {"name": "Trauma Therapy with Accelerated Resolution Therapy", "category": "Mental Health", "description": "Evidence-based trauma therapy using Accelerated Resolution Therapy (ART).", "is_featured": false, "patient_fit": "Individuals with a history of trauma."}, {"name": "Perinatal Mental Health", "category": "Mental Health", "description": "Support for individuals experiencing perinatal mental health challenges.", "is_featured": false, "patient_fit": "Pregnant and postpartum individuals."}, {"name": "Asian Parenting", "category": "Mental Health", "description": "Therapy addressing the unique challenges of Asian parenting.", "is_featured": false, "patient_fit": "Asian parents and families."}], "short_description": "A Vietnamese-speaking psychologist in Orange County providing individual and couples therapy, neurodiversity-affirming care, and psychological evaluations for immigration — in-person and online.", "google_website_url": "http://www.ocaapsych.com/", "google_primary_type": "Medical Clinic", "provider_credentials": {"education": [], "providers": ["Nina Nguy"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "2900 Bristol St Ste D106, Costa Mesa, CA 92626, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/111385512992867717344", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU5qMUE45VDTVRf9s-sr3cfBQkBhAZiyZK34N49nKX0CiR3_t8=s100-p-k-no-mo", "displayName": "Nina Nguy, Psy.D."}], [{"uri": "https://maps.google.com/maps/contrib/111385512992867717344", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU5qMUE45VDTVRf9s-sr3cfBQkBhAZiyZK34N49nKX0CiR3_t8=s100-p-k-no-mo", "displayName": "Nina Nguy, Psy.D."}]]}'::jsonb, '2026-06-26T12:55:33.022214+00:00', 'nina-nguy-psyd-pmh-c', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('9a454bc2-db38-42bc-8401-e4b41c5abe78', NULL, 'Brainpower Wellness Institute', 'Brainpower Wellness Institute is a mental health and wellness clinic dedicated to providing comprehensive care for individuals seeking to improve their cognitive and emotional well-being. The institute offers a range of services including therapy, counseling, and wellness programs designed to support mental health and personal growth. With a focus on holistic and evidence-based approaches, Brainpower Wellness Institute aims to empower patients to achieve their full potential.', '2230 W Chapman Ave #212, Orange, CA 92868', 'Orange', 'CA', '92868', '(714) 712-0711', ARRAY['English', 'Vietnamese']::text[], 'Mental Health', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/brainpower-wellness-institute-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/brainpower-wellness-institute-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/brainpower-wellness-institute-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/brainpower-wellness-institute-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/brainpower-wellness-institute-google-5.webp"], "rating": 4.9, "reviews": [{"date": "2026-01-09T21:14:14.591038819Z", "text": "I came here when I was in an extremely bad place and Charles Scribner helped me immediately. He is the best and I highly recommend him. He’s cautious, caring, patient, listens and really tries to do the best of his ability to help you in any way he can. He really does have a heart and passion for his work. Thank you Brainpower for having such an outstanding psychiatric nurse.", "author": "Daniel Lloyd", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102815309781618940639/reviews"}, {"date": "2026-03-04T03:28:24.397760658Z", "text": "I was able to schedule an appointment the same week when needed, Sara has been a great help, she listens,  dedicates plenty of time needed to discuss issues, medication, and recommendations.  I really recommend her. 👍", "author": "imelda salazar", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113946925443254740951/reviews"}, {"date": "2026-02-13T09:50:03.778923104Z", "text": "Dr. May Vang is amazing. She always creates a safe space for me to talk, and how she understands emotions and expresses suggestions is one of the most helpful things I’ve experienced.\n\nShe stays neutral, as in she won’t fuel any negative emotions you already have going into the session. Instead, she will work through them with you starting from the root cause.\n\nTalking to my friends, they offer surface level validation, but sometimes validation can be a double edged sword that can fuel negative emotions. I could feel the difference between professional and unprofessional help when talking with May Vang. Rather than simple validation, she pulled information from my words and from there, started telling me about what I may have been experiencing, and on top of that, gave me guidance about how to process and cope with my emotions. She is very realistic as well. She catches my expectations through my speech, and if harmful to myself, will point it out and connect me back to the reality of my circumstances. It’s done in a way where it’s comforting, where I know now that my emotions of frustration with my emotions have been because I tried to overcome my emotions through repression and holding unrealistic expectations for recovery.\n\nI felt no judgement nor scrutinization after talking to her; instead, I felt a huge burden off my shoulders—as if I had been holding my breath for so long and was finally able to breathe. In her sessions, I can sense her expertise and experience dealing with complex emotions.\n\nWhoever is reading this and thinking of getting help, do not hesitate, even if it’s a “small thing.” I made behavioral changes that were sparked by guidance, and learned how to approach and process difficult emotions with acceptance. Complex emotions are a part of life, and it never hurts to learn about how to approach it in a healthy manner.\n\nShe is truly the epitome of a professional and exceptional doctor.", "author": "Favorite Roses", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117877339152660581020/reviews"}, {"date": "2026-02-13T05:55:40.168161735Z", "text": "Psychiatry services are decent. Was satisfied with my treatment until recently.\n\nScheduling has always been a nightmare between using the portal and being unable to reach a psychiatrist directly. Upon calling I only reach a receptionist who does not seem to have access to the psychiatrist’s direct schedule. It’s a lot of back and forth from there to set up an appointment or reschedule.\n\nRecently, I needed to meet before our scheduled time, and sent multiple messages asking to schedule. Typically, the psychiatrist or receptionist has at the very least responded in their own portal even when I didn’t express a concern. In this instance where I expressed a concern with treatment, I received no response within a week. This was moderately disappointing, and is leading me to question continuing treatment with BWI.", "author": "Theodore W", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/110790389537534783803/reviews"}, {"date": "2025-12-04T18:34:39.242517283Z", "text": "Dr Samir is an excellent listener. He analyzed my situation accurately and carefully. Instead of writing a Rx, he let me work with him to find the best solution for me at the time. I felt empowered, appreciated, cared for and helped professionally.", "author": "Elif Doganalp", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107144323219337969475/reviews"}], "website": "https://bpwimh.com/", "location": {"latitude": 33.7876283, "longitude": -117.87661409999998}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "price_tier": "$$", "source_url": "https://bpwimh.com/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": true, "scout_query": "Vietnamese mental health counseling in Orange County, CA", "search_text": "mental health | psychiatry | psychiatrist | psychology | therapist | counseling | depression | anxiety | tâm lý | tâm thần | trầm cảm | 정신과 | 심리상담 | 心理医生 | 精神科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt", "google_types": ["doctor", "medical_clinic", "health", "point_of_interest", "service", "establishment"], "open_weekend": true, "rating_count": 366, "open_saturday": true, "quality_score": 80, "working_hours": {"friday": "8:00 AM – 9:00 PM", "monday": "8:00 AM – 9:00 PM", "sunday": "9:00 AM – 6:00 PM", "tuesday": "8:00 AM – 9:00 PM", "saturday": "9:00 AM – 6:00 PM", "thursday": "8:00 AM – 9:00 PM", "wednesday": "8:00 AM – 9:00 PM"}, "review_profile": {"rating": 4.9, "source": "google", "themes": [{"theme": "Clinical Expertise", "mentions": 4, "sentiment": "Positive", "summary_quote": "Reviewers consistently commend the staff for their deep understanding, careful analysis, and effective treatment approaches."}, {"theme": "Communication", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients appreciate the staff''s ability to listen attentively and provide thoughtful, personalized guidance."}, {"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Many reviewers highlight the staff''s caring, patient, and dedicated approach to their work."}, {"theme": "Scheduling", "mentions": 1, "sentiment": "Negative", "summary_quote": "Some patients express frustration with the scheduling process, citing difficulties in reaching psychiatrists directly."}, {"theme": "Treatment Outcomes", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients report feeling empowered and supported in their treatment journeys, with effective solutions tailored to their needs."}], "summary": "Patients overwhelmingly praise Brainpower Wellness Institute for its compassionate and professional care, highlighting the expertise and dedication of its staff. While most reviews are highly positive, some mention challenges with scheduling and communication.", "review_count": 366, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2026-01-09T21:14:14.591038819Z", "text": "I came here when I was in an extremely bad place and Charles Scribner helped me immediately. He is the best and I highly recommend him. He’s cautious, caring, patient, listens and really tries to do the best of his ability to help you in any way he can. He really does have a heart and passion for his work. Thank you Brainpower for having such an outstanding psychiatric nurse.", "author": "Daniel Lloyd", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102815309781618940639/reviews"}, {"date": "2026-03-04T03:28:24.397760658Z", "text": "I was able to schedule an appointment the same week when needed, Sara has been a great help, she listens,  dedicates plenty of time needed to discuss issues, medication, and recommendations.  I really recommend her. 👍", "author": "imelda salazar", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113946925443254740951/reviews"}, {"date": "2026-02-13T09:50:03.778923104Z", "text": "Dr. May Vang is amazing. She always creates a safe space for me to talk, and how she understands emotions and expresses suggestions is one of the most helpful things I’ve experienced.\n\nShe stays neutral, as in she won’t fuel any negative emotions you already have going into the session. Instead, she will work through them with you starting from the root cause.\n\nTalking to my friends, they offer surface level validation, but sometimes validation can be a double edged sword that can fuel negative emotions. I could feel the difference between professional and unprofessional help when talking with May Vang. Rather than simple validation, she pulled information from my words and from there, started telling me about what I may have been experiencing, and on top of that, gave me guidance about how to process and cope with my emotions. She is very realistic as well. She catches my expectations through my speech, and if harmful to myself, will point it out and connect me back to the reality of my circumstances. It’s done in a way where it’s comforting, where I know now that my emotions of frustration with my emotions have been because I tried to overcome my emotions through repression and holding unrealistic expectations for recovery.\n\nI felt no judgement nor scrutinization after talking to her; instead, I felt a huge burden off my shoulders—as if I had been holding my breath for so long and was finally able to breathe. In her sessions, I can sense her expertise and experience dealing with complex emotions.\n\nWhoever is reading this and thinking of getting help, do not hesitate, even if it’s a “small thing.” I made behavioral changes that were sparked by guidance, and learned how to approach and process difficult emotions with acceptance. Complex emotions are a part of life, and it never hurts to learn about how to approach it in a healthy manner.\n\nShe is truly the epitome of a professional and exceptional doctor.", "author": "Favorite Roses", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117877339152660581020/reviews"}, {"date": "2026-02-13T05:55:40.168161735Z", "text": "Psychiatry services are decent. Was satisfied with my treatment until recently.\n\nScheduling has always been a nightmare between using the portal and being unable to reach a psychiatrist directly. Upon calling I only reach a receptionist who does not seem to have access to the psychiatrist’s direct schedule. It’s a lot of back and forth from there to set up an appointment or reschedule.\n\nRecently, I needed to meet before our scheduled time, and sent multiple messages asking to schedule. Typically, the psychiatrist or receptionist has at the very least responded in their own portal even when I didn’t express a concern. In this instance where I expressed a concern with treatment, I received no response within a week. This was moderately disappointing, and is leading me to question continuing treatment with BWI.", "author": "Theodore W", "rating": 3, "source": "google", "author_url": "https://www.google.com/maps/contrib/110790389537534783803/reviews"}, {"date": "2025-12-04T18:34:39.242517283Z", "text": "Dr Samir is an excellent listener. He analyzed my situation accurately and carefully. Instead of writing a Rx, he let me work with him to find the best solution for me at the time. I felt empowered, appreciated, cared for and helped professionally.", "author": "Elif Doganalp", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107144323219337969475/reviews"}]}, "review_summary": "Patients overwhelmingly praise Brainpower Wellness Institute for its compassionate and professional care, highlighting the expertise and dedication of its staff. While most reviews are highly positive, some mention challenges with scheduling and communication.", "about_highlight": "Brainpower Wellness Institute is a mental health and wellness clinic dedicated to providing comprehensive care for individuals seeking to improve their cognitive and emotional well-being. The institute offers a range of services including therapy, counseling, and wellness programs designed to support mental health and personal growth. With a focus on holistic and evidence-based approaches, Brainpower Wellness Institute aims to empower patients to achieve their full potential.", "google_maps_url": "https://maps.google.com/?cid=10968117169646581417&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJTXuMrLUllYARqbalR3SUNpg", "quality_missing": ["services", "insurance", "team_members", "appointment_url"], "search_keywords": ["mental health", "psychiatry", "psychiatrist", "psychology", "therapist", "counseling", "depression", "anxiety", "tâm lý", "tâm thần", "trầm cảm", "정신과", "심리상담", "心理医生", "精神科", "english", "vietnamese", "tiếng việt", "người việt", "bác sĩ việt"], "short_description": "Brainpower Wellness Institute is a mental health and wellness clinic offering therapy, counseling, and wellness programs to support cognitive and emotional well-being.", "google_website_url": "https://bpwimh.com/", "google_primary_type": "Doctor", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "2230 W Chapman Ave #212, Orange, CA 92868, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/114939819267396442509", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUopHBmYMYJSY8hmeVGKo7ZHIrWchZFaU7gWmdk6vrfS4NDfxeO=s100-p-k-no-mo", "displayName": "Brainpower Wellness Institute"}], [{"uri": "https://maps.google.com/maps/contrib/114939819267396442509", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUopHBmYMYJSY8hmeVGKo7ZHIrWchZFaU7gWmdk6vrfS4NDfxeO=s100-p-k-no-mo", "displayName": "Brainpower Wellness Institute"}], [{"uri": "https://maps.google.com/maps/contrib/114939819267396442509", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUopHBmYMYJSY8hmeVGKo7ZHIrWchZFaU7gWmdk6vrfS4NDfxeO=s100-p-k-no-mo", "displayName": "Brainpower Wellness Institute"}], [{"uri": "https://maps.google.com/maps/contrib/114939819267396442509", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUopHBmYMYJSY8hmeVGKo7ZHIrWchZFaU7gWmdk6vrfS4NDfxeO=s100-p-k-no-mo", "displayName": "Brainpower Wellness Institute"}], [{"uri": "https://maps.google.com/maps/contrib/114939819267396442509", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUopHBmYMYJSY8hmeVGKo7ZHIrWchZFaU7gWmdk6vrfS4NDfxeO=s100-p-k-no-mo", "displayName": "Brainpower Wellness Institute"}]]}'::jsonb, '2026-06-26T12:56:06.810465+00:00', 'brainpower-wellness-institute', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('153bbc38-dc5d-4e16-8a24-00995bb8505e', NULL, 'CARDIOCLINIC - Dr. Zaka Khan, MD', 'Dr. Zaka Khan is a cardiologist with specialized training in Cardiac Electrophysiology and Cardiovascular Diseases. His clinical focus includes diagnosis and treatment of complex heart rhythm disorders, including atrial fibrillation, supraventricular tachycardia, ventricular tachycardia, and other arrhythmias. Dr. Khan’s care style is centered on helping patients understand their diagnosis, review available treatment options, and make informed decisions about long-term heart health. His background in electrophysiology allows him to evaluate rhythm concerns ranging from common palpitations to complex arrhythmias requiring advanced testing or procedures.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('efff24fe-0aaf-4f13-87c6-80d02a940599', NULL, 'Union Dental Center', 'Union Dental Center is a family-owned general dental practice located in the heart of Los Angeles, serving the community since 1980 with over 200,000 patient visits. Our dentists collectively have over 90 years of experience and are graduates of USC and other leading dental schools. Our support staff have been a part of the team for over 60 years, ensuring you always see a familiar face. We treat patients of all ages, from young children to seniors, and many have been coming to our clinic for over 30 years.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('21c6a895-4cc8-4144-925a-30bb4e097658', NULL, 'Aria Medical Primary Care Dr Tam Cung', 'Dr. Cung is a primary care physician with more than 10 years of experience. Seeing many older adult patients in nursing, rehab, and assisted living where illness could have been prevented, he opened an outpatient clinic focused on preventative care and reducing medication reliance. His team cares for the entire family, from children to grandparents, and helps patients navigate the complex healthcare system. With a philosophy rooted in food as medicine, minimal medication, and holistic well-being, Dr. Cung and his staff are committed to helping patients live happy and healthy lives.', '3951 Alma Road, ste 402', 'McKinney', 'TX', '75070', '(469) 714-0057', ARRAY['English', 'Vietnamese']::text[], 'Primary Care', FALSE, '{"fax": "(469) 757-2388", "email": "ma@ariamedicalclinic.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/aria-medical-primary-care-dr-tam-cung-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/aria-medical-primary-care-dr-tam-cung-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/aria-medical-primary-care-dr-tam-cung-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/aria-medical-primary-care-dr-tam-cung-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/aria-medical-primary-care-dr-tam-cung-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2025-11-13T04:48:32.145424957Z", "text": "Dr. Cung is knowledgeable, professional, intelligent, and respectful. He intently listens and wisely responds to all data gathered so patient assessments are completely aligned with necessary tests to ensure accurate diagnoses leading to correct treatments and prescriptive measures! Dr. Cung is a refreshing presence to any medical care team!  He values human life and dignity, and he is driven to provide compassionate care for all! Dr. Cung is the BEST!", "author": "Renee Bueche", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110533966081996472939/reviews"}, {"date": "2026-01-13T20:53:51.075788050Z", "text": "I have sent my insurance card and information to their email address to become a new patient as their process states, 30 days ago, with a follow up request 8 days ago, and still no scheduled appointment. I have blue cross, so insurance is not an issue. The lady said they would expedite my request. I called today for a status check and still no resolution. If u don’t want me as a patient, just say that!", "author": "Kayla D", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/108832886982156463247/reviews"}, {"date": "2025-07-30T18:22:38.006465012Z", "text": "I had a wonderful visit to for my issue. The care I received from Doctor Tam Cung was exceptional. They listened attentively to my concerns and provided personalized treatment that yielded positive results. The entire team at the clinic displayed a high level of professionalism and made me feel comfortable throughout my visit. I highly endorse for their excellent service and expertise. Call, Text, Email are available if you need to contact them. His office (3951 Alma Rd ste 402, McKinney, TX 75070) is nice, clean and professional.", "author": "Hung Ho", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100271117909868252405/reviews"}, {"date": "2025-07-29T19:55:54.703403842Z", "text": "***Update*** I received a call from the Office Manager who apologized for my experience. We were able to talk things out and so happy that I received a called to rectify this situation. I hope Dr Cung sees this review and addresses the feedback with his staff. I called Dr. Cung''s office to setup a new patient appointment. I received the answering service and left a message. I never received a call back, so two days later, I called the office again and a gentleman answered. I provided my information thinking I was scheduling an appointment and the gentleman said he would provide my information to the scheduling team and someone will call me back to setup an appointment. Days go by and no one called. So, I called again and a woman answered the phone. She requested that I send the insurance cards via email to validate insurance. I asked her if there was a secure site they could be uploaded to since one of the insurance cards included the social security number. She said no, office policy is to email them. I asked if I could provide the primary insurance via email and the secondary at the time of my appointment since it included a social security number. She said she needed to ask her office manager and would call me back. It''s been over a week and I still have not received a call back. I am disgusted with this staff. I hope they improved their communication.", "author": "Casandra Winbush", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/114743095576068061581/reviews"}, {"date": "2025-01-29T14:55:19.251565Z", "text": "Dr. Tam Cung is the best doctor I’ve seen in my 12 years in the U.S.! He is very knowledgeable, explains everything clearly, and even used the internet to show me exactly which ligaments were affected. Super friendly and attentive. His secretary is also amazing—Amanda Rodriguez managed to fit me into the schedule quickly. Highly recommend!", "author": "Jose Augusto Rizental", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113951058773491402225/reviews"}], "website": "http://www.ariamedicalclinic.com/", "location": {"latitude": 33.159852, "longitude": -96.7151557}, "services": ["Primary Care", "Preventative Care", "Healthcare Navigation"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Same Day Appointment Available", "detail": "Same day appointments are available for patients.", "category": "convenience"}, {"title": "Bilingual Staff (English & Vietnamese)", "detail": "Medical staff can speak English and Vietnamese.", "category": "culture"}, {"title": "Preventative Care Focus", "detail": "Dr. Cung opened the clinic with the main goal of preventative care and getting patients off medications.", "category": "care"}, {"title": "Holistic Care Philosophy", "detail": "Holistic care includes physical, mental, and financial health.", "category": "care"}], "price_tier": "$$", "source_url": "http://www.ariamedicalclinic.com/", "appointment": {"booking_note": "Same Day Appointment Available!", "appointment_url": null, "new_patient_note": null, "phone_booking_available": null, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese speaking medical clinic in Dallas, TX", "search_text": "primary care | family doctor | general practitioner | annual physical | checkup | bác sĩ gia đình | khám tổng quát | nội khoa | 내과 | 가정의학과 | 家庭医生 | 全科医生 | 内科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | preventative care | healthcare navigation | preventive | dr. tam cung | primary care physician", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 25, "team_members": [{"name": "Dr. Tam Cung", "role": "Primary Care Physician", "bio_snippet": "Primary care physician with more than 10 years of experience. Opened the clinic with a focus on preventative care and reducing medication reliance. Philosophy: Food is medicine, the less meds the better, holistic care, and always improve yourself.", "languages_spoken": ["English", "Vietnamese"]}], "language_note": "The clinic''s staff speaks English and Vietnamese, and the website includes a Vietnamese greeting (''Xin Chào!''), indicating culturally responsive care for the Vietnamese-speaking community.", "open_saturday": false, "quality_score": 93, "working_hours": {"friday": "8:00 AM – 4:30 PM", "monday": "8:00 AM – 4:30 PM", "sunday": "Closed", "tuesday": "8:00 AM – 4:30 PM", "saturday": "Closed", "thursday": "8:00 AM – 4:30 PM", "wednesday": "8:00 AM – 4:30 PM"}, "gallery_images": ["http://img1.wsimg.com/isteam/ip/92cd10cd-5bf4-426e-9123-09802c13ab2c/blob-b3b08f4.png/:/cr=t:0%25,l:0%25,w:100%25,h:100%25/rs=w:600,h:600,cg:true"], "review_profile": {"rating": 4.8, "source": "google", "themes": [{"theme": "Compassionate care", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight compassionate care in their feedback."}, {"theme": "Friendly staff", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight friendly staff in their feedback."}, {"theme": "Clear explanations", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight clear explanations in their feedback."}, {"theme": "Comfortable visits", "mentions": 3, "sentiment": "Positive", "summary_quote": "Patients highlight comfortable visits in their feedback."}], "summary": "Aria Medical Primary Care Dr Tam Cung has a 4.8 star Google rating from 25 Google reviews. Patients commonly mention compassionate care, friendly staff, clear explanations, comfortable visits.", "review_count": 25, "concern_themes": [], "positive_themes": ["knowledgeable", "professional", "great bedside manner", "nice location"], "featured_reviews": [{"dat