INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('95ad8e61-7e96-4749-b3e9-8d45ba69c703', NULL, 'Southwest WomanCare OBGYN', 'Southwest WomanCare OBGYN is a comprehensive women''s health clinic located in Houston, TX, offering obstetrics and gynecology services for women of all ages. The team of expert practitioners provides caring expertise that patients can trust, involving them in every step of their health care. Services include well-woman exams, STD testing, modern birth control options, and pregnancy care—from routine to high-risk—to ensure healthy pregnancies and easy deliveries. The clinic is dedicated to excellent care for women at every stage of life, from adolescence through menopause.', '7789 Southwest Fwy, Suite 400, Houston, TX 77074', 'Houston', 'TX', '77074', '(832) 649-4273', ARRAY['English', 'Vietnamese']::text[], 'OB/GYN', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southwest-womancare-obgyn-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southwest-womancare-obgyn-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southwest-womancare-obgyn-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southwest-womancare-obgyn-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southwest-womancare-obgyn-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2026-05-13T01:46:37.695558397Z", "text": "Dr. Bui and Dr. Christie provided exceptional care throughout my entire pregnancy and safely delivered my baby by C-section. From my prenatal visits to delivery, they were compassionate, professional, and attentive to every concern I had. They always took the time to explain everything clearly and made me feel comfortable and supported during such an important time in my life.\n\nDuring my C-section delivery, Dr. Bui, Dr. Christie and the medical team made me feel calm and well cared for, and I am truly grateful for the safe delivery of my baby. Their expertise, kindness, and dedication gave me confidence every step of the way. I highly recommend Dr. Bui and Dr. Christie to anyone looking for an experienced and caring OB-GYN.", "author": "Thu Nguyen", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115955382472682926417/reviews"}, {"date": "2026-02-14T01:25:50.130251986Z", "text": "Dr. Christie is truly one of the best doctors I’ve ever had. She is knowledgeable, thorough, and incredibly good at what she does - but what really sets her apart is how human she is. She’s warm, hilarious, and makes appointments feel so much less intimidating.\n\nI’ve had a complicated women’s health journey, and she has always taken me seriously, listened carefully, and treated me with respect and compassion. I trust her completely, which is not something I say lightly.\n\nIf you’re looking for an OB-GYN who is both clinically excellent and genuinely cares, she is it. I’m so grateful to be her patient.", "author": "Jenna", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/118171225796543990609/reviews"}, {"date": "2026-05-13T02:48:38.994206825Z", "text": "dr bui is amazing at making you feel comfortable and always seems to be able to distract you from what she''s doing, shes amazing!", "author": "m f", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/112011095835954951185/reviews"}, {"date": "2025-11-05T05:26:30.609657773Z", "text": "Worst office i have ever been to. Gotten a call about my test results and was told a lie. Had given me misinformation. Very inaccurate and now no one knows wth is going on. Called numerous (11) times and call was ignored. Called from another number and they answered. These ppl are a joke and they arent on one accord at all! I would stay far away. My refund better be issued to me ASAP. On top of all that calling i did, and complaints that were made. Management still has not contacted me to rectify the situation or address my concerns. My biggest mistake was not recording the Call when I was given wrong info. You can get sued for giving ppl wrong info, im staying on top of this one real tough. You ppl suck!", "author": "Shereika Thompson", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/111725988155400444355/reviews"}, {"date": "2025-04-17T03:16:43.636614Z", "text": "Dr. Alexandra Christie / Dr. Bui is excellent.\nDr. Christie was our primary doctor.\nThey provided helpful insight throughout our pregnancy as we had a lot of novice questions as we were first time parents.\n\nThe fact that we were able to pull off a baby delivery naturally with zero complications in a newly settled city with no one to help us still amazes me. A lot of   that credit goes to those doctors", "author": "Praful Premadas", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117144174634535793208/reviews"}], "website": "http://www.swwobgyn.com/", "location": {"latitude": 29.6927699, "longitude": -95.52394249999999}, "services": ["Polycystic Ovarian Syndrome", "Birth Control", "Pap Smears", "Pregnancy", "STD Testing", "Fibroids", "Menopause", "Adolescent and Teenage Care"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Caring Expertise That You Can Trust", "detail": "Our team of obstetric