INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('4e098e5e-ce24-4127-aec8-50386f9d8cb8', NULL, 'New Welling Physical Therapy and Acupuncture Clinic 張譯之醫生團隊', 'The provided source content is a parked GoDaddy domain page with no clinic-related information. It does not contain any content about New Welling Physical Therapy and Acupuncture Clinic 張譯之醫生團隊. There is no about section, services, team, location, or other clinic details available from this source.', '139 Centre St Ste 318, New York, NY 10013', 'New York', 'NY', '10013', '(718) 321-3600', ARRAY['English', 'Chinese']::text[], 'Ophthalmology', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/new-welling-physical-therapy-and-acupuncture-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/new-welling-physical-therapy-and-acupuncture-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/new-welling-physical-therapy-and-acupuncture-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/new-welling-physical-therapy-and-acupuncture-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/new-welling-physical-therapy-and-acupuncture-clinic-google-5.webp"], "rating": 4.1, "reviews": [{"date": "2021-08-23T04:35:17.224805Z", "text": "I genuinely cannot stop talking about this place! I came in for early onset carpel tunnel in my hands, wrists, arms, and shoulders and just by looking at my arms they knew exactly where the pain was and what to do. I received massage, acupuncture, electrode therapy, heat therapy, and a treatment plan with such attentive care. I had many questions about other areas of concern and the doctor was very specific on what to eat and not to. Without doing any tests he knew my 8 constitution body type. Very sterile and clean place. Saw immediate results and felt immediately better. I’ve been dealing with my carpel tunnel for about a year trying massages, stress balls, & different massage guns, yet in one session with Dr Zhong I’ve never felt better. I’m excited for my next appointment! Thank you so much", "author": "Grace Hong", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115989303114142369896/reviews"}, {"date": "2025-01-14T01:25:10.721158Z", "text": "I was introduced to this clinic by my sister, and I am happy to say my experience has only been good. I have come here multiple times in the last few years to treat knots in my body and tendonitis in my arms and hands. Dr Zhang and the massage therapist can speak Cantonese and Mandarin, and can understand some basic English. For specific questions in English, using a translation app would be useful. You can make an appointment beforehand, but I think they mainly take patients via walk-in, so wait times can be up in the air. Seeing the doctors here is definitely worth any kind of wait! I always go for the combo treatment (massage, acupuncture, cupping, and electrode therapy)!", "author": "J. Zeng", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/106143494761897272664/reviews"}, {"date": "2021-01-13T23:30:32.541312Z", "text": "Doctor Zhang is very experienced with Chinese traditional medicine. I visited for my spraining knee from snowboarding. His team treated me with acupuncture, cupping and tuina (message). The bruise immediately looked much better than before and appeared lighter than before. I would recommend Doctor Zhang to my friends!\n\nAttached the new office hour for COVID.", "author": "Jacqueline Chen", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113881463275862758509/reviews"}, {"date": "2022-12-11T15:56:56.299287Z", "text": "The doctor and the receptionist are not respecting people’s time. And I found the receptionists are extremely rude and got such a horrible attitude !  But the doctor is actually nice and skillful. We made reservations at 9am many times, and sometimes only couple minutes late cuz the traffic. And then you need to wait for 2 hours to get in, additionally, there is no order at all, sometimes when people come later than you , but they just got in before you despite you have waited for hours already!!!!", "author": "Nina", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/108042312883695744442/reviews"}, {"date": "2022-12-07T14:54:59.993828Z", "text": "I called the counter, and the man who answered was unclear about the prices. The first time I went for a consultation, the doctor was friendly and skilled; the massage cost $20 and acupuncture $50. The whole service, including massage, cupping, electrotherapy, and acupuncture, cost $70. The second time, I wanted a follow-up appointment and only wanted acupuncture, but the counter staff said acupuncture alone would cost $60. This makes me suspect price gouging. The counter staff were extremely rude and quoted inflated prices; their service was appalling.", "author": "Joshua", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/118103595412751155055/reviews"}], "website": "https://questwise.us/products/anti-fatigue-nutritional-eye-patches#", "location": {"latitude": 40.7175205, "longitude": -74.00081449999999}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "price_tier": "$$", "source_url": "ht