INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('4fdc5b2c-3c40-4944-8c88-25a53e02ef35', NULL, 'Wilshire Cardiology Group', 'Wilshire Cardiology Group is a dedicated heart clinic run by a multi-disciplinary team of cardiac professionals. The clinic focuses on excellence in clinical treatment for patients and their families, striving for the best results through teamwork, vision, and the practical application of academic inquiry and research to healing heart diseases. They offer a comprehensive cardiology program including treatment of a full range of cardiovascular disorders and diseases such as angina, antiplatelet therapy, arrhythmia, congestive heart failure, lipid disorders, and coronary artery disease.', '500 S. Virgil Ave. Suite 200, Los Angeles, CA 90020', 'Los Angeles', 'CA', '90020', '(213) 387-8000', ARRAY['English', 'Korean']::text[], 'Cardiology', FALSE, '{"email": "info@wilshirecardiology.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/wilshire-cardiology-group-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/wilshire-cardiology-group-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/wilshire-cardiology-group-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/wilshire-cardiology-group-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/wilshire-cardiology-group-google-5.webp"], "rating": 4, "reviews": [{"date": "2021-04-22T02:00:49.006474Z", "text": "A close family friend recommended this clinic so I wasn''t expecting much. I was surprised by how friendly the staff were and especially how friendly the doctor was. I felt nervous being at a new place, but the doctor and staff made me feel comfortable during and after the appointment. The restrooms and rooms are also super clean as well as regularly santizied. Thank you for the pleasant experience.", "author": "이진숙", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108637219414404098450/reviews"}, {"date": "2021-03-09T23:10:42.545680Z", "text": "I had wonderful and warm experience from start to finish by Dr. Steve. Park and Eun Y. Kim NP on my first ever health exam. They explained everything to me in a very clear manner. All of the staff was great.", "author": "JJ Lee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102714160664270007993/reviews"}, {"date": "2018-01-03T06:20:33.172Z", "text": "Very kind people", "author": "Kevin Kim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113297014818614027696/reviews"}], "website": "https://wcgcenter.com/", "location": {"latitude": 34.064994899999995, "longitude": -118.28672809999998}, "services": ["Comprehensive Cardiology Program", "Varicose Veins Treatment"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Multi-disciplinary team", "detail": "Run by a multi-disciplinary team of cardiac professionals focusing on teamwork and clinical excellence.", "category": "care"}, {"title": "Comprehensive cardiology program", "detail": "Treatment of a full range of cardiovascular disorders including angina, arrhythmia, congestive heart failure, coronary artery disease, and more.", "category": "care"}, {"title": "Academic research driven", "detail": "Practical application of academic inquiry and research to healing heart diseases.", "category": "care"}], "price_tier": "$$", "source_url": "https://wcgcenter.com/", "appointment": {"booking_note": "Mon-Fri 8 to 5 by appointment only", "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": null, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean cardiology clinic in Los Angeles, CA", "search_text": "cardiology | cardiologist | heart doctor | ekg | blood pressure | tim mạch | bác sĩ tim | 심장내과 | 心脏科 | 心血管 | english | korean | 한국어 | 한인 | 한국말 | comprehensive cardiology program | varicose veins treatment | dr. steve park | physician", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 6, "team_members": [{"name": "Dr. Steve Park", "role": "Physician", "bio_snippet": "Completed medical education at the University of Minnesota, internship and residency at Northwestern University.", "languages_spoken": []}], "open_saturday": false, "quality_score": 93, "working_hours": {"friday": "9:00 AM – 5:00 PM", "monday": "8:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "8:00 AM – 5:00 PM", "wednesday": "8:00 AM – 5:00 PM"}, "gallery_images": ["https://wcgcenter.com/static/media/navbar-logo.51c76d147841c2cfac45.png", "https://wcgcenter.com/static/media/aboutWCG.a25a5744fd125d45a479.png", "https://wcgcenter.com/static/media/physicians.b40edb5ad7232056e63a.png", "https://wcgcenter.com/static/media/varicose_veins.1ae144cd1916a125b5a6.png"], "review_profile": {"rating": 4, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 3, "sentiment": "Positive", "summary_quote": "Every reviewer highlights friendly, knowledgeable staff who make patients feel comfortable."}, {"theme": "Facility Environment", "mentions": 1, "sentiment": "Positive", "summary_quote": "Patients appreciate the clean and well-sanitized facilities."}, {"theme": "Communication", "mentions": 1, "sentiment": "Positive", "summary_quote": "Staff and doctors are praised for explaining procedures and results clearly."}], "summary": "Patients consistently praise Wilshire Cardiology Group for its friendly and professional staff, clean facilities, and clear communication during appointments.", "review_count": 6, "concern_themes": [], "positive_themes": [], "featured_reviews": [{"date": "2021-04-22T02:00:49.006474Z", "text": "A close family friend recommended this clinic so I wasn''t expecting much. I was surprised by how friendly the staff were and especially how friendly the doctor was. I felt nervous being at a new place, but the doctor and staff made me feel comfortable during and after the appointment. The restrooms and rooms are also super clean as well as regularly santizied. Thank you for the pleasant experience.", "author": "이진숙", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108637219414404098450/reviews"}, {"date": "2021-03-09T23:10:42.545680Z", "text": "I had wonderful and warm experience from start to finish by Dr. Steve. Park and Eun Y. Kim NP on my first ever health exam. They explained everything to me in a very clear manner. All of the staff was great.", "author": "JJ Lee", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102714160664270007993/reviews"}, {"date": "2018-01-03T06:20:33.172Z", "text": "Very kind people", "author": "Kevin Kim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113297014818614027696/reviews"}]}, "review_summary": "Patients consistently praise Wilshire Cardiology Group for its friendly and professional staff, clean facilities, and clear communication during appointments.", "about_highlight": "Wilshire Cardiology Group is a dedicated heart clinic run by a multi-disciplinary team of cardiac professionals. The clinic focuses on excellence in clinical treatment for patients and their families, striving for the best results through teamwork, vision, and the practical application of academic inquiry and research to healing heart diseases. They offer a comprehensive cardiology program including treatment of a full range of cardiovascular disorders and diseases such as angina, antiplatelet therapy, arrhythmia, congestive heart failure, lipid disorders, and coronary artery disease.", "google_maps_url": "https://maps.google.com/?cid=13843450456609948538&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA", "google_place_id": "ChIJO8_83YK4woAReoP0M9jQHcA", "quality_missing": ["insurance", "appointment_url"], "search_keywords": ["cardiology", "cardiologist", "heart doctor", "ekg", "blood pressure", "tim mạch", "bác sĩ tim", "심장내과", "心脏科", "心血管", "english", "korean", "한국어", "한인", "한국말", "comprehensive cardiology program", "varicose veins treatment", "dr. steve park", "physician"], "services_offered": [{"name": "Comprehensive Cardiology Program", "category": "Cardiology", "description": "Treatment of a full range of cardiovascular disorders and diseases such as angina, antiplatelet therapy, arrhythmia, congestive heart failure, lipid disorders, coronary artery disease.", "is_featured": true, "patient_fit": null}, {"name": "Varicose Veins Treatment", "category": "Cardiology", "description": "Varicose veins often cause symptoms like heaviness, fatigue or lower body aches after standing or sitting for long periods.", "is_featured": false, "patient_fit": "Patients experiencing leg heaviness, fatigue or aches after prolonged standing or sitting."}], "short_description": "A dedicated heart clinic run by a multi-disciplinary team of cardiac professionals, focusing on excellence in clinical treatment for patients and their families.", "google_website_url": "https://wcgcenter.com/", "google_primary_type": "Medical Clinic", "provider_credentials": {"education": [], "providers": ["Dr. Steve Park"], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "google_business_status": "OPERATIONAL", "google_formatted_address": "500 S Virgil Ave #200, Los Angeles, CA 90020, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/103164643003145248357", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUISag93BStvdrKkoX7SOd-T1x_TmoEFZc2E_EN4Hjug8ZYpxM=s100-p-k-no-mo", "displayName": "Wilshire Cardiology Group"}], [{"uri": "https://maps.google.com/maps/contrib/103164643003145248357", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUISag93BStvdrKkoX7SOd-T1x_TmoEFZc2E_EN4Hjug8ZYpxM=s100-p-k-no-mo", "displayName": "Wilshire Cardiology Group"}], [{"uri": "https://maps.google.com/maps/contrib/103164643003145248357", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUISag93BStvdrKkoX7SOd-T1x_TmoEFZc2E_EN4Hjug8ZYpxM=s100-p-k-no-mo", "displayName": "Wilshire Cardiology Group"}], [{"uri": "https://maps.google.com/maps/contrib/100196820951107601242", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjU3UDeUtOacTNY1-XfIro7k_ExAooHPET9QvII1pCk1l-AL-ahxhw=s100-p-k-no-mo", "displayName": "David PARK"}], [{"uri": "https://maps.google.com/maps/contrib/103164643003145248357", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjUISag93BStvdrKkoX7SOd-T1x_TmoEFZc2E_EN4Hjug8ZYpxM=s100-p-k-no-mo", "displayName": "Wilshire Cardiology Group"}]]}'::jsonb, '2026-06-26T13:41:24.567905+00:00', 'wilshire-cardiology-group', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('e1a36d85-c1c1-4f68-8859-4c914c6d1bcf', NULL, 'UCLA Health Cardiovascular Center', 'The UCLA Health Cardiovascular Center in Westwood offers world-class care for all aspects of heart and vascular health. Our multidisciplinary team of experts uses the latest advancements in cardiology to deliver personalized treatment plans. With a focus on innovation, compassion and excellence, the center provides comprehensive cardiac surgery, interventional cardiology, electrophysiology, and more, all backed by UCLA Health''s reputation as one of the most dependable names in healthcare. Patients can expect outstanding customer service and a commitment to achieving optimal heart health and overall well-being.', '100 UCLA Medical Plaza, Suites 545, 630 & 690', 'Los Angeles', 'CA', '90095', '310-825-8816', ARRAY['English', 'Korean']::text[], 'Cardiology', FALSE, '{"fax": "310-825-9013", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ucla-health-cardiovascular-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ucla-health-cardiovascular-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ucla-health-cardiovascular-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ucla-health-cardiovascular-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/ucla-health-cardiovascular-center-google-5.webp"], "rating": 3.5, "reviews": [{"date": "2024-12-13T20:11:56.707525Z", "text": "I''m sharing the experience I had when I brought my dad in for a TAVR, which is a common minimally invasive valve replacement procedure. The nurse support was great -- highly responsive and knowledgeable and kept my review above 1 star. On the day of the procedure, we showed up as instructed before noon for an afternoon appointment. We waited for over 2 hours before someone saw us, which I came to understand is pretty standard. They want you there early in case there''s a cancelation of a prior procedure so the doctors don''t need to wait. OK.\n\nOn this day, we actually waited over 7 hours before they finally canceled and asked us to reschedule. It seems they had other procedures that kept demanding the surgical room we were to use, so we kept getting bumped. The system is very geared to physician/hospital convenience, and perhaps that''s a function of supply and demand, but it''s hard on patients (when they finally canceled, my 83 year old dad had been fasting for almost 24 hours).\n\nMy advice is to schedule the first appointment of the day -- they have you get there at an insane hour (well before you really need to be there in case you get lost on the way, I guess), but it''s better than taking your chances with a later appointment. I''m going to try taking my dad to another hospital and just hope that they do more for patient convenience.", "author": "Reid Bengard", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/110069409299321479824/reviews"}, {"date": "2023-03-03T00:32:01.394503Z", "text": "Seems like these reviews are old - I want to share what a current experience is. My father is a patient at UCLA - he has afib. He got sick last week and was admitted to the ER on his general doctor’s advice as his heart rate had spiked. After 24 hours they discharged him - the ER doctor didn’t really say anything at all. We immediately called his cardiologist and the soonest we could get an appointment was a month out. My father was in the hospital yesterday for heart issues and he can’t even see his heart doctor. UCLA likes to promote itself as one of the best hospitals in the country but that is certainly not the case for normal patients on insurance - the wait times are absolutely insane and there seems to be no method to the madness at all.", "author": "Sam Savage", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/103547993241255856216/reviews"}, {"date": "2025-09-16T00:43:27.227217231Z", "text": "I never do this but I’m on a roll I’ve been battling an infection since I had open heart surgery three years ago my cardiologist thru ucla referred me to dr peter downey I saw him last week terrible experience he was more concerned about why I haven’t seen the cardiac surgeon that originally did the surgery I was completely put a back about that I ended leaving in tears and very frustrated dr downey asked what I want him to do I drove three hours in traffic for that it was literally insane would not recommend", "author": "Dawn Kolleda", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/115430272256467483217/reviews"}, {"date": "2021-05-25T11:17:02.575259Z", "text": "The Doctors and the staff at UCLA Cardiovascular Center and Ronald Reagan Medical Center SAVED MY LIFE. I had a heart transplant last year and they deserve a 100 stars.", "author": "Henry Taroian", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105034753985162956438/reviews"}, {"date": "2020-02-05T22:34:16.810289Z", "text": "Perfect I got to see the Doctor the same day I called for the Appointment, I was seen right away and all my concerns were addressed I do not think there is any better care anywhere knowledgeable, caring Doctors!", "author": "Rebecca French", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101303687777621790515/reviews"}], "website": "https://www.uclahealth.org/locations/cardiovascular-center", "location": {"latitude": 34.065679599999996, "longitude": -118.44569599999998}, "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "World-class cardiovascular care", "detail": "Comprehensive cardiac surgery and interventional cardiology with outstanding customer service.", "category": "care"}, {"title": "Multidisciplinary team", "detail": "Experts using the latest advancements in cardiology for personalized treatment plans.", "category": "care"}, {"title": "Innovation and compassion", "detail": "Dedicated to helping patients achieve optimal heart health with a focus on excellence.", "category": "care"}], "price_tier": "$$", "source_url": "https://www.uclahealth.org/locations/cardiovascular-center?utm_source=google&utm_medium=Yext", "appointment": {"booking_note": null, "appointment_url": "https://cloud.h.uclahealth.org/appointment?id=71&utm_source=uclah_owned&utm_content=cardiovascular-center&utm_campaign=enterprise_aq_request-appointment&utm_medium=location-profile", "new_patient_note": null, "phone_booking_available": null, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean cardiology clinic in Los Angeles, CA", "search_text": "cardiology | cardiologist | heart doctor | ekg | blood pressure | tim mạch | bác sĩ tim | 심장내과 | 心脏科 | 心血管 | english | korean | 한국어 | 한인 | 한국말 | olujimi ajijola, md, phd | electrophysiology | olcay aksoy, md | interventional cardiology | abbas ardehali, md | cardiac surgery | arnold s. baas, md | peyman benharash, md, facs | reshma m. biniwale, md, ms, mchs | noel g. boyle, md, phd | jason s. bradfield, md | nicholas k. brownell, md, phd | eric buch, md | xinjiang cai, md, phd | richard cheng, md | geoffrey w. cho, md | daniel cruz, md, phd | bernardo curi mendes, md | vasc