INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('a70b4d6c-0f4b-4285-957c-c2c396d00f1a', NULL, '金桥中医馆 (Jinqiao Chinese Medicine Clinic)', '金桥中医馆位于纽约曼哈顿唐人街，是一间字号老、信誉好的专业中医馆。我们提供全面的中医诊疗服务，包括内科、外科、妇科、儿科及男科，由两位经验丰富的女中医主理——温德度医师（六十多年临床经验，荣获美国中医名家大奖）和陈兆麟医师（近六十年临床经验）。本馆引进韩式煎药设备，提供代客煎药服务，高压提取药效好，120分钟可取，并支持UPS邮寄至外州。此外，我们还设有新会陈皮专卖店，并接受OTC保健卡。', '73A Eldridge St', 'New York', 'NY', '10002', '(212)334-9443', ARRAY['中文', 'Chinese']::text[], 'Dermatology', FALSE, '{"email": "zhaowq8@gmail.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jinqiao-chinese-medicine-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jinqiao-chinese-medicine-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jinqiao-chinese-medicine-clinic-google-3.webp", "https://lh3.googleusercontent.com/place-photos/AJRVUZNKCcT68_gdq7ucqW2xA7JseyyNWbs-sm1NE2NEsbNSp0dj5YnIeT8dLfEOx1cm3aJUL3VzLSxmt9cP6KbC7SAxgvCPVZT7heOfrr83OWzPmate67bPubTLMMKfa8uffTqJUMHYoHA8AFeAPQ=s4800-w1200", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/jinqiao-chinese-medicine-clinic-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2026-01-22T18:07:07.911109303Z", "text": "Just by pressing on my\nPulse she knew that I haven’t gotten my period in a while", "author": "Bunny Marvel", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102239992493684970370/reviews"}, {"date": "2019-02-26T04:40:29.002596Z", "text": "Recently went there with mixed feelings, the doctor was so patient and helpful, explained everything carefully and respectfully, I recommend it.", "author": "建立ss", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108943674509940525674/reviews"}, {"date": "2023-02-12T21:10:47.246953Z", "text": "The boss was very nice and kind. The Chinese medicine doctor has good techniques.", "author": "kai z", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101521721079520701582/reviews"}, {"date": "2019-05-11T15:46:59.090108Z", "text": "It is very nice doctor and good for everyone. It is very helpful and I appreciate their good service.", "author": "ya chen Yang", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100695483045657712022/reviews"}, {"date": "2019-10-11T02:43:16.175792Z", "text": "Mom and I have been there a couple times. People are friendly. Nice!", "author": "Jen Xue", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116962525542804296976/reviews"}], "website": "http://www.555hk.net/", "location": {"latitude": 40.716876500000005, "longitude": -73.9927356}, "services": ["内科", "外科", "妇科", "儿科", "男科", "代客煎药"], "insurance": {"notes": "接受OTC保健卡（联合、维加、飞达利）。未提及Medicaid、Medicare或商业保险。", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": ["OTC 联合", "OTC 维加", "OTC 飞达利"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "专业中医馆", "detail": "坐落于曼哈顿唐人街，字号老、信誉好，提供内、外、妇、儿全科中医诊疗。", "category": "care"}, {"title": "韩式煎药服务", "detail": "引进韩式高压煎药设备，药效好，120分钟可取药。", "category": "convenience"}, {"title": "UPS邮寄服务", "detail": "煎好的中药可通过UPS邮寄，方便外州客人。", "category": "convenience"}, {"title": "经验丰富的女中医", "detail": "温德度医师和陈兆麟医师均拥有近六十年临床经验，专精妇儿科及疑难杂症。", "category": "care"}, {"title": "美国中医名家大奖", "detail": "温德度医师于2019年荣获美国中医名家大奖殊荣。", "category": "reviews"}, {"title": "接受OTC保健卡", "detail": "接受联合、维加、飞达利等OTC保健卡。", "category": "insurance"}], "price_tier": "$$", "source_url": "http://