INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6fab551b-117a-461a-b93c-4b801b205355', NULL, 'Korean Home Health Care Inc.', 'Korean Home Health Care Inc. is a home health care agency serving the Dallas, TX area. The agency’s mission is to participate as an active part of the community, providing and continuously improving patient recovery and independence by delivering value-driven, high quality and compassionate care. Their team includes fully trained and licensed nurses, home health aides, physical therapists, and social services professionals, offering a comprehensive range of in-home care options.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('0ab5f44b-064e-4098-9f05-456ff1987821', NULL, 'Clinica Hispana Vida Sana', 'Clínica Hispana Vida Sana es una clínica familiar con tres ubicaciones en el norte de Texas (Fort Worth, Plano y Dallas), dedicada a brindar atención médica de excelencia a la comunidad hispana. Nuestro equipo de doctores con experiencia ofrece servicios en español e inglés, incluyendo medicina general, laboratorio, control de diabetes, presión arterial, ultrasonido y rayos X. Con más de 35,000 pacientes atendidos, nos enorgullece ofrecer consultas médicas desde $30 y estamos abiertos los 7 días de la semana para su conveniencia.', '6242 Rufe Snow Dr suite: 220 Fort Worth Texas 76148', 'Fort Worth', 'TX', '76148', '(469)917-8363', ARRAY['English', 'Spanish', 'Vietnamese']::text[], 'Primary Care', FALSE, '{"email": "info@chvidasana.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-hispana-vida-sana-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-hispana-vida-sana-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-hispana-vida-sana-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-hispana-vida-sana-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/clinica-hispana-vida-sana-google-5.webp"], "rating": 4.9, "pricing": [{"name": "Consulta Médica General", "notes": "Precio promocional mencionado en la página principal.", "price": "$30", "category": "exam", "price_range": null}], "reviews": [{"date": "2025-09-09T17:13:22.605445624Z", "text": "Exceptional efficiency and warmth! Our annual exam was perfectly on time with almost no wait at the clinic. The entire staff was welcoming and friendly, and the professionalism throughout was top-tier. A truly impressive practice. Highly recommended.", "author": "Ajaz Karim", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103316732910495210911/reviews"}, {"date": "2026-01-02T22:47:54.528513478Z", "text": "Great service!\nKnowledgeable and empathetic personnel.", "author": "Vania", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107892903732998279207/reviews"}, {"date": "2025-09-23T17:26:43.377935840Z", "text": "Very nice staff and doctor. No rush and wait times like other clinics. Very clean and well-maintained clinic. Very reasonable charge as well.\n5/5.", "author": "Sheetal Panchal", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107108118240637846778/reviews"}, {"date": "2024-09-08T22:13:57.550843Z", "text": "Had a pleasant experience.  They always have trouble drawing blood, but Mariana was the best! She hit my vein on the first try.\nDefinitely recommend.", "author": "TC Dominguez", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117223584161603033286/reviews"}, {"date": "2025-04-08T17:30:27.706673Z", "text": "Doctor Fonseca is a very accurate professional. Everybody here is so kind, they make you feel well and the results are very good. Thanks", "author": "Sonia Romero", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/111379423447326126215/reviews"}], "website": "https://www.clinicahispanavidasana.com/", "location": {"latitude": 32.85849040000001, "longitude": -97.2371639}, "services": ["Medicina General", "Laboratorio", "Examen y Tratamiento de la Diabetes", "Contro