], [{"uri": "https://maps.google.com/maps/contrib/102625239089834291082", "photoUri": "https://lh3.googleusercontent.com/a/ACg8ocKv43o4RR1rPKM3TnE3Y5N6USYWlayQ0u8os1D-zCFfc-m2Qg=s100-p-k-no-mo", "displayName": "B Hailey"}]]}'::jsonb, '2026-06-26T13:51:38.46314+00:00', 'misarang-beauty-m-clinic', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('5d34aa66-ae2e-4e52-b21c-8a6fc0946483', NULL, 'XING ZHANG ACUPUNCTURE & Herbal Medicine', 'Xing Zhang Acupuncture & Herbs Clinic is a dedicated acupuncture and herbal medicine practice located in New York, NY. The clinic offers a range of services including acupuncture, herbal medicine, and related therapeutic treatments. The team, led by experienced practitioners, focuses on providing comprehensive care tailored to individual patient needs. The clinic is committed to transparent pricing with package discounts and assists patients with insurance verification.', '44 E 32nd St, Floor 8, New York, NY 10016', 'New York', 'NY', '10016', '(718) 666-2931', ARRAY['English', 'Chinese']::text[], 'Dermatology', FALSE, '{"email": "xingzhangacupuncture@gmail.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/xing-zhang-acupuncture-herbal-medicine-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/xing-zhang-acupuncture-herbal-medicine-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/xing-zhang-acupuncture-herbal-medicine-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/xing-zhang-acupuncture-herbal-medicine-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/xing-zhang-acupuncture-herbal-medicine-google-5.webp"], "rating": 5, "pricing": [{"name": "Package Discount", "notes": "Discounts available on package purchases for services.", "price": null, "category": "membership", "price_range": null}], "reviews": [{"date": "2026-06-05T13:01:35.842543209Z", "text": "I’ve been going to Dr. Zhang for almost a year and my health has completely improved. I went to him after nothing was working and my friend recommended him, from the first session I felt at ease. Now a year later, I feel mentally and physically better, no more brain fog and less stress spikes. I also really like that he takes personalized proactive holistic approach to address things which helped me address more underlining causes.", "author": "Ro De", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107142293385028190744/reviews"}, {"date": "2026-02-12T16:41:56.206505999Z", "text": "Dr Zhang has been so helpful. I started seeing him during my second round of egg retrieval going weekly for acupuncture sessions. I looked forward to my sessions and seeing him because he kept me on track and gave great advice around healthy habits to do throughout the week. I would definitely recommend his service. I gave 4 stars because unfortunately my insurance didn’t cover it but when you find someone good it’s worth the investment.", "author": "Rolanda Bell", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/107080841824740693874/reviews"}, {"date": "2026-05-22T15:28:23.018999169Z", "text": "Dr Zhang is the best! I originally came to him when I experienced intense nerve pain that no doctor to could give me answers for. After consistently going for a few months I felt insanely better and no longer have the pain anymore. Very knowledgeable and cares", "author": "Cassie Renner", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116388577698653628437/reviews"}, {"date": "2025-10-23T20:18:19.607092940Z", "text": "Dr. Zhang/Johnson is amazing! I started coming to Strive Total Wellness originally for some severe chronic lower back-pain. Shortly after six months, not only is my back-pain now gone, Johnson is helping me in my other health aspects.\n\nI have done cuppings and needles with electricity with Johnson. Each time, I am left feeling better right after the appt. Johnson also gives good advice for my diets (when I do follow it thoroughly, my eczema wouldn’t flare up).\n\nRecently, I switched my back pain concerns (woo hoo!) to focus on my painful periods, and Johnson’s practices have been instrumental in helping me heal and feel better.\n\nI’d definitely recommend Johnson!", "author": "LZ H", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105411543779486801985/reviews"}, {"date": "2026-01-30T14:32:30.176591468Z", "text": "I have been seeing Xing Zhang for herbal blends to remedy a viral infection when western medicine said there was no treatment. The experience is very fast and easy and I’m very grateful for the care!", "author": "Nicole S", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113760105928603992436/reviews"}], "website": "http://www.zhangxingacupuncture.com/", "location": {"latitude": 40.7458692, "longitude": -73.9829669}, "services": ["Acupuncture", "Herbal Medicine"], "insurance": {"notes": "Insurance verification assistance is available. Specific accepted plans are not listed.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Package Discounts Available", "detail": "The clinic offers package discounts on services.", "category": "pricing"}, {"title": "Insurance Verification Assistance", "detail": "The clinic assists with insurance verification for patients.", "category": "insurance"}, {"title": "Located in Midtown Manhattan", "detail": "Conveniently located at 44 E 32nd St, Floor 8, New York, NY 10016.", "category": "convenience"}], "price_tier": "$$", "source_url": "http://www.zhangxingacupuncture.com/", "appointment"