INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('813c1dca-7025-4532-a461-0564bfe78878', NULL, 'Juliette Aiyana, L.Ac. Traditional Chinese Medicine Herbalist', 'Juliette Aiyana, L.Ac., MTCM is a licensed acupuncturist and herbalist specializing in Traditional Chinese Herbal Medicine and holistic tele-health consultations. She takes the time to understand each patient''s unique needs, identifies the root causes of imbalance, and creates personalized wellness plans. Her boutique practice offers virtual online video appointments, with herbs and supplements shipped directly to patients'' doors. Juliette has specialized training in identifying and supporting skin diseases on diverse skin tones and provides affirming care for people of all ages, races, genders, sexual orientations, body sizes, abilities, and cultural or ethnic identities.', '134 W 26th St #903, New York, NY 10001', 'New York', 'NY', '10001', '(646) 504-2251', ARRAY['English', 'Chinese']::text[], 'Dermatology', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/juliette-aiyana-l.ac.-traditional-chinese-medicine-herbalist-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/juliette-aiyana-l.ac.-traditional-chinese-medicine-herbalist-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/juliette-aiyana-l.ac.-traditional-chinese-medicine-herbalist-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/juliette-aiyana-l.ac.-traditional-chinese-medicine-herbalist-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/juliette-aiyana-l.ac.-traditional-chinese-medicine-herbalist-google-5.webp"], "rating": 5, "reviews": [{"date": "2025-12-18T06:03:28.281931732Z", "text": "Juliette has been great! She is kind, caring, helpful, and knowledgable. I have been going to her for LS. So far things have seemed to really improve but I will have to come back and write a review with the final results. The herbs need some more time to reach their potential!", "author": "pamelathings", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107497132319140031005/reviews"}, {"date": "2025-01-28T21:35:11.410331Z", "text": "Our experience with Juliette has been amazing! My toddler was struggling with serve eczema for about a year. We tried all type of steroid creams but nothing worked long term. After working with her for a number of months, my daughter’s eczema is completely gone! Juliette is thorough, reassuring, and has helped my family with a number of issues. Highly recommend!", "author": "Alexis Welch", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110975592940618090046/reviews"}, {"date": "2025-02-15T01:23:58.540027Z", "text": "When I found Juliette, I had actively been experiencing lichen simplex chronicus for over a year. I had been to numerous doctors, specialists, and dermatologists who all just prescribed me steroid cream after steroid cream, despite me telling them that it obviously wasn’t working for me. I was at a point of serious frustration with western medicine. My skin was itchy, red, and not getting any better.\n\nAfter reading positive reviews for Juliette from patients with similar skin conditions, I decided to make an appointment with her. After about 6 months of treatment, my skin has improved DRASTICALLY! The only barrier is that the medicine isn’t covered by insurance so it’s a little pricy but it’s definitely worth it. I tried everything possible before starting Chinese medicine and this was the only thing that made my condition budge.\n\nIn addition, Juliette is very kind, warm, and genuinely cares about you. She listened to me more than any doctor I’ve ever been too. The treatment plan she creates for you is very detailed and takes into account many variables that could be impacting your healing. She also presents to you month to month picture comparisons so you can see your healing journey. I can’t recommend Juliette enough.", "author": "Courtney Quigley", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103490523162167345145/reviews"}, {"date": "2023-05-26T14:45:23.583755Z", "text": "Juliette is great! I have been seeing her for almost 6 months now. She has definitely changed my skin!She is thorough, and has her patients’s holistic goals in mind. Juliette never makes you feel rushed, is attentive, thoughtful and kind. As a plus she is fun person and only recommends what you truly need, without having you send tons on expensive unneeded stuff. Above all she is honest and very clear with process, what to expect. I definitely recommend her!", "author": "brenda mf", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107043012428958341949/reviews"}, {"date": "2023-06-01T21:00:14.065222Z", "text": "I’ve been seeing Juliette for some months now in an attempt to heal my acne that has appeared in adulthood. I tried so many holistic remedies, products, and facials before working with her and have only seen significant improvement with her guidance and the herbs she’s having me take. She has me track my progress in pictures every month which has REALLY helped me see the improvement and keep me motivated to keep getting better. I felt hopeless about my acne for 2 years, and I am so grateful for Juliette and how much she has helped me. She helps you dissect all different areas and aspects of your lifestyle and makes suggestions on even small things you can do to help better yourself and the goals you want to achieve.  I’d really recommend Juliette to anyone looking to heal any of the health conditions she tackles!!!", "author": "Astrid Lopus", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114553085863207905969/reviews"}], "website": "http://www.julietteaiyana.com/", "location": {"latitude": 40.7453297, "longitude": -73.9929523}, "services": ["Dermatology", "Gut & Digestive Health", "Allergies & Immunity", "Pelvic, Menstrual & Hormone Support", "Initial Consultation", "Follow-Up Consultation"], "insurance": {"notes": "No insurance information mentioned on the page. The practice appears to be self-pay based on the consultation booking model.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Virtual Tele-Health Consultations", "detail": "Convenient online video appointments from the comfort of your home.", "category": "convenience"}, {"title": "Personalized Herbal Treatments", "detail": "Customized Chinese herbal formulas and supplements shipped to your door.", "category": "care"}, {"title": "Specialized in Skin of Color", "detail": "Juliette has specialized training in identifying and supporting skin diseases on diverse skin tones.", "category": "culture"}, {"title": "Affirming Care for All", "detail": "Safe and respectful space for people of all ages, races, genders, sexual orientations, body sizes, abilities, and cultural identities.", "category": "culture"}, {"title": "Comprehensive Initial Consultation", "detail": "1.5-hour initial meeting to understand root causes and create a tailored treatment plan.", "category": "care"}], "price_tier": "$$", "source_url": "http://www.julietteaiyana.com/", "appointment": {"booking_note": "Book Now button on the site leads to Acusimple booking page.", "appointment_url": "https://acusimple.com/bookings/1622", "new_patient_note": "Initial consultation is 1.5 hours; follow-ups are 30 minutes monthly.", "phone_booking_available": null, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese dermatology clinic in New York, NY", "search_text": "dermatology | dermatologist | skin doctor | acne | eczema | skin cancer | da liễu | bác sĩ da liễu | 피부과 | 皮肤科 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | gut & digestive health | allergies & immunity | pelvic, menstrual & hormone support | initial consultation | follow-up consultation | gastroenterology | immunology | women''s health | consultation | juliette aiyana | licensed acupuncturist (l.ac.), master of traditional chinese medicine (mtcm), herbalist", "google_types": ["skin_care_clinic", "medical_clinic", "doctor", "consultant", "health", "point_of_interest", "service", "establishment"], "open_weekend": false, "rating_count": 27, "team_members": [{"name": "Juliette Aiyana", "role": "Licensed Acupuncturist (L.Ac.), Master of Traditional Chinese Medicine (MTCM), Herbalist", "bio_snippet": "Takes time to understand each patient''s unique needs, identifies root causes of imbalance, and creates personalized wellness plans. Specialized training in skin diseases on diverse skin tones. Affirming care for all identities.", "languages_spoken": []}], "language_note": "Juliette Aiyana''s practice affirms people of various ages, races, genders, sexual orientations, body sizes, abilities, and cultural or ethnic identities. She stands against systemic bias and oppression in healthcare, creating a safe and respectful space for healing. Her approach integrates Traditional Chinese Herbal Medicine principles.", "open_saturday": false, "quality_score": 95, "working_hours": {"friday": "10:00 AM – 6:00 PM", "monday": "10:00 AM – 6:00 PM", "sunday": "Closed", "tuesday": "10:00 AM – 6:00 PM", "saturday": "Closed", "thursday": "10:00 AM – 6:0