INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('ba13776d-b91f-455e-8e3b-76f721be0c93', NULL, 'Los Angeles Orthopaedic Hospital', 'Los Angeles Orthopaedic Hospital is dedicated to providing outstanding care for patients with musculoskeletal disorders. Through the support of the Orthopaedic Foundation, the hospital ensures that children receive care regardless of their ability to pay. The institution also advances care worldwide for all musculoskeletal patients through medical education and scientific research.', '2400 S. Flower St. Los Angeles CA 90007', 'Los Angeles', 'CA', '90007', '(213) 741-8330', ARRAY['English', 'Korean']::text[], 'Orthopedics', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/los-angeles-orthopaedic-hospital.webp"], "rating": 5, "reviews": [{"date": "2024-12-11T03:27:48.112151Z", "text": "This hospital will always be in my heart. My daughter had surgery there in 1981. She had polio and couldn''t walk. Now she walks and is 47 years old.\n\nI love you for doing such wonderful work for people who don''t have the financial resources to pay for such amazing surgeries and everything else needed for children with orthopedic problems.\nGod bless you.", "author": "Zoy Karmyn", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/117532776467714320446/reviews"}], "website": "http://www.orthohospital.org/", "location": {"latitude": 34.0279162, "longitude": -118.27346840000001}, "services": ["Outpatient Appointments", "Hospital Info / Physician Referral", "Urgent Medical Care", "Hemophilia Center", "Rehabilitation Therapy"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "a