INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('a26108a6-0250-4cf6-8739-8f33694dcfc4', NULL, 'Providence Pediatrics - Redondo Beach', 'Providence Pediatrics - Redondo Beach, part of Providence Medical Institute, provides specialized pediatric care for children from birth to adolescence. Using the latest medical advances, the team offers comprehensive services including well-child visits, sick and urgent care, immunizations, developmental consultations, sport physicals, vision and hearing screenings, prenatal consults, and in-hospital newborn care. Additional areas of focus include nutritional counseling, integrative medicine, weight management, diabetes care, and behavioral health issues like ADHD.', '520 N Prospect Ave, Suite 211, Redondo Beach, CA 90277', 'Redondo Beach', 'CA', '90277', '310-406-2349', ARRAY['English', 'Korean']::text[], 'Pediatrics', TRUE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/providence-pediatrics-redondo-beach-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/providence-pediatrics-redondo-beach-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/providence-pediatrics-redondo-beach-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/providence-pediatrics-redondo-beach-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/providence-pediatrics-redondo-beach-google-5.webp"], "rating": 5, "reviews": [{"date": "2023-03-21T15:05:17.808188Z", "text": "Dr Hannah Kim is the *best*. The office staff is also friendly.", "author": "britt marlowe", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103859634291689857118/reviews"}, {"date": "2025-08-20T01:19:16.361697873Z", "text": "저희 세 아이들은 거의 3년동안 이 소아과를 이용해왔습니다.\nDr. Hannah Kim 선생님은 아이가 언어 발달이 늦다고 느껴졌을 때는 신속하게 스피치 테라피스트에 대한 레퍼럴을 해주셨고, 리저널 센터에 대한 안내를 해주셨습니다.\n어떤 날은 아이가 eczema 증상으로 인해 어린이 피부과를 가야 했고, 어떤 날은 손가락 뼈가 다친 것이 의심이 되어 사진을 찍어야 할 때도 있었습니다. 어떤 날에는 갑작스럽게 아이가 열이 오른뒤 해열제가 들지 않을 때도 있었습니다. 그럴 때마다 병원에서의 신속한 검사 덕분에 아이의 증상을 알 수 있었고 적절한 조치를 취할 수 있었습니다. 저희 세 아이들은 친절하고 신속한 대응을 해주는 이 소아과 덕분에 지난 3년간 건강하게 자랄 수 있었습니다.\n\n저는 한국어가 모국어로서 영어가 능숙하진 않습니다. 다른 지역에서 영어로 아이의 증상을 설명하는 것에는 익숙했지만, 아이에 대해 심도깊은 질문을 하거나, 증상을 자세하게 설명하고 오해없이 이해해야 할 때면 한국어가 편할 수 밖에 없었습니다. 저는 이 지역에 사는 한국어를 쓰는 부모님께도 그런 점에서 Dr.Kim을 추천하고 싶습니다. 그녀는 친절하게 당신에게 설명해주실 것입니다.\n가끔 환자가 많아서 병원 예약시간보다 대기 시간이 길어질 때도 있습니다. 하지만 그외에는 모두 좋았습니다. Providence 앱을 통해 아이의 진료기록이나 메세지를 이용하는 것도 편하고, 직원분들은 모두 친절하게 대해주십니다.\n저희 가족은 타 주로 이사를 하게 되어 소아과를 계속 이용할 수 없게 된 점에 대해서 아쉽지만, 정말 이 곳이 만족스러웠기에 다른 분께 추천드리고 싶습니다. 그동안 감사했습니다!\n\n-----\n\nOur three children have been patients at this pediatrics for nearly three years. When we noticed delays in one of our child’s speech development, she promptly provided a referral to a speech therapist and offered guidance on how to connect with the Regional Center.\n\nThere were days when we needed to see a pediatric dermatologist for eczema, or when we suspected a broken finger and needed imaging. At times, our child had sudden high fevers that didn’t respond to medication. Each time, the clinic conducted quick and thorough evaluations, helping us understand the issue and take appropriate action.\n\nThanks to the kind and responsive care from this clinic, all three of our children have grown up healthy over the past three years.\n\nAnd English is not my strongest language. While I’m used to describing symptoms in English, I often find it more comfortable to explain in detail or ask deeper questions in Korean. That’s why I especially recommend Dr. Kim to other Korean-speaking parents in the area. She is warm, compassionate, and will take the time to explain things clearly.\n\nSometimes the wait time can be a bit long when there are many patients, even with an appointment. But aside from that, everything else has been excellent. The Providence app makes it easy to check records and send messages, and every single staff member we’ve encountered has been kind, caring, and professional.\nOur family is now moving out of state, so we unfortunately won’t be able to continue visiting this pediatrics. We’re truly sad to leave, because our experience here has been so positive. Thank you so much for everything over the years — I wholeheartedly recommend this pediatrics to others.", "author": "Ahyoung Cho", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/116253336477199401514/reviews"}], "website": "https://www.providence.org/locations/socal/redondo-beach-pediatrics", "location": {"latitude": 33.8534426, "longitude": -118.37993239999999}, "services": ["Well Child and Adolescent Care", "Sick and Urgent Care", "Immunizations", "Developmental/Behavioral Consultations", "Sport and Scout Physicals", "Vision and Hearing Screenings", "Prenatal Consults", "In-Hospital Newborn Care", "Nutritional Counseling", "Integrative and Holistic Medicine", "Weight Management and Diabetes Care", "Behavioral Issues and ADHD Management"], "insurance": {"notes": "Coverage may vary by specific plan. Please verify with your insurance provider before visiting us for care. Established patients should call to verify insurance acceptance.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": ["Aetna", "Blue Cross Blue Shield", "Cigna", "Coventry/First Health PPO", "Health Net", "Multiplan PPO", "TRICARE", "UnitedHealthcare"], "out_of_network_available": null, "accepts_private_insurance": true}, "highlights": [{"title": "High Patient Ratings", "detail": "Rated 4.9 out of 5 stars from 93 patient ratings.", "category": "reviews"}, {"title": "Comprehensive Pediatric Care", "detail": "Offers well-child visits, sick care, immunizations, developmental consultations, sport physicals, and more for children from birth to adolescence.", "category": "care"}, {"title": "Wide Insurance Acceptance", "detail": "Accepts a broad range of insurance plans including Aetna, Anthem Blue Cross, Blue Shield, Cigna, Health Net, United Healthcare, and more.", "category": "insurance"}, {"title": "Specialized Focus Areas", "detail": "Additional focus on nutritional counseling, integrative medicine, weight management, diabetes, and behavioral issues like ADHD.", "category": "care"}, {"title": "Convenient Hours", "detail": "Open Monday through Friday from 8 a.m. to 5 p.m.", "category": "convenience"}], "price_tier": "$$", "source_url": "https://www.providence.org/locations/socal/redondo-beach-pediatrics?Is=location&y_source=1_OTU3NTg5NS03MTUtbG9jYXRpb24ud2Vic2l0ZQ%3D%3D", "appointment": {"booking_note": "Return patients can schedule using MyChart. New patients can book a clinic visit or video visit.", "appointment_url": null, "new_patient_note": "New patients can choose between a clinic visit or video visit.", "phone_booking_available": true, "online_booking_available": true, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Korean pediatric clinic in Los Angeles, CA", "search_text": "pediatrics | pediatrician | child doctor | vaccines | newborn | nhi khoa | bác sĩ nhi | khám trẻ em | 소아과 | 소아청소년과 | 儿科 | english | korean | 한국어 | 한인 | 한국말 | well child and adolescent care | sick and urgent care | immunizations | developmental/behavioral consultations | sport and scout physicals | vision and hearing screenings | prenatal consults | in-hospital newborn care | nutritional counseling | integrative and holistic medicine | weight management and diabetes care | behavioral issues and adhd management | preventive | urgent care | consultation | screening | inpatient | wellness | chronic care | behavioral health | aetna | blue cross blue shield | cigna | coventry/first health ppo | health net | multiplan ppo | tricare | unitedhealthcare", "google_types": ["medical_clinic", "doctor", "health", "point_of_interest", "establishment"], "open_weekend": false, "rating_count": 3, "open_saturday": false, "quality_score": 95, "working_hours": {"friday": "8:00 AM – 5:00 PM", "monday": "8:00 AM – 5:00 PM", "sunday": "Closed", "tuesday": "8:00 AM – 5:00 PM", "saturday": "Closed", "thursday": "8:00 AM – 5:00 PM", "wednesday": "8:00 AM – 5:00 PM"}, "gallery_images": ["https://cdn.providence.org/asset/yFLb1VqYY9HClYEBXS943g10/project/psjh/shared/images/locations/thumbnails/pmi-redondobeach-thmb/jpg?rev=d27ce3d855014fbb81a341b8beca0948&hash=3AB9717CB8CD05FACA11E124100C54B6"], "review_profile": {"rating": 5, "source": "google", "themes": [{"theme": "Staff Professionalism", "mentions": 2, "sentiment": "Positive", "summary_quote": "Patients describe the staff as friendly and professional."}, {"theme": "Clinical Expertise", "mentions": 2, "sentiment": "Positive", "summary_quote": "Dr. Hannah Kim is praised for her expertise and quick referrals for specialized care."}, {"theme": "Communication", "mentions": 1, "sentiment": "Positive", "summary_quote": "Dr. Kim is commended for her clear explanations, especially for Korean-speaking families."}, {"theme": "Facility Environment", "mentions": 1, "sentiment": "Neutral", "summary_quote": "The Providence app and overall facility are noted as convenient, though wait times can be long."}, {"theme": "Treatment Outcomes", "mentions": 1, "sentiment": "Positive", "summary_quote": "Patients appreciate the clinic''s role in their children''s healthy growth over three years."}], "summary": "Patients consistently praise Dr. Hannah Kim and the staff at Providence Pediatrics - Redondo Beach for their friendly, professional, and responsive care, particularly highligh