red": false, "patient_fit": "Children and adolescents"}, {"name": "Vision and Hearing Screenings", "category": "Screening", "description": "Screenings to detect vision and hearing issues.", "is_featured": false, "patient_fit": "Children"}, {"name": "Prenatal Consults", "category": "Consultation", "description": "Consultations for expecting parents to prepare for newborn care.", "is_featured": false, "patient_fit": "Expecting parents"}, {"name": "In-Hospital Newborn Care", "category": "Inpatient", "description": "Care for newborns during hospital stays.", "is_featured": false, "patient_fit": "Newborns"}, {"name": "Nutritional Counseling", "category": "Wellness", "description": "Guidance on nutrition for healthy growth and weight management.", "is_featured": false, "patient_fit": "Children and adolescents"}, {"name": "Integrative and Holistic Medicine", "category": "Wellness", "description": "Holistic approaches to pediatric care.", "is_featured": false, "patient_fit": "Children"}, {"name": "Weight Management and Diabetes Care", "category": "Chronic Care", "description": "Management of weight issues and diabetes in children.", "is_featured": false, "patient_fit": "Children and adolescents"}, {"name": "Behavioral Issues and ADHD Management", "category": "Behavioral Health", "description": "Evaluation and treatment for behavioral concerns and ADHD.", "is_featured": false, "patient_fit": "Children and adolescents"}], "short_description": "Providence Pediatrics - Redondo Beach provides specialized pediatric care for children from birth to adolescence, offering well-child visits, sick care, immunizations, and more.", "google_website_url": "https://www.providence.org/locations/socal/redondo-beach-pediatrics?Is=location&y_source=1_OTU3NTg5NS03MTUtbG9jYXRpb24ud2Vic2l0ZQ%3D%3D", "insurance_accepted": ["Aetna", "Blue Cross Blue Shield", "Cigna", "Coventry/First Health PPO", "Health Net", "Multiplan PPO", "TRICARE", "UnitedHealthcare"], "google_primary_type": "Doctor", "provider_credentials": {"education": [], "providers": [], "residency": [], "years_in_practice": null, "board_certifications": [], "hospital_affiliations": [], "professional_memberships": []}, "accepting_new_patients": true, "google_business_status": "OPERATIONAL", "google_formatted_address": "520 N Prospect Ave #211, Redondo Beach, CA 90277, USA", "google_photo_attributions": [[{"uri": "https://maps.google.com/maps/contrib/116102437743534570221", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWnrvd2rezAWBkKowVWB4xVsC6xErtU-3wYQ3AkU1991XLbCJIf=s100-p-k-no-mo", "displayName": "Providence Pediatrics - Redondo Beach"}], [{"uri": "https://maps.google.com/maps/contrib/116102437743534570221", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWnrvd2rezAWBkKowVWB4xVsC6xErtU-3wYQ3AkU1991XLbCJIf=s100-p-k-no-mo", "displayName": "Providence Pediatrics - Redondo Beach"}], [{"uri": "https://maps.google.com/maps/contrib/116102437743534570221", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWnrvd2rezAWBkKowVWB4xVsC6xErtU-3wYQ3AkU1991XLbCJIf=s100-p-k-no-mo", "displayName": "Providence Pediatrics - Redondo Beach"}], [{"uri": "https://maps.google.com/maps/contrib/116102437743534570221", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWnrvd2rezAWBkKowVWB4xVsC6xErtU-3wYQ3AkU1991XLbCJIf=s100-p-k-no-mo", "displayName": "Providence Pediatrics - Redondo Beach"}], [{"uri": "https://maps.google.com/maps/contrib/116102437743534570221", "photoUri": "https://lh3.googleusercontent.com/a-/ALV-UjWnrvd2rezAWBkKowVWB4xVsC6xErtU-3wYQ3AkU1991XLbCJIf=s100-p-k-no-mo", "displayName": "Providence Pediatrics - Redondo Beach"}]]}'::jsonb, '2026-06-26T14:18:27.564083+00:00', 'providence-pediatrics-redondo-beach', NULL, FALSE) ON CONFLICT DO NOTHING;
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('28c8d089-6607-4a3f-a866-02d7abb4847c', NULL, 'Beverly Cardiology Group', 'Beverly Cardiology Group offers exceptional care in the fields of internal medicine and cardiology. They provide expert diagnoses and treatments for those with heart disease, as well as preventive care for those at risk. Their mission is to deliver extraordinary care to every patient by world-class trained cardiologists who are at the top of their field. The clinic is owned by Dr. Il Young Kim and Dr. Diana Kim, and their physicians speak English, Korean, and Spanish, making them accessible to a diverse patient population.', '3919 Beverly Blvd Ste 100', 'Los Angeles', 'CA', '90004', '(323) 662-1175', ARRAY['English', 'Korean', 'Spanish']::text[], 'Cardiology', FALSE, '{"fax": "(323) 662-7817", "email": "info@beverlycardiology.com", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/beverly-cardiology-group.webp"], "rating": 4.8, "reviews": [{"date": "2026-04-10T12:48:15.649070342Z", "text": "Dr Kim is awesome", "author": "Lee Richerson", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/117357201128358410443/reviews"}, {"date": "2022-11-17T16:14:28.409892Z", "text": "I just love it there staff are very nice and helpfully my cardiologist it''s the best I really recommend this place", "author": "Monica Ruiz", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109566928047907514977/reviews"}, {"date": "2026-02-04T18:40:12.772002545Z", "text": "Dr. Diana Kim, thank you always. I sincerely thank you again for your outstanding skills and meticulous judgment in providing meticulous care. I hope your family is always filled with joy and ha