INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('2ec4d4e9-007a-44ae-9ef4-75c2eff2a290', NULL, 'Chinese Acupuncture & Oriental Herbs Clinic', 'Chinese Acupuncture & Oriental Herbs Clinic, also known as Lake City Chinese Acupuncture & Oriental Herbs, is led by Yun Wang, M.D. (China), M.Ac., E.A.M.P., who has over 35 years of experience. Dr. Wang received his medical training at Qingdao Medical College (1978) and acupuncture training at the Northwest Institute of Acupuncture and Oriental Medicine (1993). The clinic specializes in treating musculoskeletal pain, trauma, stroke, and many other medical conditions using Chinese acupuncture and oriental herbs. Dr. Wang also serves as a professor and clinical supervisor at the Seattle Institute of Oriental Medicine, bringing deep expertise and academic rigor to patient care. The clinic serves King and Snohomish County areas including Seattle, Lake City, Shoreline, University District, Mountlake Terrace, Kenmore, Ballard, Fremont, Lynnwood, and Edmonds.', '11046 Lake City Way NE, Seattle, WA 98125', 'Seattle', 'WA', '98125', '206-367-9180', ARRAY['English', 'Chinese']::text[], 'Acupuncture & TCM', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-acupuncture-oriental-herbs-clinic-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-acupuncture-oriental-herbs-clinic-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-acupuncture-oriental-herbs-clinic-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-acupuncture-oriental-herbs-clinic-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/chinese-acupuncture-oriental-herbs-clinic-google-5.webp"], "rating": 4.5, "reviews": [{"date": "2025-12-31T23:12:44.694161537Z", "text": "I should have searched up Chinese acupuncture on my own before going to acupuncture under my insurance. This gentleman/owner is very knowledgeable and kind and has a lot of experience with acupuncture, you can trust in him to help alleviate the pain. I''m going to keep going to him!", "author": "Valerie Reynaga", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/115275521703971224754/reviews"}, {"date": "2025-06-07T22:23:20.892488Z", "text": "I had a dream that I should go inside and talk with the Healers here.\nSo, I did last Monday as I was having Severe Pain.\nI met Dr. Wang. 😇\nA Very Gentle Soul.\nHe gave me a Deeply Sincere Consultation and then he applied my first Acupuncture which was Amazing and Very Relaxing.\nAfter the Session, I was able to Move and Walk So Much Better and I was beyond Amazed how Good I  felt.\nThis was the first time in 8 Years that I was able to walk Without severe pain🙏\nI was Surprised because I had become so used to the pain and being able to walk and drive Without Pain was So Wonderful and Gave Me Great Hope.\nDr. Wang made Specific Teas to take every day, that were made just for my Needs.\nHe Is Extremely Gifted and He Has Such Amazing, Ancient Wisdoms.\nIf You are Truly Seeking Healing,\nDr. Wang is a Sincere,\nKind and Compassionate,\nExtremely Wise Healer Who Can Truly Understand and Help You.\n❤️🤗❤️", "author": "Kelly Kelleher", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/103169132381708882131/reviews"}, {"date": "2023-07-16T17:08:15.199747Z", "text": "I am giving Dr. Want two stars because I really like his friendly personality and his medical training.  I however did not have a good experience here.  I came in for chronic insomnia.  I made the mistake of telling him about the insomnia before he took my pulse, checked my tongue, eyes, etc.  So basically the consultation was pretty poorly done, because he was going off when I described, not my physical conditions.  And the consultation was not good.  Usually you are supposed to sit at a table and have your hands resting when he takes the pulse, but he had me reach my arms out.  He did not ask to see the tongue, and when I suggested it, he looked at it from across the 15 ft wide room.  He never checked my eyes.  He gave me the standard ''formula'' for insomnia which I only took for for 4 of the 8 days, because it made my insomnia 10x worse (it''s still worse now, even 10 days after going off the medication).  The problem is that I should not have been treated for just insomnia, as my insomnia is a symptom of something much bigger.  If you go to see this doctor, I would recommend that you not tell him any symptoms, so that he is forced to take the consultation more seriously.  And the other thing I did not like was that the consultation was $100!  At all other Chinese doctors, the consultation is free (since it''s a 5 minute conversation), and then you just buy the herbs.  I did not negotiate down to $50, but I still felt that was too much money for a 5 minute chat, which was in the end was an incorrect diagnosis.  Other people have had great experiences with him, so I would not write him off, I would just avoid telling him your symptoms so that you can get a more accurate reading of what your body is saying.  He is very experienced and knowledgeable, and I understand that my case is unique.", "author": "LK", "rating": 2, "source": "google", "author_url": "https://www.google.com/maps/contrib/104965083135046454112/reviews"}, {"date": "2016-09-09T08:29:48.981Z", "text": "Dr. Wang is a kind and generous medical professional. He is no common acupuncturist, but in fact, a fully educated MD (his degree is from China). His knowledge in conventional western medicine is comparable to most MDs here and he knows full well what can and cannot be treated through herbal medicines and acupuncture. He would provide you with the most pleasant and accurate medical experience. I highly recommend him.", "author": "Leo Lam, Ph.D.", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/100658780705232598736/reviews"}, {"date": "2019-11-15T22:07:47.306172Z", "text": "Dr. Wang is a very experienced doctor. And he is GOOD!\nI had seen several western medicine doctors and all of them cannot treat the pressure in my ears, which lasted for 2 months. They believed it was because of meniere''s disease.\nDr. Wang did not agree with their diagnose and helped me get rid of the pressure in my ears in 10 days with Chinese herb medicine.", "author": "Tao Ye", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104003727289047085411/reviews"}], "website": "http://www.lakecityacupuncture.com/", "location": {"latitude": 47.7097421, "longitude": -122.30047909999999}, "services": ["Chinese Acupuncture", "Oriental Herbal Medicine"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Over 35 Years Experience", "detail": "Dr. Yun Wang has over 35 years of experience in Chinese acupuncture and oriental herbs.", "category": "care"}, {"title": "Chinese-Trained Physician", "detail": "Dr. Wang received his medical training at Qingdao Medical College (1978) and acupuncture training at the Northwest Institute of Acupuncture and Oriental Medicine.", "category": "culture"}, {"title": "Professor & Clinical Supervisor", "detail": "Dr. Wang is a professor and clinical supervisor at the Seattle Institute of Oriental Medicine.", "category": "care"}, {"title": "Specializes in Pain & Stroke", "detail": "Specializes in treatment of musculoskeletal pain, trauma, stroke, and many other medical conditions.", "category": "care"}, {"title": "Custom Herbal Formulas", "detail": "Custom Chinese herbal formulas available and can be shipped upon request.", "category": "convenience"}], "price_tier": "$$", "source_url": "http://www.lakecityacupuncture.com/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Chinese speaking medical clinic in Seattle, WA", "search_text": "acupuncture & tcm | acupuncture | chinese medicine | tcm | herbal medicine | cupping | pain relief | châm cứu | đông y | y học cổ truyền | 한의원 | 침술 | 한약 | 中医 | 针灸 | 中药 | english | chinese | mandarin | cantonese | 中文 | 普通话 | 国语 | 粤语 | 广东话 | 华人 | chinese acupuncture | oriental herbal medicine | yun wang | m.d. (china), m.ac., e.a.m.p.", "google_types": ["medical_clinic", "health", "point_of_interest", "establishment"], "open_weekend": true, "rating_count": 25, "team_members": [{"name": "Yun Wang", "role": "M.D. (China), M.Ac., E.A.M.P.", "bio_snippet": "Received medical training at Qingdao Medical College (1978) and acupuncture training at the Northwest Institute of Acupuncture and Oriental Medicine (1993). Over 35 years experience. Professor and clinical supervisor at the Seattle Institute of Oriental Medicine.", "languages_spoken": []}], "language_note": "The clinic specializes in traditional Chinese acupuncture and oriental herbs, reflecting a deep Asian medical heritage. Dr. Yun Wang is a Chinese-trained physician (M.D. from Qingdao Medical College) and an experienced acupuncturist, providing culturally rooted care for the Asian and broader community in the Seattle area.", "open_saturday": true, "quality_score": 93, "working_hours": {"friday": "10:00 AM – 6:00 PM", "monday": "10:00 AM – 6:00 