INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('da1a7d19-11ee-4705-be9e-6aabe9572bbb', NULL, 'VN CARES', 'VN CARES (Vietnamese Cancer Awareness Research and Education Society) is a UC Davis undergraduate volunteer-driven clinic and research organization. The clinic is dedicated to bridging health disparities within the Vietnamese community by providing cancer awareness, education, and clinical services. With a focus on culturally responsive care, VN CARES operates at 6341 Folsom Blvd, Sacramento, CA, and is staffed by passionate student volunteers and an officer board. Their mission extends beyond clinic walls into research, education, and public relations, all aimed at serving the Vietnamese patient population.', '6341 Folsom Blvd, Sacramento, CA, 95819', 'Sacramento', 'CA', '95819', '(916)-542-2737', ARRAY['English', 'Vietnamese']::text[], 'Community Health Center', FALSE, '{"email": "clinic@vncares.org", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/vn-cares.webp"], "website": "https://vncaresorg.wordpress.com/", "location": {"latitude": 38.5553947, "longitude": -121.42915749999999}, "services": ["Cancer Awareness and Education", "Clinic Services", "Research and Education"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Bridging Health Disparities in the Vietnamese Community", "detail": "The clinic and research branches are dedicated to serving the Vietnamese patient population by addressing gaps in healthcare access and cancer awareness.", "category": "culture"}, {"title": "UC Davis Undergraduate Volunteer-Run", "detail": "Student volunteers are the hear