INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('ed886ec7-93dd-4a45-8d45-74b45be6678d', NULL, 'NAMI Orange County (NAMI OC)', 'NAMI Orange County (NAMI OC) is a dedicated affiliate of the National Alliance on Mental Illness serving Orange County, California. The organization focuses on improving the lives of community members affected by mental illness through no-cost support groups, educational classes, a peer-run WarmLine, and youth mentoring programs. Their mission is to create a future where all individuals affected by mental illness can experience hope, recovery, and wellness in a world free of stigma. NAMI OC provides a range of programs tailored to family members, peers, teens, young adults, schools, and workplaces, and actively fosters community through advocacy, outreach, events, and volunteer opportunities.', '16480 South Harbor Boulevard, Ste #101, Fountain Valley, CA, 92708, United States', 'Fountain Valley', 'CA', '92708', '714-544-8488', ARRAY['English', 'Vietnamese']::text[], 'Mental Health', FALSE, '{"email": "info@namioc.org", "images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/nami-orange-county-nami-oc.webp"], "pricing": [{"name": "Family-to-Family Class", "notes": "The class is offered at no charge to participants.", "price": "No cost", "category": "education", "price_range": null}, {"name": "WarmLine", "notes": "The OC WarmLine is a free, confidential peer support service.", "price": "Free", "category": "support", "price_range": null}, {"name": "Donation", "notes": "Tax-deductible donations support all NAMI OC programs and services.", "price": "Any amount", "category": "fundraising", "price_range": null}], "website": "https://www.namioc.org/", "location": {"latitude": 33.7239578, "longitude": -117.91934789999999}, "services": ["Support Groups", "WarmLine", "Family-to-Family", "Peer Mentoring", "Youth & Young Adult Programs", "Advocacy & Outreach", "NAMIWalks & Tour de NAMI"], "insurance": {"notes": "NAMI OC provides no-cost programs and services; no insurance is required or discussed.", "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "No-Cost Programs", "detail": "Family-to-Family classes and support groups are offered at no charge to participants.", "category": "access"}, {"title": "WarmLine & Live Chat", "detail": "The NAMI OC WarmLine is available daily from 12:00 PM to 12:00 AM, seven days a week, 365 days a year, with call-backs available.", "category": "convenience"}, {"title": "Youth & Young Adult Focus", "detail": "Dedicated mentoring services and podcasts like ''Anxiety Sucks'' address the needs of teens and young adults.", "category": "care"}, {"title": "Community Events", "detail": "Annual events such as NAMIWalks and Tour de NAMI help raise awareness and support for mental health.", "category": "culture"}], "price_tier": "$$", "source_url": "https://www.namioc.org/", "appointment": {"booking_note": null, "appointment_url": null, "new_patient_note": null, "phone_booking_available": true, "online_booking_available": false, "free_consultation_available": null}, "open_sunday": false, "scout_query": "Vietnamese mental health counseling in Orange County, CA", "search_text": "mental health | psychiatry | psychiatrist | psychology | therapist | counseling | depression | anxiety | tâm lý | tâm thần | trầm cảm | 정신과 | 심리상담 | 心理医生 | 精神科 | english | vietnamese | tiếng việt | người việt | bác sĩ việt | support groups | warmline | family-to-family | peer mentoring | youth & young adult programs | advocacy & outreach | namiwalks & tour de nami | support | crisis support | education | youth | advocacy | events | cork | tour de nami rider / 