INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('dd1cc656-ce56-44f1-9bcc-b4278a7f0270', NULL, 'Southern California Eye Institute (SCEI)', 'The Southern California Eye Institute (SCEI) is a leading ophthalmology center dedicated to ending blindness through advanced medical and surgical eye care, innovative research, and education. Under the leadership of Founding Director Dr. Rohit Varma, MD, MPH, SCEI provides compassionate, personalized care using state-of-the-art technologies including lasers, novel imaging devices, minimally invasive and complex surgical techniques. The institute''s team of board-certified ophthalmologists, glaucoma specialists, optometrists, and researchers are committed to restoring vision and transforming hope into reality for every patient. SCEI also houses the SCEI Vision Van, a mobile clinic bringing eye care to underserved communities, and offers specialized services across multiple locations in Los Angeles, Pasadena, and Bakersfield.', '1300 North Vermont Avenue, Doctors Tower, Ste 101, Los Angeles, CA 90027', 'Los Angeles', 'CA', '90027', '1-833-270-3937', ARRAY['English', 'Russian', 'Korean']::text[], 'Ophthalmology', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southern-california-eye-institute-scei-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southern-california-eye-institute-scei-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southern-california-eye-institute-scei-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southern-california-eye-institute-scei-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/southern-california-eye-institute-scei-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2026-06-04T21:52:33.574909669Z", "text": "They are great. Very friendly and kind behavior. I like their service Definitely recommend", "author": "Zakia Sultana", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107358476073695333010/reviews"}, {"date": "2026-01-05T22:13:28.150761228Z", "text": "Dr Popat didn''t just go through the routine but also educated me difference of glaucoma and cataract and other informative facts related to the checkup.\nShe is also not rushing.  She established a calm and professional atmosphere.  Front desk girl is very pleasant and helpful ☺️", "author": "M DeeDee De Leon", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/102310239139553501650/reviews"}, {"date": "2026-01-14T03:54:27.068916614Z", "text": "The visit was easy in and out, Both the Dr. and Receptionist/Assistant were very helpful and pleasant to talk to, My Husband was the Patient and is a bit difficult to deal with, He was Happy with the glasses I chose for Him, I really appreciate both the Dr. and Assistant very much.", "author": "Elie Zindros", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114863745697229707549/reviews"}, {"date": "2025-12-16T18:59:26.197925541Z", "text": "I want to say a huge thank you to the medical staff. This was my first time here, and if I ever need help, I''ll definitely return to this clinic. They''re highly qualified, attentive, and knowledgeable.", "author": "Karine Oganisyan", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/107989970288858807000/reviews"}, {"date": "2025-10-27T20:46:59.069584247Z", "text": "Dr. Nicole Fuerst (Ophthalmologist ) and her entire team are tops! I am Always treated so warmly by all. They have an optometry Department that is connected to them, with a super nice young lady named “Q” running the front, and she really goes above and beyond for patients and is very knowledgeable about your Health insurance and coverages. They would’ve gotten five stars but my last visit end of October I had to wait an unusually long time to see my ophthalmologist. I’m not sure, but they might’ve been understaffed that day.\nDr. Nicole is there only once per month, on Wednesday, so book well in advance if you want An appointment with her.", "author": "Jeanette St. John", "rating": 4, "source": "google", "author_url": "https://www.google.com/maps/contrib/100377896776655479641/reviews"}], "website": "https://sceyes.org/", "location": {"latitude": 34.0963187, "longitude": -118.2903056}, "services": ["Cataract & Refractive Surgery", "Cornea & External Diseases", "Glaucoma", "Neuro-ophthalmology & Strabismus", "Ocular Oncology", "Oculo-facial Plastics & Reconstructive Surgery", "Pediatric Ophthalmology", "Retinal Diseases"], "insurance": {"notes": null, "accepts_medicaid": null, "accepts_medicare": null, "accepted_networks": [], "out_of_network_available": null, "accepts_private_insurance": false}, "highlights": [{"title": "Advanced Technology", "detail": "Employs lasers, novel imaging devices, minimally invasive and complex surgical techniques, as well as research in stem cell therapies and AI.", "category": "technology"}, {"title": "Expert Team", "detail": "Includes board-certified ophthalmologists, glaucoma specialists, optometrists, and researchers led by Dr. Rohit Varma, a renowned glaucoma expert.", "category": "care"}, {"title": "Multiple Locations", "detail": "Conveniently located in Los Angeles, Pasadena, and Bakersfield, California.", "category": "convenience"}, {"title": "Vision Van", "detail": "Mobile eye care unit providing services to underserved communities throughout Southern Califor