INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('f59c4248-a4ca-4d44-b488-327a669f863a', NULL, 'Poway Modern Dentistry', 'Welcome to Poway Modern Dentistry, your trusted dentist in Poway, CA. Led by Dr. Viet Nguyen, our practice is committed to providing top-notch dental care tailored to your needs. We offer a comprehensive range of services, from routine cleanings to advanced treatments, ensuring oral health is our priority. Our team is dedicated to making quality dental care affordable and accessible so you can enjoy a beautiful smile without breaking the bank.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('48c446e4-dc8b-42ac-a740-b32a3b5a4027', NULL, 'SKYLINE DENTISTRY. David Nguyen DDS', 'At Dental Care Today of Richardson, we are committed to helping people across the city and the surrounding areas fulfill all their dental needs. Backed by years of experience, Dr. David Nguyen, DDS, FICOI has an in-depth understanding of various areas of dentistry. From preventive care and restorative dentistry to cosmetic dentistry and more, he and our team of professionals can resolve all your oral healthcare problems. Using cutting-edge techniques in our state-of-the-art office, we have what it takes to help you achieve your dental goals. Whether you want a brighter smile, are suffering from any type of dental issue, require a regular checkup, or have any other needs, we can handle it. Our dental team genuinely cares about our patients, and we will work diligently to help you with all your needs. As a boutique dental office, we are able to give each of our patients 100% of our time and attention. When you work with us, you work one-on-one with our skilled and experienced Richardson dentist. No matter how tough your problem may be, we can help you treat it in a timely and professional manner.', '1600 North Plano Rd Ste 2200, Richardson TX 75081', 'Richardson', 'TX', '75081', '214-377-8881', ARRAY['English', 'Vietnamese']::text[], 'Dental', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/skyline-dentistry.-david-nguyen-dds-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/skyline-dentistry.-david-nguyen-dds-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/skyline-dentistry.-david-nguyen-dds-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/skyline-dentistry.-david-nguyen-dds-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/skyline-dentistry.-david-nguyen-dds-google-5.webp"], "rating": 4.8, "reviews": [{"date": "2021-07-16T16:29:28.103412Z", "text": "I always have an amazing experience here. The staff is professional and always willing to help. Everybody is very friendly and accommodating, and their great communication makes scheduling a very simple and easy process. The office itself is very modern and clean as well. Dr. Nguyen is very caring and friendly, and always leaves my teeth looking better than ever! If you’re looking for a skilled dentist who genuinely cares about your teeth and health, Dental Care Today is the place to go!", "author": "Quynh Dam", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109591012018961237782/reviews"}, {"date": "2018-09-12T19:30:51.741931Z", "text": "This place truly puts their clients first. While I didn''t have any major dental procedures done, the entire team was patient, transparent and accomodating on my first visit. I didn''t feel rushed, and the dental hygienist was very careful while cleaning my teeth. Dr. Nguyen took great care of me, and explained clearly recommended treatment. They will work with your insurance to guarantee the best rate for you. Thank you for great service!", "author": "Weronika Lo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/108528809965462710849/reviews"}, {"date": "2017-10-20T21:29:06.347Z", "text": "I love Dental Care Today! I have been going to them ever since they took over the previous practice. I don''t live in Richardson but I couldn''t imagine going anywhere else. I even got my husband to join as we truly feel like family there. My parents also go there too and we have always had a pleasant experience. They offer great hours, Saturday appointments, and the staff is amazing. They are always very accommodating and they go above and beyond every visit. We recently took our 4 month old there while my husband and I had our appointments and they staggered us so that one of us could always be with the baby. Danielle even gave my daughter a cute little toy to keep her entertained. We are very happy customers for life.", "author": "Elaine Stiglmeier", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/105820796905705665225/reviews"}, {"date": "2021-07-18T22:25:13.565243Z", "text": "I have been coming to Dental Care Today in Richardson for many years and always come out feeling satisfied with their top notch quality of service. The office is clean, staffs are polite and accommodating. Scheduling is like a breeze and I can come in and out pretty quick without wasting my time. Dr Nguyen is very friendly and professional, knowledgeable and confident in his expertises and experiences, which put my mind as ease. I highly recommend Dental Care Today for anyone who are looking for great quality of dental care services.", "author": "Giang T. Ngo", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/109339194965038797188/reviews"}, {"date": "2020-11-17T17:27:54.705342Z", "text": "Dr. Nguyen and staff here are amazing and make you feel comfortable. I’ve had horrible previous dental experience, but he has a way to make sure you’re calm and listen to your concerns. The hygienist is to also gentle and thorough. I will Never go to another dentist. I’ve recommended this dentist to my friends and family as well.", "author": "Maddy A", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/110687788575846272528/reviews"}], "website": "https://w