INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('2bb961b2-1b09-45ad-bbcf-371ec218db38', NULL, 'Karen Chan Acupuncture & Herbal Medicine', 'Karen Chan Acupuncture & Herbal Medicine is a healing sanctuary rooted in Traditional Chinese Medicine, offering gentle, personalized care through acupuncture, custom herbal medicine, Celluma LED light therapy, microneedling, and Dolphin Neurostim. With over 15 years of experience, Karen Chan creates tailored treatment plans to support physical, mental, and emotional well-being, addressing chronic pain, stress, digestive issues, hormonal imbalances, and more.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('777032a1-ce07-4965-a0d0-68edfa24a248', NULL, 'Rose Park Dental', 'At Rose Park Dental, our philosophy of care governs everything we do. We truly care about our patients and want you to feel very comfortable with our experienced, well-trained, and friendly staff. We offer bilingual support in Spanish and Vietnamese to assist patients who prefer to communicate in those languages. We recognize each patient as an individual and strive to help you retain your teeth in comfort, function, and esthetics for a lifetime.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('0ec92fd5-3ded-42ce-aa5e-bf6aa7dc8a7d', NULL, 'CANAL DENTAL GROUP', 'At Canal Dental Group, our goal is to offer you the best comprehensive dental healthcare. We believe it is essential to listen to you, the patient, and understand your needs. Our dentists not only offer a breadth of treatment plans and options but are also trained in state-of-the-art techniques and technologies. We are Committed To Dental Excellence.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('ec62b9c5-8508-4e42-a3dc-7abe630d0704', NULL, 'Koreatown Youth & Community Center (KYCC) - Clinical Services', 'KYCC Clinical Services provides accessible, high-quality mental health care in English, Korean, and Spanish to low-income, multiethnic, and recently immigrated families and individuals in Koreatown. Services include individual and family therapy, neurofeedback, and Positive Parenting Program, all delivered in a culturally responsive, in-language setting. As a one-stop shop, KYCC integrates clinical services with broader family support, financial coaching, drug and alcohol recovery, and supportive housing to serve the whole person and the whole family. The agency is built on a mission to help community members realize their full social and economic potential. With over 15,700 individuals served annually across 12 locations, KYCC is deeply rooted in Koreatown and trusted by the community. KYCC Clinical Services also accepts clients through insurance partnerships and offers a dedicated self-pay program for those without coverage.', '3727 W. 6th St., Suite 300, Los Angeles, CA 90020', 'Los Angeles', 'CA', '90020', '(213) 365-7400', ARRAY['English', 'Korean', 'Spanish']::text[], 'Mental Health', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/koreatown-youth-community-center-kycc-clinical-services-google-1.webp"], "rating": 4.2, "pricing": [{"name": "Mental Health Counseling - Self-Pay", "notes": "New self-pay option available for mental health services. Free counseling also available for youth and API families.", "price": null, "category": "Mental Health", "price_range": null}], "reviews": [{"date": "2025-07-08T08:58:58.504125193Z", "text": "First  time there to have my taxes done i love this place they did my taxes in 2025 for the year 2024 taxes I was very happy the people there are very professional they made me feel so comfortable they also have excellent customer service I will definitely be going back in 2026 😊", "author": "Lydia White", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/114007176193943758511/reviews"}, {"date": "2024-04-15T16:09:53.309536Z", "text": "After some general treatment in Recovery etc.... I would not recommend this program at all if you value any type of professionalism or your privacy.  12 step programs are administered here so if you do not prefer 12 step programs this is a huge no for me.  I have left KYCC due to unprofessional behavior.  I didn''t have the zero star option.", "author": "Natasha Gascon", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/105549378221770359159/reviews"}, {"date": "2025-06-29T19:53:40.063696413Z", "text": "This place is the worst they will lie to you I was told by shania that k y c c would pay my rent in full for year And that was a lie.\nAfter six months I started to have to pay portion of my rent which I shouldn''t had to Preston was the worst case manager didn''t get along with him and miss may will lie to you and she will tell section 8 nothing but lies about you if you don''t work with them and mrs miss Clark is very rude All they did was lie to me and They put me in a apartment that I could not afford On my own at all, never told me that my EHY Voucher was not a Guarantee,but I was approved for my EHV Voucher and no one told that I was approved..so now i''m homeless again So how was this program supposed to help People and  keep them off the street they don''t care about helping anyone at all", "author": "Steven Richards", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/115147579876875998558/reviews"}, {"date": "2025-03-05T19: