INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('9c057b4d-fa78-4131-a46d-6a4ab8217e6a', NULL, 'Eye Medical Clinic', 'Eye Medical Clinic is a comprehensive eye care destination in San Jose, California, offering everything from routine family eye exams to advanced medical, surgical, and laser procedures for cataracts and glaucoma. With a legacy of more than 75 years serving the San Jose area, the clinic has built a trusted reputation that generations of families rely on, growing alongside Silicon Valley while embracing the most advanced techniques and technology in eye care and vision correction.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('6319fb3e-46e1-4ded-b12e-624517d08b9c', NULL, 'Pannu Dental Group', 'Pannu Dental Group, led by Dr. Dalvir S. Pannu, has been serving the San Jose community for over 20 years, opening its doors in 2003. The practice offers multi-specialty care under one roof, including general, cosmetic, restorative, orthodontic, implant, and pediatric dentistry, so that patients can receive coordinated treatment plans without referrals to multiple offices. The team uses advanced technology like digital X-rays, cone-beam CT imaging, intraoral scanning, and the FDA-cleared Yomi robotic implant system to deliver precise, predictable results with minimal discomfort.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('7973389c-bc1b-491e-85db-9ccb1f307461', NULL, 'Harmony Acupuncture Chinese Medicine, Inc.', 'Harmony Acupuncture Chinese Medicine, Inc. is a result-driven Chinese Medicine clinic in San Jose, CA, led by Dr. Juliet Kwok, DTCM, L.Ac. The clinic specializes in fertility acupuncture and Chinese medicine, helping patients with infertility, IVF support, natural conception, pain management, stress disorders, and a wide range of women''s health and wellness concerns. Dr. Kwok provides tailored, holistic treatments combining acupuncture, herbal medicine, and lifestyle guidance, with a strong focus on individual patient needs and a commitment to helping patients achieve their family dreams and overall health goals.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('a2da3ee9-41d6-4f63-b497-f981e8c871cd', NULL, 'UT Physicians Cardiology – Texas Medical Center', 'UT Physicians Cardiology at Texas Medical Center offers one of the most comprehensive ranges of advanced cardiovascular diagnostic and imaging modalities available in the United States. Internationally recognized cardiology specialists interpret each study, ensuring precise analysis and a personalized treatment plan to optimize cardiovascular health. Located in the UTHealth Houston Professional Building, this clinic serves adult patients with expertise in non-invasive imaging, heart rhythm monitoring, pacemaker optimization, and advanced cardiac PET-CT.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('05e5bc67-5227-4608-81b1-88e9fd7af9c4', NULL, 'Athletic Heart of San Francisco', 'Athletic Heart of San Francisco is a cardiology clinic dedicated to heart disease prevention through early detection. Founded by a board-certified cardiologist with over 20 years of clinical experience, the clinic offers prompt access to cardiac care for self-referred patients. They combine consultations and testing to provide timely evaluations, using advanced technologies to assess cardiovascular health.
INSERT INTO public.clinics ("id", "org_id", "name", "description", "address", "city", "state", "zip_code", "phone", "languages", "specialty", "is_telehealth_available", "metadata", "created_at", "slug", "claimed_by", "is_claimed") VALUES ('57f16240-1671-4e72-8e41-2f6e3fc9f778', NULL, 'Reconstructive Orthopedic Center', 'Reconstructive Orthopedic Center (ROC) is a Houston-based orthopedic practice offering same-day comprehensive injury assessment, diagnosis, and treatment. The center provides personalized treatment plans that prioritize non-surgical options first, with an experienced team of board-certified physicians who have over two decades of experience. ROC features an in-house surgical facility certified by the Joint Commission (JCAHO), an integrated therapy center offering physical therapy, occupational therapy, and hydrotherapy, and a commitment to high-quality, affordable care with payment plans and acceptance of most major insurance providers.', '1200 BINZ ST, SUITE 100, HOUSTON TX 77004', 'HOUSTON', 'TX', '77004', '713-520-1210', ARRAY['English', 'Vietnamese']::text[], 'Orthopedics', FALSE, '{"images": ["https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/reconstructive-orthopedic-center-google-1.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/reconstructive-orthopedic-center-google-2.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/reconstructive-orthopedic-center-google-3.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/reconstructive-orthopedic-center-google-4.webp", "https://smkyqdkuablxlexyuhgs.supabase.co/storage/v1/object/public/generated-images/generated-clinics/google-places/reconstructive-orthopedic-center-google-5.webp"], "rating": 4.9, "reviews": [{"date": "2026-05-15T15:21:39.542595848Z", "text": "Dr. Masson has been a huge help throughout my recovery. He has taken the time to listen to my concerns about my leg and arm and has shown genuine care during every visit. His professionalism, patience, and dedication have made a difficult situation much easier to handle. I truly appreciate the support, treatment, and encouragement he has provided along the way. I’m grateful to have a doctor who is so attentive and committed to helping me heal.\n\nThe staff has also been amazing from the moment I walk in. Everyone is kind, respectful, and welcoming, and they always make me feel comfortable. They are very professional, helpful, and attentive, and they work hard to make sure patients are taken care of. I truly appreciate the positive atmosphere and excellent customer service from the entire team.", "author": "Jessi", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101989551781338778266/reviews"}, {"date": "2026-06-09T20:33:58.136376076Z", "text": "Really disorganized when it comes to scheduling anything. I have had to follow up so many times for various needs for my mom and before we even had surgery was told every day something new we had to get done and it''s been a cat and mouse chase with trying to schedule her therapy with one person blaming another for not getting back to them with what they need and yada yada yada. Thankfully the surgery was well done but the organization here has been less than professional. Nice people, but when you''re needing to care for your loved ones it would be helpful to have a better system in place. Extremely unimpressed.", "author": "Richard Chaz Gomez", "rating": 1, "source": "google", "author_url": "https://www.google.com/maps/contrib/103512236597936416283/reviews"}, {"date": "2026-03-28T14:52:00.777688720Z", "text": "Dr. Masson is absolutely amazing! I came to him for a second opinion after another doctor recommended extensive surgery. After a thorough examination, Dr. Masson explained that surgery was not necessary at this time and that my shoulder could be treated without it—and he was right.\nThanks to his expertise, I went from being in severe pain to having no pain at all, without undergoing surgery. He is incredibly knowledgeable, attentive, and truly cares about his patients.\nI couldn''t have asked for a better experience and highly recommend Dr. Masson to anyone seeking honest, skilled, and compassionate care.\nI would give him 10 Stars if I could!!\nHis staff is also extremely nice and caring!! Everyone is amazing!", "author": "Julie Burrow", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/104501252365768008084/reviews"}, {"date": "2026-02-13T21:04:06.156600087Z", "text": "Dr. Masson is the BEST! He’s helped me w various issues that required surgery, and ea time it resulted in complete healing and scars that are barely visible. He is kind, understanding, and has a very warm bedside manner. I highly recommend him!", "author": "Rene Grossimon", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/113695893632068747202/reviews"}, {"date": "2026-02-21T20:38:34.586512682Z", "text": "Dr Masson is the BEST orthopedics doctor/surgeon in Houston, hands down!\nIf you’re looking for a veteran doctor and one who knows his profession look no further than Dr Masson. He has excellent bedside manners, takes time out to explain everything to you.\nPerformed my shoulder rotator cuff surgery etc and I’m feeling my best after two weeks already. I’ve been with him for a couple decades and will never ever choose another orthepedics doctor/surgeon. His  staff is not bad either.\nScale of 1-10…he’s a 10+‼️👍 J Gudger", "author": "anonymous anonymous", "rating": 5, "source": "google", "author_url": "https://www.google.com/maps/contrib/101355313593958148814/reviews"}], "website": "https://rocmd.net/", "location": {"latitude": 29.724494500000002, "longitude": -95.3878852},